'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Settings,
    Save,
    Upload,
    CheckCircle2,
    Loader2,
    Globe,
    Shield,
    Bell,
    Palette
} from 'lucide-react';

import { settingsService, academicYearService } from '@/lib/services';
import { AcademicYear } from '@/types/database.types';

export default function GlobalSettingsPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [showSuccess, setShowSuccess] = useState(false);
    const [isLoading, setIsLoading] = useState(true);

    // Form state
    const [settings, setSettings] = useState({
        appName: '',
        tagline: '',
        logoUrl: '',
        primaryColor: '#8b5cf6',
        maintenanceMode: false,
        allowRegistration: true,
        emailNotifications: true,
        smsNotifications: false,
        autoBackup: true,
        sessionTimeout: 30,
        activeAcademicYearId: '',
    });

    const [academicYears, setAcademicYears] = useState<AcademicYear[]>([]);

    const loadData = useCallback(async () => {
        try {
            setIsLoading(true);
            const [fetchedSettings, fetchedYears] = await Promise.all([
                settingsService.get(),
                academicYearService.getAll()
            ]);

            setSettings({
                appName: fetchedSettings.app_name,
                tagline: fetchedSettings.tagline || '',
                logoUrl: fetchedSettings.logo_url || '',
                primaryColor: fetchedSettings.primary_color,
                maintenanceMode: fetchedSettings.maintenance_mode,
                allowRegistration: fetchedSettings.allow_registration,
                emailNotifications: fetchedSettings.email_notifications,
                smsNotifications: fetchedSettings.sms_notifications,
                autoBackup: fetchedSettings.auto_backup,
                sessionTimeout: fetchedSettings.session_timeout,
                activeAcademicYearId: fetchedSettings.active_academic_year_id || '',
            });

            setAcademicYears(fetchedYears);
            setIsLoading(false);
        } catch (_error) {
            console.error('Error loading settings:', _error);
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'super_admin') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            loadData();
        });
        return () => cancelAnimationFrame(timer);
    }, [router, loadData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleSave = async () => {
        setIsSaving(true);
        try {
            await settingsService.update({
                app_name: settings.appName,
                tagline: settings.tagline,
                logo_url: settings.logoUrl,
                primary_color: settings.primaryColor,
                maintenance_mode: settings.maintenanceMode,
                allow_registration: settings.allowRegistration,
                email_notifications: settings.emailNotifications,
                sms_notifications: settings.smsNotifications,
                auto_backup: settings.autoBackup,
                session_timeout: settings.sessionTimeout,
                active_academic_year_id: settings.activeAcademicYearId || null,
            });

            // If academic year changed, we might need to update that table too or it's handled by this foreign key
            if (settings.activeAcademicYearId) {
                // Optional: Ensure only one is active in academic_years table if we want redundancy
                // await academicYearService.setActive(settings.activeAcademicYearId);
            }

            setShowSuccess(true);
            setTimeout(() => setShowSuccess(false), 3000);
        } catch (_error) {
            console.error('Error saving settings:', _error);
            alert('Gagal menyimpan pengaturan');
        } finally {
            setIsSaving(false);
        }
    };

    if (!user || isLoading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50">
                <Loader2 className="w-8 h-8 text-purple-600 animate-spin" />
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Success Toast */}
            {showSuccess && (
                <div className="fixed top-4 right-4 z-[60] bg-emerald-500 text-white px-6 py-4 rounded-xl shadow-lg flex items-center gap-3">
                    <CheckCircle2 className="w-6 h-6" />
                    <span className="font-medium">Settings berhasil disimpan!</span>
                </div>
            )}

            {/* Sidebar */}
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Breadcrumb & Title */}
                    <div className="mb-6">
                        <Link
                            href="/dashboard/admin"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 mb-2"
                        >
                            <ArrowLeft className="w-4 h-4" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div>
                                <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-3">
                                    <Settings className="w-7 h-7 text-purple-600" />
                                    Global Settings
                                </h1>
                                <p className="text-gray-500">
                                    Konfigurasi pengaturan global aplikasi
                                </p>
                            </div>
                            <button
                                onClick={handleSave}
                                disabled={isSaving}
                                className="flex items-center gap-2 px-5 py-3 bg-purple-600 hover:bg-purple-700 text-white font-semibold rounded-xl transition-colors shadow-lg shadow-purple-500/30 disabled:opacity-50"
                            >
                                {isSaving ? (
                                    <>
                                        <Loader2 className="w-5 h-5 animate-spin" />
                                        Menyimpan...
                                    </>
                                ) : (
                                    <>
                                        <Save className="w-5 h-5" />
                                        Save Settings
                                    </>
                                )}
                            </button>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                        {/* General Settings */}
                        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
                            <h3 className="font-semibold text-gray-800 mb-6 flex items-center gap-2">
                                <Globe className="w-5 h-5 text-purple-600" />
                                General Settings
                            </h3>
                            <div className="space-y-5">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">App Name</label>
                                    <input
                                        type="text"
                                        value={settings.appName}
                                        onChange={(e) => setSettings({ ...settings, appName: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30 focus:border-purple-500"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Tagline</label>
                                    <input
                                        type="text"
                                        value={settings.tagline}
                                        onChange={(e) => setSettings({ ...settings, tagline: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30 focus:border-purple-500"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Upload Logo</label>
                                    <div className="flex items-center gap-4">
                                        <div className="w-16 h-16 bg-gradient-to-br from-purple-500 to-indigo-600 rounded-xl flex items-center justify-center overflow-hidden">
                                            {settings.logoUrl ? (
                                                <img src={settings.logoUrl} alt="Logo" className="w-full h-full object-cover" />
                                            ) : (
                                                <span className="text-white font-bold text-xl">SP</span>
                                            )}
                                        </div>
                                        <label className="flex items-center gap-2 px-4 py-2.5 border border-gray-200 rounded-xl text-gray-700 hover:bg-gray-50 cursor-pointer transition-colors">
                                            <Upload className="w-4 h-4" />
                                            <span>Pilih File</span>
                                            <input
                                                type="file"
                                                className="hidden"
                                                accept="image/*"
                                                onChange={(e) => {
                                                    const file = e.target.files?.[0];
                                                    if (file) {
                                                        const reader = new FileReader();
                                                        reader.onloadend = () => {
                                                            setSettings({ ...settings, logoUrl: reader.result as string });
                                                        };
                                                        reader.readAsDataURL(file);
                                                    }
                                                }}
                                            />
                                        </label>
                                    </div>
                                    <p className="text-xs text-gray-400 mt-2">Recommended: 512x512px, PNG or SVG</p>
                                </div>
                            </div>
                        </div>

                        {/* Appearance */}
                        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
                            <h3 className="font-semibold text-gray-800 mb-6 flex items-center gap-2">
                                <Palette className="w-5 h-5 text-purple-600" />
                                Appearance
                            </h3>
                            <div className="space-y-5">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Primary Color</label>
                                    <div className="flex items-center gap-3">
                                        <input
                                            type="color"
                                            value={settings.primaryColor}
                                            onChange={(e) => setSettings({ ...settings, primaryColor: e.target.value })}
                                            className="w-12 h-12 rounded-lg border border-gray-200 cursor-pointer"
                                        />
                                        <input
                                            type="text"
                                            value={settings.primaryColor}
                                            onChange={(e) => setSettings({ ...settings, primaryColor: e.target.value })}
                                            className="flex-1 px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30 font-mono"
                                        />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Tahun Ajaran Aktif</label>
                                    <select
                                        value={settings.activeAcademicYearId}
                                        onChange={(e) => setSettings({ ...settings, activeAcademicYearId: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30 text-gray-900 font-bold"
                                        disabled={academicYears.length === 0}
                                    >
                                        <option value="">-- Pilih Tahun Ajaran --</option>
                                        {academicYears.map(year => (
                                            <option key={year.id} value={year.id}>{year.name} {year.is_active ? '(Aktif)' : ''}</option>
                                        ))}
                                    </select>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Session Timeout (minutes)</label>
                                    <input
                                        type="number"
                                        value={settings.sessionTimeout}
                                        onChange={(e) => setSettings({ ...settings, sessionTimeout: parseInt(e.target.value) })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30"
                                    />
                                </div>
                            </div>
                        </div>

                        {/* Security Settings */}
                        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
                            <h3 className="font-semibold text-gray-800 mb-6 flex items-center gap-2">
                                <Shield className="w-5 h-5 text-purple-600" />
                                Security & Access
                            </h3>
                            <div className="space-y-4">
                                {/* Maintenance Mode */}
                                <div className="flex items-center justify-between p-4 bg-gray-50 rounded-xl">
                                    <div>
                                        <p className="font-medium text-gray-800">Maintenance Mode</p>
                                        <p className="text-sm text-gray-500">Disable access for non-admin users</p>
                                    </div>
                                    <label className="relative inline-flex items-center cursor-pointer">
                                        <input
                                            type="checkbox"
                                            checked={settings.maintenanceMode}
                                            onChange={(e) => setSettings({ ...settings, maintenanceMode: e.target.checked })}
                                            className="sr-only peer"
                                        />
                                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-purple-500/30 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-purple-600"></div>
                                    </label>
                                </div>

                                {/* Allow Registration */}
                                <div className="flex items-center justify-between p-4 bg-gray-50 rounded-xl">
                                    <div>
                                        <p className="font-medium text-gray-800">Allow New Registrations</p>
                                        <p className="text-sm text-gray-500">Enable self-registration for new users</p>
                                    </div>
                                    <label className="relative inline-flex items-center cursor-pointer">
                                        <input
                                            type="checkbox"
                                            checked={settings.allowRegistration}
                                            onChange={(e) => setSettings({ ...settings, allowRegistration: e.target.checked })}
                                            className="sr-only peer"
                                        />
                                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-purple-500/30 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-purple-600"></div>
                                    </label>
                                </div>

                                {/* Auto Backup */}
                                <div className="flex items-center justify-between p-4 bg-gray-50 rounded-xl">
                                    <div>
                                        <p className="font-medium text-gray-800">Auto Backup</p>
                                        <p className="text-sm text-gray-500">Daily automatic database backup at 02:00</p>
                                    </div>
                                    <label className="relative inline-flex items-center cursor-pointer">
                                        <input
                                            type="checkbox"
                                            checked={settings.autoBackup}
                                            onChange={(e) => setSettings({ ...settings, autoBackup: e.target.checked })}
                                            className="sr-only peer"
                                        />
                                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-purple-500/30 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-purple-600"></div>
                                    </label>
                                </div>
                            </div>
                        </div>

                        {/* Notification Settings */}
                        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
                            <h3 className="font-semibold text-gray-800 mb-6 flex items-center gap-2">
                                <Bell className="w-5 h-5 text-purple-600" />
                                Notifications
                            </h3>
                            <div className="space-y-4">
                                {/* Email Notifications */}
                                <div className="flex items-center justify-between p-4 bg-gray-50 rounded-xl">
                                    <div>
                                        <p className="font-medium text-gray-800">Email Notifications</p>
                                        <p className="text-sm text-gray-500">Send system alerts via email</p>
                                    </div>
                                    <label className="relative inline-flex items-center cursor-pointer">
                                        <input
                                            type="checkbox"
                                            checked={settings.emailNotifications}
                                            onChange={(e) => setSettings({ ...settings, emailNotifications: e.target.checked })}
                                            className="sr-only peer"
                                        />
                                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-purple-500/30 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-purple-600"></div>
                                    </label>
                                </div>

                                {/* SMS Notifications */}
                                <div className="flex items-center justify-between p-4 bg-gray-50 rounded-xl">
                                    <div>
                                        <p className="font-medium text-gray-800">SMS Notifications</p>
                                        <p className="text-sm text-gray-500">Send critical alerts via SMS</p>
                                    </div>
                                    <label className="relative inline-flex items-center cursor-pointer">
                                        <input
                                            type="checkbox"
                                            checked={settings.smsNotifications}
                                            onChange={(e) => setSettings({ ...settings, smsNotifications: e.target.checked })}
                                            className="sr-only peer"
                                        />
                                        <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-purple-500/30 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-purple-600"></div>
                                    </label>
                                </div>
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User,
    ROLE_NAMES,
    ROLE_COLORS,
    UserRole
} from '@/lib/auth';
import { Profile } from '@/types/database.types';
import {
    Plus,
    Search,
    Edit,
    Trash2,
    CheckCircle2,
    UserX,
    UserCheck,
    Building2,
    Loader2,
    KeyRound,
    ArrowLeft,
    Users,
    RefreshCw,
    Phone,
    MoreVertical
} from 'lucide-react';
import AddUserModal, { NewUserData } from '@/components/admin/AddUserModal';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';

// ============================================
// Types
// ============================================


const ROLE_OPTIONS: { value: UserRole | 'all'; label: string }[] = [
    { value: 'all', label: 'Semua Role' },
    { value: 'admin_keuangan', label: 'Admin Keuangan' },
    { value: 'admin_akademik', label: 'Admin Akademik' },
    { value: 'kesantrian', label: 'Bagian Kesantrian' },
    { value: 'admin_absensi', label: 'Admin Absensi' },
    { value: 'wali_kelas', label: 'Wali Kelas' },
    { value: 'ustadz', label: 'Ustadz' },
    { value: 'wali_santri', label: 'Wali Santri' },
    { value: 'santri', label: 'Santri' },
];

const STATUS_OPTIONS = [
    { value: 'all', label: 'Semua Status' },
    { value: 'active', label: 'Active' },
    { value: 'inactive', label: 'Inactive' },
];

import { usersService } from '@/lib/services/users';
import { pesantrenService, Pesantren } from '@/lib/services/pesantren';

import EditUserModal from '@/components/admin/EditUserModal';
import ResetPasswordModal from '@/components/admin/ResetPasswordModal';
import { systemService } from '@/lib/services/system';

export default function UserManagementPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);

    // User list state
    const [users, setUsers] = useState<Profile[]>([]);
    const [pesantrens, setPesantrens] = useState<Pesantren[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [filterRole, setFilterRole] = useState<UserRole | 'all'>('all');
    const [filterStatus, setFilterStatus] = useState<'all' | 'active' | 'inactive'>('all');
    const [filterPesantren, setFilterPesantren] = useState<string>('all');

    // Modal states
    const [showAddModal, setShowAddModal] = useState(false);
    const [showEditModal, setShowEditModal] = useState(false);
    const [showResetPasswordModal, setShowResetPasswordModal] = useState(false);
    const [selectedUser, setSelectedUser] = useState<Profile | null>(null);
    const [showDeleteConfirm, setShowDeleteConfirm] = useState<string | null>(null);

    // UI states
    const [showSuccess, setShowSuccess] = useState(false);
    const [successMessage, setSuccessMessage] = useState('');

    const fetchUsers = useCallback(async () => {
        try {
            setIsLoading(true);
            const [userData, pesantrenData] = await Promise.all([
                usersService.getAll(),
                pesantrenService.getAll()
            ]);
            setUsers(userData);
            setPesantrens(pesantrenData);
            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching users:', error);
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'super_admin') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchUsers();
        });
        return () => cancelAnimationFrame(timer);
    }, [router, fetchUsers]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    // Filter users
    const filteredUsers = users.filter((u: Profile) => {
        const matchSearch = (u.name?.toLowerCase() || '').includes(searchQuery.toLowerCase()) ||
            (u.email?.toLowerCase() || '').includes(searchQuery.toLowerCase());
        const matchRole = filterRole === 'all' || u.role === filterRole;
        const matchStatus = filterStatus === 'all' ||
            (filterStatus === 'active' ? u.is_active : !u.is_active);
        const matchPesantren = filterPesantren === 'all' || u.pesantren_id === filterPesantren;

        return matchSearch && matchRole && matchStatus && matchPesantren;
    });

    // Handle create user
    const handleCreateUser = async (userData: NewUserData) => {
        try {
            const result = await usersService.create(
                userData.email,
                userData.password,
                userData.name,
                userData.role as UserRole,
                userData.phone,
                userData.pesantrenId
            );

            if (!result.success) {
                alert(result.error || 'Failed to create user');
                return;
            }

            await systemService.logAction('CREATE_USER', 'Profile', userData.email, { name: userData.name, role: userData.role });

            fetchUsers();
            setShowAddModal(false);
            setSuccessMessage(`User ${userData.name} berhasil ditambahkan!`);
            setShowSuccess(true);
            setTimeout(() => setShowSuccess(false), 4000);
        } catch (_error) {
            alert('Gagal menambah user');
        }
    };

    // Handle edit user
    const handleEditUser = (u: Profile) => {
        setSelectedUser(u);
        setShowEditModal(true);
    };

    const handleUpdateUser = async (userId: string, data: { name: string; role: UserRole; phone: string }) => {
        try {
            // Update profile info
            await usersService.update(userId, {
                name: data.name,
                phone: data.phone
            });

            // Update role if changed
            const oldUser = users.find(u => u.id === userId);
            if (oldUser.role !== data.role) {
                await usersService.updateRole(userId, data.role);
            }

            await systemService.logAction('UPDATE_USER', 'Profile', userId, { ...data, oldRole: oldUser.role });

            fetchUsers();
            setShowEditModal(false);
            setSuccessMessage(`User ${data.name} berhasil diperbarui!`);
            setShowSuccess(true);
            setTimeout(() => setShowSuccess(false), 4000);
        } catch (error) {
            console.error('Error updating user:', error);
            alert('Gagal memperbarui user');
        }
    };

    // Handle delete user
    const handleDeleteUser = async (userId: string) => {
        // Prevent self-deletion
        if (user?.id === userId) {
            alert('Anda tidak dapat menghapus akun Anda sendiri.');
            return;
        }

        try {
            const userToDelete = users.find(u => u.id === userId);

            // Call service which calls RPC delete_user_complete
            await usersService.delete(userId);

            await systemService.logAction('DELETE_USER', 'Profile', userId, { name: userToDelete?.name, email: userToDelete?.email });

            setUsers(users.filter(u => u.id !== userId));
            setShowDeleteConfirm(null);
            setSuccessMessage(`User ${userToDelete?.name} berhasil dihapus permanen!`);
            setShowSuccess(true);
            setTimeout(() => setShowSuccess(false), 4000);
        } catch (error: unknown) {
            console.error('Delete error:', error);
            const message = error instanceof Error ? error.message : 'Terjadi kesalahan sistem';
            alert(`Gagal menghapus user: ${message}`);
        }
    };

    // Toggle user status
    const handleToggleStatus = async (userToUpdate: Profile) => {
        try {
            const result = await usersService.toggleActive(userToUpdate.id);
            await systemService.logAction('TOGGLE_STATUS_USER', 'Profile', userToUpdate.id, { active: result.is_active });
            fetchUsers();
        } catch (_error) {
            alert('Gagal mengubah status');
        }
    };

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-purple-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-purple-600 animate-spin" />
                    <span>Loading User Management...</span>
                </div>
            </div>
        );
    }

    // Quick stats

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Success Toast */}
            {showSuccess && (
                <div className="fixed top-4 right-4 z-[60] bg-emerald-500 text-white px-6 py-4 rounded-xl shadow-lg flex items-center gap-3 animate-slide-up">
                    <CheckCircle2 className="w-6 h-6" />
                    <span className="font-medium">{successMessage}</span>
                </div>
            )}

            {/* Delete Confirmation Modal */}
            {showDeleteConfirm && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-2xl w-full max-w-md shadow-2xl p-6">
                        <div className="flex items-center gap-4 mb-4">
                            <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center">
                                <UserX className="w-6 h-6 text-red-600" />
                            </div>
                            <div>
                                <h3 className="text-lg font-bold text-gray-800">Hapus User?</h3>
                                <p className="text-sm text-gray-500">
                                    {users.find(u => u.id === showDeleteConfirm)?.name}
                                </p>
                            </div>
                        </div>
                        <p className="text-gray-600 mb-6">
                            Tindakan ini tidak dapat dibatalkan. User akan dihapus permanen dari sistem.
                        </p>
                        <div className="flex gap-3">
                            <button
                                onClick={() => setShowDeleteConfirm(null)}
                                className="flex-1 py-3 border border-gray-200 text-gray-700 font-medium rounded-xl hover:bg-gray-50 transition-colors"
                            >
                                Batal
                            </button>
                            <button
                                onClick={() => handleDeleteUser(showDeleteConfirm)}
                                className="flex-1 py-3 bg-red-600 hover:bg-red-700 text-white font-medium rounded-xl transition-colors"
                            >
                                Ya, Hapus
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Add User Modal */}
            <AddUserModal
                isOpen={showAddModal}
                onClose={() => setShowAddModal(false)}
                onSubmit={handleCreateUser}
            />

            {/* Edit User Modal */}
            <EditUserModal
                isOpen={showEditModal}
                user={selectedUser}
                onClose={() => setShowEditModal(false)}
                onSubmit={handleUpdateUser}
            />

            {/* Reset Password Modal */}
            <ResetPasswordModal
                isOpen={showResetPasswordModal}
                user={selectedUser}
                onClose={() => setShowResetPasswordModal(false)}
                onSuccess={() => {
                    setSuccessMessage(`Password ${selectedUser?.name} berhasil direset!`);
                    setShowSuccess(true);
                    setTimeout(() => setShowSuccess(false), 4000);
                }}
                adminId={user?.id || ''}
            />

            {/* Sidebar */}
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Breadcrumb & Title */}
                    <div className="mb-6">
                        <Link
                            href="/dashboard/admin"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 mb-2"
                        >
                            <ArrowLeft className="w-4 h-4" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div>
                                <h1 className="text-2xl font-bold text-gray-800">User Management</h1>
                                <p className="text-gray-500">Kelola semua akun pengguna sistem</p>
                            </div>
                            <button
                                onClick={() => setShowAddModal(true)}
                                className="flex items-center gap-2 px-5 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-xl transition-colors shadow-lg shadow-emerald-500/30"
                            >
                                <Plus className="w-5 h-5" />
                                Tambah User Baru
                            </button>
                        </div>
                    </div>

                    {/* Stats Cards */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
                        <div className="bg-white rounded-xl p-4 border border-gray-100 shadow-sm">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-purple-100 rounded-lg flex items-center justify-center">
                                    <Users className="w-5 h-5 text-purple-600" />
                                </div>
                                <div>
                                    <p className="text-2xl font-bold text-gray-800">{users.length}</p>
                                    <p className="text-sm text-gray-500">Total Users</p>
                                </div>
                            </div>
                        </div>
                        <div className="bg-white rounded-xl p-4 border border-gray-100 shadow-sm">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-emerald-100 rounded-lg flex items-center justify-center">
                                    <UserCheck className="w-5 h-5 text-emerald-600" />
                                </div>
                                <div>
                                    <p className="text-2xl font-bold text-gray-800">{users.filter(u => u.is_active).length}</p>
                                    <p className="text-sm text-gray-500">Active</p>
                                </div>
                            </div>
                        </div>
                        <div className="bg-white rounded-xl p-4 border border-gray-100 shadow-sm">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-gray-100 rounded-lg flex items-center justify-center">
                                    <UserX className="w-5 h-5 text-gray-600" />
                                </div>
                                <div>
                                    <p className="text-2xl font-bold text-gray-800">{users.filter(u => !u.is_active).length}</p>
                                    <p className="text-sm text-gray-500">Inactive</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Filters & Actions */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm mb-6">
                        <div className="p-4 flex flex-col md:flex-row gap-4">
                            {/* Search */}
                            <div className="relative flex-1">
                                <Search className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                <input
                                    type="text"
                                    placeholder="Cari nama, email, atau telepon..."
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30 focus:border-purple-500"
                                />
                            </div>

                            {/* Role Filter */}
                            <select
                                value={filterRole}
                                onChange={(e) => setFilterRole(e.target.value as UserRole | 'all')}
                                className="px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30 focus:border-purple-500"
                            >
                                {ROLE_OPTIONS.map(role => (
                                    <option key={role.value} value={role.value}>{role.label}</option>
                                ))}
                            </select>

                            {/* Status Filter */}
                            <select
                                value={filterStatus}
                                onChange={(e) => setFilterStatus(e.target.value as 'all' | 'active' | 'inactive')}
                                className="px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30 focus:border-purple-500"
                            >
                                {STATUS_OPTIONS.map(status => (
                                    <option key={status.value} value={status.value}>{status.label}</option>
                                ))}
                            </select>

                            {/* Pesantren Filter */}
                            <select
                                value={filterPesantren}
                                onChange={(e) => setFilterPesantren(e.target.value)}
                                className="px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-purple-500/30 focus:border-purple-500"
                            >
                                <option value="all">Semua Pesantren</option>
                                {pesantrens.map(p => (
                                    <option key={p.id} value={p.id}>{p.name}</option>
                                ))}
                            </select>

                            {/* Refresh */}
                            <button
                                onClick={fetchUsers}
                                className="p-2.5 bg-gray-50 border border-gray-200 rounded-xl hover:bg-gray-100 transition-colors"
                            >
                                <RefreshCw className={`w-5 h-5 text-gray-600 ${isLoading ? 'animate-spin' : ''}`} />
                            </button>
                        </div>
                    </div>

                    {/* User Table */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead className="bg-gray-50 border-b border-gray-100">
                                    <tr>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">User</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Unit Pesantren</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Role</th>
                                        <th className="text-center p-4 text-sm font-semibold text-gray-600">Status</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Dibuat</th>
                                        <th className="text-center p-4 text-sm font-semibold text-gray-600">Aksi</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100">
                                    {filteredUsers.length === 0 ? (
                                        <tr>
                                            <td colSpan={6} className="p-12 text-center">
                                                <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                                                    <Users className="w-8 h-8 text-gray-400" />
                                                </div>
                                                <p className="font-medium text-gray-800 mb-1">Tidak ada user ditemukan</p>
                                                <p className="text-sm text-gray-500">Coba ubah filter pencarian Anda</p>
                                            </td>
                                        </tr>
                                    ) : (
                                        filteredUsers.map(u => {
                                            const roleColor = ROLE_COLORS[u.role as UserRole] || ROLE_COLORS.ustadz;
                                            return (
                                                <tr key={u.id} className="hover:bg-white/[0.02] transition-colors group">
                                                    <td className="p-4">
                                                        <div className="flex items-center gap-3">
                                                            <div className={`w-10 h-10 rounded-full flex items-center justify-center ${roleColor.bg}`}>
                                                                <span className={`font-medium ${roleColor.text}`}>{u.name.charAt(0)}</span>
                                                            </div>
                                                            <div>
                                                                <p className="font-medium text-gray-800">{u.name}</p>
                                                                <p className="text-sm text-gray-500">{u.email}</p>
                                                            </div>
                                                        </div>
                                                    </td>
                                                    <td className="p-4">
                                                        <div className="flex items-center gap-1.5 text-gray-600 px-3 py-1 bg-gray-50 rounded-lg w-fit border border-gray-100">
                                                            <Building2 className="w-3.5 h-3.5 text-purple-500" />
                                                            <span className="text-xs font-semibold">
                                                                {pesantrens.find(p => p.id === u.pesantren_id)?.name || 'Pusat'}
                                                            </span>
                                                        </div>
                                                        <div className="mt-1 flex items-center gap-1 text-gray-400 text-[11px]">
                                                            <Phone className="w-3 h-3" />
                                                            <span>{u.phone || '-'}</span>
                                                        </div>
                                                    </td>
                                                    <td className="p-4">
                                                        <div className="flex flex-wrap gap-1">
                                                            <span className={`px-3 py-1 rounded-full text-xs font-medium ${roleColor.bg} ${roleColor.text}`}>
                                                                {ROLE_NAMES[u.role as UserRole]}
                                                            </span>
                                                            {u.secondary_roles && u.secondary_roles.length > 0 && u.secondary_roles.map((sr: string) => (
                                                                <span key={sr} className="px-2 py-1 rounded-full text-xs font-medium bg-purple-100 text-purple-700 border border-purple-200">
                                                                    + {ROLE_NAMES[sr as UserRole] || sr}
                                                                </span>
                                                            ))}
                                                        </div>
                                                    </td>
                                                    <td className="p-4 text-center">
                                                        <button
                                                            onClick={() => handleToggleStatus(u.id)}
                                                            className={`px-3 py-1 rounded-full text-xs font-medium transition-colors ${u.is_active
                                                                ? 'bg-emerald-100 text-emerald-700 hover:bg-emerald-200'
                                                                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                                                                }`}
                                                        >
                                                            {u.is_active ? 'Active' : 'Inactive'}
                                                        </button>
                                                    </td>
                                                    <td className="p-4 text-gray-500 text-sm">
                                                        {new Date(u.created_at).toLocaleDateString('id-ID')}
                                                    </td>
                                                    <td className="p-4">
                                                        <div className="flex items-center justify-center gap-1">
                                                            <button
                                                                onClick={() => handleEditUser(u)}
                                                                disabled={u.role === 'super_admin'}
                                                                className={`p-2 rounded-lg transition-colors ${u.role === 'super_admin' ? 'text-gray-300 cursor-not-allowed' : 'hover:bg-purple-50 text-purple-600'}`}
                                                                title={u.role === 'super_admin' ? 'Super Admin tidak dapat diedit' : 'Edit User'}
                                                            >
                                                                <Edit className="w-4 h-4" />
                                                            </button>
                                                            <button
                                                                onClick={() => setShowDeleteConfirm(u.id)}
                                                                disabled={u.id === user?.id || u.role === 'super_admin'}
                                                                className={`p-2 rounded-lg transition-colors ${u.id === user?.id || u.role === 'super_admin' ? 'text-gray-300 cursor-not-allowed' : 'hover:bg-red-50 text-red-600'}`}
                                                                title={u.role === 'super_admin' ? 'Super Admin tidak dapat dihapus' : 'Hapus User'}
                                                            >
                                                                <Trash2 className="w-4 h-4" />
                                                            </button>
                                                            <button
                                                                onClick={() => {
                                                                    setSelectedUser(u);
                                                                    setShowResetPasswordModal(true);
                                                                }}
                                                                disabled={u.role === 'super_admin'}
                                                                className={`p-2 rounded-lg transition-colors ${u.role === 'super_admin' ? 'text-gray-300 cursor-not-allowed' : 'hover:bg-amber-50 text-amber-600'}`}
                                                                title="Reset Password"
                                                            >
                                                                <KeyRound className="w-4 h-4" />
                                                            </button>
                                                            <button
                                                                className="p-2 hover:bg-gray-100 rounded-lg text-gray-600 transition-colors"
                                                                title="More Options"
                                                            >
                                                                <MoreVertical className="w-4 h-4" />
                                                            </button>
                                                        </div>
                                                    </td>
                                                </tr>
                                            );
                                        })
                                    )}
                                </tbody>
                            </table>
                        </div>

                        {/* Pagination */}
                        <div className="p-4 border-t border-gray-100 flex flex-col md:flex-row items-center justify-between gap-4">
                            <p className="text-sm text-gray-500">
                                Menampilkan {filteredUsers.length} dari {users.length} users
                            </p>
                            <div className="flex items-center gap-2">
                                <button className="px-3 py-1.5 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50 disabled:opacity-50" disabled>
                                    Sebelumnya
                                </button>
                                <button className="px-3 py-1.5 bg-purple-600 text-white rounded-lg text-sm">
                                    1
                                </button>
                                <button className="px-3 py-1.5 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50 disabled:opacity-50" disabled>
                                    Selanjutnya
                                </button>
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import {
    Plus,
    Search,
    Edit,
    Trash2,
    CheckCircle2,
    XCircle,
    BookOpen,
    Loader2,
    RotateCcw,
    AlertTriangle,
    Calendar
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { hafalanTypesService, HafalanType } from '@/lib/services/hafalan-types';
import HafalanTypeModal from '@/components/hafalan/HafalanTypeModal';

const CATEGORY_CONFIG = {
    quran: { label: 'Al-Qur\'an', color: 'blue', icon: '­ƒôû' },
    doa: { label: 'Doa', color: 'green', icon: '­ƒñ▓' },
    mufrodat: { label: 'Mufrodat', color: 'purple', icon: '­ƒôØ' },
    hadits: { label: 'Hadits', color: 'amber', icon: '­ƒô£' },
    nadhom: { label: 'Nadhom', color: 'pink', icon: 'Ô£ì´©Å' },
    other: { label: 'Lainnya', color: 'gray', icon: '­ƒôÜ' }
};

export default function HafalanTypesPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);

    // Data state
    const [hafalanTypes, setHafalanTypes] = useState<HafalanType[]>([]);
    const [filteredTypes, setFilteredTypes] = useState<HafalanType[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    // Filter state
    const [searchQuery, setSearchQuery] = useState('');
    const [categoryFilter, setCategoryFilter] = useState<string>('all');
    const [statusFilter, setStatusFilter] = useState<string>('all');

    // Modal state
    const [showModal, setShowModal] = useState(false);
    const [editData, setEditData] = useState<HafalanType | null>(null);

    // Stats
    const [stats, setStats] = useState({
        total: 0,
        active: 0,
        inactive: 0,
        by_category: {} as Record<string, number>
    });

    const fetchHafalanTypes = async () => {
        try {
            setIsLoading(true);
            const [types, statistics] = await Promise.all([
                hafalanTypesService.getAllIncludingInactive(),
                hafalanTypesService.getStatistics()
            ]);
            setHafalanTypes(types);
            setStats(statistics);
        } catch (_error) {
            console.error('Error fetching hafalan types:', _error);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'admin_akademik') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchHafalanTypes();
        });
        return () => cancelAnimationFrame(timer);
    }, [router]);

    const applyFilters = () => {
        let filtered = [...hafalanTypes];

        // Search filter
        if (searchQuery) {
            filtered = filtered.filter(type =>
                type.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                type.description.toLowerCase().includes(searchQuery.toLowerCase())
            );
        }

        // Category filter
        if (categoryFilter !== 'all') {
            filtered = filtered.filter(type => type.category === categoryFilter);
        }

        // Status filter
        if (statusFilter === 'active') {
            filtered = filtered.filter(type => type.is_active);
        } else if (statusFilter === 'inactive') {
            filtered = filtered.filter(type => !type.is_active);
        }

        setFilteredTypes(filtered);
    };

    useEffect(() => {
        applyFilters();
    }, [hafalanTypes, searchQuery, categoryFilter, statusFilter]);

    const handleSave = async (data: Omit<HafalanType, 'id' | 'created_at' | 'updated_at'>) => {
        try {
            if (editData) {
                await hafalanTypesService.update(editData.id, data);
            } else {
                await hafalanTypesService.create(data);
            }
            await fetchHafalanTypes();
            setShowModal(false);
            setEditData(null);
        } catch (error: unknown) {
            throw error;
        }
    };

    const handleEdit = (type: HafalanType) => {
        setEditData(type);
        setShowModal(true);
    };

    const handleDelete = async (type: HafalanType) => {
        if (!confirm(`Yakin ingin menonaktifkan "${type.name}"?`)) return;

        try {
            await hafalanTypesService.delete(type.id);
            await fetchHafalanTypes();
        } catch (error: unknown) {
            const errorMsg = error instanceof Error ? error.message : 'Gagal menghapus hafalan type';
            alert(errorMsg);
        }
    };

    const handleReactivate = async (type: HafalanType) => {
        try {
            await hafalanTypesService.reactivate(type.id);
            await fetchHafalanTypes();
        } catch (error: unknown) {
            const errorMsg = error instanceof Error ? error.message : 'Gagal mengaktifkan kembali hafalan type';
            alert(errorMsg);
        }
    };

    const handleHardDelete = async (type: HafalanType) => {
        // Double confirmation for hard delete
        const firstConfirm = confirm(
            `PERINGATAN!\n\nAnda akan MENGHAPUS PERMANEN "${type.name}" dari database.\n\nData yang sudah dihapus TIDAK BISA dikembalikan!\n\nLanjutkan?`
        );

        if (!firstConfirm) return;

        const secondConfirm = confirm(
            `KONFIRMASI TERAKHIR!\n\nYakin ingin menghapus "${type.name}" PERMANEN?\n\nTindakan ini TIDAK BISA dibatalkan!`
        );

        if (!secondConfirm) return;

        try {
            await hafalanTypesService.hardDelete(type.id);
            await fetchHafalanTypes();
            alert('Hafalan type berhasil dihapus permanen dari database');
        } catch (error: unknown) {
            const errorMsg = error instanceof Error ? error.message : 'Gagal menghapus hafalan type';
            alert('ERROR: ' + errorMsg);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (!user) return null;

    return (
        <div className="min-h-screen bg-black flex">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Header */}
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
                        <div>
                            <h1 className="text-2xl font-bold text-white tracking-tight">
                                Master Hafalan Types
                            </h1>
                            <p className="text-gray-400">Kelola jenis-jenis hafalan yang tersedia di pesantren</p>
                        </div>
                        <button
                            onClick={() => {
                                setEditData(null);
                                setShowModal(true);
                            }}
                            className="flex items-center gap-2 px-6 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-xl transition-all shadow-lg shadow-emerald-900/20"
                        >
                            <Plus className="w-5 h-5" />
                            Tambah Hafalan Type
                        </button>
                    </div>

                    {/* Stats Cards */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                        {[
                            { label: 'Total Types', value: stats.total, icon: BookOpen, color: 'text-violet-400', bg: 'bg-violet-400/10' },
                            { label: 'Aktif', value: stats.active, icon: CheckCircle2, color: 'text-emerald-400', bg: 'bg-emerald-400/10' },
                            { label: 'Nonaktif', value: stats.inactive, icon: XCircle, color: 'text-rose-400', bg: 'bg-rose-400/10' },
                            { label: 'Kategori', value: Object.keys(stats.by_category).length, icon: Calendar, color: 'text-amber-400', bg: 'bg-amber-400/10' }
                        ].map((stat, i) => (
                            <div key={i} className="bg-gray-800/50 p-5 rounded-2xl border border-gray-700/50 backdrop-blur-sm">
                                <div className="flex items-center justify-between mb-3">
                                    <p className="text-sm font-medium text-gray-400">{stat.label}</p>
                                    <div className={`p-2 rounded-xl ${stat.bg}`}>
                                        <stat.icon className={`w-5 h-5 ${stat.color}`} />
                                    </div>
                                </div>
                                <p className="text-3xl font-bold text-white">{stat.value}</p>
                            </div>
                        ))}
                    </div>

                    {/* Filters */}
                    <div className="bg-gray-800/50 p-5 rounded-2xl border border-gray-700/50 mb-6 backdrop-blur-sm">
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            {/* Search */}
                            <div className="relative">
                                <Search className="w-5 h-5 text-gray-500 absolute left-4 top-1/2 -translate-y-1/2" />
                                <input
                                    type="text"
                                    placeholder="Cari nama hafalan..."
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    className="w-full pl-12 pr-4 py-3 bg-gray-900/50 border border-gray-700/50 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/50 text-white placeholder-gray-500"
                                />
                            </div>

                            {/* Category Filter */}
                            <select
                                value={categoryFilter}
                                onChange={(e) => setCategoryFilter(e.target.value)}
                                className="px-4 py-3 bg-gray-900/50 border border-gray-700/50 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/50 text-white"
                            >
                                <option value="all">Semua Kategori</option>
                                {Object.entries(CATEGORY_CONFIG).map(([key, config]) => (
                                    <option key={key} value={key} className="bg-gray-900">{config.icon} {config.label}</option>
                                ))}
                            </select>

                            {/* Status Filter */}
                            <select
                                value={statusFilter}
                                onChange={(e) => setStatusFilter(e.target.value)}
                                className="px-4 py-3 bg-gray-900/50 border border-gray-700/50 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/50 text-white"
                            >
                                <option value="all">Semua Status</option>
                                <option value="active" className="bg-gray-900">Aktif</option>
                                <option value="inactive" className="bg-gray-900">Nonaktif</option>
                            </select>
                        </div>
                    </div>

                    {/* Hafalan Types List */}
                    <div className="space-y-4">
                        {isLoading ? (
                            <div className="bg-gray-800/50 p-12 rounded-2xl border border-gray-700/50 text-center">
                                <Loader2 className="w-8 h-8 text-emerald-500 animate-spin mx-auto mb-3" />
                                <p className="text-gray-400">Memuat data...</p>
                            </div>
                        ) : filteredTypes.length === 0 ? (
                            <div className="bg-gray-800/50 p-12 rounded-2xl border border-gray-700/50 text-center">
                                <p className="text-gray-500 italic">Tidak ada data hafalan type</p>
                            </div>
                        ) : (
                            filteredTypes.map((type) => {
                                const config = CATEGORY_CONFIG[type.category as keyof typeof CATEGORY_CONFIG];
                                return (
                                    <div
                                        key={type.id}
                                        className="group bg-gray-800/30 p-6 rounded-2xl border border-gray-700/30 hover:bg-gray-800/50 hover:border-gray-700/50 transition-all backdrop-blur-sm"
                                    >
                                        <div className="flex items-start justify-between">
                                            <div className="flex-1">
                                                <div className="flex items-center gap-4 mb-2">
                                                    <div className="text-3xl w-12 h-12 bg-gray-900/50 rounded-xl flex items-center justify-center border border-gray-700/50">
                                                        {config.icon}
                                                    </div>
                                                    <div>
                                                        <h3 className="text-lg font-bold text-white">{type.name}</h3>
                                                        <div className="flex flex-wrap items-center gap-2 mt-1">
                                                            <span className={`px-2 py-0.5 rounded-lg text-xs font-bold bg-${config.color}-500/10 text-${config.color}-400 border border-${config.color}-500/20`}>
                                                                {config.label}
                                                            </span>
                                                            <span className="text-sm text-gray-500">
                                                                {type.total_units} {type.unit_name}
                                                            </span>
                                                            {type.is_active ? (
                                                                <span className="px-2 py-0.5 rounded-lg text-xs font-bold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                                                                    Aktif
                                                                </span>
                                                            ) : (
                                                                <span className="px-2 py-0.5 rounded-lg text-xs font-bold bg-rose-500/10 text-rose-400 border border-rose-500/20">
                                                                    Nonaktif
                                                                </span>
                                                            )}
                                                        </div>
                                                    </div>
                                                </div>
                                                {type.description && (
                                                    <p className="text-sm text-gray-400 mt-2 ml-16 max-w-2xl">{type.description}</p>
                                                )}
                                            </div>

                                            <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button
                                                    onClick={() => handleEdit(type)}
                                                    className="p-2.5 bg-violet-500/10 hover:bg-violet-500/20 text-violet-400 rounded-xl transition-all border border-violet-500/20"
                                                    title="Edit"
                                                >
                                                    <Edit className="w-4 h-4" />
                                                </button>
                                                {type.is_active ? (
                                                    <button
                                                        onClick={() => handleDelete(type)}
                                                        className="p-2.5 bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 rounded-xl transition-all border border-rose-500/20"
                                                        title="Nonaktifkan"
                                                    >
                                                        <Trash2 className="w-4 h-4" />
                                                    </button>
                                                ) : (
                                                    <>
                                                        <button
                                                            onClick={() => handleReactivate(type)}
                                                            className="p-2.5 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 rounded-xl transition-all border border-emerald-500/20"
                                                            title="Aktifkan Kembali"
                                                        >
                                                            <RotateCcw className="w-4 h-4" />
                                                        </button>
                                                        <button
                                                            onClick={() => handleHardDelete(type)}
                                                            className="p-2.5 bg-rose-500/10 hover:bg-rose-500/20 text-rose-400 rounded-xl transition-all border border-rose-500/20"
                                                            title="Hapus Permanen"
                                                        >
                                                            <AlertTriangle className="w-4 h-4" />
                                                        </button>
                                                    </>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                );
                            })
                        )}
                    </div>
                </main>
            </div>

            {/* Modal */}
            <HafalanTypeModal
                isOpen={showModal}
                onClose={() => {
                    setShowModal(false);
                    setEditData(null);
                }}
                onSave={handleSave}
                editData={editData}
            />
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Users,
    Search,
    Loader2,
    UserPlus,
    UserMinus,
    GraduationCap,
    ChevronRight,
    Filter
} from 'lucide-react';
import { classesService, ClassWithRelations } from '@/lib/services/classes';
import { studentsService } from '@/lib/services/students';

interface Student {
    id: string;
    name: string;
    nis: string;
    class_id: string | null;
    gender: 'L' | 'P';
}

export default function AnggotaKelasPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [classes, setClasses] = useState<ClassWithRelations[]>([]);
    const [students, setStudents] = useState<Student[]>([]);
    const [selectedClass, setSelectedClass] = useState<string | null>(null);
    const [searchQuery, setSearchQuery] = useState('');

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || !['super_admin', 'admin_akademik'].includes(currentUser.role)) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData();
    }, [router]);

    const fetchData = async () => {
        try {
            setIsLoading(true);
            const [classesData, studentsData] = await Promise.all([
                classesService.getAll(),
                studentsService.getAll()
            ]);
            setClasses(classesData);
            setStudents(studentsData as unknown as Student[]);
            if (classesData.length > 0) {
                setSelectedClass(classesData[0].id);
            }
        } catch (error) {
            console.error('Error fetching data:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const getClassName = (classId: string | null) => {
        if (!classId) return 'Belum ada kelas';
        const cls = classes.find(c => c.id === classId);
        return cls?.name || 'Unknown';
    };

    const studentsInClass = students.filter(s => s.class_id === selectedClass);
    const studentsWithoutClass = students.filter(s => !s.class_id);

    const filteredStudents = studentsInClass.filter(
        s => s.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            s.nis.includes(searchQuery)
    );

    const selectedClassData = classes.find(c => c.id === selectedClass);

    if (!user) return null;

    return (
        <div className="min-h-screen bg-black flex">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader
                    user={user}
                    onMenuClick={() => setSidebarOpen(true)}
                />

                <main className="p-4 lg:p-6">
                    {/* Back Button */}
                    <Link
                        href="/dashboard/akademik/kelas"
                        className="inline-flex items-center gap-2 text-gray-400 hover:text-white mb-6 transition-colors"
                    >
                        <ArrowLeft className="w-4 h-4" />
                        Kembali ke Manajemen Kelas
                    </Link>

                    {/* Header */}
                    <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
                        <div>
                            <h1 className="text-2xl font-bold text-white">Anggota Kelas</h1>
                            <p className="text-gray-400">Kelola daftar santri per kelas</p>
                        </div>
                    </div>

                    {isLoading ? (
                        <div className="flex items-center justify-center py-20">
                            <Loader2 className="w-8 h-8 text-emerald-500 animate-spin" />
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                            {/* Class List Sidebar */}
                            <div className="lg:col-span-1 bg-gray-800/50 rounded-2xl border border-gray-700/50 p-4 h-fit">
                                <h3 className="font-semibold text-white mb-4">Pilih Kelas</h3>
                                <div className="space-y-2">
                                    {classes.map(cls => {
                                        const count = students.filter(s => s.class_id === cls.id).length;
                                        return (
                                            <button
                                                key={cls.id}
                                                onClick={() => setSelectedClass(cls.id)}
                                                className={`w-full flex items-center justify-between p-3 rounded-xl transition-all ${selectedClass === cls.id
                                                    ? 'bg-emerald-500/20 border border-emerald-500/50 text-emerald-400'
                                                    : 'bg-gray-700/30 hover:bg-gray-700/50 text-gray-300 border border-transparent'
                                                    }`}
                                            >
                                                <div className="flex items-center gap-3">
                                                    <GraduationCap className="w-4 h-4" />
                                                    <span>{cls.name}</span>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    <span className="text-xs bg-gray-600/50 px-2 py-0.5 rounded-full">
                                                        {count}
                                                    </span>
                                                    <ChevronRight className="w-4 h-4" />
                                                </div>
                                            </button>
                                        );
                                    })}

                                    {/* Unassigned Students */}
                                    <button
                                        onClick={() => setSelectedClass(null)}
                                        className={`w-full flex items-center justify-between p-3 rounded-xl transition-all ${selectedClass === null
                                            ? 'bg-orange-500/20 border border-orange-500/50 text-orange-400'
                                            : 'bg-gray-700/30 hover:bg-gray-700/50 text-gray-300 border border-transparent'
                                            }`}
                                    >
                                        <div className="flex items-center gap-3">
                                            <UserMinus className="w-4 h-4" />
                                            <span>Belum Terdaftar</span>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <span className="text-xs bg-orange-600/30 px-2 py-0.5 rounded-full">
                                                {studentsWithoutClass.length}
                                            </span>
                                            <ChevronRight className="w-4 h-4" />
                                        </div>
                                    </button>
                                </div>
                            </div>

                            {/* Students List */}
                            <div className="lg:col-span-3 bg-gray-800/50 rounded-2xl border border-gray-700/50 overflow-hidden">
                                {/* Header */}
                                <div className="p-4 border-b border-gray-700/50 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                                    <div>
                                        <h3 className="font-semibold text-white">
                                            {selectedClass === null
                                                ? 'Santri Belum Terdaftar di Kelas'
                                                : `Anggota ${selectedClassData?.name || 'Kelas'}`}
                                        </h3>
                                        <p className="text-sm text-gray-400">
                                            {selectedClass === null
                                                ? `${studentsWithoutClass.length} santri`
                                                : `${studentsInClass.length} santri`}
                                        </p>
                                    </div>

                                    {/* Search */}
                                    <div className="relative">
                                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                        <input
                                            type="text"
                                            value={searchQuery}
                                            onChange={(e) => setSearchQuery(e.target.value)}
                                            placeholder="Cari nama/NIS..."
                                            className="pl-9 pr-4 py-2 bg-gray-700/50 border border-gray-600 rounded-lg text-white text-sm placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-emerald-500/50"
                                        />
                                    </div>
                                </div>

                                {/* Table */}
                                {(selectedClass === null ? studentsWithoutClass : filteredStudents).length === 0 ? (
                                    <div className="p-12 text-center">
                                        <Users className="w-12 h-12 text-gray-600 mx-auto mb-4" />
                                        <p className="text-gray-400">Tidak ada santri di kelas ini</p>
                                    </div>
                                ) : (
                                    <table className="w-full">
                                        <thead>
                                            <tr className="border-b border-gray-700/50">
                                                <th className="text-left p-4 text-gray-400 font-medium">NIS</th>
                                                <th className="text-left p-4 text-gray-400 font-medium">Nama</th>
                                                <th className="text-left p-4 text-gray-400 font-medium">JK</th>
                                                {selectedClass === null && (
                                                    <th className="text-left p-4 text-gray-400 font-medium">Aksi</th>
                                                )}
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {(selectedClass === null ? studentsWithoutClass : filteredStudents).map((student) => (
                                                <tr key={student.id} className="border-b border-gray-700/30 hover:bg-gray-700/20">
                                                    <td className="p-4 text-gray-300 font-mono text-sm">{student.nis}</td>
                                                    <td className="p-4 text-white">{student.name}</td>
                                                    <td className="p-4">
                                                        <span className={`px-2 py-1 rounded text-xs font-medium ${student.gender === 'L'
                                                            ? 'bg-blue-500/20 text-blue-400'
                                                            : 'bg-pink-500/20 text-pink-400'
                                                            }`}>
                                                            {student.gender === 'L' ? 'Laki-laki' : 'Perempuan'}
                                                        </span>
                                                    </td>
                                                    {selectedClass === null && (
                                                        <td className="p-4">
                                                            <button className="px-3 py-1.5 bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-400 rounded-lg text-sm font-medium transition-colors flex items-center gap-1">
                                                                <UserPlus className="w-4 h-4" />
                                                                Masukkan ke Kelas
                                                            </button>
                                                        </td>
                                                    )}
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                )}
                            </div>
                        </div>
                    )}
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Plus,
    Search,
    Edit,
    Trash2,
    CheckCircle2,
    GraduationCap,
    X
} from 'lucide-react';

import { classesService, ClassWithRelations } from '@/lib/services/classes';
import { ClassInsert, ClassUpdate } from '@/types/database.types';
import { Loader2 } from 'lucide-react';
import ClassModal from '@/components/admin/ClassModal';

export default function ManajemenKelasPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [filterLevel, setFilterLevel] = useState('Semua');
    const [classes, setClasses] = useState<ClassWithRelations[]>([]);
    const [studentCounts, setStudentCounts] = useState<Record<string, number>>({});
    const [isLoading, setIsLoading] = useState(true);

    // Modal state
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedClass, setSelectedClass] = useState<ClassWithRelations | null>(null);

    // Promote State
    const [isPromoteModalOpen, setIsPromoteModalOpen] = useState(false);
    const [promoteFrom, setPromoteFrom] = useState('');
    const [promoteTo, setPromoteTo] = useState('');
    const [isPromoting, setIsPromoting] = useState(false);

    const fetchData = async () => {
        try {
            setIsLoading(true);
            const [classesData, counts] = await Promise.all([
                classesService.getAll(),
                classesService.getStudentCounts()
            ]);
            setClasses(classesData);
            setStudentCounts(counts);
            setIsLoading(false);
        } catch (error: unknown) {
            console.error('Error fetching classes:', error);
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_akademik' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchData();
        });
        return () => cancelAnimationFrame(timer);
    }, [router]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleOpenAddModal = () => {
        setSelectedClass(null);
        setIsModalOpen(true);
    };

    const handleOpenEditModal = (cls: ClassWithRelations) => {
        setSelectedClass(cls);
        setIsModalOpen(true);
    };

    const handleSubmitClass = async (data: ClassInsert | ClassUpdate) => {
        try {
            if (selectedClass) {
                await classesService.update(selectedClass.id, data);
            } else {
                await classesService.create(data as ClassInsert);
            }
            fetchData();
        } catch (error: unknown) {
            console.error('Error saving class:', error);
            throw error;
        }
    };

    const handlePromote = async () => {
        if (!promoteFrom || !promoteTo) {
            alert('Mohon pilih kelas asal dan tujuan!');
            return;
        }
        if (promoteFrom === promoteTo) {
            alert('Kelas asal dan tujuan tidak boleh sama!');
            return;
        }

        if (!confirm('Anda yakin ingin memindahkan SELURUH siswa dari kelas asal ke kelas tujuan? Tindakan ini tidak dapat dibatalkan dengan mudah.')) return;

        setIsPromoting(true);
        try {
            const res = await classesService.promoteStudents(promoteFrom, promoteTo);
            alert(`Berhasil memindahkan ${res.moved_count} siswa!`);
            setIsPromoteModalOpen(false);
            setPromoteFrom('');
            setPromoteTo('');
            fetchData();
        } catch (error) {
            console.error(error);
            alert('Gagal melakukan kenaikan kelas.');
        } finally {
            setIsPromoting(false);
        }
    };

    const handleDeleteClass = async (id: string) => {
        if (confirm('Apakah Anda yakin ingin menghapus kelas ini? Semua data terkait (jadwal, dsb) mungkin akan hilang.')) {
            try {
                await classesService.delete(id);
                fetchData();
            } catch (_error) {
                alert('Gagal menghapus kelas. Pastikan tidak ada data santri yang terhubung.');
            }
        }
    };

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-blue-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
                    <span>Loading Data Kelas...</span>
                </div>
            </div>
        );
    }

    const filteredClasses = classes.filter(cls => {
        const matchesSearch = cls.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            (cls.homeroom_teacher?.name.toLowerCase().includes(searchQuery.toLowerCase()));

        const isTsanawiyah = cls.grade_level >= 7 && cls.grade_level <= 9;
        const isAliyah = cls.grade_level >= 10 && cls.grade_level <= 12;

        const matchesLevel = filterLevel === 'Semua' ||
            (filterLevel === 'Tsanawiyah' && isTsanawiyah) ||
            (filterLevel === 'Aliyah' && isAliyah);

        return matchesSearch && matchesLevel;
    });

    return (
        <div className="min-h-screen bg-[#050505] flex">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Header */}
                    <div className="mb-10">
                        <Link
                            href="/dashboard/akademik"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-white mb-6 transition-colors group"
                        >
                            <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-1" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                            <div>
                                <h1 className="text-3xl font-black text-white tracking-tight flex items-center gap-3">
                                    <span className="w-2 h-8 bg-blue-600 rounded-full block"></span>
                                    Data Kelas & Rombel
                                </h1>
                                <p className="text-gray-400 mt-1">
                                    Kelola rombongan belajar dan penugasan wali kelas
                                </p>
                            </div>
                            <div className="flex flex-wrap gap-3">
                                <button
                                    onClick={() => setIsPromoteModalOpen(true)}
                                    className="flex items-center gap-2 px-6 py-3.5 bg-indigo-600/10 hover:bg-indigo-600 text-indigo-400 hover:text-white border border-indigo-500/20 rounded-2xl font-bold transition-all shadow-lg active:scale-95"
                                >
                                    <GraduationCap className="w-5 h-5" />
                                    Kenaikan Kelas
                                </button>
                                <button
                                    onClick={handleOpenAddModal}
                                    className="flex items-center gap-2 px-6 py-3.5 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-bold transition-all shadow-lg shadow-blue-500/20 active:scale-95"
                                >
                                    <Plus className="w-5 h-5" />
                                    Tambah Kelas
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Promote Modal */}
                    {isPromoteModalOpen && (
                        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
                            <div className="bg-neutral-900 w-full max-w-lg rounded-[2.5rem] shadow-2xl border border-white/10 overflow-hidden animate-in zoom-in-95 duration-300 p-8">
                                <div className="flex justify-between items-center mb-6">
                                    <h2 className="text-xl font-black text-white flex items-center gap-3">
                                        <GraduationCap className="w-6 h-6 text-indigo-500" />
                                        Batch Kenaikan Kelas
                                    </h2>
                                    <button
                                        onClick={() => setIsPromoteModalOpen(false)}
                                        className="p-2 hover:bg-white/5 rounded-full transition-colors"
                                    >
                                        <X className="w-5 h-5 text-gray-500" />
                                    </button>
                                </div>
                                <div className="p-4 bg-indigo-500/5 border border-indigo-500/20 rounded-2xl mb-8">
                                    <p className="text-sm text-indigo-300 font-medium leading-relaxed">
                                        Pindahkan seluruh siswa secara massal. Pastikan kapasitas kelas tujuan mencukupi sebelum memproses.
                                    </p>
                                </div>

                                <div className="space-y-6">
                                    <div className="space-y-2">
                                        <label className="block text-xs font-black text-gray-500 uppercase tracking-widest ml-1">Dari Kelas (Sumber)</label>
                                        <select
                                            value={promoteFrom}
                                            onChange={(e) => setPromoteFrom(e.target.value)}
                                            className="w-full px-5 py-4 bg-black/40 border border-white/5 rounded-2xl text-white font-bold appearance-none focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all"
                                        >
                                            <option value="" className="bg-neutral-900">-- Pilih Kelas Asal --</option>
                                            {classes.map(c => (
                                                <option key={c.id} value={c.id} className="bg-neutral-900">{c.name} (Santri: {studentCounts[c.id] || 0})</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div className="flex justify-center relative -my-4 z-10">
                                        <div className="w-10 h-10 bg-indigo-600 rounded-full flex items-center justify-center shadow-lg border-4 border-neutral-900">
                                            <ArrowLeft className="w-5 h-5 rotate-[-90deg] text-white" />
                                        </div>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="block text-xs font-black text-gray-500 uppercase tracking-widest ml-1">Ke Kelas (Tujuan)</label>
                                        <select
                                            value={promoteTo}
                                            onChange={(e) => setPromoteTo(e.target.value)}
                                            className="w-full px-5 py-4 bg-black/40 border border-white/5 rounded-2xl text-white font-bold appearance-none focus:outline-none focus:ring-2 focus:ring-indigo-500/50 transition-all"
                                        >
                                            <option value="" className="bg-neutral-900">-- Pilih Kelas Tujuan --</option>
                                            {classes.map(c => (
                                                <option key={c.id} value={c.id} className="bg-neutral-900">{c.name} (Kapasitas: {c.capacity})</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>

                                <div className="pt-8 flex gap-4">
                                    <button
                                        onClick={() => setIsPromoteModalOpen(false)}
                                        className="flex-1 py-4 bg-neutral-800 hover:bg-neutral-700 text-gray-400 font-bold rounded-2xl transition-all"
                                    >
                                        Batal
                                    </button>
                                    <button
                                        onClick={handlePromote}
                                        disabled={isPromoting}
                                        className="flex-[2] py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-black rounded-2xl flex items-center justify-center gap-2 shadow-lg shadow-indigo-500/20 active:scale-95 transition-all disabled:opacity-50"
                                    >
                                        {isPromoting ? <Loader2 className="animate-spin" /> : <CheckCircle2 className="w-5 h-5" />}
                                        Proses Kenaikan
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Modal */}
                    <ClassModal
                        isOpen={isModalOpen}
                        onClose={() => setIsModalOpen(false)}
                        onSubmit={handleSubmitClass}
                        classData={selectedClass}
                    />

                    {/* Filters & Stats */}
                    <div className="flex flex-col lg:flex-row gap-6 mb-8">
                        <div className="flex-1 relative">
                            <Search className="w-6 h-6 text-gray-600 absolute left-4 top-1/2 -translate-y-1/2" />
                            <input
                                type="text"
                                placeholder="Cari nama kelas atau wali kelas..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="w-full pl-12 pr-6 py-4 bg-neutral-900/40 border border-white/5 rounded-[1.5rem] text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all backdrop-blur-sm"
                            />
                        </div>
                        <div className="flex gap-4">
                            <div className="bg-neutral-900/40 border border-white/5 rounded-[1.5rem] p-1 flex items-center backdrop-blur-sm">
                                {['Semua', 'Tsanawiyah', 'Aliyah'].map((level) => (
                                    <button
                                        key={level}
                                        onClick={() => setFilterLevel(level)}
                                        className={`px-6 py-2.5 rounded-2xl text-sm font-bold transition-all ${filterLevel === level
                                            ? 'bg-blue-600 text-white shadow-lg'
                                            : 'text-gray-500 hover:text-white'
                                            }`}
                                    >
                                        {level}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Classes Grid - Better for 3D UI than just a table */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {filteredClasses.map((cls) => {
                            const isTsanawiyah = cls.grade_level >= 7 && cls.grade_level <= 9;
                            const currentTotal = studentCounts[cls.id] || 0;
                            const capacity = cls.capacity || 30;
                            const fillPercent = Math.min((currentTotal / capacity) * 100, 100);

                            return (
                                <div
                                    key={cls.id}
                                    className="group relative bg-neutral-900/60 border border-white/5 rounded-[2.5rem] overflow-hidden transition-all duration-300 hover:shadow-[0_20px_50px_rgba(37,99,235,0.1)] hover:-translate-y-1"
                                >
                                    {/* 3D Glass Effect Overlay */}
                                    <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-tr from-white/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"></div>

                                    <div className="p-7">
                                        <div className="flex items-start justify-between mb-6">
                                            <div className="flex items-center gap-4">
                                                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl shadow-lg border transition-transform group-hover:scale-110 duration-500 ${isTsanawiyah
                                                    ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400'
                                                    : 'bg-purple-500/10 border-purple-500/20 text-purple-400'
                                                    }`}>
                                                    {cls.grade_level}
                                                </div>
                                                <div>
                                                    <h3 className="text-xl font-black text-white tracking-tight">{cls.name}</h3>
                                                    <div className="flex items-center gap-2 mt-0.5">
                                                        <span className={`text-[10px] font-black uppercase tracking-widest px-2 py-0.5 rounded-md ${isTsanawiyah ? 'bg-emerald-500/20 text-emerald-400' : 'bg-purple-500/20 text-purple-400'
                                                            }`}>
                                                            {isTsanawiyah ? 'Tsanawiyah' : 'Aliyah'}
                                                        </span>
                                                        <span className="w-1 h-1 bg-gray-700 rounded-full"></span>
                                                        <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">
                                                            TA {cls.academic_year?.name || '2025/2026'}
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-1.5 opacity-0 group-hover:opacity-100 transition-all">
                                                <button
                                                    onClick={() => handleOpenEditModal(cls)}
                                                    className="p-2.5 bg-neutral-800 hover:bg-blue-600 text-gray-400 hover:text-white rounded-xl border border-white/5 transition-all active:scale-95"
                                                >
                                                    <Edit className="w-4 h-4" />
                                                </button>
                                                <button
                                                    onClick={() => handleDeleteClass(cls.id)}
                                                    className="p-2.5 bg-neutral-800 hover:bg-rose-600 text-gray-400 hover:text-white rounded-xl border border-white/5 transition-all active:scale-95"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </button>
                                            </div>
                                        </div>

                                        <div className="space-y-5">
                                            {/* Homeroom Teacher */}
                                            <div className="bg-black/40 border border-white/5 rounded-2xl p-4 flex items-center gap-3">
                                                <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center font-black text-white text-[10px] shadow-lg border border-white/10 shrink-0">
                                                    {cls.homeroom_teacher?.name ? cls.homeroom_teacher.name.split(' ').map(n => n[0]).slice(0, 2).join('') : '??'}
                                                </div>
                                                <div className="min-w-0">
                                                    <p className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Wali Kelas</p>
                                                    <p className="text-sm font-bold text-gray-300 truncate">
                                                        {cls.homeroom_teacher?.name || 'Belum ditugaskan'}
                                                    </p>
                                                </div>
                                            </div>

                                            {/* Capacity Progress */}
                                            <div className="space-y-2 px-1">
                                                <div className="flex justify-between items-end">
                                                    <p className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Kapasitas Kelas</p>
                                                    <p className="text-sm font-black text-white">
                                                        {currentTotal}
                                                        <span className="text-gray-600 font-bold ml-1">/ {capacity}</span>
                                                    </p>
                                                </div>
                                                <div className="h-2 bg-black/60 rounded-full overflow-hidden p-0.5 border border-white/5">
                                                    <div
                                                        className={`h-full rounded-full transition-all duration-1000 ${currentTotal >= capacity ? 'bg-rose-500' : currentTotal >= capacity * 0.8 ? 'bg-amber-500' : 'bg-blue-500'
                                                            }`}
                                                        style={{ width: `${fillPercent}%` }}
                                                    />
                                                </div>
                                            </div>
                                        </div>

                                        <div className="mt-6 pt-5 border-t border-white/5 flex items-center justify-between">
                                            <div className="flex items-center gap-1.5 text-emerald-400">
                                                <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.8)]"></div>
                                                <span className="text-[10px] font-black uppercase tracking-widest">Status Aktif</span>
                                            </div>
                                            <Link
                                                href={`/dashboard/akademik/kelas/anggota?id=${cls.id}`}
                                                className="text-[10px] font-black text-blue-500 uppercase tracking-widest hover:text-blue-400 transition-colors"
                                            >
                                                Lihat Santri ÔåÆ
                                            </Link>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>

                    {filteredClasses.length === 0 && (
                        <div className="flex flex-col items-center justify-center py-20 bg-neutral-900/40 border border-white/5 rounded-[2.5rem]">
                            <div className="w-20 h-20 bg-neutral-800 rounded-2xl flex items-center justify-center mb-6 border border-white/5 shadow-inner">
                                <Search className="w-10 h-10 text-gray-600" />
                            </div>
                            <h3 className="text-xl font-bold text-white mb-2">Data tidak ditemukan</h3>
                            <p className="text-gray-500 max-w-xs text-center">
                                Coba kata kunci pencarian lain atau pilih filter jenjang yang berbeda.
                            </p>
                        </div>
                    )}
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Users,
    UserCheck,
    Search,
    Loader2,
    Save,
    X,
    ChevronDown,
    GraduationCap
} from 'lucide-react';
import { classesService, ClassWithRelations } from '@/lib/services/classes';
import { teachersService } from '@/lib/services/teachers';

interface Teacher {
    id: string;
    name: string;
    user_id?: string | null;
}

export default function WaliKelasPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [classes, setClasses] = useState<ClassWithRelations[]>([]);
    const [teachers, setTeachers] = useState<Teacher[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [isSaving, setIsSaving] = useState<string | null>(null);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || !['super_admin', 'admin_akademik'].includes(currentUser.role)) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData();
    }, [router]);

    const fetchData = async () => {
        try {
            setIsLoading(true);
            const [classesData, teachersData] = await Promise.all([
                classesService.getAll(),
                teachersService.getAll()
            ]);
            setClasses(classesData);
            setTeachers(teachersData);
        } catch (error) {
            console.error('Error fetching data:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleAssignWali = async (classId: string, teacherId: string | null) => {
        setIsSaving(classId);
        try {
            await classesService.update(classId, { homeroom_teacher_id: teacherId });
            // Update local state
            setClasses(prev => prev.map(c =>
                c.id === classId ? { ...c, homeroom_teacher_id: teacherId } : c
            ));
        } catch (error) {
            console.error('Error assigning homeroom teacher:', error);
            alert('Gagal menyimpan wali kelas');
        } finally {
            setIsSaving(null);
        }
    };

    const filteredClasses = classes.filter(c =>
        c.name.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const getTeacherName = (teacherId: string | null | undefined) => {
        if (!teacherId) return null;
        const teacher = teachers.find(t => t.id === teacherId);
        return teacher?.name || null;
    };

    // Check if teacher is already assigned to another class
    const isTeacherAssigned = (teacherId: string, excludeClassId: string) => {
        return classes.some(c => c.homeroom_teacher_id === teacherId && c.id !== excludeClassId);
    };

    if (!user) return null;

    return (
        <div className="min-h-screen bg-black flex">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader
                    user={user}
                    onMenuClick={() => setSidebarOpen(true)}
                />

                <main className="p-4 lg:p-6">
                    {/* Back Button */}
                    <Link
                        href="/dashboard/akademik/kelas"
                        className="inline-flex items-center gap-2 text-gray-400 hover:text-white mb-6 transition-colors"
                    >
                        <ArrowLeft className="w-4 h-4" />
                        Kembali ke Manajemen Kelas
                    </Link>

                    {/* Header */}
                    <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
                        <div>
                            <h1 className="text-2xl font-bold text-white">Penugasan Wali Kelas</h1>
                            <p className="text-gray-400">Tentukan guru yang menjadi wali untuk setiap kelas</p>
                        </div>
                    </div>

                    {/* Search */}
                    <div className="relative mb-6 max-w-md">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                        <input
                            type="text"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            placeholder="Cari kelas..."
                            className="w-full pl-10 pr-4 py-3 bg-gray-800/50 border border-gray-700/50 rounded-xl text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-emerald-500/50"
                        />
                    </div>

                    {/* Content */}
                    {isLoading ? (
                        <div className="flex items-center justify-center py-20">
                            <Loader2 className="w-8 h-8 text-emerald-500 animate-spin" />
                        </div>
                    ) : filteredClasses.length === 0 ? (
                        <div className="bg-gray-800/50 rounded-2xl border border-gray-700/50 p-12 text-center">
                            <GraduationCap className="w-16 h-16 text-gray-600 mx-auto mb-4" />
                            <h3 className="text-lg font-medium text-white mb-2">Belum Ada Kelas</h3>
                            <p className="text-gray-400">Tambahkan kelas terlebih dahulu di menu Manajemen Kelas</p>
                        </div>
                    ) : (
                        <div className="bg-gray-800/50 rounded-2xl border border-gray-700/50 overflow-hidden">
                            <table className="w-full">
                                <thead>
                                    <tr className="border-b border-gray-700/50">
                                        <th className="text-left p-4 text-gray-400 font-medium">Kelas</th>
                                        <th className="text-left p-4 text-gray-400 font-medium">Tingkat</th>
                                        <th className="text-left p-4 text-gray-400 font-medium">Wali Kelas</th>
                                        <th className="text-left p-4 text-gray-400 font-medium w-80">Pilih Guru</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {filteredClasses.map((cls) => (
                                        <tr key={cls.id} className="border-b border-gray-700/30 hover:bg-gray-700/20">
                                            <td className="p-4">
                                                <div className="flex items-center gap-3">
                                                    <div className="w-10 h-10 bg-emerald-500/20 rounded-lg flex items-center justify-center">
                                                        <Users className="w-5 h-5 text-emerald-400" />
                                                    </div>
                                                    <span className="font-medium text-white">{cls.name}</span>
                                                </div>
                                            </td>
                                            <td className="p-4 text-gray-400">
                                                Kelas {cls.grade_level}
                                            </td>
                                            <td className="p-4">
                                                {getTeacherName(cls.homeroom_teacher_id) ? (
                                                    <span className="px-3 py-1 bg-emerald-500/20 text-emerald-400 rounded-full text-sm font-medium">
                                                        {getTeacherName(cls.homeroom_teacher_id)}
                                                    </span>
                                                ) : (
                                                    <span className="text-gray-500 italic">Belum ditentukan</span>
                                                )}
                                            </td>
                                            <td className="p-4">
                                                <div className="flex items-center gap-2">
                                                    <div className="relative flex-1">
                                                        <select
                                                            value={cls.homeroom_teacher_id || ''}
                                                            onChange={(e) => handleAssignWali(cls.id, e.target.value || null)}
                                                            disabled={isSaving === cls.id}
                                                            className="w-full px-3 py-2 bg-gray-700/50 border border-gray-600 rounded-lg text-white appearance-none focus:outline-none focus:ring-2 focus:ring-emerald-500/50 disabled:opacity-50"
                                                        >
                                                            <option value="">-- Pilih Guru --</option>
                                                            {teachers.map((teacher) => (
                                                                <option
                                                                    key={teacher.id}
                                                                    value={teacher.id}
                                                                    disabled={isTeacherAssigned(teacher.id, cls.id)}
                                                                >
                                                                    {teacher.name} {isTeacherAssigned(teacher.id, cls.id) ? '(Sudah jadi Wali Kelas)' : ''}
                                                                </option>
                                                            ))}
                                                        </select>
                                                        <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                                                    </div>
                                                    {isSaving === cls.id && (
                                                        <Loader2 className="w-5 h-5 text-emerald-500 animate-spin" />
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}

                    {/* Info */}
                    <div className="mt-6 p-4 bg-blue-500/10 border border-blue-500/30 rounded-xl">
                        <div className="flex items-start gap-3">
                            <UserCheck className="w-5 h-5 text-blue-400 mt-0.5" />
                            <div>
                                <h4 className="font-medium text-blue-300">Catatan Penting</h4>
                                <p className="text-sm text-blue-300/80 mt-1">
                                    Satu guru hanya dapat menjadi wali kelas untuk satu kelas saja.
                                    Guru yang sudah ditugaskan akan ditandai dan tidak dapat dipilih untuk kelas lain.
                                </p>
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState, useRef, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import {
    APP_SETTINGS,
    RaporConfig,
    saveSettings,
    getSemesterName,
    getStoredSettings
} from '@/lib/raporConfig';
import { raporSettingsService } from '@/lib/services/rapor-settings';
import { supabase } from '@/lib/supabase';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Save,
    Loader2,
    CheckCircle2,
    Building,
    User as UserIcon,
    CalendarDays,
    BookOpen,
    RotateCcw,
    Eye,
    Upload,
    ImageIcon,
    X
} from 'lucide-react';

export default function RaporSettingsPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Settings state - initialized with stored/default values
    const [settings, setSettings] = useState<RaporConfig>(APP_SETTINGS);

    // UI state
    const [isSaving, setIsSaving] = useState(false);
    const [isUploading, setIsUploading] = useState(false);
    const [showSuccess, setShowSuccess] = useState(false);
    const [showPreview, setShowPreview] = useState(false);
    const [isLoading, setIsLoading] = useState(true);

    const loadSettings = useCallback(async () => {
        setIsLoading(true);
        try {
            // Try to load from database first
            const dbSettings = await raporSettingsService.getSettings();
            if (dbSettings) {
                setSettings({
                    ...APP_SETTINGS,
                    yayasan_name: dbSettings.yayasan_name || APP_SETTINGS.yayasan_name,
                    school_name: dbSettings.school_name || APP_SETTINGS.school_name,
                    school_name_arabic: dbSettings.school_name_arabic || '',
                    address: dbSettings.address || '',
                    phone: dbSettings.phone || '',
                    email: dbSettings.email || '',
                    website: dbSettings.website || '',
                    logo_url: dbSettings.logo_url || '',
                    pengasuh_pondok_name: dbSettings.pengasuh_pondok_name || '',
                    pengasuh_pondok_nip: dbSettings.pengasuh_pondok_nip || '',
                    active_semester: dbSettings.active_semester || 1,
                    academic_year: dbSettings.academic_year || '2024/2025',
                    report_city: dbSettings.report_city || '',
                    city_date: ''
                });
            } else {
                // Fallback to localStorage
                const stored = getStoredSettings();
                setSettings(stored);
            }
        } catch (_e) {
            console.warn('Load from DB failed, using localStorage:', _e);
            const stored = getStoredSettings();
            setSettings(stored);
        }
        setIsLoading(false);
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_akademik' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            loadSettings();
        });
        return () => cancelAnimationFrame(timer);
    }, [router, loadSettings]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleSave = async () => {
        setIsSaving(true);

        try {
            // Save to database
            await raporSettingsService.updateSettings({
                yayasan_name: settings.yayasan_name,
                school_name: settings.school_name,
                school_name_arabic: settings.school_name_arabic,
                address: settings.address,
                phone: settings.phone,
                email: settings.email,
                website: settings.website,
                logo_url: settings.logo_url,
                pengasuh_pondok_name: settings.pengasuh_pondok_name || '',
                pengasuh_pondok_nip: settings.pengasuh_pondok_nip || '',
                active_semester: settings.active_semester,
                academic_year: settings.academic_year,
                report_city: settings.report_city
            });

            // Also save to localStorage for backup
            saveSettings(settings);

            setShowSuccess(true);
            setTimeout(() => setShowSuccess(false), 3000);
        } catch (error) {
            console.error('Save error:', error);
            // Fallback to localStorage only
            saveSettings(settings);
            setShowSuccess(true);
            setTimeout(() => setShowSuccess(false), 3000);
        }

        setIsSaving(false);
    };

    const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        // Validate file
        if (!file.type.startsWith('image/')) {
            alert('Hanya file gambar yang diperbolehkan!');
            return;
        }
        if (file.size > 2 * 1024 * 1024) {
            alert('Ukuran file maksimal 2MB!');
            return;
        }

        setIsUploading(true);
        try {
            const logoUrl = await raporSettingsService.uploadLogo(file);
            setSettings({ ...settings, logo_url: logoUrl });
            alert('Logo berhasil diupload!');
        } catch (error: unknown) {
            console.error('Upload error:', error);
            alert('Gagal mengupload logo: ' + (error instanceof Error ? error.message : 'Unknown error'));
        } finally {
            setIsUploading(false);
            if (fileInputRef.current) {
                fileInputRef.current.value = '';
            }
        }
    };

    const handleRemoveLogo = () => {
        if (confirm('Hapus logo?')) {
            setSettings({ ...settings, logo_url: '' });
        }
    };

    const handleReset = () => {
        if (confirm('Reset semua pengaturan ke default?')) {
            setSettings(APP_SETTINGS);
            localStorage.removeItem('rapor_settings');
        }
    };

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50">
                <div className="flex flex-col items-center gap-3">
                    <Loader2 className="w-8 h-8 text-blue-600 animate-spin" />
                    <span className="text-gray-500">Memuat pengaturan...</span>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-[#050505] flex">
            {/* Success Toast */}
            {showSuccess && (
                <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[100] bg-emerald-500/20 backdrop-blur-md border border-emerald-500/50 text-emerald-400 px-8 py-4 rounded-[2rem] shadow-2xl flex items-center gap-3 animate-in fade-in slide-in-from-top-4">
                    <div className="w-8 h-8 rounded-full bg-emerald-500/20 flex items-center justify-center border border-emerald-500/30">
                        <CheckCircle2 className="w-5 h-5 text-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.8)]" />
                    </div>
                    <span className="font-black uppercase tracking-widest text-xs">Konfigurasi Berhasil Disimpan</span>
                </div>
            )}

            {/* Sidebar */}
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Breadcrumb & Title */}
                    <div className="mb-10">
                        <Link
                            href="/dashboard/akademik"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-white mb-6 transition-colors group"
                        >
                            <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-1" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                            <div>
                                <h1 className="text-3xl font-black text-white tracking-tight flex items-center gap-3 uppercase">
                                    <span className="w-2 h-8 bg-blue-600 rounded-full block"></span>
                                    Konfigurasi Template Rapor
                                </h1>
                                <p className="text-gray-400 mt-1 font-medium">
                                    Pengaturan identitas lembaga, logo, and penandatangan berkas rapor.
                                </p>
                            </div>
                            <button
                                onClick={() => setShowPreview(!showPreview)}
                                className={`flex items-center gap-2 px-6 py-3.5 rounded-2xl font-black text-xs uppercase tracking-widest transition-all border ${showPreview
                                    ? 'bg-blue-600/10 border-blue-500/50 text-blue-400'
                                    : 'bg-neutral-900/40 border-white/5 text-gray-400 hover:text-white backdrop-blur-sm'
                                    }`}
                            >
                                <Eye className="w-5 h-5" />
                                {showPreview ? 'Tutup Preview' : 'Preview Kop Rapor'}
                            </button>
                        </div>
                    </div>

                    {/* Preview Section - Modern Glass Style */}
                    {showPreview && (
                        <div className="relative bg-white rounded-[2.5rem] p-12 mb-10 shadow-[0_20px_60px_rgba(255,255,255,0.05)] border border-white overflow-hidden animate-in zoom-in-95 duration-300">
                            <div className="absolute top-0 right-10 bg-blue-600 px-6 py-2 rounded-b-2xl font-black text-[10px] text-white uppercase tracking-[0.2em] shadow-lg shadow-blue-500/20">PREVIEW AKTIF</div>

                            <div style={{ fontFamily: "'Times New Roman', serif" }} className="text-black max-w-4xl mx-auto">
                                <div className="flex items-center gap-8 py-4">
                                    {settings.logo_url ? (
                                        <div className="w-24 h-24 flex items-center justify-center border-2 border-gray-100 rounded-3xl p-2 bg-white shadow-inner shrink-0 rotate-3 group-hover:rotate-0 transition-transform duration-500">
                                            <img src={settings.logo_url} alt="Logo" className="w-full h-full object-contain" />
                                        </div>
                                    ) : (
                                        <div className="w-24 h-24 bg-gray-50 border-2 border-dashed border-gray-200 rounded-3xl flex items-center justify-center text-gray-300 text-[10px] font-bold uppercase tracking-widest shrink-0">
                                            LOGO
                                        </div>
                                    )}
                                    <div className="flex-1 text-center">
                                        <p className="text-lg font-bold tracking-wide mb-1 uppercase leading-tight">{settings.yayasan_name}</p>
                                        <h2 className="text-3xl font-black tracking-wider uppercase mb-2 text-blue-900">{settings.school_name}</h2>
                                        <p className="text-sm font-medium italic text-gray-600 mb-1">{settings.address}</p>
                                        <p className="text-xs font-bold text-gray-500 uppercase tracking-tighter">Telp: {settings.phone} | Email: {settings.email}</p>
                                    </div>
                                    <div className="w-24 lg:block hidden"></div>
                                </div>
                                <div className="h-1 bg-black w-full mt-4"></div>
                                <div className="h-0.5 bg-black w-full mt-0.5"></div>
                            </div>
                        </div>
                    )}

                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                        {/* Institution Info - Left Column */}
                        <div className="bg-neutral-900/40 border border-white/5 rounded-[3rem] p-8 backdrop-blur-md shadow-2xl space-y-8">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-blue-600/10 rounded-2xl flex items-center justify-center border border-blue-500/20">
                                    <Building className="w-5 h-5 text-blue-500 shadow-[0_0_10px_rgba(37,99,235,0.4)]" />
                                </div>
                                <h3 className="font-black text-white text-lg tracking-tight uppercase">Identitas Lembaga</h3>
                            </div>

                            <div className="space-y-6">
                                <div className="grid grid-cols-1 gap-6">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-2">Nama Yayasan</label>
                                        <input
                                            type="text"
                                            placeholder="Yayasan Pendidikan Islam..."
                                            value={settings.yayasan_name}
                                            onChange={(e) => setSettings({ ...settings, yayasan_name: e.target.value })}
                                            className="w-full px-6 py-4 bg-black/40 border border-white/5 rounded-2xl text-white placeholder-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all font-bold"
                                        />
                                    </div>

                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-2">Nama Instansi</label>
                                        <input
                                            type="text"
                                            placeholder="Pondok Pesantren..."
                                            value={settings.school_name}
                                            onChange={(e) => setSettings({ ...settings, school_name: e.target.value })}
                                            className="w-full px-6 py-4 bg-black/40 border border-white/5 rounded-2xl text-white placeholder-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all font-bold"
                                        />
                                    </div>
                                </div>

                                <div className="space-y-2">
                                    <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-2">Alamat Operasional</label>
                                    <textarea
                                        rows={3}
                                        value={settings.address}
                                        onChange={(e) => setSettings({ ...settings, address: e.target.value })}
                                        className="w-full px-6 py-4 bg-black/40 border border-white/5 rounded-2xl text-white placeholder-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all font-bold resize-none"
                                    />
                                </div>

                                <div className="grid grid-cols-2 gap-6">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-2">Telepon</label>
                                        <input
                                            type="text"
                                            value={settings.phone}
                                            onChange={(e) => setSettings({ ...settings, phone: e.target.value })}
                                            className="w-full px-6 py-4 bg-black/40 border border-white/5 rounded-2xl text-white placeholder-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all font-bold text-sm"
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-2">Email Official</label>
                                        <input
                                            type="email"
                                            value={settings.email}
                                            onChange={(e) => setSettings({ ...settings, email: e.target.value })}
                                            className="w-full px-6 py-4 bg-black/40 border border-white/5 rounded-2xl text-white placeholder-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all font-bold text-sm"
                                        />
                                    </div>
                                </div>

                                {/* Logo Upload - 3D Card Style */}
                                <div className="pt-8 border-t border-white/5">
                                    <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-2 mb-4 block">Logo Header Rapor</label>
                                    <div className="bg-black/20 border border-white/5 rounded-[2rem] p-6 flex flex-col md:flex-row items-center gap-8">
                                        {settings.logo_url ? (
                                            <div className="relative group shrink-0">
                                                <div className="absolute -inset-2 bg-blue-500/20 rounded-3xl blur-xl opacity-0 group-hover:opacity-100 transition-opacity"></div>
                                                <img src={settings.logo_url} alt="Logo" className="relative w-28 h-28 object-contain bg-white rounded-[2rem] p-4 border border-white/10 shadow-2xl" />
                                                <button
                                                    onClick={handleRemoveLogo}
                                                    className="absolute -top-2 -right-2 w-8 h-8 bg-rose-600 text-white rounded-full flex items-center justify-center hover:bg-rose-500 active:scale-95 shadow-lg border border-white/20 z-10"
                                                >
                                                    <X className="w-5 h-5" />
                                                </button>
                                            </div>
                                        ) : (
                                            <div className="w-28 h-28 border-2 border-dashed border-white/10 rounded-[2rem] flex flex-col items-center justify-center bg-black/40 gap-2 overflow-hidden relative shrink-0">
                                                {isUploading ? (
                                                    <Loader2 className="w-8 h-8 text-blue-500 animate-spin" />
                                                ) : (
                                                    <>
                                                        <ImageIcon className="w-10 h-10 text-gray-700" />
                                                        <span className="text-[8px] font-black text-gray-700 uppercase tracking-widest">Tiada Logo</span>
                                                    </>
                                                )}
                                            </div>
                                        )}
                                        <div className="flex-1 space-y-4 w-full">
                                            <input
                                                ref={fileInputRef}
                                                type="file"
                                                accept="image/*"
                                                onChange={handleLogoUpload}
                                                className="hidden"
                                                id="logo-upload"
                                            />
                                            <label
                                                htmlFor="logo-upload"
                                                className={`flex items-center justify-center gap-3 px-6 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest cursor-pointer transition-all ${isUploading
                                                    ? 'bg-neutral-800 text-gray-500 cursor-not-allowed'
                                                    : 'bg-white text-black hover:bg-gray-200'
                                                    }`}
                                            >
                                                {isUploading ? (
                                                    <>
                                                        <Loader2 className="w-4 h-4 animate-spin" />
                                                        Processing...
                                                    </>
                                                ) : (
                                                    <>
                                                        <Upload className="w-5 h-5" />
                                                        Upload Berkas Logo
                                                    </>
                                                )}
                                            </label>
                                            <div className="relative">
                                                <div className="absolute inset-y-0 left-4 flex items-center pointer-events-none">
                                                    <BookOpen className="w-4 h-4 text-gray-700" />
                                                </div>
                                                <input
                                                    type="text"
                                                    placeholder="URL logo (opsional)..."
                                                    value={settings.logo_url}
                                                    onChange={(e) => setSettings({ ...settings, logo_url: e.target.value })}
                                                    className="w-full pl-12 pr-6 py-3 bg-black/40 border border-white/5 rounded-xl text-white placeholder-gray-700 focus:outline-none text-xs font-bold"
                                                />
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Right Column */}
                        <div className="space-y-8">
                            {/* Signatories */}
                            <div className="bg-neutral-900/40 border border-white/5 rounded-[3rem] p-8 backdrop-blur-md shadow-2xl">
                                <div className="flex items-center gap-3 mb-8">
                                    <div className="w-10 h-10 bg-amber-500/10 rounded-2xl flex items-center justify-center border border-amber-500/20">
                                        <UserIcon className="w-5 h-5 text-amber-500 shadow-[0_0_10px_rgba(245,158,11,0.4)]" />
                                    </div>
                                    <h3 className="font-black text-white text-lg tracking-tight uppercase">Pejabat Berwenang</h3>
                                </div>

                                <div className="space-y-6">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-2">Nama Pengasuh / Kepala</label>
                                        <input
                                            type="text"
                                            value={settings.pengasuh_pondok_name || ''}
                                            onChange={(e) => setSettings({ ...settings, pengasuh_pondok_name: e.target.value })}
                                            className="w-full px-6 py-4 bg-black/40 border border-white/5 rounded-2xl text-white placeholder-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all font-bold"
                                        />
                                    </div>

                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-2">NIP / NIY / NIK</label>
                                        <input
                                            type="text"
                                            value={settings.pengasuh_pondok_nip || ''}
                                            onChange={(e) => setSettings({ ...settings, pengasuh_pondok_nip: e.target.value })}
                                            className="w-full px-6 py-4 bg-black/40 border border-white/5 rounded-2xl text-white placeholder-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all font-bold font-mono tracking-tighter"
                                        />
                                    </div>
                                </div>
                            </div>

                            {/* Semester & Academic Year */}
                            <div className="bg-neutral-900/40 border border-white/5 rounded-[3rem] p-8 backdrop-blur-md shadow-2xl">
                                <div className="flex items-center gap-3 mb-8">
                                    <div className="w-10 h-10 bg-emerald-500/10 rounded-2xl flex items-center justify-center border border-emerald-500/20">
                                        <CalendarDays className="w-5 h-5 text-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.4)]" />
                                    </div>
                                    <h3 className="font-black text-white text-lg tracking-tight uppercase">Kalender Akademik</h3>
                                </div>

                                <div className="space-y-8">
                                    <div className="space-y-4">
                                        <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-2">Semester Berjalan</label>
                                        <div className="flex p-2 bg-black/60 rounded-[1.8rem] border border-white/5 gap-2">
                                            <button
                                                onClick={() => setSettings({ ...settings, active_semester: 1 })}
                                                className={`flex-1 py-4 rounded-[1.5rem] font-black text-xs uppercase tracking-widest transition-all ${settings.active_semester === 1
                                                    ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/40'
                                                    : 'text-gray-500 hover:text-gray-300'
                                                    }`}
                                            >
                                                Ganjil (1)
                                            </button>
                                            <button
                                                onClick={() => setSettings({ ...settings, active_semester: 2 })}
                                                className={`flex-1 py-4 rounded-[1.5rem] font-black text-xs uppercase tracking-widest transition-all ${settings.active_semester === 2
                                                    ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/40'
                                                    : 'text-gray-500 hover:text-gray-300'
                                                    }`}
                                            >
                                                Genap (2)
                                            </button>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-2 gap-6">
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-2">Tahun Ajaran</label>
                                            <input
                                                type="text"
                                                value={settings.academic_year}
                                                onChange={(e) => setSettings({ ...settings, academic_year: e.target.value })}
                                                placeholder="2024/2025"
                                                className="w-full px-6 py-4 bg-black/40 border border-white/5 rounded-2xl text-white font-bold"
                                            />
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black text-gray-600 uppercase tracking-[0.2em] ml-2">Kota Penerbitan</label>
                                            <input
                                                type="text"
                                                value={settings.report_city}
                                                onChange={(e) => setSettings({ ...settings, report_city: e.target.value })}
                                                placeholder="Nama Kota"
                                                className="w-full px-6 py-4 bg-black/40 border border-white/5 rounded-2xl text-white font-bold"
                                            />
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Dynamic Info Box */}
                            <div className="group relative bg-gradient-to-br from-blue-600/20 to-indigo-600/10 border border-blue-500/30 rounded-[2.5rem] p-8 overflow-hidden transition-all duration-500 hover:shadow-2xl">
                                <div className="absolute -top-10 -right-10 w-40 h-40 bg-blue-500/10 rounded-full blur-[50px] group-hover:bg-blue-500/20 transition-all duration-700"></div>
                                <div className="flex items-center gap-3 mb-4">
                                    <div className="w-10 h-10 bg-blue-500/20 rounded-2xl flex items-center justify-center border border-blue-500/30">
                                        <BookOpen className="w-5 h-5 text-blue-400" />
                                    </div>
                                    <h4 className="font-black text-blue-400 text-sm uppercase tracking-widest">Informasi Sistem</h4>
                                </div>
                                <div className="space-y-3 relative z-10">
                                    <div className="flex items-center justify-between py-2 border-b border-white/5">
                                        <span className="text-xs font-bold text-gray-500 uppercase tracking-tighter">Status Periode</span>
                                        <span className="text-xs font-black text-emerald-500 uppercase tracking-widest bg-emerald-500/10 px-3 py-1 rounded-full">Aktif</span>
                                    </div>
                                    <div className="flex items-center justify-between py-2 border-b border-white/5">
                                        <span className="text-xs font-bold text-gray-500 uppercase tracking-tighter">Semester</span>
                                        <span className="text-xs font-black text-white uppercase tracking-widest">{settings.active_semester === 1 ? 'Ganjil' : 'Genap'}</span>
                                    </div>
                                    <div className="flex items-center justify-between py-2 border-b border-white/5">
                                        <span className="text-xs font-bold text-gray-500 uppercase tracking-tighter">Target Rapor</span>
                                        <span className="text-xs font-black text-white uppercase tracking-widest">{getSemesterName(settings.active_semester)}</span>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Action Buttons */}
                    <div className="mt-12 flex flex-col md:flex-row gap-6 justify-end">
                        <button
                            onClick={handleReset}
                            className="px-8 py-5 border border-white/10 text-gray-500 font-black text-xs uppercase tracking-[0.2em] rounded-2xl hover:text-rose-500 hover:border-rose-500/30 hover:bg-rose-500/5 transition-all active:scale-95 transition-all flex items-center justify-center gap-3"
                        >
                            <RotateCcw className="w-5 h-5" />
                            Reset Default
                        </button>
                        <button
                            onClick={handleSave}
                            disabled={isSaving}
                            className="px-10 py-5 bg-blue-600 hover:bg-blue-500 text-white font-black text-xs uppercase tracking-[0.2em] rounded-3xl transition-all flex items-center justify-center gap-3 shadow-[0_15px_40px_rgba(37,99,235,0.3)] disabled:opacity-50 active:scale-95 group"
                        >
                            {isSaving ? (
                                <>
                                    <Loader2 className="w-5 h-5 animate-spin" />
                                    Processing...
                                </>
                            ) : (
                                <>
                                    <Save className="w-6 h-6 transition-transform group-hover:rotate-12" />
                                    Simpan Perubahan
                                </>
                            )}
                        </button>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User,
    ROLE_NAMES
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    FileSpreadsheet,
    CheckCircle2,
    AlertCircle,
    Loader2,
    Download,
    Trash2,
    Save,
    Eye,
    FileWarning,
    Table,
    FileText,
    Users,
    UserPlus,
    Phone
} from 'lucide-react';
import { parseFile, ParsedStudentData, ParseResult } from '@/lib/utils/file-parser';
import { supabase } from '@/lib/supabase';
import { classesService } from '@/lib/services/classes';

// ============================================
// Types
// ============================================

interface ClassOption {
    id: string;
    name: string;
}

// ============================================
// Column Mapping Info
// ============================================

const EXPECTED_COLUMNS = [
    { key: 'no', label: 'NO', required: false },
    { key: 'nis', label: 'NAMA INDUK SANTRI', required: true },
    { key: 'nama', label: 'NAMA SANTRI', required: true },
    { key: 'ttl', label: 'TTL', required: false },
    { key: 'jenisKelamin', label: 'JENIS KELAMIN', required: true },
    { key: 'namaAyah', label: 'NAMA AYAH', required: false },
    { key: 'noHpWali', label: 'No Hp wali santri', required: false },
    { key: 'alamat', label: 'ALAMAT', required: false },
];

export default function ImportSantriPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);

    // File upload state
    const [isDragging, setIsDragging] = useState(false);
    const [uploadedFile, setUploadedFile] = useState<File | null>(null);
    const [isProcessing, setIsProcessing] = useState(false);
    const [parseError, setParseError] = useState<string | null>(null);

    // Data state
    const [parsedData, setParsedData] = useState<ParsedStudentData[]>([]);
    const [showPreview, setShowPreview] = useState(false);

    // Class selection
    const [classes, setClasses] = useState<ClassOption[]>([]);
    const [selectedClassId, setSelectedClassId] = useState<string>('');

    // Auto-create user option (1 akun = santri + wali)
    const [createStudentAccount, setCreateStudentAccount] = useState(true);

    // Save state
    const [isSaving, setIsSaving] = useState(false);
    const [saveProgress, setSaveProgress] = useState({ current: 0, total: 0 });
    const [saveResults, setSaveResults] = useState<{ success: number; failed: number; errors: string[] }>({ success: 0, failed: 0, errors: [] });
    const [saveComplete, setSaveComplete] = useState(false);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_akademik' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }

        const fetchClasses = async () => {
            try {
                const data = await classesService.getAll();
                setClasses(data.map(c => ({ id: c.id, name: c.name })));
            } catch (_error) {
                console.error('Error fetching classes:', _error);
            }
        };

        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchClasses();
        });
        return () => cancelAnimationFrame(timer);
    }, [router]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    // Drag & Drop handlers
    const handleDragEnter = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDragging(true);
    }, []);

    const handleDragLeave = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDragging(false);
    }, []);

    const handleDragOver = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
    }, []);

    const handleDrop = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDragging(false);

        const files = e.dataTransfer.files;
        if (files.length > 0) {
            handleFileSelect(files[0]);
        }
    }, []);

    const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = e.target.files;
        if (files && files.length > 0) {
            handleFileSelect(files[0]);
        }
    };

    const handleFileSelect = async (file: File) => {
        const validExtensions = ['.xlsx', '.xls', '.csv', '.docx', '.doc'];
        const fileExtension = '.' + file.name.split('.').pop()?.toLowerCase();

        if (!validExtensions.includes(fileExtension)) {
            alert('Format file tidak didukung. Gunakan file Excel (.xlsx, .xls, .csv) atau Word (.docx)');
            return;
        }

        setUploadedFile(file);
        setIsProcessing(true);
        setParseError(null);

        try {
            const result: ParseResult = await parseFile(file);

            if (!result.success || result.data.length === 0) {
                setParseError(result.message || 'Tidak ada data yang dapat dibaca');
                setIsProcessing(false);
                return;
            }

            setParsedData(result.data);
            setShowPreview(true);
            setParsedData(result.data);
            setShowPreview(true);
        } catch (error: unknown) {
            console.error('Parse error:', error);
            const errorMsg = error instanceof Error ? error.message : 'Gagal memproses file';
            setParseError(errorMsg);
        } finally {
            setIsProcessing(false);
        }
    };

    const handleRemoveFile = () => {
        setUploadedFile(null);
        setParsedData([]);
        setShowPreview(false);
        setParseError(null);
        setSaveComplete(false);
        setSaveResults({ success: 0, failed: 0, errors: [] });
    };

    const handleSaveToDatabase = async () => {
        const validData = parsedData.filter(d => d.isValid);
        if (validData.length === 0) {
            alert('Tidak ada data valid untuk disimpan!');
            return;
        }

        if (!selectedClassId) {
            alert('Pilih kelas terlebih dahulu!');
            return;
        }

        // Validasi pesantren_id - PENTING untuk multi-tenancy
        if (!user?.pesantrenId) {
            console.warn('Warning: pesantrenId is not set for current user');
            if (!confirm('Peringatan: Pesantren ID tidak terdeteksi. Santri mungkin akan masuk ke pesantren yang salah. Lanjutkan?')) {
                return;
            }
        }

        setIsSaving(true);
        setSaveProgress({ current: 0, total: validData.length });
        const results = { success: 0, failed: 0, errors: [] as string[] };

        console.log('Starting import for', validData.length, 'students to class', selectedClassId, 'pesantren:', user?.pesantrenId);

        for (let i = 0; i < validData.length; i++) {
            const row = validData[i];
            setSaveProgress({ current: i + 1, total: validData.length });

            try {
                // Prepare data for RPC - Unified account (1 akun = santri + wali)
                const studentData = {
                    nis: String(row.nis),
                    name: String(row.nama),
                    gender: row.jenisKelamin,
                    class_id: selectedClassId,
                    birth_info: row.ttl || '',
                    parent_name: row.namaAyah || row.namaIbu || 'Wali ' + row.nama,
                    parent_phone: row.noHpWali || null,
                    address: row.alamat || '',
                    // IMPORTANT: Include pesantren_id from current user
                    pesantren_id: user?.pesantrenId || null,
                    // Auto user creation - 1 akun bisa dual role
                    email: `santri.${row.nis}@pesantren.local`,
                    create_student_account: createStudentAccount
                };

                console.log(`[${i + 1}/${validData.length}] Saving:`, row.nama, 'NIS:', row.nis);

                // Try RPC first
                const { data: rpcData, error: rpcError } = await supabase.rpc('automated_registration', {
                    p_type: 'student',
                    p_data: studentData
                });

                if (rpcError) {
                    console.warn('RPC error:', rpcError);

                    // Fallback: Direct insert without user creation
                    console.log('Fallback: Using direct insert...');
                    const { data: insertData, error: insertError } = await supabase
                        .from('students')
                        .insert({
                            nis: String(row.nis),
                            name: String(row.nama),
                            gender: row.jenisKelamin,
                            class_id: selectedClassId,
                            birth_info: row.ttl || '',
                            parent_name: row.namaAyah || row.namaIbu || '',
                            parent_phone: row.noHpWali || '',
                            address: row.alamat || '',
                            pesantren_id: user?.pesantrenId || null,
                            status: 'active'
                        })
                        .select();

                    if (insertError) {
                        console.error('Insert error:', insertError);
                        throw new Error(insertError.message || insertError.code);
                    }

                    console.log('Direct insert success:', insertData);
                    results.success++;
                } else {
                    // Check RPC response
                    if (rpcData && rpcData.success === false) {
                        console.warn('RPC returned failure:', rpcData.message);
                        throw new Error(rpcData.message || 'RPC failed');
                    }
                    console.log('RPC success:', rpcData);
                    results.success++;
                }
            } catch (error: unknown) {
                console.error(`Error saving row ${i + 1}:`, error);
                results.failed++;
                const errorMsg = error instanceof Error ? error.message : 'Unknown error';
                results.errors.push(`Baris ${i + 1} (${row.nama}): ${errorMsg}`);
            }

            // Small delay to prevent overwhelming the server
            await new Promise(r => setTimeout(r, 100));
        }

        console.log('Import complete:', results);
        setSaveResults(results);
        setIsSaving(false);
        setSaveComplete(true);
    };

    const downloadTemplate = () => {
        // Format sesuai dengan file user
        const headers = ['NO', 'NAMA INDUK SANTRI', 'NAMA SANTRI', 'TTL', 'JENIS KELAMIN', 'NAMA AYAH', 'NAMA IBU', 'ALAMAT'];
        const sampleRows = [
            ['1', '0272170721', 'Adelia Andriyani', 'Merandung Sari, 03 April 2008', 'Perempuan', 'Abu Bakar', '', 'Toba'],
            ['2', '0273170721', 'Agus Sulis Tiani', 'Sukaraja Tiga, 14 Agustus 2008', 'Perempuan', 'Miskani', '', 'Melaris'],
            ['3', '0276170721', 'Al Faiz Maulana Setiawan', 'Bandar Lampung, 17 Februari 2009', 'Laki Laki', 'Sugianto', '', 'Telusan Lunyai'],
        ];

        const csvContent = [headers.join(','), ...sampleRows.map(row => row.join(','))].join('\n');
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = 'template_import_santri.csv';
        link.click();
    };

    if (!user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-black">
                <Loader2 className="w-8 h-8 text-blue-500 animate-spin" />
            </div>
        );
    }

    const validCount = parsedData.filter(d => d.isValid).length;
    const invalidCount = parsedData.filter(d => !d.isValid).length;

    return (
        <div className="min-h-screen bg-black">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Breadcrumb & Title */}
                    <div className="mb-6">
                        <Link
                            href="/dashboard/akademik/santri"
                            className="inline-flex items-center gap-2 text-sm text-gray-400 hover:text-white mb-2 transition-colors"
                        >
                            <ArrowLeft className="w-4 h-4" />
                            Kembali ke Data Santri
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div>
                                <h1 className="text-2xl font-bold text-white">Import Data Santri</h1>
                                <p className="text-gray-400">Upload file Excel atau Word untuk import data santri secara massal</p>
                            </div>
                            <button
                                onClick={downloadTemplate}
                                className="flex items-center gap-2 px-4 py-2 border border-gray-600 text-gray-300 font-medium rounded-xl hover:bg-gray-800 transition-colors"
                            >
                                <Download className="w-5 h-5" />
                                Download Template
                            </button>
                        </div>
                    </div>

                    {/* Column Mapping Info */}
                    <div className="bg-blue-500/10 border border-blue-500/30 rounded-xl p-4 mb-6">
                        <div className="flex items-start gap-3">
                            <Table className="w-5 h-5 text-blue-400 mt-0.5" />
                            <div>
                                <h3 className="font-semibold text-blue-300 mb-2">Format Kolom yang Diharapkan</h3>
                                <div className="flex flex-wrap gap-2">
                                    {EXPECTED_COLUMNS.map(col => (
                                        <span
                                            key={col.key}
                                            className={`px-2 py-1 rounded text-xs font-medium ${col.required
                                                ? 'bg-blue-500/30 text-blue-300'
                                                : 'bg-gray-700 text-gray-400'
                                                }`}
                                        >
                                            {col.label} {col.required && '*'}
                                        </span>
                                    ))}
                                </div>
                                <p className="text-sm text-blue-400 mt-2">* = Wajib diisi | Format: Excel (.xlsx, .xls, .csv) atau Word (.docx)</p>
                            </div>
                        </div>
                    </div>

                    {/* Upload Area */}
                    {!showPreview && (
                        <div
                            onDragEnter={handleDragEnter}
                            onDragLeave={handleDragLeave}
                            onDragOver={handleDragOver}
                            onDrop={handleDrop}
                            className={`relative border-2 border-dashed rounded-2xl p-12 text-center transition-all ${isDragging
                                ? 'border-blue-500 bg-blue-500/10'
                                : 'border-gray-600 bg-gray-800/50 hover:border-gray-500'
                                }`}
                        >
                            {isProcessing ? (
                                <div className="space-y-4">
                                    <Loader2 className="w-16 h-16 text-blue-500 animate-spin mx-auto" />
                                    <div>
                                        <p className="font-semibold text-white">Memproses File...</p>
                                        <p className="text-sm text-gray-400">{uploadedFile?.name}</p>
                                    </div>
                                </div>
                            ) : parseError ? (
                                <div className="space-y-4">
                                    <AlertCircle className="w-16 h-16 text-red-500 mx-auto" />
                                    <div>
                                        <p className="font-semibold text-red-400">Gagal Memproses File</p>
                                        <p className="text-sm text-gray-400">{parseError}</p>
                                    </div>
                                    <button
                                        onClick={handleRemoveFile}
                                        className="px-4 py-2 bg-gray-700 text-white rounded-lg hover:bg-gray-600"
                                    >
                                        Coba Lagi
                                    </button>
                                </div>
                            ) : (
                                <>
                                    <div className="w-20 h-20 bg-blue-500/20 rounded-full flex items-center justify-center mx-auto mb-4">
                                        <FileSpreadsheet className="w-10 h-10 text-blue-400" />
                                    </div>
                                    <h3 className="text-lg font-semibold text-white mb-2">
                                        Drag & Drop File di Sini
                                    </h3>
                                    <p className="text-gray-400 mb-4">atau klik untuk memilih file</p>
                                    <input
                                        type="file"
                                        accept=".xlsx,.xls,.csv,.docx,.doc"
                                        onChange={handleFileInputChange}
                                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                                    />
                                    <div className="flex items-center justify-center gap-4 text-sm text-gray-500">
                                        <span className="flex items-center gap-1">
                                            <FileSpreadsheet className="w-4 h-4" /> Excel
                                        </span>
                                        <span className="flex items-center gap-1">
                                            <FileText className="w-4 h-4" /> Word
                                        </span>
                                    </div>
                                </>
                            )}
                        </div>
                    )}

                    {/* Preview Section */}
                    {showPreview && !saveComplete && (
                        <div className="space-y-6">
                            {/* File Info & Stats */}
                            <div className="bg-gray-800/50 rounded-2xl border border-gray-700 p-6">
                                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                                    <div className="flex items-center gap-4">
                                        <div className="w-14 h-14 bg-emerald-500/20 rounded-xl flex items-center justify-center">
                                            <FileSpreadsheet className="w-7 h-7 text-emerald-400" />
                                        </div>
                                        <div>
                                            <p className="font-semibold text-white">{uploadedFile?.name}</p>
                                            <p className="text-sm text-gray-400">
                                                {parsedData.length} baris data terdeteksi
                                            </p>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-3">
                                        <div className="flex items-center gap-2 px-3 py-1.5 bg-emerald-500/20 text-emerald-400 rounded-lg">
                                            <CheckCircle2 className="w-4 h-4" />
                                            <span className="text-sm font-medium">{validCount} Valid</span>
                                        </div>
                                        {invalidCount > 0 && (
                                            <div className="flex items-center gap-2 px-3 py-1.5 bg-red-500/20 text-red-400 rounded-lg">
                                                <AlertCircle className="w-4 h-4" />
                                                <span className="text-sm font-medium">{invalidCount} Error</span>
                                            </div>
                                        )}
                                        <button
                                            onClick={handleRemoveFile}
                                            className="p-2 hover:bg-gray-700 rounded-lg text-gray-400"
                                        >
                                            <Trash2 className="w-5 h-5" />
                                        </button>
                                    </div>
                                </div>
                            </div>

                            {/* Settings */}
                            <div className="bg-gray-800/50 rounded-2xl border border-gray-700 p-6">
                                <h3 className="font-semibold text-white mb-4 flex items-center gap-2">
                                    <Users className="w-5 h-5 text-blue-400" />
                                    Pengaturan Import
                                </h3>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    {/* Class Selection */}
                                    <div>
                                        <label className="block text-sm font-medium text-gray-300 mb-1.5">
                                            Kelas Tujuan *
                                        </label>
                                        <select
                                            value={selectedClassId}
                                            onChange={(e) => setSelectedClassId(e.target.value)}
                                            className="w-full px-4 py-3 bg-gray-700/50 border border-gray-600 rounded-xl text-white focus:outline-none focus:ring-2 focus:ring-blue-500/50"
                                        >
                                            <option value="">Pilih Kelas...</option>
                                            {classes.map(c => (
                                                <option key={c.id} value={c.id}>{c.name}</option>
                                            ))}
                                        </select>
                                    </div>

                                    {/* Auto create unified account (santri + wali) */}
                                    <div className="flex items-center gap-3 p-4 bg-emerald-500/10 border border-emerald-500/30 rounded-xl">
                                        <input
                                            type="checkbox"
                                            id="createStudent"
                                            checked={createStudentAccount}
                                            onChange={(e) => setCreateStudentAccount(e.target.checked)}
                                            className="w-5 h-5 rounded border-emerald-500 text-emerald-600 focus:ring-emerald-500"
                                        />
                                        <label htmlFor="createStudent" className="flex flex-col text-gray-300">
                                            <span className="flex items-center gap-2 font-medium">
                                                <UserPlus className="w-4 h-4 text-emerald-400" />
                                                Buat Akun Login
                                            </span>
                                            <span className="text-xs text-gray-500">1 akun = bisa login Santri & Wali</span>
                                        </label>
                                    </div>
                                </div>

                                {/* Info box for dual-role */}
                                <div className="mt-4 p-3 bg-blue-500/10 border border-blue-500/20 rounded-lg">
                                    <p className="text-xs text-blue-300">
                                        <strong>­ƒÆí Info:</strong> Setiap santri mendapat 1 akun yang bisa digunakan untuk login sebagai <strong>Santri</strong> atau <strong>Wali Santri</strong> dengan email & password yang sama.
                                    </p>
                                </div>
                            </div>

                            {/* Data Preview Table */}
                            <div className="bg-gray-800/50 rounded-2xl border border-gray-700 overflow-hidden">
                                <div className="p-5 border-b border-gray-700 flex items-center justify-between">
                                    <div className="flex items-center gap-2">
                                        <Eye className="w-5 h-5 text-gray-400" />
                                        <h3 className="font-semibold text-white">Preview Data Import</h3>
                                    </div>
                                </div>
                                <div className="overflow-x-auto">
                                    <table className="w-full">
                                        <thead className="bg-gray-700/50 border-b border-gray-600">
                                            <tr>
                                                <th className="text-left p-4 text-sm font-semibold text-gray-400">Status</th>
                                                <th className="text-left p-4 text-sm font-semibold text-gray-400">NO</th>
                                                <th className="text-left p-4 text-sm font-semibold text-gray-400">NIS</th>
                                                <th className="text-left p-4 text-sm font-semibold text-gray-400">Nama Santri</th>
                                                <th className="text-center p-4 text-sm font-semibold text-gray-400">JK</th>
                                                <th className="text-left p-4 text-sm font-semibold text-gray-400">No HP Wali</th>
                                                <th className="text-left p-4 text-sm font-semibold text-gray-400">Nama Ayah</th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-gray-700">
                                            {parsedData.slice(0, 20).map((row, index) => (
                                                <tr key={index} className={`hover:bg-gray-700/30 ${!row.isValid ? 'bg-red-500/10' : ''}`}>
                                                    <td className="p-4">
                                                        {row.isValid ? (
                                                            <CheckCircle2 className="w-5 h-5 text-emerald-500" />
                                                        ) : (
                                                            <div className="group relative">
                                                                <AlertCircle className="w-5 h-5 text-red-500" />
                                                                <div className="absolute left-0 top-6 hidden group-hover:block bg-red-900 text-white text-xs p-2 rounded-lg shadow-lg z-10 whitespace-nowrap">
                                                                    {row.errors.join(', ')}
                                                                </div>
                                                            </div>
                                                        )}
                                                    </td>
                                                    <td className="p-4 text-gray-400">{row.no}</td>
                                                    <td className="p-4">
                                                        <span className={`font-medium ${!row.nis ? 'text-red-400' : 'text-white'}`}>
                                                            {row.nis || '-'}
                                                        </span>
                                                    </td>
                                                    <td className="p-4 font-medium text-white">{row.nama}</td>
                                                    <td className="p-4 text-center">
                                                        <span className={`px-2 py-0.5 rounded text-xs font-medium ${row.jenisKelamin === 'L'
                                                            ? 'bg-blue-500/20 text-blue-400'
                                                            : 'bg-pink-500/20 text-pink-400'
                                                            }`}>
                                                            {row.jenisKelamin}
                                                        </span>
                                                    </td>
                                                    <td className="p-4 text-gray-400 text-sm">{row.noHpWali || '-'}</td>
                                                    <td className="p-4 text-gray-400 text-sm">{row.namaAyah || '-'}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                    {parsedData.length > 20 && (
                                        <div className="p-4 text-center text-gray-500 bg-gray-700/30">
                                            ... dan {parsedData.length - 20} data lainnya
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* Progress Bar (saat saving) */}
                            {isSaving && (
                                <div className="bg-gray-800/50 rounded-2xl border border-gray-700 p-6">
                                    <div className="flex items-center justify-between mb-2">
                                        <span className="text-white font-medium">Mengimpor data...</span>
                                        <span className="text-gray-400">{saveProgress.current} / {saveProgress.total}</span>
                                    </div>
                                    <div className="w-full h-3 bg-gray-700 rounded-full overflow-hidden">
                                        <div
                                            className="h-full bg-blue-500 rounded-full transition-all duration-300"
                                            style={{ width: `${(saveProgress.current / saveProgress.total) * 100}%` }}
                                        />
                                    </div>
                                </div>
                            )}

                            {/* Action Buttons */}
                            <div className="flex flex-col md:flex-row gap-4 justify-end">
                                <button
                                    onClick={handleRemoveFile}
                                    disabled={isSaving}
                                    className="px-6 py-3 border border-gray-600 text-gray-300 font-medium rounded-xl hover:bg-gray-800 transition-colors disabled:opacity-50"
                                >
                                    Batalkan Import
                                </button>
                                <button
                                    onClick={handleSaveToDatabase}
                                    disabled={isSaving || validCount === 0 || !selectedClassId}
                                    className="px-6 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-xl transition-colors flex items-center justify-center gap-2 shadow-lg shadow-emerald-500/30 disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    {isSaving ? (
                                        <>
                                            <Loader2 className="w-5 h-5 animate-spin" />
                                            Menyimpan...
                                        </>
                                    ) : (
                                        <>
                                            <Save className="w-5 h-5" />
                                            Simpan ke Database ({validCount} data)
                                        </>
                                    )}
                                </button>
                            </div>

                            {/* Warning for invalid data */}
                            {invalidCount > 0 && (
                                <div className="bg-amber-500/10 border border-amber-500/30 rounded-xl p-4">
                                    <div className="flex items-start gap-3">
                                        <FileWarning className="w-5 h-5 text-amber-400 mt-0.5" />
                                        <div>
                                            <h4 className="font-semibold text-amber-300">Perhatian</h4>
                                            <p className="text-sm text-amber-400/80">
                                                Terdapat {invalidCount} baris data yang tidak valid dan tidak akan disimpan.
                                                Hover pada ikon error untuk melihat detail kesalahan.
                                            </p>
                                        </div>
                                    </div>
                                </div>
                            )}
                        </div>
                    )}

                    {/* Save Complete Result */}
                    {saveComplete && (
                        <div className="bg-gray-800/50 rounded-2xl border border-gray-700 p-8 text-center">
                            <div className="w-20 h-20 bg-emerald-500/20 rounded-full flex items-center justify-center mx-auto mb-6">
                                <CheckCircle2 className="w-10 h-10 text-emerald-400" />
                            </div>
                            <h2 className="text-2xl font-bold text-white mb-2">Import Selesai!</h2>
                            <p className="text-gray-400 mb-6">
                                {saveResults.success} data berhasil diimpor
                                {saveResults.failed > 0 && `, ${saveResults.failed} gagal`}
                            </p>

                            {saveResults.errors.length > 0 && (
                                <div className="bg-red-500/10 border border-red-500/30 rounded-xl p-4 mb-6 text-left max-h-40 overflow-y-auto">
                                    <h4 className="font-semibold text-red-300 mb-2">Error Details:</h4>
                                    <ul className="text-sm text-red-400 space-y-1">
                                        {saveResults.errors.map((err, i) => (
                                            <li key={i}>ÔÇó {err}</li>
                                        ))}
                                    </ul>
                                </div>
                            )}

                            <div className="flex gap-4 justify-center">
                                <button
                                    onClick={handleRemoveFile}
                                    className="px-6 py-3 bg-gray-700 text-white font-medium rounded-xl hover:bg-gray-600 transition-colors"
                                >
                                    Import Lagi
                                </button>
                                <Link
                                    href="/dashboard/akademik/santri"
                                    className="px-6 py-3 bg-blue-600 text-white font-medium rounded-xl hover:bg-blue-700 transition-colors"
                                >
                                    Lihat Data Santri
                                </Link>
                            </div>
                        </div>
                    )}
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Plus,
    Search,
    Edit,
    Trash2,
    Filter,
    Download,
    UserCheck,
    Users
} from 'lucide-react';

import { studentsService, StudentWithRelations } from '@/lib/services/students';
import { Loader2 } from 'lucide-react';
import SantriModal from '@/components/admin/SantriModal';

export default function ManajemenSantriPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [students, setStudents] = useState<StudentWithRelations[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    // Modal state
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selectedSantri, setSelectedSantri] = useState<StudentWithRelations | null>(null);

    const fetchStudents = async () => {
        try {
            setIsLoading(true);
            const data = await studentsService.getAll();
            setStudents(data);
            setIsLoading(false);
        } catch (error: unknown) {
            console.error('Error fetching students:', error);
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_akademik' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchStudents();
        });
        return () => cancelAnimationFrame(timer);
    }, [router]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleOpenAddModal = () => {
        setSelectedSantri(null);
        setIsModalOpen(true);
    };

    const handleOpenEditModal = (santri: StudentWithRelations) => {
        setSelectedSantri(santri);
        setIsModalOpen(true);
    };

    const handleSubmitSantri = async (data: any) => { // eslint-disable-line @typescript-eslint/no-explicit-any
        try {
            if (selectedSantri) {
                // When updating, only send fields that exist in students table
                // Exclude email (managed in profiles), and other non-table fields
                const updateData = {
                    name: data.name,
                    nis: data.nis,
                    gender: data.gender,
                    class_id: data.class_id,
                    birth_place: data.birth_place || null,
                    birth_date: data.birth_date || null,
                    address: data.address || null,
                    parent_name: data.parent_name,
                    parent_phone: data.parent_phone || null,
                    status: data.status || 'active'
                };
                await studentsService.update(selectedSantri.id, updateData);
            } else {
                // Create new - RPC will handle user creation
                const result = await studentsService.create(data);
                const resultWithCreds = result as any; // eslint-disable-line @typescript-eslint/no-explicit-any

                // Show generated credentials if available
                if (resultWithCreds && resultWithCreds.email && resultWithCreds.password) {
                    setTimeout(() => {
                        alert(`Ô£à Santri berhasil ditambahkan!\n\n­ƒôº Email: ${resultWithCreds.email}\n­ƒöæ Password: ${resultWithCreds.password}\n\nSimpan informasi ini untuk login santri/wali.`);
                    }, 500);
                }
            }
            fetchStudents();
        } catch (error: unknown) {
            console.error('Error saving santri:', error);
            throw error;
        }
    };

    const handleDeleteSantri = async (id: string) => {
        if (confirm('Apakah Anda yakin ingin menghapus data santri ini?')) {
            try {
                await studentsService.delete(id);
                fetchStudents();
            } catch (_e) {
                alert('Gagal menghapus data santri.');
            }
        }
    };

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-blue-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-blue-600 animate-spin" />
                    <span>Loading Data Santri...</span>
                </div>
            </div>
        );
    }

    const filteredStudents = students.filter(s =>
        s.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        s.nis.includes(searchQuery)
    );

    return (
        <div className="min-h-screen bg-[#050505] flex">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Header */}
                    <div className="mb-10">
                        <Link
                            href="/dashboard/akademik"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-white mb-6 transition-colors group"
                        >
                            <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-1" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                            <div>
                                <h1 className="text-3xl font-black text-white tracking-tight flex items-center gap-3">
                                    <span className="w-2 h-8 bg-blue-600 rounded-full block"></span>
                                    Manajemen Santri
                                </h1>
                                <p className="text-gray-400 mt-1">
                                    Kelola database santri, perwalian, dan akun wali santri
                                </p>
                            </div>
                            <div className="flex flex-wrap gap-3">
                                <Link
                                    href="/dashboard/akademik/santri/import"
                                    className="flex items-center gap-2 px-6 py-3.5 bg-neutral-900/40 border border-white/5 text-gray-400 hover:text-white font-bold rounded-2xl transition-all backdrop-blur-sm active:scale-95"
                                >
                                    <Download className="w-5 h-5" />
                                    Import Massal
                                </Link>
                                <button
                                    onClick={handleOpenAddModal}
                                    className="flex items-center gap-2 px-6 py-3.5 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-bold transition-all shadow-lg shadow-blue-500/20 active:scale-95"
                                >
                                    <Plus className="w-5 h-5" />
                                    Tambah Santri
                                </button>
                            </div>
                        </div>
                    </div>

                    <SantriModal
                        isOpen={isModalOpen}
                        onClose={() => setIsModalOpen(false)}
                        onSubmit={handleSubmitSantri}
                        santriData={selectedSantri}
                    />

                    {/* Stats & Filters */}
                    <div className="flex flex-col lg:flex-row gap-6 mb-8">
                        <div className="flex-1 relative">
                            <Search className="w-6 h-6 text-gray-600 absolute left-4 top-1/2 -translate-y-1/2" />
                            <input
                                type="text"
                                placeholder="Cari NIS atau nama santri..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="w-full pl-12 pr-6 py-4 bg-neutral-900/40 border border-white/5 rounded-[1.5rem] text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500/30 transition-all backdrop-blur-sm shadow-inner"
                            />
                        </div>
                        <div className="flex items-center gap-6">
                            <div className="flex flex-col items-end">
                                <p className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Total Terdaftar</p>
                                <p className="text-xl font-black text-blue-500">{students.length} <span className="text-gray-600 font-bold ml-1 text-sm tracking-tight">Santri</span></p>
                            </div>
                            <button className="p-4 bg-neutral-900 border border-white/5 rounded-2xl text-gray-500 hover:text-white hover:border-blue-500/50 transition-all shadow-lg group active:scale-90">
                                <Filter className="w-6 h-6 group-hover:rotate-180 transition-transform duration-500" />
                            </button>
                        </div>
                    </div>

                    {/* Students Grid - Using cards for 3D premium feel */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {filteredStudents.map((s) => (
                            <div
                                key={s.id}
                                className="group relative bg-neutral-900/60 border border-white/5 rounded-[2.5rem] overflow-hidden transition-all duration-300 hover:shadow-[0_20px_50px_rgba(37,99,235,0.1)] hover:-translate-y-1"
                            >
                                {/* 3D Glass Reflection Overlay */}
                                <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-tr from-white/5 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"></div>

                                <div className="p-7">
                                    <div className="flex items-start justify-between mb-6">
                                        <div className="flex items-center gap-4">
                                            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl shadow-lg border transition-all duration-500 group-hover:scale-110 group-hover:rotate-3 ${s.gender === 'L'
                                                ? 'bg-blue-500/10 border-blue-500/20 text-blue-400'
                                                : 'bg-pink-500/10 border-pink-500/20 text-pink-400'
                                                }`}>
                                                {s.name.charAt(0)}
                                            </div>
                                            <div className="min-w-0">
                                                <h3 className="text-lg font-black text-white tracking-tight truncate leading-tight group-hover:text-blue-400 transition-colors">
                                                    {s.name}
                                                </h3>
                                                <p className="text-xs font-black text-gray-500 uppercase tracking-widest mt-1">NIS: {s.nis}</p>
                                            </div>
                                        </div>
                                        <div className={`px-3 py-1 bg-black/40 border border-white/5 rounded-xl flex items-center gap-1.5`}>
                                            <div className={`w-1.5 h-1.5 rounded-full ${s.status === 'active' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.8)]' : 'bg-gray-600'}`}></div>
                                            <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">{s.status === 'active' ? 'Aktif' : 'Nonaktif'}</span>
                                        </div>
                                    </div>

                                    <div className="space-y-4">
                                        <div className="bg-black/40 border border-white/5 rounded-2xl p-4 flex items-center justify-between">
                                            <div className="flex flex-col">
                                                <span className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Penempatan Kelas</span>
                                                <span className="text-sm font-bold text-gray-300">{s.class?.name || 'Belum diatur'}</span>
                                            </div>
                                            <div className="w-8 h-8 rounded-lg bg-neutral-800 flex items-center justify-center">
                                                <UserCheck className="w-4 h-4 text-blue-500" />
                                            </div>
                                        </div>

                                        <div className="bg-black/20 border border-white/5 rounded-2xl p-4 flex items-center gap-3">
                                            <div className="w-9 h-9 rounded-full bg-neutral-800 flex items-center justify-center shrink-0">
                                                <Users className="w-4 h-4 text-gray-500" />
                                            </div>
                                            <div className="min-w-0">
                                                <p className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Wali Santri</p>
                                                <p className="text-xs font-bold text-gray-400 truncate mt-0.5">{s.parent_name || 'Tidak ada data'}</p>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="mt-8 flex items-center gap-2">
                                        <button className="flex-1 py-3 bg-neutral-800 hover:bg-neutral-700 text-gray-400 hover:text-white rounded-xl text-[10px] font-black uppercase tracking-widest transition-all border border-white/5">
                                            Detail Profil
                                        </button>
                                        <div className="flex items-center gap-1.5">
                                            <button
                                                onClick={() => handleOpenEditModal(s)}
                                                className="p-3 bg-neutral-800 hover:bg-emerald-600 text-gray-500 hover:text-white rounded-xl border border-white/5 transition-all active:scale-95"
                                            >
                                                <Edit className="w-4 h-4" />
                                            </button>
                                            <button
                                                onClick={() => handleDeleteSantri(s.id)}
                                                className="p-3 bg-neutral-800 hover:bg-rose-600 text-gray-500 hover:text-white rounded-xl border border-white/5 transition-all active:scale-95"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    {filteredStudents.length === 0 && (
                        <div className="flex flex-col items-center justify-center py-24 bg-neutral-900/40 border border-white/5 rounded-[3rem] backdrop-blur-sm">
                            <div className="w-24 h-24 bg-neutral-800 rounded-3xl flex items-center justify-center mb-6 border border-white/5 shadow-inner animate-bounce">
                                <Search className="w-12 h-12 text-gray-600" />
                            </div>
                            <h3 className="text-xl font-black text-white mb-2">Santri tidak ditemukan</h3>
                            <p className="text-gray-500 max-w-xs text-center font-medium">
                                Coba kata kunci NIS atau nama santri yang berbeda.
                            </p>
                        </div>
                    )}
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    Calendar,
    Plus,
    Edit,
    Trash2,
    CheckCircle2,
    XCircle,
    Loader2,
    ArrowLeft,
    CalendarDays
} from 'lucide-react';
import { academicYearsService, AcademicYear } from '@/lib/services/academic-years';

export default function TahunAjaranPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [years, setYears] = useState<AcademicYear[]>([]);

    // Modal states
    const [showModal, setShowModal] = useState(false);
    const [editingYear, setEditingYear] = useState<AcademicYear | null>(null);
    const [formData, setFormData] = useState({
        name: '',
        semester: 'ganjil' as 'ganjil' | 'genap',
        start_date: '',
        end_date: ''
    });
    const [isSubmitting, setIsSubmitting] = useState(false);

    const fetchData = async () => {
        try {
            setIsLoading(true);
            const data = await academicYearsService.getAll();
            setYears(data);
        } catch (error) {
            console.error('Error fetching academic years:', error);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || !['super_admin', 'admin_akademik'].includes(currentUser.role)) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData();
    }, [router]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const openAddModal = () => {
        setEditingYear(null);
        setFormData({ name: '', semester: 'ganjil', start_date: '', end_date: '' });
        setShowModal(true);
    };

    const openEditModal = (year: AcademicYear) => {
        setEditingYear(year);
        setFormData({
            name: year.name,
            semester: year.semester,
            start_date: year.start_date || '',
            end_date: year.end_date || ''
        });
        setShowModal(true);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);

        try {
            if (editingYear) {
                await academicYearsService.update(editingYear.id, formData);
            } else {
                await academicYearsService.create(formData);
            }
            setShowModal(false);
            fetchData();
        } catch (error) {
            console.error('Error saving:', error);
            alert('Gagal menyimpan data');
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleSetActive = async (id: string) => {
        try {
            await academicYearsService.setActive(id);
            fetchData();
        } catch (error) {
            console.error('Error setting active:', error);
            alert('Gagal mengaktifkan tahun ajaran');
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('Yakin hapus tahun ajaran ini?')) return;
        try {
            await academicYearsService.delete(id);
            fetchData();
            alert('Tahun ajaran berhasil dihapus!');
        } catch (error: unknown) {
            console.error('Error deleting:', error);
            const errorMsg = error instanceof Error ? error.message : 'Unknown error';
            alert(`Gagal menghapus: ${errorMsg}\n\nJika masih gagal, jalankan SQL fix-academic-years-rls.sql di Supabase`);
        }
    };

    if (!user) return null;

    return (
        <div className="min-h-screen bg-[#050505] flex">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="flex-1 lg:ml-64">
                <DashboardHeader
                    user={user}
                    onMenuClick={() => setSidebarOpen(true)}
                />

                <main className="p-4 lg:p-8">
                    {/* Back Button */}
                    <Link
                        href="/dashboard/akademik"
                        className="inline-flex items-center gap-2 text-gray-400 hover:text-white mb-8 transition-colors group"
                    >
                        <ArrowLeft className="w-4 h-4 transition-transform group-hover:-translate-x-1" />
                        <span className="text-sm font-medium">Kembali ke Dashboard</span>
                    </Link>

                    {/* Header */}
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10">
                        <div>
                            <h1 className="text-3xl font-extrabold text-white tracking-tight flex items-center gap-3">
                                <span className="w-2 h-8 bg-emerald-500 rounded-full block"></span>
                                Tahun Ajaran
                            </h1>
                            <p className="text-gray-400 mt-1">Kelola periode akademik dan status semester aktif</p>
                        </div>
                        <button
                            onClick={openAddModal}
                            className="flex items-center gap-2 px-6 py-3.5 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl font-bold transition-all shadow-lg shadow-emerald-500/20 hover:scale-[1.02] active:scale-95"
                        >
                            <Plus className="w-5 h-5" />
                            Tambah Tahun Ajaran
                        </button>
                    </div>

                    {/* Content */}
                    {isLoading ? (
                        <div className="flex flex-col items-center justify-center py-24 gap-4">
                            <Loader2 className="w-12 h-12 text-emerald-500 animate-spin" />
                            <p className="text-gray-500 font-medium animate-pulse">Memuat data akadmik...</p>
                        </div>
                    ) : years.length === 0 ? (
                        <div className="relative overflow-hidden bg-neutral-900/40 rounded-3xl border border-white/5 p-16 text-center backdrop-blur-sm">
                            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-emerald-500/20 to-transparent"></div>
                            <div className="w-20 h-20 bg-neutral-800 rounded-2xl flex items-center justify-center mx-auto mb-6 border border-white/5 shadow-inner">
                                <CalendarDays className="w-10 h-10 text-gray-500" />
                            </div>
                            <h3 className="text-xl font-bold text-white mb-2">Belum Ada Tahun Ajaran</h3>
                            <p className="text-gray-400 mb-8 max-w-sm mx-auto">
                                Belum ada data tahun ajaran yang tercatat. Silakan buat tahun ajaran baru untuk memulai operasional akademik.
                            </p>
                            <button
                                onClick={openAddModal}
                                className="inline-flex items-center gap-2 px-6 py-3 bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl font-bold transition-all"
                            >
                                <Plus className="w-5 h-5" />
                                Buat Tahun Ajaran Pertama
                            </button>
                        </div>
                    ) : (
                        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
                            {years.map((year) => (
                                <div
                                    key={year.id}
                                    className={`group relative rounded-[2rem] border transition-all duration-300 ${year.is_active
                                        ? 'bg-gradient-to-br from-emerald-500/10 via-neutral-900 to-neutral-900 border-emerald-500/40 shadow-[0_20px_50px_rgba(16,185,129,0.1)] ring-1 ring-emerald-500/20'
                                        : 'bg-neutral-900/60 border-white/5 hover:border-emerald-500/30'
                                        }`}
                                >
                                    {/* 3D Reflection Effect */}
                                    <div className="absolute top-0 left-0 w-full h-full rounded-[2rem] bg-gradient-to-tr from-white/5 to-transparent pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity"></div>

                                    <div className="p-7">
                                        <div className="flex items-start justify-between mb-6">
                                            <div className="flex items-center gap-4">
                                                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center border transition-transform duration-500 group-hover:scale-110 ${year.is_active
                                                    ? 'bg-emerald-500/20 border-emerald-500/30 shadow-[0_0_20px_rgba(16,185,129,0.2)]'
                                                    : 'bg-neutral-800 border-white/5 shadow-inner'
                                                    }`}>
                                                    <Calendar className={`w-7 h-7 ${year.is_active ? 'text-emerald-400' : 'text-gray-500'}`} />
                                                </div>
                                                <div>
                                                    <h3 className={`font-black text-xl tracking-tight leading-tight ${year.is_active ? 'text-white' : 'text-gray-300'}`}>
                                                        {year.name}
                                                    </h3>
                                                    <div className="flex items-center gap-2 mt-1">
                                                        <span className={`text-xs font-bold uppercase tracking-wider px-2 py-0.5 rounded-md ${year.is_active
                                                            ? 'bg-emerald-500/20 text-emerald-400'
                                                            : 'bg-neutral-800 text-gray-500'}`}
                                                        >
                                                            Semester {year.semester}
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                            {year.is_active && (
                                                <div className="flex h-8 items-center px-3 bg-emerald-500 rounded-xl shadow-[0_0_15px_rgba(16,185,129,0.5)]">
                                                    <span className="text-[10px] font-black text-white uppercase tracking-tighter">Aktif</span>
                                                </div>
                                            )}
                                        </div>

                                        <div className={`p-4 rounded-2xl mb-6 flex flex-col gap-2 ${year.is_active ? 'bg-black/40' : 'bg-neutral-950/40'}`}>
                                            <div className="flex items-center justify-between text-xs">
                                                <span className="text-gray-500 font-medium">Rentang Waktu</span>
                                            </div>
                                            {year.start_date && year.end_date ? (
                                                <p className={`text-sm font-bold tracking-tight ${year.is_active ? 'text-emerald-400' : 'text-gray-400'}`}>
                                                    {new Date(year.start_date).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' })}
                                                    <span className="mx-2 opacity-50">ÔÇó</span>
                                                    {new Date(year.end_date).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' })}
                                                </p>
                                            ) : (
                                                <p className="text-sm text-gray-600 italic">Belum diatur</p>
                                            )}
                                        </div>

                                        <div className="flex items-center gap-2">
                                            {!year.is_active ? (
                                                <button
                                                    onClick={() => handleSetActive(year.id)}
                                                    className="flex-1 flex items-center justify-center gap-2 px-4 py-2.5 bg-emerald-500/10 hover:bg-emerald-500 text-emerald-400 hover:text-white rounded-xl text-sm font-bold transition-all border border-emerald-500/20 hover:border-emerald-500"
                                                >
                                                    <CheckCircle2 className="w-4 h-4" />
                                                    Aktifkan
                                                </button>
                                            ) : (
                                                <div className="flex-1 flex items-center justify-center gap-2 px-4 py-2.5 bg-emerald-500/5 text-emerald-500/40 rounded-xl text-sm font-bold border border-emerald-500/10">
                                                    <CheckCircle2 className="w-4 h-4" />
                                                    Sedang Aktif
                                                </div>
                                            )}
                                            <div className="flex items-center gap-1.5 ml-2">
                                                <button
                                                    onClick={() => openEditModal(year)}
                                                    className="p-3 bg-neutral-800 hover:bg-neutral-700 text-gray-400 hover:text-white rounded-xl transition-all border border-white/5 active:scale-90"
                                                >
                                                    <Edit className="w-4 h-4" />
                                                </button>
                                                <button
                                                    onClick={() => handleDelete(year.id)}
                                                    className="p-3 bg-neutral-800 hover:bg-red-500/20 text-gray-400 hover:text-red-400 rounded-xl transition-all border border-white/5 active:scale-90"
                                                >
                                                    <Trash2 className="w-4 h-4" />
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </main>
            </div>

            {/* Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-50 flex items-center justify-center p-4 transition-all duration-300">
                    <div className="bg-neutral-900 rounded-[2.5rem] w-full max-w-md shadow-2xl border border-white/10 overflow-hidden transition-all scale-100 animate-in fade-in zoom-in duration-300">
                        <div className="p-8 border-b border-white/5 relative overflow-hidden">
                            <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/5 blur-3xl -mr-16 -mt-16"></div>
                            <h3 className="text-xl font-black text-white relative z-10 flex items-center gap-3">
                                <span className="w-1.5 h-6 bg-emerald-500 rounded-full"></span>
                                {editingYear ? 'Perbarui Tahun Ajaran' : 'Tahun Ajaran Baru'}
                            </h3>
                            <p className="text-gray-500 text-sm mt-2">Atur periode akademik untuk operasional sekolah</p>
                        </div>

                        <form onSubmit={handleSubmit} className="p-8 space-y-6">
                            <div className="space-y-2">
                                <label className="block text-xs font-black text-gray-500 uppercase tracking-widest ml-1">
                                    Nama Tahun Ajaran
                                </label>
                                <input
                                    type="text"
                                    value={formData.name}
                                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                    placeholder="Contoh: 2025/2026"
                                    required
                                    className="w-full px-5 py-4 bg-black/40 border border-white/5 rounded-2xl text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-emerald-500/50 focus:border-emerald-500/50 transition-all font-medium"
                                />
                            </div>

                            <div className="space-y-2">
                                <label className="block text-xs font-black text-gray-500 uppercase tracking-widest ml-1">
                                    Pilih Semester
                                </label>
                                <div className="grid grid-cols-2 gap-3">
                                    {['ganjil', 'genap'].map((sem) => (
                                        <button
                                            key={sem}
                                            type="button"
                                            onClick={() => setFormData({ ...formData, semester: sem as 'ganjil' | 'genap' })}
                                            className={`py-3.5 rounded-2xl text-sm font-bold capitalize transition-all border ${formData.semester === sem
                                                ? 'bg-emerald-500 border-emerald-400 text-white shadow-lg shadow-emerald-500/20'
                                                : 'bg-black/40 border-white/5 text-gray-500 hover:border-white/20'
                                                }`}
                                        >
                                            {sem}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="block text-xs font-black text-gray-500 uppercase tracking-widest ml-1">
                                        Mulai
                                    </label>
                                    <input
                                        type="date"
                                        value={formData.start_date}
                                        onChange={(e) => setFormData({ ...formData, start_date: e.target.value })}
                                        className="w-full px-4 py-3.5 bg-black/40 border border-white/5 rounded-2xl text-white focus:outline-none focus:ring-2 focus:ring-emerald-500/50 transition-all font-medium text-sm"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="block text-xs font-black text-gray-500 uppercase tracking-widest ml-1">
                                        Selesai
                                    </label>
                                    <input
                                        type="date"
                                        value={formData.end_date}
                                        onChange={(e) => setFormData({ ...formData, end_date: e.target.value })}
                                        className="w-full px-4 py-3.5 bg-black/40 border border-white/5 rounded-2xl text-white focus:outline-none focus:ring-2 focus:ring-emerald-500/50 transition-all font-medium text-sm"
                                    />
                                </div>
                            </div>

                            <div className="flex gap-4 pt-4">
                                <button
                                    type="button"
                                    onClick={() => setShowModal(false)}
                                    disabled={isSubmitting}
                                    className="flex-1 py-4 bg-neutral-800 hover:bg-neutral-700 text-gray-400 hover:text-white font-bold rounded-2xl transition-all disabled:opacity-50"
                                >
                                    Batal
                                </button>
                                <button
                                    type="submit"
                                    disabled={isSubmitting}
                                    className="flex-1 py-4 bg-emerald-600 hover:bg-emerald-500 text-white font-black rounded-2xl transition-all flex items-center justify-center gap-2 disabled:opacity-50 shadow-lg shadow-emerald-500/20 active:scale-95"
                                >
                                    {isSubmitting ? (
                                        <>
                                            <Loader2 className="w-5 h-5 animate-spin" />
                                            Proses...
                                        </>
                                    ) : (
                                        'Simpan Data'
                                    )}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import {
    getCurrentUser,
    User
} from '@/lib/auth';
import {
    Home,
    Plus,
    X,
    Shield,
    FileWarning,
    Calendar,
    Clock,
    CheckCircle2,
    TrendingUp,
    FileText,
    Users as UsersIcon
} from 'lucide-react';
import {
    ChartCard,
    ViolationTrendChart,
    ViolationRadarChart,
    PermissionStatsChart
} from '@/components/charts';

// ============================================
// Types
// ============================================

interface TrendData {
    name: string;
    violations: number;
}

interface RadarData {
    subject: string;
    value: number;
    fullMark: number;
}

interface PermStats {
    name: string;
    value: number;
}

interface Violator {
    student_id: string;
    student_name: string;
    class_name: string;
    total_points: number;
}

interface PermissionRequest {
    id: string;
    studentName: string;
    studentClass: string;
    parentName: string;
    parentPhone: string;
    reason: string;
    startDate: string;
    endDate: string;
    status: 'pending' | 'approved' | 'rejected';
    createdAt: string;
}

import { kesantrianService } from '@/lib/services/kesantrian';
import { studentsService, StudentWithRelations } from '@/lib/services/students';
import { Loader2 } from 'lucide-react';

export default function KesantrianDashboard() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    // Violation form
    const [showViolationModal, setShowViolationModal] = useState(false);
    const [violationForm, setViolationForm] = useState({
        studentId: '',
        category: 'ringan' as 'ringan' | 'sedang' | 'berat',
        points: 0,
        notes: '',
    });

    // Real Data State
    const [stats, setStats] = useState({
        totalViolations: 0,
        pendingPermissions: 0,
        dormOccupancy: '0/0',
        studentsOut: 0
    });
    const [permissions, setPermissions] = useState<PermissionRequest[]>([]);
    const [violationTrend, setViolationTrend] = useState<TrendData[]>([]);
    const [violationRadar, setViolationRadar] = useState<RadarData[]>([]);
    const [permissionStats, setPermissionStats] = useState<PermStats[]>([]);
    const [students, setStudents] = useState<StudentWithRelations[]>([]);
    const [topViolators, setTopViolators] = useState<Violator[]>([]);

    const [processingId, setProcessingId] = useState<string | null>(null);

    // UI state
    const [isSaving, setIsSaving] = useState(false);
    const [showSuccess, setShowSuccess] = useState(false);
    const [successMessage, setSuccessMessage] = useState('');

    const fetchData = useCallback(async () => {
        try {
            const [
                s,
                p,
                trend,
                radar,
                pStats,
                allStudents,
                violators
            ] = await Promise.all([
                kesantrianService.getStats(),
                kesantrianService.getPendingPermissions(),
                kesantrianService.getViolationTrend(),
                kesantrianService.getViolationRadar(),
                kesantrianService.getPermissionStats(),
                studentsService.getAll(),
                kesantrianService.getTopViolators()
            ]);

            setStats(s);
            setPermissions((p as unknown) as PermissionRequest[]);
            setViolationTrend(trend as unknown as TrendData[]);
            setViolationRadar(radar as unknown as RadarData[]);
            setPermissionStats(pStats as unknown as PermStats[]);
            setStudents(allStudents);
            setTopViolators((violators || []) as unknown as Violator[]);
            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching kesantrian data:', error);
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        // Role check handled by layout
        if (currentUser) {
            setUser(currentUser);
            fetchData();
        }
    }, [fetchData]);

    const handleSaveViolation = async () => {
        if (!user) return;
        setIsSaving(true);
        try {
            await kesantrianService.recordViolation({
                studentId: violationForm.studentId,
                type: violationForm.category,
                description: violationForm.notes,
                points: violationForm.points,
                reportedBy: user.id
            });

            setSuccessMessage('Pelanggaran berhasil dicatat!');
            setShowSuccess(true);
            setShowViolationModal(false);
            setViolationForm({ studentId: '', category: 'ringan', points: 0, notes: '' });
            fetchData(); // Refresh data
        } catch (err) {
            console.error('Failed to save violation:', err);
        } finally {
            setIsSaving(false);
            setTimeout(() => setShowSuccess(false), 3000);
        }
    };

    const handlePermissionAction = async (id: string, action: 'approved' | 'rejected') => {
        if (!user) return;
        setProcessingId(id);
        try {
            await kesantrianService.updatePermissionStatus(id, action, user.id);
            setPermissions(prev => prev.map(p =>
                p.id === id ? { ...p, status: action } : p
            ));
            setSuccessMessage(action === 'approved' ? 'Izin disetujui!' : 'Izin ditolak!');
            setShowSuccess(true);
            fetchData(); // Refresh stats
        } catch (err) {
            console.error('Failed to handle permission:', err);
        } finally {
            setProcessingId(null);
            setTimeout(() => setShowSuccess(false), 3000);
        }
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-96">
                <Loader2 className="w-8 h-8 text-rose-600 animate-spin" />
            </div>
        );
    }

    if (!user) return null;

    const pendingPermissions = permissions.filter(p => p.status === 'pending');

    return (
        <div>
            {/* Welcome Banner */}
            <div className="bg-gradient-to-r from-rose-500 to-orange-600 rounded-2xl p-6 lg:p-8 text-white mb-8 shadow-lg">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div>
                        <div className="flex items-center gap-3 mb-2">
                            <Shield className="w-8 h-8" />
                            <h2 className="text-2xl font-bold">Portal Kesantrian</h2>
                        </div>
                        <p className="text-rose-50 text-opacity-90">
                            Monitoring kedisiplinan dan perizinan santri terpadu.
                        </p>
                    </div>
                    <button
                        onClick={() => setShowViolationModal(true)}
                        className="flex items-center gap-2 px-6 py-3 bg-white text-rose-600 hover:bg-rose-50 rounded-xl font-bold transition-all shadow-md active:scale-95"
                    >
                        <Plus className="w-5 h-5" />
                        Catat Pelanggaran
                    </button>
                </div>
            </div>

            {/* Quick Stats */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                {[
                    { label: 'Total Pelanggaran', value: stats.totalViolations.toString(), icon: FileWarning, color: 'rose' },
                    { label: 'Pending Izin', value: stats.pendingPermissions.toString(), icon: Clock, color: 'orange' },
                    { label: 'Kamar Terisi', value: stats.dormOccupancy, icon: Home, color: 'amber' },
                    { label: 'Santri Izin', value: stats.studentsOut.toString(), icon: UsersIcon, color: 'blue' },
                ].map((stat, i) => (
                    <div key={i} className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
                        <div className="flex items-center justify-between mb-2">
                            <div className={`p-2.5 rounded-xl bg-${stat.color}-50 text-${stat.color}-600`}>
                                <stat.icon className="w-5 h-5" />
                            </div>
                            <TrendingUp className="w-4 h-4 text-emerald-500" />
                        </div>
                        <p className="text-sm text-gray-500 font-medium">{stat.label}</p>
                        <h3 className="text-xl font-bold text-gray-800">{stat.value}</h3>
                    </div>
                ))}
            </div>

            {/* Top Row: Violation Trend (Wide) */}
            <div className="mb-8">
                <ChartCard
                    title="Tren Kedisiplinan Bulan Ini"
                    subtitle="Statistik jumlah pelanggaran per minggu"
                    className="!p-6 h-80"
                >
                    <ViolationTrendChart data={violationTrend} height="100%" />
                </ChartCard>
            </div>

            {/* Middle Row: Radar + Bar */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
                <ChartCard
                    title="Peta Masalah Santri"
                    subtitle="Distribusi jenis pelanggaran yang sering terjadi"
                    className="h-96"
                >
                    <ViolationRadarChart data={violationRadar} height="100%" />
                </ChartCard>

                <ChartCard
                    title="Alasan Izin Keluar"
                    subtitle="Kategori alasan izin santri keluar lingkungan pesantren"
                    className="h-96"
                >
                    <PermissionStatsChart data={permissionStats} height="100%" />
                </ChartCard>
            </div>

            {/* Bottom Row: Recent Permissions */}
            <div className="space-y-4 mt-8">
                <div className="flex items-center justify-between">
                    <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                        <Shield className="w-5 h-5 text-orange-500" />
                        Permohonan Terbaru
                    </h3>
                    <button onClick={() => router.push('/dashboard/kesantrian/perizinan')} className="text-sm text-orange-600 font-semibold hover:underline">
                        Lihat Semua
                    </button>
                </div>

                {pendingPermissions.length === 0 ? (
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-12 text-center">
                        <div className="w-16 h-16 bg-emerald-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <CheckCircle2 className="w-8 h-8 text-emerald-600" />
                        </div>
                        <h4 className="font-semibold text-gray-800 mb-2">Semua Izin Telah Diproses</h4>
                        <p className="text-gray-500 text-sm">Tidak ada permohonan izin yang menunggu persetujuan.</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                        {pendingPermissions.map(request => (
                            <div key={request.id} className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden flex flex-col">
                                <div className="p-5 border-b border-gray-50 bg-gray-50/30">
                                    <div className="flex items-start justify-between">
                                        <div className="flex items-center gap-3">
                                            <div className="w-10 h-10 bg-orange-100 rounded-lg flex items-center justify-center font-bold text-orange-700">
                                                {request.studentName.charAt(0)}
                                            </div>
                                            <div>
                                                <h4 className="font-bold text-gray-800 leading-none mb-1">{request.studentName}</h4>
                                                <p className="text-xs text-gray-500 font-medium">Kelas {request.studentClass}</p>
                                            </div>
                                        </div>
                                        <span className="px-2.5 py-1 bg-amber-100 text-amber-700 text-[10px] font-bold rounded-full uppercase tracking-wider">
                                            Pending
                                        </span>
                                    </div>
                                </div>
                                <div className="p-5 flex-1 space-y-4">
                                    <div className="flex items-start gap-3">
                                        <FileText className="w-4 h-4 text-gray-400 mt-0.5" />
                                        <div>
                                            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-0.5">Alasan</p>
                                            <p className="text-sm font-medium text-gray-700">{request.reason}</p>
                                        </div>
                                    </div>
                                    <div className="flex items-start gap-3">
                                        <Calendar className="w-4 h-4 text-gray-400 mt-0.5" />
                                        <div>
                                            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-0.5">Masa Izin</p>
                                            <p className="text-sm font-medium text-gray-700">{request.startDate} - {request.endDate}</p>
                                        </div>
                                    </div>
                                </div>
                                <div className="p-4 bg-gray-50/50 flex gap-3">
                                    <button
                                        onClick={() => handlePermissionAction(request.id, 'rejected')}
                                        className="flex-1 py-2.5 border border-red-200 text-red-600 text-sm font-bold rounded-xl hover:bg-red-50 transition-colors"
                                    >
                                        Tolak
                                    </button>
                                    <button
                                        onClick={() => handlePermissionAction(request.id, 'approved')}
                                        className="flex-1 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white text-sm font-bold rounded-xl transition-colors shadow-lg shadow-emerald-200"
                                    >
                                        Setujui
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
            {/* Top Violators Section */}
            <div className="mt-8">
                <ChartCard
                    title="Top Pelanggaran Santri"
                    subtitle="Daftar santri dengan poin akumulasi tertinggi. Perlu perhatian khusus."
                    className="!p-0 overflow-hidden"
                >
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-gray-50 border-b border-gray-100">
                                <tr>
                                    <th className="text-left px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Nama Santri</th>
                                    <th className="text-left px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Kelas</th>
                                    <th className="text-left px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Total Poin</th>
                                    <th className="text-center px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-widest">Status</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-50">
                                {topViolators.map((v: Violator, index: number) => (
                                    <tr key={v.student_id} className="hover:bg-rose-50/10 transition-colors">
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-3">
                                                <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs ${index === 0 ? 'bg-rose-100 text-rose-700' : 'bg-gray-100 text-gray-600'}`}>
                                                    {index + 1}
                                                </div>
                                                <span className="font-bold text-gray-800">{v.student_name}</span>
                                            </div>
                                        </td>
                                        <td className="px-6 py-4 text-sm text-gray-600 font-medium">{v.class_name || '-'}</td>
                                        <td className="px-6 py-4">
                                            <span className="text-rose-600 font-black">{v.total_points} Poin</span>
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            {v.total_points >= 50 ? (
                                                <span className="px-3 py-1 bg-red-100 text-red-700 text-xs font-bold rounded-full">SP 1</span>
                                            ) : v.total_points >= 20 ? (
                                                <span className="px-3 py-1 bg-orange-100 text-orange-700 text-xs font-bold rounded-full">Perhatian</span>
                                            ) : (
                                                <span className="px-3 py-1 bg-emerald-100 text-emerald-700 text-xs font-bold rounded-full">Aman</span>
                                            )}
                                        </td>
                                    </tr>
                                ))}
                                {topViolators.length === 0 && (
                                    <tr>
                                        <td colSpan={4} className="px-6 py-8 text-center text-gray-500 text-sm">
                                            Belum ada data pelanggaran yang tercatat.
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </ChartCard>
            </div>

            {/* Violation Modal */}
            {showViolationModal && (
                <div className="fixed inset-0 bg-black/60 z-[60] flex items-center justify-center p-4 backdrop-blur-sm">
                    <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl animate-scale-in">
                        <div className="p-6 border-b border-gray-100 flex items-center justify-between">
                            <div>
                                <h3 className="text-lg font-bold text-gray-800">Catat Pelanggaran</h3>
                                <p className="text-xs text-gray-500 font-medium uppercase tracking-wider mt-0.5">Buku Hitam Digital</p>
                            </div>
                            <button onClick={() => setShowViolationModal(false)} className="p-2 hover:bg-gray-100 rounded-lg">
                                <X className="w-5 h-5 text-gray-400" />
                            </button>
                        </div>
                        <div className="p-6 space-y-5">
                            <div>
                                <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">Pilih Santri</label>
                                <select
                                    value={violationForm.studentId}
                                    onChange={(e) => setViolationForm({ ...violationForm, studentId: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-rose-500/20 focus:border-rose-500 font-medium"
                                >
                                    <option value="">Cari nama santri...</option>
                                    {students.map(student => (
                                        <option key={student.id} value={student.id}>
                                            {student.name} - Kelas {student.class?.name || 'N/A'}
                                        </option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">Jenis Pelanggaran</label>
                                <select
                                    value={violationForm.category}
                                    onChange={(e) => {
                                        const cat = e.target.value as 'ringan' | 'sedang' | 'berat';
                                        const points = cat === 'ringan' ? 5 : cat === 'sedang' ? 15 : 50;
                                        setViolationForm({
                                            ...violationForm,
                                            category: cat,
                                            points: points
                                        });
                                    }}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-rose-500/20 focus:border-rose-500 font-medium"
                                >
                                    <option value="">Pilih kategori...</option>
                                    <option value="ringan">Ringan (-5 poin)</option>
                                    <option value="sedang">Sedang (-15 poin)</option>
                                    <option value="berat">Berat (-50 poin)</option>
                                </select>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">Poin (Otomatis)</label>
                                    <input
                                        type="number"
                                        readOnly
                                        value={violationForm.points}
                                        className="w-full px-4 py-3 bg-red-50 border border-red-100 rounded-xl text-red-600 font-bold focus:outline-none"
                                    />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">Tanggal</label>
                                    <input
                                        type="text"
                                        readOnly
                                        value={new Date().toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric' })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl text-gray-500 font-medium focus:outline-none"
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">Catatan Musyrif</label>
                                <textarea
                                    rows={3}
                                    value={violationForm.notes}
                                    onChange={(e) => setViolationForm({ ...violationForm, notes: e.target.value })}
                                    placeholder="Ketikan kronologi singkat..."
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-rose-500/20 focus:border-rose-500 resize-none font-medium"
                                />
                            </div>
                        </div>
                        <div className="p-6 border-t border-gray-100 flex gap-3 bg-gray-50/50">
                            <button
                                onClick={() => setShowViolationModal(false)}
                                className="flex-1 py-3 text-gray-500 font-bold hover:text-gray-700 transition-colors"
                            >
                                Batal
                            </button>
                            <button
                                onClick={handleSaveViolation}
                                disabled={!violationForm.studentId || !violationForm.category || isSaving}
                                className="flex-[2] py-3 bg-red-600 hover:bg-red-700 text-white font-bold rounded-xl transition-all shadow-md active:scale-95 disabled:opacity-50"
                            >
                                {isSaving ? 'Menyimpan...' : 'Simpan Pelanggaran'}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Success Toast */}
            {showSuccess && (
                <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[100] bg-gray-900/90 backdrop-blur-md text-white px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 animate-slide-up">
                    <CheckCircle2 className="w-5 h-5 text-emerald-400" />
                    <span className="text-sm font-bold tracking-wide">{successMessage}</span>
                </div>
            )}
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import Link from 'next/link';
import {
    getCurrentUser,
    User
} from '@/lib/auth';
import {
    ArrowLeft,
    Shield,
    Search,
    Check,
    X,
    Clock,
    History,
    Calendar,
    Phone,
    UserCheck,
    MapPin
} from 'lucide-react';

// ============================================
// Types & Data
// ============================================

import { permissionsService, PermissionWithRelations } from '@/lib/services/permissions';
import { Loader2 } from 'lucide-react';

import PermissionModal from '@/components/admin/PermissionModal';
import { Plus } from 'lucide-react';

export default function PerizinanPage() {
    const [user, setUser] = useState<User | null>(null);
    const [activeTab, setActiveTab] = useState<'pending' | 'history'>('pending');
    const [searchQuery, setSearchQuery] = useState('');
    const [permits, setPermits] = useState<PermissionWithRelations[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isManualModalOpen, setIsManualModalOpen] = useState(false);

    const fetchPermits = async () => {
        try {
            setIsLoading(true);
            const data = activeTab === 'pending'
                ? await permissionsService.getPending()
                : await permissionsService.getHistory();
            setPermits(data);
            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching permits:', error);
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (currentUser) {
            const timer = requestAnimationFrame(() => {
                setUser(currentUser);
                fetchPermits();
            });
            return () => cancelAnimationFrame(timer);
        }
    }, [activeTab]);

    const handleAction = async (id: string, status: 'approved' | 'rejected') => {
        if (!user) return;
        try {
            await permissionsService.updateStatus(id, status, user.id);
            fetchPermits();
        } catch (_error) {
            alert('Gagal memperbarui status perizinan');
        }
    };

    const handleManualSubmit = async (data: any) => { // eslint-disable-line @typescript-eslint/no-explicit-any
        try {
            await permissionsService.create(data);
            setIsManualModalOpen(false);
            // If we are in 'history' tab, refresh. If in 'pending', switch to 'history' or just refresh?
            // Since manual permits are auto-approved, they go to history.
            if (activeTab === 'history') {
                fetchPermits();
            } else {
                setActiveTab('history'); // Switch to history to see the new permit
            }
        } catch (error) {
            throw error; // Let modal handle error alert
        }
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-96">
                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin" />
            </div>
        );
    }

    const filteredPermits = permits.filter(p => {
        const matchesSearch = p.students?.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
            p.reason.toLowerCase().includes(searchQuery.toLowerCase());
        return matchesSearch;
    });

    return (
        <div>
            {/* Header */}
            <div className="mb-6">
                <Link
                    href="/dashboard/kesantrian"
                    className="inline-flex items-center gap-2 text-sm text-gray-400 hover:text-gray-600 mb-2 transition-colors font-medium"
                >
                    <ArrowLeft className="w-4 h-4" />
                    Kembali ke Dashboard
                </Link>
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                    <div>
                        <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-3">
                            <UserCheck className="w-8 h-8 text-indigo-600" />
                            Manajemen Perizinan
                        </h1>
                        <p className="text-gray-500 text-sm">
                            Kelola permohonan keluar santri dan monitoring status kepulangan
                        </p>
                    </div>
                    <button
                        onClick={() => setIsManualModalOpen(true)}
                        className="flex items-center gap-2 px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-2xl transition-all shadow-md active:scale-95"
                    >
                        <Plus className="w-5 h-5" />
                        Buat Izin Manual
                    </button>
                </div>
            </div>

            <PermissionModal
                isOpen={isManualModalOpen}
                onClose={() => setIsManualModalOpen(false)}
                onSubmit={handleManualSubmit}
            />

            {/* Tab Navigation & Search */}
            <div className="flex flex-col xl:flex-row gap-4 mb-8">
                <div className="flex bg-white p-1 rounded-2xl border border-gray-100 shadow-sm">
                    <button
                        onClick={() => setActiveTab('pending')}
                        className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-bold text-sm transition-all ${activeTab === 'pending'
                            ? 'bg-indigo-600 text-white shadow-md'
                            : 'text-gray-500 hover:bg-gray-50'
                            }`}
                    >
                        <Clock className="w-4 h-4" />
                        Menunggu Persetujuan
                        {permits.filter(p => p.status === 'pending').length > 0 && (
                            <span className={`px-2 py-0.5 rounded-full text-[10px] ${activeTab === 'pending' ? 'bg-white/20' : 'bg-red-50 text-red-600'}`}>
                                {permits.filter(p => p.status === 'pending').length}
                            </span>
                        )}
                    </button>
                    <button
                        onClick={() => setActiveTab('history')}
                        className={`flex items-center gap-2 px-6 py-2.5 rounded-xl font-bold text-sm transition-all ${activeTab === 'history'
                            ? 'bg-indigo-600 text-white shadow-md'
                            : 'text-gray-500 hover:bg-gray-50'
                            }`}
                    >
                        <History className="w-4 h-4" />
                        Riwayat Izin
                    </button>
                </div>

                <div className="flex-1 relative">
                    <Search className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                    <input
                        type="text"
                        placeholder="Cari nama santri atau alasan..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full pl-12 pr-4 py-3 bg-white border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 shadow-sm font-medium text-gray-700"
                    />
                </div>
            </div>

            {/* Permits List */}
            <div className="space-y-4">
                {filteredPermits.map((p) => (
                    <div key={p.id} className="bg-white rounded-[2rem] border border-gray-100 shadow-sm overflow-hidden group hover:shadow-md transition-all">
                        <div className="p-6">
                            <div className="flex flex-col lg:flex-row gap-6">
                                {/* Santri Info */}
                                <div className="lg:w-1/4">
                                    <div className="flex items-center gap-4 mb-4">
                                        <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center font-bold text-indigo-700 shadow-sm">
                                            {p.students?.name?.charAt(0) || '?'}
                                        </div>
                                        <div>
                                            <h4 className="font-extrabold text-gray-800 leading-tight">{p.students?.name || 'Unknown'}</h4>
                                            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-0.5">Kelas {p.students?.classes?.name || '-'}</p>
                                        </div>
                                    </div>
                                    <div className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${p.status === 'pending' ? 'bg-amber-100 text-amber-700' :
                                        p.status === 'approved' ? 'bg-emerald-100 text-emerald-700' :
                                            p.status === 'completed' ? 'bg-blue-100 text-blue-700' : 'bg-rose-100 text-rose-700'
                                        }`}>
                                        {p.status === 'pending' ? 'Menunggu' :
                                            p.status === 'approved' ? 'Disetujui' :
                                                p.status === 'completed' ? 'Kembali' : 'Ditolak'}
                                    </div>
                                </div>

                                {/* Details */}
                                <div className="flex-1 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                    <div className="space-y-3">
                                        <div className="flex items-start gap-3">
                                            <div className="p-2 bg-gray-50 rounded-lg text-gray-400"><Calendar className="w-4 h-4" /></div>
                                            <div>
                                                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest leading-none mb-1">Durasi Izin</p>
                                                <p className="text-sm font-bold text-gray-700">{new Date(p.start_date).toLocaleDateString('id-ID')} - {new Date(p.end_date).toLocaleDateString('id-ID')}</p>
                                            </div>
                                        </div>
                                        <div className="flex items-start gap-3">
                                            <div className="p-2 bg-gray-50 rounded-lg text-gray-400"><MapPin className="w-4 h-4" /></div>
                                            <div>
                                                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest leading-none mb-1">Tipe Izin</p>
                                                <p className="text-sm font-bold text-gray-700 uppercase">{p.permission_type || '-'}</p>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="lg:col-span-2">
                                        <div className="flex items-start gap-3">
                                            <div className="p-2 bg-gray-50 rounded-lg text-gray-400 font-bold text-xs">?</div>
                                            <div>
                                                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest leading-none mb-1">Alasan Pengajuan</p>
                                                <p className="text-sm font-medium text-gray-600 leading-relaxed italic">&quot;{p.reason}&quot;</p>
                                            </div>
                                        </div>
                                        <div className="mt-4 flex items-center gap-4">
                                            <div className="flex -space-x-2">
                                                <div className="w-8 h-8 rounded-full bg-gray-100 border-2 border-white flex items-center justify-center"><Phone className="w-3.5 h-3.5 text-gray-400" /></div>
                                                <div className="w-8 h-8 rounded-full bg-indigo-50 border-2 border-white flex items-center justify-center"><span className="text-[10px] font-bold text-indigo-600">W</span></div>
                                            </div>
                                            <p className="text-xs font-bold text-gray-500">Kontak Wali: {p.students?.parent_phone || '-'}</p>
                                        </div>
                                    </div>
                                </div>

                                {/* Actions */}
                                <div className="lg:w-1/6 flex md:flex-row lg:flex-col gap-2 justify-center">
                                    {p.status === 'pending' ? (
                                        <>
                                            <button
                                                onClick={() => handleAction(p.id, 'approved')}
                                                className="flex-1 lg:flex-none py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-xl text-xs transition-all flex items-center justify-center gap-2 shadow-sm"
                                            >
                                                <Check className="w-4 h-4" /> SETUJU
                                            </button>
                                            <button
                                                onClick={() => handleAction(p.id, 'rejected')}
                                                className="flex-1 lg:flex-none py-2.5 border border-rose-200 text-rose-600 font-bold rounded-xl text-xs hover:bg-rose-50 transition-all flex items-center justify-center gap-2"
                                            >
                                                <X className="w-4 h-4" /> TOLAK
                                            </button>
                                        </>
                                    ) : (
                                        <button className="w-full py-2.5 bg-gray-50 text-gray-400 font-bold rounded-xl text-[10px] uppercase tracking-widest group-hover:bg-indigo-50 group-hover:text-indigo-600 transition-all">
                                            Lihat Detail
                                        </button>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                ))}
                {filteredPermits.length === 0 && (
                    <div className="p-16 text-center bg-white rounded-[2rem] border border-dashed border-gray-200">
                        <Shield className="w-12 h-12 text-gray-200 mx-auto mb-4" />
                        <h3 className="font-bold text-gray-800">Antrian Bersih!</h3>
                        <p className="text-gray-400 text-sm">Tidak ada permohonan izin dalam kategori ini.</p>
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    TrendingUp,
    TrendingDown,
    Wallet,
    FileSpreadsheet,
    Loader2,
    AlertCircle,
    PieChart,
    ArrowLeft,
    FileText,
    Calendar,
    Download,
    CheckCircle,
    Clock
} from 'lucide-react';

import { financeService } from '@/lib/services/finance';
import * as XLSX from 'xlsx';

interface IncomeItem {
    type: string;
    amount: number;
}

interface ExpenseItem {
    category: string;
    amount: number;
}

interface ReportData {
    summary: {
        totalInvoiced: number;
        totalPaid: number;
        totalUnpaid: number;
        totalExpense: number;
        netIncome: number;
        collectionRate: number;
    };
    invoiceCount: {
        total: number;
        paid: number;
        partial: number;
        pending: number;
    };
    incomeByType: IncomeItem[];
    expenseByCategory: ExpenseItem[];
}


export default function LaporanPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);

    // Set default dates to current month
    const now = new Date();
    const firstDay = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];

    const [startDate, setStartDate] = useState(firstDay);
    const [endDate, setEndDate] = useState(lastDay);
    const [isLoading, setIsLoading] = useState(true);
    const [reportData, setReportData] = useState<ReportData | null>(null);

    const fetchReport = useCallback(async () => {
        try {
            setIsLoading(true);
            const data = await financeService.getReport({ startDate, endDate });
            setReportData(data);
        } catch (error) {
            console.error('Error fetching report:', error);
        } finally {
            setIsLoading(false);
        }
    }, [startDate, endDate]);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_keuangan' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchReport();
    }, [router, fetchReport]);

    const handleExport = async () => {
        try {
            const data = await financeService.getExportData(startDate, endDate);

            // 1. Summary Sheet
            const summaryData = [
                ['Laporan Keuangan Smart Pesantren'],
                [`Periode: ${startDate} s/d ${endDate}`],
                [''],
                ['Ringkasan Pemasukan & Pengeluaran'],
                ['Total Tagihan', formatCurrency(summary.totalInvoiced)],
                ['Total Pemasukan (Terbayar)', formatCurrency(summary.totalPaid)],
                ['Total Pengeluaran', formatCurrency(summary.totalExpense)],
                ['Laba Bersih / Surplus', formatCurrency(summary.netIncome)],
                ['Total Tunggakan', formatCurrency(summary.totalUnpaid)]
            ];
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const wsSummary = XLSX.utils.aoa_to_sheet(summaryData as any);

            // 2. Invoices Sheet (Detailed)
            const invoiceRows = data.invoices.map((inv: {
                id: string;
                created_at: string;
                students?: { name: string; classes?: { name: string } };
                invoice_type: string;
                amount: number;
                payments?: { amount: number }[];
                status: string;
                due_date: string;
            }) => {
                const totalPaid = (inv.payments || []).reduce((sum: number, p: { amount: number }) => sum + Number(p.amount), 0);
                const remaining = Number(inv.amount) - totalPaid;
                return {
                    'Invoice ID': inv.id,
                    'Tanggal': new Date(inv.created_at).toLocaleDateString('id-ID'),
                    'Nama Santri': inv.students?.name || 'Unknown',
                    'Kelas': inv.students?.classes?.name || '-',
                    'Jenis Tagihan': inv.invoice_type,
                    'Nominal Tagihan': Number(inv.amount),
                    'Sudah Bayar': totalPaid,
                    'Sisa Tagihan': remaining,
                    'Status': inv.status === 'paid' ? 'Lunas' : (inv.status === 'partial' ? 'Cicilan' : 'Belum Lunas'),
                    'Jatuh Tempo': new Date(inv.due_date).toLocaleDateString('id-ID')
                };
            });
            const wsInvoices = XLSX.utils.json_to_sheet(invoiceRows);

            // 3. Expenses Sheet
            const expenseRows = data.expenses.map((exp: {
                expense_date: string;
                category: string;
                description: string;
                amount: number;
                pic?: string;
            }) => ({
                'Tanggal': new Date(exp.expense_date).toLocaleDateString('id-ID'),
                'Kategori': exp.category,
                'Deskripsi': exp.description,
                'Nominal': Number(exp.amount),
                'PIC': exp.pic || '-'
            }));
            const wsExpenses = XLSX.utils.json_to_sheet(expenseRows);

            // Create Workbook
            const wb = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(wb, wsSummary, "Ringkasan");
            XLSX.utils.book_append_sheet(wb, wsInvoices, "Data Tagihan");
            XLSX.utils.book_append_sheet(wb, wsExpenses, "Data Pengeluaran");

            // Download
            XLSX.writeFile(wb, `Laporan_Keuangan_${startDate}_${endDate}.xlsx`);
        } catch (error) {
            console.error('Export failed:', error);
            alert('Gagal mengexport data.');
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const formatCurrency = (amount: number | undefined | null) => {
        if (amount === undefined || amount === null || isNaN(amount)) return 'Rp 0';
        return new Intl.NumberFormat('id-ID', {
            style: 'currency',
            currency: 'IDR',
            minimumFractionDigits: 0
        }).format(amount);
    };

    if (!user || isLoading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-emerald-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
                    <span>Menyiapkan Laporan Keuangan...</span>
                </div>
            </div>
        );
    }

    const summary = reportData?.summary || {
        totalInvoiced: 0,
        totalPaid: 0,
        totalUnpaid: 0,
        totalExpense: 0,
        netIncome: 0,
        collectionRate: 0
    };

    const invoiceCount = reportData?.invoiceCount || {
        total: 0,
        paid: 0,
        partial: 0,
        pending: 0
    };

    const incomeByType = reportData?.incomeByType || [];
    const expenseByCategory = reportData?.expenseByCategory || [];

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Sidebar */}
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Breadcrumb & Title */}
                    <div className="mb-6">
                        <Link
                            href="/dashboard/keuangan"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 mb-2"
                        >
                            <ArrowLeft className="w-4 h-4" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                            <div>
                                <h1 className="text-xl lg:text-2xl font-bold text-gray-800 flex items-center gap-3">
                                    <FileText className="w-6 lg:w-7 h-6 lg:h-7 text-emerald-600" />
                                    Laporan Keuangan
                                </h1>
                                <p className="text-gray-500 text-sm lg:text-base">
                                    Ringkasan dan export laporan keuangan
                                </p>
                            </div>
                            <div className="flex flex-wrap gap-2">
                                <button
                                    onClick={handleExport}
                                    className="flex items-center gap-2 px-3 lg:px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-sm font-medium rounded-xl transition-colors"
                                >
                                    <FileSpreadsheet className="w-4 h-4" />
                                    <span className="hidden sm:inline">Export</span> CSV
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Date Filter */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 mb-6">
                        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3">
                            <div className="flex items-center gap-2 text-gray-600">
                                <Calendar className="w-5 h-5" />
                                <span className="font-medium text-sm">Periode:</span>
                            </div>
                            <div className="flex flex-wrap items-center gap-2 w-full sm:w-auto">
                                <input
                                    type="date"
                                    value={startDate}
                                    onChange={(e) => setStartDate(e.target.value)}
                                    className="flex-1 sm:flex-none px-3 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 text-sm"
                                />
                                <span className="text-gray-400 text-sm">s/d</span>
                                <input
                                    type="date"
                                    value={endDate}
                                    onChange={(e) => setEndDate(e.target.value)}
                                    className="flex-1 sm:flex-none px-3 py-2 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 text-sm"
                                />
                                <button
                                    onClick={fetchReport}
                                    className="px-4 py-2 bg-gray-800 hover:bg-gray-900 text-white text-sm font-medium rounded-xl transition-all active:scale-95"
                                >
                                    Filter
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Summary Cards */}
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 lg:gap-6 mb-6">
                        {/* Total Terbayar */}
                        <div className="bg-gradient-to-br from-emerald-500 to-emerald-600 rounded-xl lg:rounded-2xl p-4 lg:p-6 text-white">
                            <div className="flex items-center gap-2 lg:gap-3 mb-2 lg:mb-4">
                                <div className="w-8 lg:w-12 h-8 lg:h-12 bg-white/20 rounded-lg lg:rounded-xl flex items-center justify-center">
                                    <TrendingUp className="w-4 lg:w-6 h-4 lg:h-6" />
                                </div>
                                <div>
                                    <p className="text-emerald-100 text-xs lg:text-sm">Total Terbayar</p>
                                    <p className="text-lg lg:text-2xl font-bold">{formatCurrency(summary.totalPaid)}</p>
                                </div>
                            </div>
                            <div className="text-xs lg:text-sm text-emerald-100">
                                {invoiceCount.paid} tagihan lunas
                            </div>
                        </div>

                        {/* Total Pengeluaran */}
                        <div className="bg-gradient-to-br from-red-500 to-rose-600 rounded-xl lg:rounded-2xl p-4 lg:p-6 text-white">
                            <div className="flex items-center gap-2 lg:gap-3 mb-2 lg:mb-4">
                                <div className="w-8 lg:w-12 h-8 lg:h-12 bg-white/20 rounded-lg lg:rounded-xl flex items-center justify-center">
                                    <TrendingDown className="w-4 lg:w-6 h-4 lg:h-6" />
                                </div>
                                <div>
                                    <p className="text-red-100 text-xs lg:text-sm">Total Pengeluaran</p>
                                    <p className="text-lg lg:text-2xl font-bold">{formatCurrency(summary.totalExpense)}</p>
                                </div>
                            </div>
                            <div className="text-xs lg:text-sm text-red-100">
                                {expenseByCategory.length} kategori
                            </div>
                        </div>

                        {/* Laba Bersih */}
                        <div className="bg-gradient-to-br from-violet-500 to-purple-600 rounded-xl lg:rounded-2xl p-4 lg:p-6 text-white">
                            <div className="flex items-center gap-2 lg:gap-3 mb-2 lg:mb-4">
                                <div className="w-8 lg:w-12 h-8 lg:h-12 bg-white/20 rounded-lg lg:rounded-xl flex items-center justify-center">
                                    <Wallet className="w-4 lg:w-6 h-4 lg:h-6" />
                                </div>
                                <div>
                                    <p className="text-violet-100 text-xs lg:text-sm">Laba Bersih</p>
                                    <p className="text-lg lg:text-2xl font-bold">{formatCurrency(summary.netIncome)}</p>
                                </div>
                            </div>
                            <div className="text-xs lg:text-sm text-violet-100">
                                Margin {summary.collectionRate}%
                            </div>
                        </div>

                        {/* Tunggakan */}
                        <div className="bg-gradient-to-br from-amber-500 to-orange-600 rounded-xl lg:rounded-2xl p-4 lg:p-6 text-white">
                            <div className="flex items-center gap-2 lg:gap-3 mb-2 lg:mb-4">
                                <div className="w-8 lg:w-12 h-8 lg:h-12 bg-white/20 rounded-lg lg:rounded-xl flex items-center justify-center">
                                    <AlertCircle className="w-4 lg:w-6 h-4 lg:h-6" />
                                </div>
                                <div>
                                    <p className="text-amber-100 text-xs lg:text-sm">Tunggakan</p>
                                    <p className="text-lg lg:text-2xl font-bold">{formatCurrency(summary.totalUnpaid)}</p>
                                </div>
                            </div>
                            <div className="text-xs lg:text-sm text-amber-100">
                                {invoiceCount.pending + invoiceCount.partial} tagihan
                            </div>
                        </div>
                    </div>

                    {/* Breakdown Cards */}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
                        {/* Income Breakdown */}
                        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 lg:p-6">
                            <h3 className="font-semibold text-gray-800 mb-4 flex items-center gap-2">
                                <TrendingUp className="w-5 h-5 text-emerald-600" />
                                Pemasukan per Jenis
                            </h3>
                            {incomeByType.length > 0 ? (
                                <div className="space-y-3">
                                    {incomeByType.map((item: IncomeItem, idx: number) => (
                                        <div key={idx} className="flex items-center justify-between p-3 bg-gray-50 rounded-xl">
                                            <span className="text-gray-700 text-sm font-medium">{item.type || 'Lainnya'}</span>
                                            <span className="text-emerald-600 font-semibold">{formatCurrency(item.amount)}</span>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                <p className="text-gray-400 italic text-center py-8">Tidak ada data pemasukan</p>
                            )}
                        </div>

                        {/* Expense Breakdown */}
                        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 lg:p-6">
                            <h3 className="font-semibold text-gray-800 mb-4 flex items-center gap-2">
                                <TrendingDown className="w-5 h-5 text-red-600" />
                                Pengeluaran per Kategori
                            </h3>
                            {expenseByCategory.length > 0 ? (
                                <div className="space-y-3">
                                    {expenseByCategory.map((item: ExpenseItem, idx: number) => (
                                        <div key={idx} className="flex items-center justify-between p-3 bg-gray-50 rounded-xl">
                                            <span className="text-gray-700 text-sm font-medium capitalize">{item.category || 'Lainnya'}</span>
                                            <span className="text-red-600 font-semibold">{formatCurrency(item.amount)}</span>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                <p className="text-gray-400 italic text-center py-8">Tidak ada data pengeluaran</p>
                            )}
                        </div>
                    </div>

                    {/* Invoice Statistics */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 lg:p-6">
                        <h3 className="font-semibold text-gray-800 mb-4 flex items-center gap-2">
                            <PieChart className="w-5 h-5 text-blue-600" />
                            Statistik Tagihan
                        </h3>
                        <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                            <div className="text-center p-4 bg-blue-50 rounded-xl">
                                <p className="text-2xl lg:text-3xl font-bold text-blue-600">{invoiceCount.total}</p>
                                <p className="text-sm text-gray-500">Total Tagihan</p>
                            </div>
                            <div className="text-center p-4 bg-emerald-50 rounded-xl">
                                <p className="text-2xl lg:text-3xl font-bold text-emerald-600">{invoiceCount.paid}</p>
                                <p className="text-sm text-gray-500">Lunas</p>
                            </div>
                            <div className="text-center p-4 bg-amber-50 rounded-xl">
                                <p className="text-2xl lg:text-3xl font-bold text-amber-600">{invoiceCount.partial}</p>
                                <p className="text-sm text-gray-500">Cicilan</p>
                            </div>
                            <div className="text-center p-4 bg-red-600 rounded-xl shadow-lg shadow-red-500/20">
                                <p className="text-2xl lg:text-3xl font-bold text-white">{invoiceCount.pending}</p>
                                <p className="text-sm text-red-100">Belum Bayar</p>
                            </div>
                        </div>

                        {/* Collection Rate Progress */}
                        <div className="mt-6">
                            <div className="flex justify-between items-center mb-2">
                                <span className="text-sm text-gray-600">Tingkat Koleksi Pembayaran</span>
                                <span className="text-sm font-semibold text-emerald-600">{summary.collectionRate}%</span>
                            </div>
                            <div className="w-full bg-gray-200 rounded-full h-3">
                                <div
                                    className="bg-gradient-to-r from-emerald-500 to-emerald-600 h-3 rounded-full transition-all duration-500"
                                    style={{ width: `${Math.min(summary.collectionRate, 100)}%` }}
                                ></div>
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import {
    ChartCard,
    CashflowChart,
    InvoiceStatusChart,
    DailyIncomeChart,
    PaymentMethodChart
} from '@/components/charts';
import {
    Wallet,
    Receipt,
    TrendingDown,
    DollarSign,
    PiggyBank,
    ArrowUpRight,
    Plus,
    Send,
    CheckCircle2,
    AlertCircle,
    X,
    Loader2
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';

// ============================================
// Types
// ============================================

interface Transaction {
    id: string;
    studentName: string;
    type: string;
    amount: number;
    date: string;
    status: 'success' | 'pending';
}

interface UnpaidStudent {
    id: string;
    name: string;
    class: string;
    type: string;
    amount: number;
    dueDate: string;
    parentPhone: string;
}

interface CashflowData {
    name: string;
    income: number;
    expense: number;
}

interface InvoiceStatusData {
    name: string;
    value: number;
    color: string;
}

interface DailyIncomeData {
    day: string;
    amount: number;
}

interface PaymentMethodData {
    name: string;
    value: number;
    color: string;
}

interface ClassItem {
    id: string;
    name: string;
}

interface StudentItem {
    id: string;
    name: string;
    nis: string;
}

interface InvoiceTypeItem {
    id: string;
    name: string;
    amount: number;
}

import { financeService, FinanceStats } from '@/lib/services/finance';
import { studentsService } from '@/lib/services/students';
import { classesService } from '@/lib/services/classes';

// ============================================
// Mock Data (kept for now as it's used in form and not fetched)
// ============================================

const INVOICE_TYPES = [
    { id: 'spp', name: 'SPP Bulanan', amount: 500000 },
    { id: 'gedung', name: 'Uang Gedung', amount: 2000000 },
    { id: 'makan', name: 'Uang Makan', amount: 300000 },
    { id: 'kitab', name: 'Uang Kitab', amount: 250000 },
    { id: 'seragam', name: 'Seragam', amount: 750000 },
];


export default function KeuanganDashboard() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [showInvoiceModal, setShowInvoiceModal] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [isLoading, setIsLoading] = useState(true);

    // Real Data State
    const [stats, setStats] = useState<FinanceStats>({
        incomeThisMonth: 0,
        expenseThisMonth: 0,
        unpaidCount: 0,
        balance: 0,
        paidCount: 0,
        partialCount: 0
    });
    const [transactions, setTransactions] = useState<Transaction[]>([]);
    const [unpaidStudents, setUnpaidStudents] = useState<UnpaidStudent[]>([]);
    const [cashflowData, setCashflowData] = useState<CashflowData[]>([]);
    const [invoiceStatusData, setInvoiceStatusData] = useState<InvoiceStatusData[]>([]);
    const [dailyIncomeData, setDailyIncomeData] = useState<DailyIncomeData[]>([]);
    const [paymentMethodData, setPaymentMethodData] = useState<PaymentMethodData[]>([]);
    const [classes, setClasses] = useState<ClassItem[]>([]);
    const [invoiceTypes, setInvoiceTypes] = useState<InvoiceTypeItem[]>([]);

    // Invoice form state
    const [invoiceForm, setInvoiceForm] = useState({
        targetType: 'class', // 'class' or 'individual'
        class: '',
        studentId: '',
        invoiceType: '',
        amount: 0,
        dueDate: '',
        notes: '',
    });

    // Reminder state
    const [sendingReminder, setSendingReminder] = useState<string | null>(null);
    const [reminderSent, setReminderSent] = useState<string[]>([]);

    const [students, setStudents] = useState<StudentItem[]>([]);

    const fetchData = useCallback(async () => {
        try {
            const [
                fStats,
                recentTx,
                unpaid,
                cashflow,
                statusDist,
                methodDist,
                dailyInc,
                allClasses,
                allStudents,
                allTypes
            ] = await Promise.all([
                financeService.getStats(),
                financeService.getRecentTransactions(),
                financeService.getUnpaidInvoices(),
                financeService.getCashflow(),
                financeService.getInvoiceStatusDistribution(),
                financeService.getPaymentMethodDistribution(),
                financeService.getDailyIncome(30),
                classesService.getAll(),
                studentsService.getAll(),
                financeService.getInvoiceTypes()
            ]);

            setStats(fStats);
            setTransactions(recentTx);
            setUnpaidStudents(unpaid);
            setCashflowData(cashflow);
            setInvoiceStatusData(statusDist);
            setPaymentMethodData(methodDist);
            setDailyIncomeData(dailyInc);
            setClasses(allClasses);
            setStudents(allStudents);
            setInvoiceTypes(allTypes);

            setIsLoading(false);
        } catch (err) {
            console.error('Error fetching finance data:', err);
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_keuangan' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData();
    }, [router, fetchData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleSendReminder = async (studentId: string) => {
        setSendingReminder(studentId);
        // In a real app, this would trigger a WhatsApp/Email API
        await new Promise(r => setTimeout(r, 1000));
        setSendingReminder(null);
        setReminderSent([...reminderSent, studentId]);
        alert('Pengingat telah dikirim ke Wali Santri via WhatsApp (Simulasi).');
    };

    const handleCreateInvoice = async () => {
        if (invoiceForm.targetType === 'class' && !invoiceForm.class) {
            alert('Harap pilih kelas!');
            return;
        }
        if (invoiceForm.targetType === 'individual' && !invoiceForm.studentId) {
            alert('Harap pilih santri!');
            return;
        }
        if (!invoiceForm.invoiceType || !invoiceForm.amount || !invoiceForm.dueDate) {
            alert('Harap isi semua kolom yang wajib.');
            return;
        }

        try {
            setIsLoading(true);
            await financeService.createInvoice({
                targetType: invoiceForm.targetType,
                studentId: invoiceForm.studentId,
                classId: invoiceForm.class,
                invoiceType: invoiceForm.invoiceType,
                amount: invoiceForm.amount,
                dueDate: invoiceForm.dueDate,
                notes: invoiceForm.notes
            });

            alert('Invoice berhasil dibuat!');
            setShowInvoiceModal(false);
            setInvoiceForm({
                targetType: 'class',
                class: '',
                studentId: '',
                invoiceType: '',
                amount: 0,
                dueDate: '',
                notes: '',
            });
            fetchData();
        } catch (err: unknown) {
            console.error('Error creating invoice:', err);
            const message = err instanceof Error ? err.message : 'Unknown error';
            alert('Gagal membuat invoice: ' + message);
        } finally {
            setIsLoading(false);
        }
    };

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-emerald-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
                    <span>Loading Finansial...</span>
                </div>
            </div>
        );
    }

    // Format currency
    const formatCurrency = (amount: number) => {
        if (amount === undefined || amount === null || isNaN(amount)) return 'Rp 0';
        return new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(amount);
    };


    return (
        <div className="min-h-screen bg-gray-50">
            {/* Invoice Modal */}
            {showInvoiceModal && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl max-h-[90vh] overflow-y-auto">
                        <div className="p-6 border-b border-gray-100 flex items-center justify-between sticky top-0 bg-white">
                            <div>
                                <h3 className="text-lg font-bold text-gray-800">Buat Tagihan Baru</h3>
                                <p className="text-sm text-gray-500">Buat tagihan SPP atau biaya lainnya</p>
                            </div>
                            <button onClick={() => setShowInvoiceModal(false)} className="p-2 hover:bg-gray-100 rounded-lg">
                                <X className="w-5 h-5 text-gray-400" />
                            </button>
                        </div>
                        <div className="p-6 space-y-5">
                            {/* Target Type */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Target Tagihan</label>
                                <select
                                    value={invoiceForm.targetType}
                                    onChange={(e) => setInvoiceForm({ ...invoiceForm, targetType: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                >
                                    <option value="all">Semua Santri</option>
                                    <option value="class">Per Kelas</option>
                                    <option value="individual">Per Santri</option>
                                </select>
                            </div>

                            {/* Class Selection */}
                            {invoiceForm.targetType === 'class' && (
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Pilih Kelas</label>
                                    <select
                                        value={invoiceForm.class}
                                        onChange={(e) => setInvoiceForm({ ...invoiceForm, class: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                    >
                                        <option value="">Pilih Kelas</option>
                                        {classes.map(c => (
                                            <option key={c.id} value={c.id}>{c.name}</option>
                                        ))}
                                    </select>
                                </div>
                            )}

                            {/* Student Selection */}
                            {invoiceForm.targetType === 'individual' && (
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Pilih Santri</label>
                                    <select
                                        value={invoiceForm.studentId}
                                        onChange={(e) => setInvoiceForm({ ...invoiceForm, studentId: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                    >
                                        <option value="">Pilih Santri</option>
                                        {students.map(s => (
                                            <option key={s.id} value={s.id}>{s.name} ({s.nis})</option>
                                        ))}
                                    </select>
                                </div>
                            )}

                            {/* Invoice Type */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Jenis Tagihan</label>
                                <select
                                    value={invoiceForm.invoiceType}
                                    onChange={(e) => {
                                        const type = INVOICE_TYPES.find(t => t.id === e.target.value);
                                        setInvoiceForm({
                                            ...invoiceForm,
                                            invoiceType: e.target.value,
                                            amount: type?.amount || 0
                                        });
                                    }}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500"
                                >
                                    <option value="">-- Pilih Jenis --</option>
                                    {invoiceTypes.length > 0 ? (
                                        invoiceTypes.map(type => (
                                            <option key={type.id} value={type.name}>{type.name} - {formatCurrency(type.amount)}</option>
                                        ))
                                    ) : (
                                        INVOICE_TYPES.map(type => (
                                            <option key={type.id} value={type.name}>{type.name} - {formatCurrency(type.amount)}</option>
                                        ))
                                    )}
                                </select>
                            </div>

                            {/* Amount */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Nominal</label>
                                <div className="relative">
                                    <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500">Rp</span>
                                    <input
                                        type="number"
                                        value={invoiceForm.amount}
                                        onChange={(e) => setInvoiceForm({ ...invoiceForm, amount: parseInt(e.target.value) || 0 })}
                                        className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500"
                                    />
                                </div>
                            </div>

                            {/* Due Date */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Jatuh Tempo</label>
                                <input
                                    type="date"
                                    value={invoiceForm.dueDate}
                                    onChange={(e) => setInvoiceForm({ ...invoiceForm, dueDate: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500"
                                />
                            </div>

                            {/* Notes */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Catatan (Opsional)</label>
                                <textarea
                                    rows={2}
                                    value={invoiceForm.notes}
                                    onChange={(e) => setInvoiceForm({ ...invoiceForm, notes: e.target.value })}
                                    placeholder="Catatan tambahan..."
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 focus:border-emerald-500 resize-none"
                                />
                            </div>
                        </div>
                        <div className="p-6 border-t border-gray-100 flex gap-3">
                            <button
                                onClick={() => setShowInvoiceModal(false)}
                                className="flex-1 py-3 border border-gray-200 text-gray-700 font-medium rounded-xl hover:bg-gray-50 transition-colors"
                            >
                                Batal
                            </button>
                            <button
                                onClick={handleCreateInvoice}
                                className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-medium rounded-xl transition-colors flex items-center justify-center gap-2"
                            >
                                <Receipt className="w-5 h-5" />
                                Buat Tagihan
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Sidebar */}
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Welcome Banner with Action */}
                    <div className="bg-gradient-to-r from-emerald-500 to-teal-600 rounded-2xl p-6 lg:p-8 text-white mb-8">
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div>
                                <div className="flex items-center gap-3 mb-2">
                                    <Wallet className="w-8 h-8" />
                                    <h2 className="text-2xl font-bold">Portal Keuangan</h2>
                                </div>
                                <p className="text-emerald-100">
                                    Kelola SPP, pembayaran, dan laporan keuangan pesantren.
                                </p>
                            </div>
                            <button
                                onClick={() => setShowInvoiceModal(true)}
                                className="flex items-center gap-2 px-5 py-3 bg-white/20 hover:bg-white/30 rounded-xl font-medium transition-colors"
                            >
                                <Plus className="w-5 h-5" />
                                Buat Tagihan Baru
                            </button>
                        </div>
                    </div>

                    {/* Financial Summary Cards */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
                        <div className="bg-white rounded-2xl p-6 border border-gray-100 shadow-sm">
                            <div className="flex items-center justify-between mb-4">
                                <div className="w-12 h-12 bg-emerald-100 rounded-xl flex items-center justify-center">
                                    <DollarSign className="w-6 h-6 text-emerald-600" />
                                </div>
                                <span className="flex items-center gap-1 text-sm text-emerald-600 font-medium">
                                    <ArrowUpRight className="w-4 h-4" /> Real-time
                                </span>
                            </div>
                            <p className="text-2xl font-bold text-gray-800">{formatCurrency(stats.incomeThisMonth)}</p>
                            <p className="text-sm text-gray-500">Pemasukan Bulan Ini</p>
                        </div>

                        <div className="bg-white rounded-2xl p-6 border border-gray-100 shadow-sm">
                            <div className="flex items-center justify-between mb-4">
                                <div className="w-12 h-12 bg-red-100 rounded-xl flex items-center justify-center">
                                    <TrendingDown className="w-6 h-6 text-red-600" />
                                </div>
                            </div>
                            <p className="text-2xl font-bold text-gray-800">{formatCurrency(stats.expenseThisMonth)}</p>
                            <p className="text-sm text-gray-500">Pengeluran Terverifikasi</p>
                        </div>

                        <div className="bg-white rounded-2xl p-6 border border-gray-100 shadow-sm">
                            <div className="flex items-center justify-between mb-4">
                                <div className="w-12 h-12 bg-amber-100 rounded-xl flex items-center justify-center">
                                    <Receipt className="w-6 h-6 text-amber-600" />
                                </div>
                            </div>
                            <p className="text-2xl font-bold text-gray-800">{stats.unpaidCount}</p>
                            <p className="text-sm text-gray-500">Tagihan Belum Lunas</p>
                        </div>

                        <div className="bg-white rounded-2xl p-6 border border-gray-100 shadow-sm">
                            <div className="flex items-center justify-between mb-4">
                                <div className="w-12 h-12 bg-blue-100 rounded-xl flex items-center justify-center">
                                    <PiggyBank className="w-6 h-6 text-blue-600" />
                                </div>
                            </div>
                            <p className="text-2xl font-bold text-gray-800">{formatCurrency(stats.balance)}</p>
                            <p className="text-sm text-gray-500">Estimasi Saldo Kas</p>
                        </div>
                    </div>

                    {/* Data Visualization Charts */}
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
                        <ChartCard
                            title="Arus Kas (Cashflow)"
                            subtitle="Pemasukan vs Pengeluaran"
                            className="lg:col-span-2"
                        >
                            <CashflowChart data={cashflowData} height={300} />
                        </ChartCard>

                        <ChartCard
                            title="Status Tagihan"
                            subtitle="Perbandingan lunas & belum bayar"
                        >
                            <InvoiceStatusChart data={invoiceStatusData} height={260} />
                            <div className="flex justify-center gap-6 mt-2">
                                {invoiceStatusData.map((d, i) => (
                                    <div key={i} className="flex items-center gap-2">
                                        <div className="w-3 h-3 rounded-full" style={{ backgroundColor: d.color }} />
                                        <span className="text-sm text-gray-600">{d.name} ({d.value})</span>
                                    </div>
                                ))}
                            </div>
                        </ChartCard>
                    </div>

                    {/* Second Row of Charts */}
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
                        <ChartCard
                            title="Trend Pemasukan Harian"
                            subtitle="30 hari terakhir"
                            className="lg:col-span-2"
                        >
                            <DailyIncomeChart data={dailyIncomeData} height={280} />
                        </ChartCard>

                        <ChartCard
                            title="Metode Pembayaran"
                            subtitle="Distribusi metode pembayaran"
                        >
                            <PaymentMethodChart data={paymentMethodData} height={280} />
                        </ChartCard>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                        {/* Recent Transactions */}
                        <div className="lg:col-span-2 bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                            <div className="p-5 border-b border-gray-100 flex items-center justify-between">
                                <h3 className="font-semibold text-gray-800">Transaksi Terbaru</h3>
                                <Link
                                    href="/dashboard/keuangan/pembayaran"
                                    className="text-sm text-emerald-600 font-medium hover:underline"
                                >
                                    Lihat Semua
                                </Link>
                            </div>
                            <div className="overflow-x-auto">
                                <table className="w-full">
                                    <thead className="bg-gray-50 border-b border-gray-100">
                                        <tr>
                                            <th className="text-left p-4 text-sm font-semibold text-gray-600">Santri</th>
                                            <th className="text-left p-4 text-sm font-semibold text-gray-600">Jenis</th>
                                            <th className="text-right p-4 text-sm font-semibold text-gray-600">Nominal</th>
                                            <th className="text-center p-4 text-sm font-semibold text-gray-600">Status</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-gray-100">
                                        {transactions.map(tx => (
                                            <tr key={tx.id} className="hover:bg-gray-50">
                                                <td className="p-4">
                                                    <div className="flex items-center gap-3">
                                                        <div className="w-8 h-8 bg-emerald-50 rounded-full flex items-center justify-center">
                                                            <span className="text-sm font-medium text-emerald-600">{tx.studentName.charAt(0)}</span>
                                                        </div>
                                                        <div>
                                                            <p className="font-medium text-gray-800">{tx.studentName}</p>
                                                            <p className="text-xs text-gray-500">{new Date(tx.date).toLocaleDateString('id-ID')}</p>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td className="p-4 text-gray-600 uppercase text-xs font-bold tracking-wider">{tx.type}</td>
                                                <td className="p-4 text-right font-semibold text-gray-800">{formatCurrency(tx.amount)}</td>
                                                <td className="p-4 text-center">
                                                    <span className={`px-3 py-1 rounded-full text-xs font-medium ${tx.status === 'success'
                                                        ? 'bg-emerald-100 text-emerald-700'
                                                        : 'bg-amber-100 text-amber-700'
                                                        }`}>
                                                        {tx.status === 'success' ? 'Lunas' : 'Pending'}
                                                    </span>
                                                </td>
                                            </tr>
                                        ))}
                                        {transactions.length === 0 && (
                                            <tr>
                                                <td colSpan={4} className="p-8 text-center text-gray-400">Belum ada transaksi</td>
                                            </tr>
                                        )}
                                    </tbody>
                                </table>
                            </div>
                        </div>

                        {/* Unpaid Students */}
                        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                            <div className="p-5 border-b border-gray-100 flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                    <AlertCircle className="w-5 h-5 text-red-500" />
                                    <h3 className="font-semibold text-gray-800">Belum Bayar</h3>
                                </div>
                                <span className="px-2 py-1 bg-red-100 text-red-700 text-xs font-medium rounded-full">
                                    {unpaidStudents.length}
                                </span>
                            </div>
                            <div className="divide-y divide-gray-100 max-h-[400px] overflow-y-auto">
                                {unpaidStudents.map(student => (
                                    <div key={student.id} className="p-4">
                                        <div className="flex items-start justify-between mb-2 gap-4">
                                            <div className="min-w-0 flex-1">
                                                <p className="font-medium text-gray-800 truncate">{student.name}</p>
                                                <p className="text-sm text-gray-500">Kelas {student.class} ÔÇó {student.type}</p>
                                            </div>
                                            <p className="font-semibold text-gray-800 whitespace-nowrap">{formatCurrency(student.amount)}</p>
                                        </div>
                                        <div className="flex items-center justify-between">
                                            <span className="text-xs text-red-600">Jatuh tempo: {new Date(student.dueDate).toLocaleDateString('id-ID')}</span>
                                            <button
                                                onClick={() => handleSendReminder(student.id)}
                                                disabled={sendingReminder === student.id || reminderSent.includes(student.id)}
                                                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${reminderSent.includes(student.id)
                                                    ? 'bg-emerald-100 text-emerald-700'
                                                    : 'bg-amber-100 hover:bg-amber-200 text-amber-700'
                                                    }`}
                                            >
                                                {sendingReminder === student.id ? (
                                                    <>
                                                        <Loader2 className="w-4 h-4 animate-spin" />
                                                        Mengirim...
                                                    </>
                                                ) : reminderSent.includes(student.id) ? (
                                                    <>
                                                        <CheckCircle2 className="w-4 h-4" />
                                                        Terkirim
                                                    </>
                                                ) : (
                                                    <>
                                                        <Send className="w-4 h-4" />
                                                        Ingatkan
                                                    </>
                                                )}
                                            </button>
                                        </div>
                                    </div>
                                ))}
                                {unpaidStudents.length === 0 && (
                                    <div className="p-8 text-center text-gray-400 italic text-sm">Semua tagihan lunas!</div>
                                )}
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    TrendingDown,
    Plus,
    Search,
    CheckCircle2,
    Loader2,
    X,
    Download,
    Calendar
} from 'lucide-react';

// ============================================
// Types & Data
// ============================================

interface Expense {
    id: string;
    date: string;
    category: 'Operasional' | 'Gaji' | 'Pembangunan' | 'Pendidikan' | 'Lainnya';
    description: string;
    amount: number;
    pic: string;
}

import { financeService } from '@/lib/services/finance';

const CATEGORIES_MAPPING: Record<string, string> = {
    'gaji': 'Gaji',
    'operasional': 'Operasional',
    'pemeliharaan': 'Pemeliharaan',
    'pengadaan': 'Pengadaan',
    'kegiatan': 'Kegiatan',
    'lainnya': 'Lainnya'
};

const CATEGORIES = Object.keys(CATEGORIES_MAPPING);

export default function PengeluaranPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [filterCategory, setFilterCategory] = useState<string>('all');
    const [showModal, setShowModal] = useState(false);
    const [isCreating, setIsCreating] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [showSuccess, setShowSuccess] = useState(false);
    const [expenses, setExpenses] = useState<Expense[]>([]);

    // Form state
    const [formData, setFormData] = useState({
        date: new Date().toISOString().split('T')[0],
        category: 'operasional',
        description: '',
        amount: 0,
        pic: '',
    });

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_keuangan' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        setUser(currentUser);
        fetchData();
    }, [router]);

    const fetchData = async () => {
        try {
            setIsLoading(true);
            const data = await financeService.getAllExpenses();
            setExpenses(data);
        } catch (error) {
            console.error('Error fetching expenses:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleCreate = async () => {
        try {
            setIsCreating(true);
            await financeService.createExpense({
                category: formData.category,
                description: formData.description,
                amount: formData.amount,
                expense_date: formData.date,
                pic: formData.pic
            });

            setIsCreating(false);
            setShowModal(false);
            setFormData({ date: new Date().toISOString().split('T')[0], category: 'operasional', description: '', amount: 0, pic: '' });
            setShowSuccess(true);
            fetchData();
            setTimeout(() => setShowSuccess(false), 3000);
        } catch (error) {
            console.error('Error creating expense:', error);
            setIsCreating(false);
            alert('Gagal mencatat pengeluaran');
        }
    };

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('id-ID', {
            style: 'currency',
            currency: 'IDR',
            minimumFractionDigits: 0
        }).format(amount);
    };

    if (!user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-emerald-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
                    <span>Loading Data Pengeluaran...</span>
                </div>
            </div>
        );
    }

    const filteredExpenses = expenses.filter(exp => {
        const matchSearch = exp.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
            exp.pic.toLowerCase().includes(searchQuery.toLowerCase());
        const matchCategory = filterCategory === 'all' || exp.category === filterCategory;
        return matchSearch && matchCategory;
    });

    const totalExpenses = expenses.reduce((sum, exp) => sum + exp.amount, 0);

    const categoryColors: Record<string, string> = {
        'operasional': 'bg-blue-100 text-blue-700',
        'gaji': 'bg-purple-100 text-purple-700',
        'pemeliharaan': 'bg-amber-100 text-amber-700',
        'pengadaan': 'bg-rose-100 text-rose-700',
        'kegiatan': 'bg-emerald-100 text-emerald-700',
        'lainnya': 'bg-gray-100 text-gray-700',
    };

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Success Toast */}
            {showSuccess && (
                <div className="fixed top-4 right-4 z-[60] bg-emerald-500 text-white px-6 py-4 rounded-xl shadow-lg flex items-center gap-3">
                    <CheckCircle2 className="w-6 h-6" />
                    <span className="font-medium">Pengeluaran berhasil dicatat!</span>
                </div>
            )}

            {/* Create Expense Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-50 flex items-center justify-center p-4 transition-all duration-300">
                    <div className="bg-white dark:bg-neutral-900 rounded-3xl w-full max-w-lg shadow-2xl border border-gray-100 dark:border-white/10 max-h-[90vh] flex flex-col transition-all scale-100">
                        <div className="p-6 border-b border-gray-100 dark:border-white/5 flex items-center justify-between flex-shrink-0">
                            <h3 className="text-xl font-bold text-gray-800 dark:text-white">Catat Pengeluaran</h3>
                            <button onClick={() => setShowModal(false)} className="p-2 hover:bg-gray-100 dark:hover:bg-white/5 rounded-lg transition-colors">
                                <X className="w-5 h-5 text-gray-400" />
                            </button>
                        </div>
                        <div className="p-6 space-y-4 overflow-y-auto flex-1">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Tanggal</label>
                                <input
                                    type="date"
                                    value={formData.date}
                                    onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 dark:text-white transition-all"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Kategori</label>
                                <select
                                    value={formData.category}
                                    onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-neutral-800 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 dark:text-white transition-all appearance-none"
                                >
                                    {CATEGORIES.map(c => (
                                        <option key={c} value={c}>{CATEGORIES_MAPPING[c]}</option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Deskripsi</label>
                                <textarea
                                    value={formData.description}
                                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                    rows={2}
                                    placeholder="Jelaskan pengeluaran..."
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 dark:text-white transition-all min-h-[80px]"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Nominal</label>
                                <input
                                    type="number"
                                    value={formData.amount}
                                    onChange={(e) => setFormData({ ...formData, amount: parseInt(e.target.value, 10) || 0 })}
                                    placeholder="0"
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 dark:text-white transition-all"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Penanggung Jawab (PIC)</label>
                                <input
                                    type="text"
                                    value={formData.pic}
                                    onChange={(e) => setFormData({ ...formData, pic: e.target.value })}
                                    placeholder="Nama penanggung jawab"
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 dark:text-white transition-all"
                                />
                            </div>
                        </div>
                        <div className="p-6 border-t border-gray-100 dark:border-white/5 flex gap-3 flex-shrink-0 bg-gray-50 dark:bg-neutral-900/50">
                            <button
                                onClick={() => setShowModal(false)}
                                className="flex-1 py-3 border border-gray-200 dark:border-white/10 text-gray-700 dark:text-gray-300 font-medium rounded-xl hover:bg-gray-100 dark:hover:bg-white/5 transition-all"
                            >
                                Batal
                            </button>
                            <button
                                onClick={handleCreate}
                                disabled={isCreating || !formData.description || !formData.amount}
                                className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-xl flex items-center justify-center gap-2 disabled:opacity-50 shadow-lg shadow-emerald-500/20 active:scale-95 transition-all"
                            >
                                {isCreating ? (
                                    <>
                                        <Loader2 className="w-5 h-5 animate-spin" />
                                        Menyimpan...
                                    </>
                                ) : (
                                    'Simpan'
                                )}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Sidebar */}
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Breadcrumb & Title */}
                    <div className="mb-6">
                        <Link
                            href="/dashboard/keuangan"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 mb-2"
                        >
                            <ArrowLeft className="w-4 h-4" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div>
                                <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-3">
                                    <TrendingDown className="w-7 h-7 text-red-600" />
                                    Pengeluaran
                                </h1>
                                <p className="text-gray-500">
                                    Catat dan kelola semua pengeluaran pesantren
                                </p>
                            </div>
                            <button
                                onClick={() => setShowModal(true)}
                                className="flex items-center gap-2 px-5 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-xl transition-colors shadow-lg shadow-emerald-500/30"
                            >
                                <Plus className="w-5 h-5" />
                                Catat Pengeluaran
                            </button>
                        </div>
                    </div>

                    {/* Summary Card */}
                    <div className="bg-gradient-to-r from-red-500 to-rose-600 rounded-2xl p-6 text-white mb-6">
                        <p className="text-red-100 text-sm mb-1">Total Pengeluaran (Tefilter)</p>
                        <p className="text-3xl font-bold">{formatCurrency(totalExpenses)}</p>
                        <div className="flex items-center gap-2 mt-2 text-red-100">
                            <Calendar className="w-4 h-4" />
                            <span className="text-sm">{new Date().toLocaleDateString('id-ID', { month: 'long', year: 'numeric' })}</span>
                        </div>
                    </div>

                    {/* Filters */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 mb-6">
                        <div className="flex flex-col md:flex-row gap-4">
                            <div className="relative flex-1">
                                <Search className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                <input
                                    type="text"
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    placeholder="Cari deskripsi atau PIC..."
                                    className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                />
                            </div>
                            <select
                                value={filterCategory}
                                onChange={(e) => setFilterCategory(e.target.value)}
                                className="px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl"
                            >
                                <option value="all">Semua Kategori</option>
                                {CATEGORIES.map(c => (
                                    <option key={c} value={c}>{CATEGORIES_MAPPING[c]}</option>
                                ))}
                            </select>
                            <button className="flex items-center gap-2 px-4 py-2.5 border border-gray-200 rounded-xl text-gray-700 hover:bg-gray-50">
                                <Download className="w-4 h-4" />
                                Export
                            </button>
                        </div>
                    </div>

                    {/* Table */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead className="bg-gray-50 border-b border-gray-100">
                                    <tr>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Tanggal</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Kategori</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Deskripsi</th>
                                        <th className="text-right p-4 text-sm font-semibold text-gray-600">Nominal</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">PIC</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100">
                                    {filteredExpenses.map(exp => (
                                        <tr key={exp.id} className="hover:bg-gray-50">
                                            <td className="p-4 text-gray-600 text-sm">{exp.date}</td>
                                            <td className="p-4">
                                                <span className={`px-2 py-1 rounded text-xs font-medium ${categoryColors[exp.category]}`}>
                                                    {CATEGORIES_MAPPING[exp.category] || exp.category}
                                                </span>
                                            </td>
                                            <td className="p-4 text-gray-800">{exp.description}</td>
                                            <td className="p-4 text-right font-semibold text-red-600">{formatCurrency(exp.amount)}</td>
                                            <td className="p-4 text-gray-600 text-sm">{exp.pic}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { supabase } from '@/lib/supabase';
import {
    getCurrentUser,
    clearSession,
    syncUserSession,
    User
} from '@/lib/auth';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Receipt,
    Plus,
    Search,
    Filter,
    CheckCircle2,
    XCircle,
    Clock,
    Download,
    Loader2,
    X
} from 'lucide-react';

import { financeService } from '@/lib/services/finance';

interface SimpleClass { id: string; name: string; }
interface SimpleStudent { id: string; name: string; nis: string; }
interface InvoiceType { id: string; name: string; amount: number; }
interface Invoice {
    id: string;
    amount: number;
    status: string;
    santriName: string;
    class: string;
    type: string;
    dueDate: string;
    description?: string;
    created_at?: string;
    paid_amount?: number;
}

// ============================================
// Types & Data
// ============================================

// Remove hardcoded types, used dynamic types instead

export default function TagihanPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [filterStatus, setFilterStatus] = useState<'all' | 'lunas' | 'belum' | 'cicilan'>('all');
    const [filterType, setFilterType] = useState<string>('all');
    const [showModal, setShowModal] = useState(false);
    const [isCreating, setIsCreating] = useState(false);
    const [showSuccess, setShowSuccess] = useState(false);

    const [invoices, setInvoices] = useState<Invoice[]>([]);
    const [classes, setClasses] = useState<SimpleClass[]>([]);
    const [students, setStudents] = useState<SimpleStudent[]>([]);
    const [invoiceTypes, setInvoiceTypes] = useState<InvoiceType[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const [showPaymentModal, setShowPaymentModal] = useState(false);
    const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);
    const [isProcessing, setIsProcessing] = useState(false);
    const [paymentAmount, setPaymentAmount] = useState(0);
    const [paidSoFar, setPaidSoFar] = useState(0);

    // Form state
    const [formData, setFormData] = useState({
        targetType: 'class',
        classId: '',
        studentId: '',
        type: 'SPP Bulanan',
        dueDate: new Date().toISOString().split('T')[0],
        amount: 500000,
        notes: ''
    });

    const fetchInvoices = useCallback(async () => {
        try {
            setIsLoading(true);
            const data = await financeService.getAllInvoices({
                status: filterStatus === 'lunas' ? 'paid' : (filterStatus === 'belum' ? 'pending' : (filterStatus === 'cicilan' ? 'partial' : 'all')),
                type: filterType
            });
            setInvoices(data as unknown as Invoice[]);
            setIsLoading(false);
        } catch (_error) {
            console.error('Error fetching invoices:', _error);
            setIsLoading(false);
        }
    }, [filterStatus, filterType]);

    const fetchInitialData = useCallback(async () => {
        try {
            // First, sync user session to make sure pesantrenId is up to date
            const updatedUser = await syncUserSession();
            if (updatedUser) setUser(updatedUser);

            const [clsRes, stdRes, types] = await Promise.all([
                supabase.from('classes').select('id, name').order('name'),
                supabase.from('students').select('id, name, nis').order('name'),
                financeService.getInvoiceTypes()
            ]);

            setClasses(clsRes.data || []);
            setStudents(stdRes.data || []);
            setInvoiceTypes(types as unknown as InvoiceType[]);

            // Set default type if available
            if (types.length > 0) {
                setFormData(prev => ({ ...prev, type: types[0].name, amount: types[0].amount }));
            }

            // fetchInvoices(); // Handled by separate useEffect
        } catch (_error) {
            console.error('Error fetching initial data:', _error);
            setIsLoading(false);
        }
    }, [fetchInvoices]);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || (currentUser.role !== 'admin_keuangan' && currentUser.role !== 'super_admin')) {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchInitialData();
        });
        return () => cancelAnimationFrame(timer);
    }, [router, fetchInitialData]);

    useEffect(() => {
        const timer = requestAnimationFrame(() => {
            fetchInvoices();
        });
        return () => cancelAnimationFrame(timer);
    }, [fetchInvoices]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleMarkAsPaid = async () => {
        if (!selectedInvoice || paymentAmount <= 0) return alert('Masukkan nominal pembayaran!');
        try {
            setIsProcessing(true);
            const result = await financeService.processPayment({
                invoice_id: selectedInvoice.id,
                amount: paymentAmount,
                payment_method: 'tunai',
                notes: 'Dibayar secara manual melalui admin'
            });
            setShowPaymentModal(false);
            setSelectedInvoice(null);
            setPaymentAmount(0);
            setPaidSoFar(0);
            setIsProcessing(false);
            setShowSuccess(true);
            fetchInvoices();
            setTimeout(() => setShowSuccess(false), 3000);
        } catch (error) {
            console.error('Error processing payment:', error);
            setIsProcessing(false);
            alert('Gagal memproses pembayaran');
        }
    };

    const handleCreate = async () => {
        if (formData.targetType === 'class' && !formData.classId) return alert('Pilih kelas!');
        if (formData.targetType === 'individual' && !formData.studentId) return alert('Pilih santri!');

        try {
            setIsCreating(true);
            const result = await financeService.createInvoice({
                targetType: formData.targetType,
                classId: formData.classId,
                studentId: formData.studentId,
                invoiceType: formData.type,
                amount: formData.amount,
                dueDate: formData.dueDate,
                notes: formData.notes
            });

            setIsCreating(false);
            setShowModal(false);
            setShowSuccess(true);
            fetchInvoices();
            setTimeout(() => setShowSuccess(false), 3000);

            if (result.count > 1) {
                alert(`Berhasil membuat ${result.count} tagihan!`);
            }
        } catch (error: unknown) {
            console.error('Error creating invoice:', error);
            setIsCreating(false);
            const errorMsg = error instanceof Error ? error.message : (typeof error === 'object' ? JSON.stringify(error) : 'Gagal membuat tagihan');
            alert('Gagal: ' + errorMsg);
        }
    };


    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('id-ID', {
            style: 'currency',
            currency: 'IDR',
            minimumFractionDigits: 0
        }).format(amount);
    };

    if (isLoading || !user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50 uppercase tracking-widest font-black text-emerald-900">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-emerald-600 animate-spin" />
                    <span>Loading Data Tagihan...</span>
                </div>
            </div>
        );
    }

    const filteredInvoices = invoices.filter(inv => {
        const matchesSearch = inv.santriName.toLowerCase().includes(searchQuery.toLowerCase()) ||
            inv.id.toLowerCase().includes(searchQuery.toLowerCase()) ||
            inv.type.toLowerCase().includes(searchQuery.toLowerCase());
        return matchesSearch;
    });

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Success Toast */}
            {showSuccess && (
                <div className="fixed top-4 right-4 z-[60] bg-emerald-500 text-white px-6 py-4 rounded-xl shadow-lg flex items-center gap-3">
                    <CheckCircle2 className="w-6 h-6" />
                    <span className="font-medium">Tagihan berhasil dibuat!</span>
                </div>
            )}

            {/* Create Invoice Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-50 flex items-center justify-center p-4 transition-all duration-300">
                    <div className="bg-white dark:bg-neutral-900 rounded-3xl w-full max-w-lg shadow-2xl border border-gray-100 dark:border-white/10 max-h-[90vh] flex flex-col transition-all scale-100">
                        <div className="p-6 border-b border-gray-100 dark:border-white/5 flex items-center justify-between shrink-0">
                            <h3 className="text-xl font-bold text-gray-800 dark:text-white">Buat Tagihan Baru</h3>
                            <button onClick={() => setShowModal(false)} className="p-2 hover:bg-gray-100 rounded-lg">
                                <X className="w-5 h-5 text-gray-500" />
                            </button>
                        </div>
                        <div className="p-6 space-y-4 overflow-y-auto flex-1 custom-scrollbar">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1.5">Target Tagihan</label>
                                <select
                                    value={formData.targetType}
                                    onChange={(e) => setFormData({ ...formData, targetType: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 dark:text-white transition-all appearance-none"
                                >
                                    <option value="all">Semua Santri</option>
                                    <option value="class">Per Kelas</option>
                                    <option value="individual">Per Santri</option>
                                </select>
                            </div>
                            {formData.targetType === 'individual' && (
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Pilih Santri</label>
                                    <select
                                        value={formData.studentId}
                                        onChange={(e) => setFormData({ ...formData, studentId: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                    >
                                        <option value="">Pilih Santri</option>
                                        {students.map(s => (
                                            <option key={s.id} value={s.id}>{s.name} ({s.nis})</option>
                                        ))}
                                    </select>
                                </div>
                            )}
                            {formData.targetType === 'class' && (
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Pilih Kelas</label>
                                    <select
                                        value={formData.classId}
                                        onChange={(e) => setFormData({ ...formData, classId: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                    >
                                        <option value="">Pilih Kelas</option>
                                        {classes.map(c => (
                                            <option key={c.id} value={c.id}>Kelas {c.name}</option>
                                        ))}
                                    </select>
                                </div>
                            )}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Jenis Tagihan</label>
                                <select
                                    value={formData.type}
                                    onChange={(e) => {
                                        const type = invoiceTypes.find(t => t.name === e.target.value);
                                        setFormData({
                                            ...formData,
                                            type: e.target.value,
                                            amount: type ? type.amount : formData.amount
                                        });
                                    }}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                >
                                    {invoiceTypes.map(t => (
                                        <option key={t.id} value={t.name}>{t.name}</option>
                                    ))}
                                </select>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Jatuh Tempo</label>
                                    <input
                                        type="date"
                                        value={formData.dueDate}
                                        onChange={(e) => setFormData({ ...formData, dueDate: e.target.value })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-gray-700 mb-1.5">Nominal</label>
                                    <input
                                        type="number"
                                        value={formData.amount}
                                        onChange={(e) => setFormData({ ...formData, amount: parseInt(e.target.value) })}
                                        className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Catatan (Opsional)</label>
                                <textarea
                                    value={formData.notes}
                                    onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30 min-h-[80px]"
                                    placeholder="Contoh: SPP Bulan Januari"
                                />
                            </div>
                        </div>
                        <div className="p-6 border-t border-gray-100 dark:border-white/5 flex gap-3 bg-gray-50 dark:bg-neutral-900/50">
                            <button
                                onClick={() => setShowModal(false)}
                                className="flex-1 py-3 border border-gray-200 text-gray-700 font-medium rounded-xl hover:bg-gray-50"
                            >
                                Batal
                            </button>
                            <button
                                onClick={handleCreate}
                                disabled={isCreating}
                                className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-medium rounded-xl flex items-center justify-center gap-2"
                            >
                                {isCreating ? (
                                    <>
                                        <Loader2 className="w-5 h-5 animate-spin" />
                                        Membuat...
                                    </>
                                ) : (
                                    'Buat Tagihan'
                                )}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Payment Modal dengan Cicilan */}
            {showPaymentModal && selectedInvoice && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[70] flex items-center justify-center p-4 transition-all duration-300">
                    <div className="bg-white dark:bg-neutral-900 rounded-3xl w-full max-w-md shadow-2xl border border-gray-100 dark:border-white/10 transition-all scale-100">
                        <div className="p-6 border-b border-gray-100 dark:border-white/5">
                            <h3 className="text-xl font-bold text-gray-800 dark:text-white">Proses Pembayaran</h3>
                            <p className="text-gray-500 text-sm mt-1">{selectedInvoice.santriName}</p>
                        </div>
                        <div className="p-6 space-y-4">
                            {/* Info Tagihan */}
                            <div className="bg-gray-50 dark:bg-black/20 rounded-xl p-4 space-y-2 border border-gray-100 dark:border-white/5">
                                <div className="flex justify-between text-sm">
                                    <span className="text-gray-500 dark:text-gray-400">Total Tagihan</span>
                                    <span className="font-semibold text-gray-800 dark:text-gray-200">{formatCurrency(selectedInvoice.amount)}</span>
                                </div>
                                <div className="flex justify-between text-sm">
                                    <span className="text-gray-500 dark:text-gray-400">Sudah Dibayar</span>
                                    <span className="font-semibold text-amber-600 dark:text-amber-500">{formatCurrency(paidSoFar)}</span>
                                </div>
                                <hr className="border-gray-200 dark:border-white/5" />
                                <div className="flex justify-between text-sm">
                                    <span className="text-gray-500 dark:text-gray-400">Sisa Tagihan</span>
                                    <span className="font-bold text-red-600 dark:text-red-500">{formatCurrency(selectedInvoice.amount - paidSoFar)}</span>
                                </div>
                            </div>

                            {/* Input Nominal Pembayaran */}
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1.5">Nominal Pembayaran</label>
                                <input
                                    type="number"
                                    value={paymentAmount}
                                    onChange={(e) => setPaymentAmount(parseInt(e.target.value) || 0)}
                                    placeholder="Masukkan nominal"
                                    className="w-full px-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                />
                                <div className="flex gap-2 mt-2">
                                    <button
                                        onClick={() => setPaymentAmount(selectedInvoice.amount - paidSoFar)}
                                        className="text-xs px-3 py-1 bg-emerald-100 text-emerald-700 rounded-lg hover:bg-emerald-200"
                                    >
                                        Bayar Lunas
                                    </button>
                                    <button
                                        onClick={() => setPaymentAmount(Math.floor((selectedInvoice.amount - paidSoFar) / 2))}
                                        className="text-xs px-3 py-1 bg-amber-100 text-amber-700 rounded-lg hover:bg-amber-200"
                                    >
                                        Setengah
                                    </button>
                                </div>
                            </div>

                            {paymentAmount > 0 && (
                                <div className="text-sm text-center p-2 rounded-lg bg-blue-50 text-blue-700">
                                    {paymentAmount >= (selectedInvoice.amount - paidSoFar)
                                        ? 'Ô£à Tagihan akan LUNAS'
                                        : `ÔÅ│ Sisa setelah bayar: ${formatCurrency(selectedInvoice.amount - paidSoFar - paymentAmount)}`
                                    }
                                </div>
                            )}
                        </div>
                        <div className="p-6 border-t border-gray-100 flex gap-3">
                            <button
                                onClick={() => { setShowPaymentModal(false); setPaymentAmount(0); setPaidSoFar(0); }}
                                className="flex-1 py-3 border border-gray-200 text-gray-700 font-medium rounded-xl hover:bg-gray-50"
                            >
                                Batal
                            </button>
                            <button
                                onClick={handleMarkAsPaid}
                                disabled={isProcessing || paymentAmount <= 0}
                                className="flex-1 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-medium rounded-xl flex items-center justify-center gap-2 disabled:opacity-50"
                            >
                                {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : `Bayar ${formatCurrency(paymentAmount)}`}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Sidebar */}
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Breadcrumb & Title */}
                    <div className="mb-6">
                        <Link
                            href="/dashboard/keuangan"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 mb-2"
                        >
                            <ArrowLeft className="w-4 h-4" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div>
                                <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-3">
                                    <Receipt className="w-7 h-7 text-emerald-600" />
                                    SPP & Tagihan
                                </h1>
                                <p className="text-gray-500">
                                    Kelola semua tagihan santri
                                </p>
                            </div>
                            <button
                                onClick={() => setShowModal(true)}
                                className="flex items-center gap-2 px-5 py-3 bg-emerald-600 hover:bg-emerald-700 text-white font-semibold rounded-xl transition-colors shadow-lg shadow-emerald-500/30"
                            >
                                <Plus className="w-5 h-5" />
                                Buat Tagihan Baru
                            </button>
                        </div>
                    </div>

                    {/* Stats Cards */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
                        <div className="bg-white rounded-xl p-4 border border-gray-100 shadow-sm">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-emerald-100 rounded-lg flex items-center justify-center">
                                    <CheckCircle2 className="w-5 h-5 text-emerald-600" />
                                </div>
                                <div>
                                    <p className="text-2xl font-bold text-gray-800">{invoices.filter(i => i.status === 'lunas').length}</p>
                                    <p className="text-sm text-gray-500">Lunas</p>
                                </div>
                            </div>
                        </div>
                        <div className="bg-white rounded-xl p-4 border border-gray-100 shadow-sm">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-red-100 rounded-lg flex items-center justify-center">
                                    <XCircle className="w-5 h-5 text-red-600" />
                                </div>
                                <div>
                                    <p className="text-2xl font-bold text-gray-800">{invoices.filter(i => i.status === 'belum').length}</p>
                                    <p className="text-sm text-gray-500">Belum Bayar</p>
                                </div>
                            </div>
                        </div>
                        <div className="bg-white rounded-xl p-4 border border-gray-100 shadow-sm">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 bg-amber-100 rounded-lg flex items-center justify-center">
                                    <Clock className="w-5 h-5 text-amber-600" />
                                </div>
                                <div>
                                    <p className="text-2xl font-bold text-gray-800">{invoices.filter(i => i.status === 'cicilan').length}</p>
                                    <p className="text-sm text-gray-500">Cicilan</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Filters */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 mb-6">
                        <div className="flex flex-col md:flex-row gap-4">
                            <div className="relative flex-1">
                                <Search className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
                                <input
                                    type="text"
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    placeholder="Cari santri atau invoice..."
                                    className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-emerald-500/30"
                                />
                            </div>
                            <select
                                value={filterStatus}
                                onChange={(e) => setFilterStatus(e.target.value as 'all' | 'lunas' | 'belum' | 'cicilan')}
                                className="px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl"
                            >
                                <option value="all">Semua Status</option>
                                <option value="lunas">Lunas</option>
                                <option value="belum">Belum Bayar</option>
                                <option value="cicilan">Cicilan</option>
                            </select>
                            <select
                                value={filterType}
                                onChange={(e) => setFilterType(e.target.value)}
                                className="px-4 py-2.5 bg-gray-50 border border-gray-200 rounded-xl"
                            >
                                <option value="all">Semua Jenis</option>
                                {invoiceTypes.map(t => (
                                    <option key={t.id} value={t.name}>{t.name}</option>
                                ))}
                            </select>
                            <button className="flex items-center gap-2 px-4 py-2.5 border border-gray-200 rounded-xl text-gray-700 hover:bg-gray-50">
                                <Download className="w-4 h-4" />
                                Export
                            </button>
                        </div>
                    </div>

                    {/* Table */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead className="bg-gray-50 border-b border-gray-100">
                                    <tr>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Invoice ID</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Santri</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Kelas</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Jenis</th>
                                        <th className="text-right p-4 text-sm font-semibold text-gray-600">Nominal</th>
                                        <th className="text-center p-4 text-sm font-semibold text-gray-600">Status</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Jatuh Tempo</th>
                                        <th className="text-center p-4 text-sm font-semibold text-gray-600">Aksi</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100">
                                    {filteredInvoices.map(inv => (
                                        <tr key={inv.id} className="hover:bg-gray-50">
                                            <td className="p-4 font-mono text-sm text-gray-800">{inv.id}</td>
                                            <td className="p-4 font-medium text-gray-800">{inv.santriName}</td>
                                            <td className="p-4 text-gray-600">{inv.class}</td>
                                            <td className="p-4">
                                                <span className="px-2 py-1 bg-gray-100 text-gray-700 rounded text-xs font-medium">
                                                    {inv.type}
                                                </span>
                                            </td>
                                            <td className="p-4 text-right font-medium text-gray-800">{formatCurrency(inv.amount)}</td>
                                            <td className="p-4 text-center">
                                                <span className={`px-3 py-1 rounded-full text-xs font-medium ${inv.status === 'lunas'
                                                    ? 'bg-emerald-100 text-emerald-700'
                                                    : inv.status === 'cicilan'
                                                        ? 'bg-amber-100 text-amber-700'
                                                        : 'bg-red-100 text-red-700'
                                                    }`}>
                                                    {inv.status === 'lunas' ? 'Lunas' : inv.status === 'cicilan' ? 'Cicilan' : 'Belum Bayar'}
                                                </span>
                                            </td>
                                            <td className="p-4 text-gray-600 text-sm">{new Date(inv.dueDate).toLocaleDateString('id-ID')}</td>
                                            <td className="p-4 text-center">
                                                {inv.status !== 'lunas' && (
                                                    <button
                                                        onClick={async () => {
                                                            setSelectedInvoice(inv);
                                                            // Fetch existing payments for this invoice
                                                            const { data: payments } = await supabase
                                                                .from('payments')
                                                                .select('amount')
                                                                .eq('invoice_id', inv.id);
                                                            const totalPaid = (payments || []).reduce((sum: number, p: { amount: number }) => sum + Number(p.amount), 0);
                                                            setPaidSoFar(totalPaid);
                                                            setPaymentAmount(inv.amount - totalPaid);
                                                            setShowPaymentModal(true);
                                                        }}
                                                        className="px-3 py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-semibold rounded-lg transition-colors"
                                                    >
                                                        Bayar
                                                    </button>
                                                )}
                                                {inv.status === 'lunas' && (
                                                    <span className="text-xs text-gray-400 italic">Selesai</span>
                                                )}
                                            </td>
                                        </tr>
                                    ))}
                                    {filteredInvoices.length === 0 && (
                                        <tr>
                                            <td colSpan={8} className="p-12 text-center text-gray-400 italic">
                                                Tidak ada data tagihan ditemukan.
                                            </td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    Award,
    BookOpen,
    Search,
    ChevronRight,
    CheckCircle2,
    Clock,
    Loader2,
    Calendar,
    Activity,
    Star,
    History as HistoryIcon,
    LayoutGrid
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { supabase } from '@/lib/supabase';
import { hafalanService } from '@/lib/services/hafalan';
import { studentDashboardService } from '@/lib/services/student-dashboard';

export default function ProgressHafalanPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [studentInfo, setStudentInfo] = useState<any>(null);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [history, setHistory] = useState<any[]>([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [summary, setSummary] = useState<any>(null);

    const fetchData = async (userId: string) => {
        try {
            setIsLoading(true);
            const { data: student, error: sError } = await supabase
                .from('students')
                .select('*')
                .eq('user_id', userId)
                .single();

            if (sError) throw sError;
            setStudentInfo(student);

            const [historyData, dashboardData] = await Promise.all([
                hafalanService.getByStudent(student.id),
                studentDashboardService.getHafalanData(student.id)
            ]);

            setHistory(historyData);
            setSummary(dashboardData);
        } catch (err) {
            console.error('Error fetching hafalan history:', err);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'santri') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [router]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const formatDate = (dateString: string) => {
        if (!dateString) return '-';
        return new Date(dateString).toLocaleDateString('id-ID', {
            day: 'numeric',
            month: 'short',
            year: 'numeric'
        });
    };

    const getGradeConfig = (grade: string | null) => {
        if (!grade) return { label: '-', color: 'text-neutral-500 bg-neutral-900 border-neutral-800' };
        const configs: Record<string, { label: string; color: string }> = {
            'A': { label: 'Mumtaz', color: 'text-emerald-400 bg-emerald-500/10 border-emerald-500/20' },
            'B': { label: 'Jayyid Jidda', color: 'text-blue-400 bg-blue-500/10 border-blue-500/20' },
            'C': { label: 'Jayyid', color: 'text-amber-400 bg-amber-500/10 border-amber-500/20' },
            'D': { label: 'Maqbul', color: 'text-orange-400 bg-orange-500/10 border-orange-500/20' },
            'E': { label: 'Dhaif', color: 'text-rose-400 bg-rose-500/10 border-rose-500/20' },
        };
        return configs[grade] || { label: grade, color: 'text-neutral-400 bg-neutral-900 border-neutral-800' };
    };

    if (isLoading && !studentInfo) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-[#050505]">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-indigo-500 animate-spin opacity-40" />
                    <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-[0.2em]">Menyinkronkan Riwayat Hafalan...</p>
                </div>
            </div>
        );
    }

    if (!user) return null;

    const latestSetoran = history[0];

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-400 font-sans selection:bg-indigo-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="px-6 py-8 lg:p-10 space-y-10 max-w-[1500px] mx-auto">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-indigo-400 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <Activity className="w-4 h-4" />
                                Achievement Tracking
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Progress <span className="text-indigo-500">Hafalan & Tahfidz</span>
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Lacak capaian hapalan harian dan target bulanan Anda.</p>
                        </div>

                        <div className="relative group self-start md:self-auto">
                            <div className="absolute -inset-1 bg-gradient-to-r from-indigo-600 to-violet-600 rounded-2xl blur opacity-25 group-hover:opacity-40 transition duration-1000 group-hover:duration-200 shadow-[0_0_20px_rgba(79,70,229,0.3)]"></div>
                            <div className="relative flex items-center gap-3 px-6 py-3 bg-neutral-900 text-white rounded-2xl font-bold uppercase tracking-widest text-[10px] border border-neutral-800">
                                <BookOpen className="w-4 h-4 text-indigo-500" />
                                Total: {summary?.completed || 0} {summary?.unitLabel || 'Unit'} Selesai
                            </div>
                        </div>
                    </div>

                    {/* Stats Summary */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl group relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-6 opacity-[0.03] group-hover:scale-110 transition-transform">
                                <Star className="w-24 h-24" />
                            </div>
                            <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mb-4">Target {summary?.unitLabel || 'Unit'} Aktif</p>
                            <div className="flex items-end justify-between relative z-10">
                                <h4 className="text-2xl lg:text-3xl font-black text-white tracking-tighter truncate pr-2">{summary?.programName || (summary?.unitLabel + ' ' + summary?.currentJuz) || '?'}</h4>
                                <span className="px-3 py-1 bg-indigo-500/10 text-indigo-400 border border-indigo-500/20 rounded-lg text-[9px] font-black uppercase tracking-widest shrink-0">In Progress</span>
                            </div>
                            <div className="w-full h-1.5 bg-neutral-900 rounded-full mt-6 overflow-hidden border border-neutral-800">
                                <div
                                    className="h-full bg-indigo-500 shadow-[0_0_10px_rgba(99,102,241,0.5)] transition-all duration-1000"
                                    style={{ width: `${summary ? Math.max(5, summary.totalProgress || 0) : 0}%` }}
                                ></div>
                            </div>
                        </div>

                        <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl group relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-6 opacity-[0.03] group-hover:scale-110 transition-transform">
                                <Clock className="w-24 h-24" />
                            </div>
                            <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mb-4">Setoran Terakhir</p>
                            <h4 className="text-2xl lg:text-3xl font-black text-white tracking-tighter truncate uppercase">{latestSetoran?.program?.hafalan_type?.name || '-'}</h4>
                            <div className="mt-3 flex items-center gap-2">
                                <div className="w-2 h-2 bg-emerald-500 rounded-full shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>
                                <p className="text-[10px] font-bold text-neutral-400 uppercase tracking-widest leading-none">
                                    {latestSetoran ? `${summary?.unitLabel || 'Unit'} ${latestSetoran.unit_number} ÔÇó Tuntas` : 'Belum Ada Setoran'}
                                </p>
                            </div>
                        </div>

                        <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl group relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-6 opacity-[0.03] group-hover:scale-110 transition-transform">
                                <Award className="w-24 h-24" />
                            </div>
                            <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mb-4">Predikat Terakhir</p>
                            <div className="flex items-center gap-4 relative z-10">
                                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-xl font-black ${getGradeConfig(latestSetoran?.grade).color}`}>
                                    {latestSetoran?.grade || '-'}
                                </div>
                                <div>
                                    <h4 className="text-white font-black uppercase tracking-tight">{getGradeConfig(latestSetoran?.grade).label}</h4>
                                    <p className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest mt-1">Evaluasi Ustadz</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* History Table */}
                    <div className="bg-[#0a0a0a] rounded-[2.5rem] border border-neutral-800/40 shadow-2xl overflow-hidden">
                        <div className="p-8 border-b border-neutral-800/50 bg-neutral-900/20 flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div>
                                <h3 className="text-sm font-black text-white uppercase tracking-widest flex items-center gap-3">
                                    <HistoryIcon className="w-5 h-5 text-indigo-500" />
                                    Log Book Setoran
                                </h3>
                                <p className="text-[10px] text-neutral-600 font-bold uppercase tracking-widest mt-0.5 ml-8">Riwayat harian evaluasi hafalan.</p>
                            </div>
                            <div className="flex items-center gap-3 px-5 py-2.5 bg-[#050505] border border-neutral-800 rounded-2xl">
                                <Clock className="w-4 h-4 text-neutral-700" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-neutral-500">Update: {formatDate(latestSetoran?.evaluated_at || latestSetoran?.created_at)}</span>
                            </div>
                        </div>
                        <div className="overflow-x-auto custom-scrollbar">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="bg-[#0e0e0e] border-b border-neutral-800/50">
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] w-32">Tanggal</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Program & Target</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Predikat</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Catatan</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] w-16"></th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-neutral-800/30">
                                    {history.length === 0 ? (
                                        <tr>
                                            <td colSpan={5} className="py-24 text-center">
                                                <div className="flex flex-col items-center gap-4 opacity-40">
                                                    <LayoutGrid className="w-12 h-12 text-neutral-700" />
                                                    <p className="text-xs font-bold text-neutral-500 uppercase tracking-widest italic">Belum ada riwayat setoran tercatat.</p>
                                                </div>
                                            </td>
                                        </tr>
                                    ) : (
                                        history.map((item) => {
                                            const cfg = getGradeConfig(item.grade);
                                            return (
                                                <tr key={item.id} className="hover:bg-neutral-900/30 transition-all group">
                                                    <td className="px-8 py-6 text-sm font-bold text-neutral-300">{formatDate(item.evaluated_at || item.created_at)}</td>
                                                    <td className="px-8 py-6">
                                                        <div className="flex items-center gap-4">
                                                            <div className="w-10 h-10 bg-indigo-500/5 border border-indigo-500/10 rounded-xl flex items-center justify-center">
                                                                <BookOpen className="w-5 h-5 text-indigo-500" />
                                                            </div>
                                                            <div>
                                                                <p className="font-black text-white text-sm uppercase tracking-tight">{item.program?.hafalan_type?.name || 'Program'}</p>
                                                                <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest mt-1">
                                                                    {item.program?.hafalan_type?.unit_name || 'Unit'} {item.unit_number} ÔÇó {item.progress_percentage}% Tuntas
                                                                </p>
                                                            </div>
                                                        </div>
                                                    </td>
                                                    <td className="px-8 py-6 text-center">
                                                        <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest border ${cfg.color}`}>
                                                            {cfg.label}
                                                        </span>
                                                    </td>
                                                    <td className="px-8 py-6">
                                                        <p className="text-xs text-neutral-500 italic max-w-xs truncate">{item.notes || 'Tidak ada catatan khusus.'}</p>
                                                    </td>
                                                    <td className="px-8 py-6 text-right">
                                                        <button className="p-2.5 bg-neutral-900 text-neutral-700 rounded-xl hover:bg-neutral-800 hover:text-white transition-all border border-neutral-800">
                                                            <ChevronRight className="w-4 h-4 text-neutral-500" />
                                                        </button>
                                                    </td>
                                                </tr>
                                            );
                                        })
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </main>
            </div>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; height: 5px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #1a1a1a; border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #262626; }
            `}</style>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    CalendarDays,
    Clock,
    User as TeacherIcon,
    MapPin,
    ChevronRight,
    Loader2,
    BookOpen,
    Activity,
    Calendar,
    LayoutGrid,
    Star
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { supabase } from '@/lib/supabase';
import { studentDashboardService } from '@/lib/services/student-dashboard';

const DAYS = [
    { label: 'Senin', value: 1 },
    { label: 'Selasa', value: 2 },
    { label: 'Rabu', value: 3 },
    { label: 'Kamis', value: 4 },
    { label: 'Jumat', value: 5 },
    { label: 'Sabtu', value: 6 },
    { label: 'Minggu', value: 0 },
];

export default function JadwalPelajaranPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [activeDay, setActiveDay] = useState(1); // Monday
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [schedule, setSchedule] = useState<any[]>([]);

    const fetchData = async (userId: string) => {
        try {
            setIsLoading(true);
            const { data: student, error: sError } = await supabase
                .from('students')
                .select('id')
                .eq('user_id', userId)
                .single();

            if (sError) throw sError;

            const scheduleData = await studentDashboardService.getWeeklySchedule(student.id);
            setSchedule(scheduleData);
        } catch (err) {
            console.error('Error fetching weekly schedule:', err);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'santri') {
            router.replace('/login');
            return;
        }

        const today = new Date().getDay();
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            setActiveDay(today);
            fetchData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [router]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (isLoading && schedule.length === 0) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-[#050505]">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-indigo-500 animate-spin opacity-40" />
                    <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-[0.2em]">Memuat Jadwal Santri...</p>
                </div>
            </div>
        );
    }

    if (!user) return null;

    const filteredSchedule = schedule.filter(item => item.day_of_week === activeDay);

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-400 font-sans selection:bg-indigo-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-10 max-w-[1500px] mx-auto">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-indigo-400 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <Activity className="w-4 h-4" />
                                Weekly Routine
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Jadwal <span className="text-indigo-500">Pelajaran Mingguan</span>
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Manajemen waktu belajar anda sepekan untuk hasil yang maksimal.</p>
                        </div>
                    </div>

                    {/* Day Selection Tabs */}
                    <div className="no-scrollbar flex overflow-x-auto p-1.5 gap-1.5 bg-[#0a0a0a] rounded-[2rem] border border-neutral-800/40 shadow-xl">
                        {DAYS.map(day => (
                            <button
                                key={day.value}
                                onClick={() => setActiveDay(day.value)}
                                className={`flex-1 min-w-[100px] py-4 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] transition-all duration-300 ${activeDay === day.value
                                    ? 'bg-indigo-600 text-white shadow-[0_10px_20px_rgba(79,70,229,0.3)]'
                                    : 'text-neutral-600 hover:text-neutral-400 hover:bg-neutral-900/50'
                                    }`}
                            >
                                {day.label}
                            </button>
                        ))}
                    </div>

                    {/* Schedule Content Table */}
                    <div className="bg-[#0a0a0a] rounded-[2.5rem] border border-neutral-800/40 shadow-2xl overflow-hidden relative group">
                        <div className="absolute top-0 right-0 p-12 opacity-[0.01] pointer-events-none group-hover:scale-110 transition-transform duration-[2000ms]">
                            <CalendarDays className="w-64 h-64" />
                        </div>

                        <div className="overflow-x-auto custom-scrollbar">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="bg-[#0e0e0e] border-b border-neutral-800/50">
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] w-48">Jam / Waktu</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Mata Pelajaran</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Ustadz / Guru</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Ruangan</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] w-16"></th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-neutral-800/20">
                                    {filteredSchedule.length > 0 ? (
                                        filteredSchedule.map((item) => (
                                            <tr key={item.id} className="hover:bg-neutral-900/30 transition-all group">
                                                <td className="px-8 py-7">
                                                    <div className="flex items-center gap-3">
                                                        <Clock className="w-4 h-4 text-indigo-500/50" />
                                                        <span className="font-black text-white text-sm">{item.start_time.slice(0, 5)} - {item.end_time.slice(0, 5)}</span>
                                                    </div>
                                                </td>
                                                <td className="px-8 py-7">
                                                    <div className="flex items-center gap-4">
                                                        <div className="w-11 h-11 bg-indigo-500/5 border border-indigo-500/10 rounded-xl flex items-center justify-center font-black text-indigo-500 text-sm group-hover:bg-indigo-600 group-hover:text-white transition-all shadow-[0_0_15px_rgba(79,70,229,0.05)]">
                                                            {item.subjects?.name?.charAt(0) || 'K'}
                                                        </div>
                                                        <span className="font-bold text-white text-sm uppercase tracking-tight">{item.subjects?.name || 'Kegiatan Pesantren'}</span>
                                                    </div>
                                                </td>
                                                <td className="px-8 py-7">
                                                    <div className="flex items-center gap-3">
                                                        <TeacherIcon className="w-4 h-4 text-neutral-700" />
                                                        <span className="font-bold text-neutral-500 text-sm whitespace-nowrap">{item.teachers?.name || 'Ustadz / Ustadzah'}</span>
                                                    </div>
                                                </td>
                                                <td className="px-8 py-7 text-center">
                                                    <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-neutral-900 border border-neutral-800 text-neutral-600 rounded-xl text-[9px] font-black uppercase tracking-widest group-hover:text-indigo-400 group-hover:border-indigo-500/20 transition-all">
                                                        <MapPin className="w-3.5 h-3.5" />
                                                        {item.room || 'Aula Utama'}
                                                    </div>
                                                </td>
                                                <td className="px-8 py-7 text-right">
                                                    <button className="p-2.5 bg-neutral-900 text-neutral-700 rounded-xl hover:bg-neutral-800 hover:text-white transition-all border border-neutral-800">
                                                        <ChevronRight className="w-4 h-4" />
                                                    </button>
                                                </td>
                                            </tr>
                                        ))
                                    ) : (
                                        <tr>
                                            <td colSpan={5} className="py-24 text-center">
                                                <div className="flex flex-col items-center gap-4 opacity-40">
                                                    <LayoutGrid className="w-12 h-12 text-neutral-700" />
                                                    <p className="text-xs font-bold text-neutral-500 uppercase tracking-widest italic">Tidak ada agenda pengajaran di hari ini.</p>
                                                </div>
                                            </td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>

                    {/* Tip Information */}
                    <div className="p-8 rounded-[2.5rem] bg-[#0c0c0c] border border-neutral-800/40 shadow-xl flex items-center gap-6 group">
                        <div className="w-14 h-14 bg-amber-500/5 border border-amber-500/10 rounded-2xl flex items-center justify-center text-amber-500 shrink-0 shadow-[0_0_20px_rgba(245,158,11,0.05)] group-hover:scale-110 transition-transform">
                            <Star className="w-6 h-6 fill-current" />
                        </div>
                        <div>
                            <h4 className="text-white font-black uppercase tracking-widest text-xs">Pesan Pagi:</h4>
                            <p className="text-neutral-500 text-sm font-medium mt-1">Disiplin adalah jembatan antara cita-cita dan pencapaian. Selamat beraktivitas!</p>
                        </div>
                    </div>
                </main>
            </div>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; height: 5px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #1a1a1a; border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #262626; }
                .no-scrollbar::-webkit-scrollbar { display: none; }
                .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    FileText,
    TrendingUp,
    Download,
    Award,
    ChevronDown,
    Loader2,
    Activity,
    Star
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { supabase } from '@/lib/supabase';
import { gradesService } from '@/lib/services/grades';
import { attendanceService } from '@/lib/services/attendance';
import { studentDashboardService } from '@/lib/services/student-dashboard';

export default function RiwayatNilaiPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [studentInfo, setStudentInfo] = useState<any>(null);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [reports, setReports] = useState<any[]>([]);
    const [summary, setSummary] = useState({
        gpa: 0,
        trend: 0,
        totalHafalan: 0,
        attendance: 100
    });

    const fetchData = useCallback(async (userId: string) => {
        try {
            setIsLoading(true);
            const { data: student, error: sError } = await supabase
                .from('students')
                .select('*')
                .eq('user_id', userId)
                .single();

            if (sError) throw sError;
            setStudentInfo(student);

            const gradesData = await gradesService.getByStudent(student.id);

            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const grouped = gradesData.reduce((acc: any, grade: any) => {
                const key = `${grade.academic_year_id || '2024'}-${grade.semester}`;
                if (!acc[key]) {
                    acc[key] = {
                        semester: `Semester ${grade.semester === 1 ? 'Ganjil' : 'Genap'} ${grade.academic_year_id || ''}`,
                        grades: []
                    };
                }
                acc[key].grades.push({
                    no: acc[key].grades.length + 1,
                    name: grade.subject?.name || 'Unknown',
                    kkm: 75,
                    score: grade.final_grade || 0,
                    letter: gradesService.getGradeLetter(grade.final_grade || 0),
                    predicate: getPredicate(grade.final_grade || 0)
                });
                return acc;
            }, {});

            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const reportsArray = Object.values(grouped).map((group: any) => {
                const avg = group.grades.length > 0
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    ? group.grades.reduce((sum: number, g: any) => sum + (g.score || 0), 0) / group.grades.length
                    : 0;
                return {
                    ...group,
                    gpa: (avg / 25).toFixed(2)
                };
            });

            setReports(reportsArray);

            const [gpaH, hafalan, attPercentage] = await Promise.all([
                studentDashboardService.getGPAHistory(student.id),
                studentDashboardService.getHafalanData(student.id),
                attendanceService.getStudentAttendanceSummary(student.id)
            ]);

            const currentGPA = reportsArray.length > 0 ? Number(reportsArray[0].gpa) : 0;
            const prevGPA = gpaH.length > 1 ? gpaH[gpaH.length - 2].gpa : currentGPA;

            setSummary({
                gpa: currentGPA,
                trend: currentGPA - prevGPA,
                totalHafalan: hafalan?.completed || 0,
                attendance: attPercentage
            });
        } catch (err) {
            console.error('Error fetching grades history:', err);
        } finally {
            setIsLoading(false);
        }
    }, []);

    const getPredicate = (score: number) => {
        if (score >= 90) return 'Sangat Baik';
        if (score >= 80) return 'Baik';
        if (score >= 70) return 'Cukup';
        return 'Kurang';
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'santri') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
    }, [router, fetchData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (isLoading && reports.length === 0) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-[#050505]">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-indigo-500 animate-spin opacity-40" />
                    <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-[0.2em]">Menyusun Lapor Akademik...</p>
                </div>
            </div>
        );
    }

    if (!user) return null;

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-400 font-sans selection:bg-indigo-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-10 max-w-[1500px] mx-auto">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-indigo-400 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <Activity className="w-4 h-4" />
                                Academic Transcript
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Riwayat <span className="text-indigo-500">Nilai & Rapor</span>
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Buku laporan pencapaian akademik digital yang terdokumentasi rapi.</p>
                        </div>
                        <div className="flex gap-4">
                            <button className="px-6 py-3.5 bg-neutral-900 border border-neutral-800 rounded-2xl text-[10px] font-black text-white hover:bg-neutral-800 transition-all flex items-center gap-3 uppercase tracking-widest shadow-xl">
                                <Download className="w-4 h-4 text-indigo-500" />
                                Export Rapor PDF
                            </button>
                        </div>
                    </div>

                    {/* Stats Summary */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div className="bg-gradient-to-br from-indigo-600 to-indigo-900 p-8 rounded-[2.5rem] text-white shadow-2xl shadow-indigo-500/10 relative overflow-hidden group">
                            <div className="relative z-10">
                                <p className="text-indigo-100/60 text-[10px] font-black uppercase tracking-widest mb-4">IPK Terakhir</p>
                                <h4 className="text-6xl font-black tracking-tighter">{summary.gpa || '0.00'}</h4>
                                <div className={`mt-6 flex items-center gap-2 text-[10px] font-black uppercase tracking-widest bg-white/10 w-fit px-4 py-2 rounded-xl backdrop-blur-md border border-white/5`}>
                                    <TrendingUp className={`w-3.5 h-3.5 ${summary.trend >= 0 ? 'text-emerald-400' : 'text-rose-400'}`} />
                                    {summary.trend >= 0 ? 'Meningkat' : 'Menurun'} {Math.abs(summary.trend).toFixed(2)}
                                </div>
                            </div>
                            <Award className="absolute top-1/2 right-0 -translate-y-1/2 w-40 h-40 text-white/10 rotate-12 group-hover:rotate-0 transition-transform duration-1000" />
                        </div>

                        <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl flex flex-col justify-center relative group overflow-hidden">
                            <div className="absolute top-0 right-0 p-8 opacity-[0.02] pointer-events-none group-hover:scale-110 transition-transform">
                                <Star className="w-32 h-32" />
                            </div>
                            <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mb-4">Progres Tahfidz</p>
                            <h4 className="text-4xl font-black text-white tracking-tighter">{summary.totalHafalan} <span className="text-lg text-neutral-600 font-bold uppercase ml-1">/ 30 Juz</span></h4>
                            <div className="w-full h-1.5 bg-neutral-900 rounded-full mt-6 overflow-hidden border border-neutral-800">
                                <div className="h-full bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,0.5)] transition-all duration-1000" style={{ width: `${(summary.totalHafalan / 30) * 100}%` }}></div>
                            </div>
                        </div>

                        <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl flex flex-col justify-center relative group overflow-hidden">
                            <div className="absolute top-0 right-0 p-8 opacity-[0.02] pointer-events-none group-hover:scale-110 transition-transform">
                                <Activity className="w-32 h-32" />
                            </div>
                            <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mb-4">Absensi Kehadiran</p>
                            <h4 className="text-4xl font-black text-white tracking-tighter">{summary.attendance}%</h4>
                            <div className="mt-4 flex items-center gap-2">
                                <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>
                                <span className="text-[10px] font-bold text-neutral-400 uppercase tracking-widest">Kualifikasi Sangat Baik</span>
                            </div>
                        </div>
                    </div>

                    {/* Reports List */}
                    <div className="space-y-10">
                        {reports.length === 0 ? (
                            <div className="bg-[#0a0a0a] p-24 rounded-[3rem] border border-neutral-800/50 text-center shadow-2xl">
                                <div className="w-20 h-20 bg-neutral-900 rounded-[2rem] flex items-center justify-center mx-auto mb-8 border border-neutral-800">
                                    <FileText className="w-10 h-10 text-neutral-800" />
                                </div>
                                <h3 className="text-2xl font-black text-white mb-2 tracking-tight">Belum Ada Transkip</h3>
                                <p className="text-neutral-500 max-w-sm mx-auto font-medium">Laporan akademik anda akan muncul di sini setelah divalidasi oleh asatidzah.</p>
                            </div>
                        ) : (
                            reports.map((report, idx) => (
                                <div key={idx} className="bg-[#0a0a0a] rounded-[2.5rem] border border-neutral-800/40 shadow-2xl overflow-hidden">
                                    <div className="p-8 border-b border-neutral-800/50 bg-neutral-900/20 flex items-center justify-between">
                                        <div>
                                            <h3 className="font-black text-white uppercase tracking-[0.2em] text-sm">{report.semester}</h3>
                                            <div className="flex items-center gap-2 mt-1">
                                                <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></div>
                                                <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest">Cumulative GPA: {report.gpa}</p>
                                            </div>
                                        </div>
                                        <button className="p-2.5 bg-[#050505] text-neutral-600 hover:text-white rounded-xl border border-neutral-800 transition-all">
                                            <ChevronDown className="w-5 h-5" />
                                        </button>
                                    </div>
                                    <div className="overflow-x-auto custom-scrollbar">
                                        <table className="w-full text-left font-sans">
                                            <thead>
                                                <tr className="bg-[#0e0e0e] border-b border-neutral-800/50">
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] w-16 text-center">No</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Mata Pelajaran</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">KKM</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Angka</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Grd</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Predikat</th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-neutral-800/20">
                                                {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                                                {report.grades.map((sub: any) => (
                                                    <tr key={sub.no} className="hover:bg-neutral-900/30 transition-all group">
                                                        <td className="px-8 py-6 text-center font-bold text-neutral-700 text-xs">{sub.no}</td>
                                                        <td className="px-8 py-6">
                                                            <div className="flex items-center gap-3">
                                                                <div className="w-8 h-8 rounded-lg bg-neutral-900 border border-neutral-800 flex items-center justify-center text-[10px] font-black text-neutral-500 group-hover:text-indigo-500 group-hover:border-indigo-500/30 transition-all">
                                                                    {sub.no}
                                                                </div>
                                                                <span className="font-bold text-white text-sm uppercase tracking-tight">{sub.name}</span>
                                                            </div>
                                                        </td>
                                                        <td className="px-8 py-6 text-center font-bold text-neutral-600 text-xs">{sub.kkm}</td>
                                                        <td className="px-8 py-6 text-center font-black text-white text-lg tracking-tighter">{sub.score}</td>
                                                        <td className="px-8 py-6 text-center">
                                                            <div className={`w-10 h-10 rounded-xl mx-auto flex items-center justify-center font-black text-sm border ${sub.letter === 'A' ? 'bg-indigo-500 text-white border-indigo-600 shadow-[0_0_15px_rgba(79,70,229,0.3)]' :
                                                                sub.letter === 'B' ? 'bg-neutral-900 text-indigo-400 border-neutral-800' :
                                                                    'bg-neutral-900 text-neutral-600 border-neutral-800'
