        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    CalendarDays,
    Clock,
    MapPin,
    CheckCircle2,
    Calendar,
    ChevronRight,
    Loader2,
    Activity,
    Info
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { ustadzService } from '@/lib/services/ustadz';
import { academicYearService } from '@/lib/services/academic';

const DAYS = ['Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];

export default function JadwalMengajarPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [activeDay, setActiveDay] = useState('Senin');

    // Data state
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [weeklySchedule, setWeeklySchedule] = useState<Record<string, any[]>>({});
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [activeYear, setActiveYear] = useState<any>(null);
    const [isLoading, setIsLoading] = useState(true);

    const fetchData = async (teacherId: string) => {
        try {
            setIsLoading(true);
            const [scheduleData, yearData] = await Promise.all([
                ustadzService.getFullWeeklySchedule(teacherId),
                academicYearService.getActive()
            ]);

            setWeeklySchedule(scheduleData);
            setActiveYear(yearData);

            const dayNames = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
            const today = dayNames[new Date().getDay()];
            if (DAYS.includes(today)) {
                setActiveDay(today);
            }

            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching data:', error);
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'ustadz') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [router]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (!user) return null;

    const schedules = weeklySchedule[activeDay] || [];

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-400 font-sans selection:bg-indigo-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-8 max-w-[1500px] mx-auto">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-indigo-400 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <Activity className="w-4 h-4" />
                                Agenda Pengajaran
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Jadwal <span className="text-indigo-500">Mengajar Mingguan</span>
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Manajemen waktu dan agenda pengajaran rutin Anda.</p>
                        </div>

                        <div className="relative group self-start md:self-auto">
                            <div className="absolute -inset-1 bg-gradient-to-r from-indigo-600 to-violet-600 rounded-2xl blur opacity-25 group-hover:opacity-40 transition duration-1000 group-hover:duration-200 shadow-[0_0_20px_rgba(79,70,229,0.3)]"></div>
                            <div className="relative flex items-center gap-3 px-6 py-3 bg-neutral-900 text-white rounded-2xl font-bold uppercase tracking-widest text-[10px] border border-neutral-800">
                                <CalendarDays className="w-4 h-4 text-indigo-500" />
                                {activeYear?.name || 'Tahun Ajaran'}
                            </div>
                        </div>
                    </div>

                    {/* Day Selection Tabs */}
                    <div className="flex flex-wrap gap-2 p-2 bg-[#0a0a0a] rounded-[2rem] border border-neutral-800/40 shadow-xl overflow-x-auto custom-scrollbar">
                        {DAYS.map(day => (
                            <button
                                key={day}
                                onClick={() => setActiveDay(day)}
                                className={`flex-1 min-w-[120px] py-4 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] transition-all relative overflow-hidden group ${activeDay === day
                                    ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20'
                                    : 'text-neutral-600 hover:bg-neutral-900 hover:text-neutral-300'
                                    }`}
                            >
                                {day}
                                {activeDay === day && (
                                    <div className="absolute bottom-0 left-0 w-full h-1 bg-white/20"></div>
                                )}
                            </button>
                        ))}
                    </div>

                    {/* Schedule List */}
                    <div className="space-y-4 min-h-[400px]">
                        {isLoading ? (
                            <div className="py-24 flex flex-col items-center justify-center gap-4">
                                <Loader2 className="w-10 h-10 text-indigo-500 animate-spin opacity-40" />
                                <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-[0.2em]">Menyusun Jadwal Anda...</p>
                            </div>
                        ) : schedules.length > 0 ? (
                            schedules.map((item) => (
                                <div
                                    key={item.id}
                                    className="bg-[#0a0a0a] p-6 lg:p-8 rounded-[2.5rem] border border-neutral-800/40 hover:border-indigo-500/30 transition-all group flex flex-col md:flex-row md:items-center gap-8 relative overflow-hidden"
                                >
                                    <div className="absolute right-0 top-0 p-8 opacity-[0.02] pointer-events-none group-hover:scale-110 transition-transform">
                                        <Clock className="w-32 h-32" />
                                    </div>

                                    {/* Time Block */}
                                    <div className="flex items-center gap-5 md:w-56 shrink-0 relative z-10">
                                        <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center text-indigo-500 shrink-0">
                                            <Clock className="w-6 h-6" />
                                        </div>
                                        <div>
                                            <p className="text-lg font-black text-white tracking-tight">{item.time}</p>
                                            <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest mt-1">KBM Routine</p>
                                        </div>
                                    </div>

                                    {/* Info Block */}
                                    <div className="flex-1 relative z-10">
                                        <div className="flex flex-wrap items-center gap-3 mb-2">
                                            <span className="px-3 py-1 bg-neutral-900 border border-neutral-800 text-neutral-500 rounded-lg text-[10px] font-bold uppercase tracking-wider">
                                                {item.class}
                                            </span>
                                            <div className="flex items-center gap-1.5 text-neutral-600 ml-1">
                                                <MapPin className="w-3.5 h-3.5" />
                                                <span className="text-[10px] font-bold uppercase tracking-wide">{item.room}</span>
                                            </div>
                                        </div>
                                        <h3 className="text-xl lg:text-2xl font-black text-white group-hover:text-indigo-400 transition-colors uppercase tracking-tight">
                                            {item.subject}
                                        </h3>
                                    </div>

                                    {/* Action/Status */}
                                    <div className="flex items-center justify-between md:justify-end gap-6 border-t md:border-t-0 border-neutral-900 pt-6 md:pt-0 relative z-10">
                                        <span className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest border ${item.status === 'Selesai'
                                            ? 'bg-emerald-500/5 text-emerald-500 border-emerald-500/10'
                                            : 'bg-indigo-500/5 text-indigo-400 border-indigo-500/10 shadow-[0_0_15px_rgba(79,70,229,0.1)]'
                                            }`}>
                                            {item.status}
                                        </span>
                                        <button className="w-12 h-12 bg-neutral-900 text-neutral-600 rounded-2xl flex items-center justify-center hover:bg-indigo-600 hover:text-white transition-all border border-neutral-800 hover:border-indigo-500 group-hover:translate-x-1 shadow-lg shadow-black/50">
                                            <ChevronRight className="w-5 h-5" />
                                        </button>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <div className="bg-[#0a0a0a] rounded-[3rem] border-2 border-dashed border-neutral-800/40 p-20 text-center opacity-60">
                                <div className="w-24 h-24 bg-neutral-900 rounded-full flex items-center justify-center mx-auto mb-8 animate-pulse">
                                    <Calendar className="w-12 h-12 text-neutral-800" />
                                </div>
                                <h3 className="text-xl font-bold text-white mb-3 uppercase tracking-widest">Tidak Ada Jadwal</h3>
                                <p className="text-neutral-600 max-w-sm mx-auto text-sm font-medium">Persiapkan materi untuk hari berikutnya atau gunakan waktu luang untuk evaluasi santri.</p>
                            </div>
                        )}
                    </div>

                    {/* Pro Tip Section */}
                    <div className="p-8 lg:p-10 bg-gradient-to-br from-indigo-950/40 to-black rounded-[3rem] border border-indigo-500/20 relative overflow-hidden group shadow-2xl">
                        <div className="absolute right-0 top-0 p-12 opacity-[0.05] group-hover:scale-110 transition-transform duration-1000">
                            <Info className="w-48 h-48 text-indigo-500" />
                        </div>
                        <div className="relative z-10">
                            <h4 className="text-xl font-black text-white mb-4 flex items-center gap-3">
                                <CheckCircle2 className="w-6 h-6 text-indigo-500" />
                                Verifikasi Kehadiran Guru
                            </h4>
                            <p className="text-neutral-400 text-sm max-w-2xl font-medium leading-relaxed uppercase tracking-wide opacity-80">
                                Pastikan Anda melakukan SCAN QR CODE di setiap awal KBM untuk rekapitulasi kehadiran otomatis di sistem pusat pesantren.
                            </p>
                        </div>
                    </div>
                </main>
            </div>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; height: 5px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #1a1a1a; border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #262626; }
            `}</style>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    ClipboardCheck,
    Save,
    CheckCircle2,
    Loader2,
    Star,
    Search,
    ChevronDown,
    Filter,
    Activity,
    Users
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { ustadzService } from '@/lib/services/ustadz';
import { gradesService } from '@/lib/services/grades';
import { studentsService } from '@/lib/services/students';
import { academicYearService } from '@/lib/services/academic';

interface Class {
    id: string;
    name: string;
}

interface Subject {
    id: string;
    name: string;
}

interface AcademicYear {
    id: string;
    name: string;
}

interface Student {
    id: string;
    name: string;
    nis?: string;
}

interface GradeRecord {
    uh1: number;
    uh2: number;
    uts: number;
    uas: number;
    id?: string;
}

export default function InputNilaiMapelPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);

    // Filter Options
    const [availableClasses, setAvailableClasses] = useState<Class[]>([]);
    const [availableSubjects, setAvailableSubjects] = useState<Subject[]>([]);
    const [activeYear, setActiveYear] = useState<AcademicYear | null>(null);

    // Filters
    const [selectedClass, setSelectedClass] = useState('');
    const [selectedSubject, setSelectedSubject] = useState('');
    const [searchTerm, setSearchTerm] = useState('');

    // Students & Grades state
    const [students, setStudents] = useState<Student[]>([]);
    const [grades, setGrades] = useState<Record<string, GradeRecord>>({});

    // UI state
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [showSuccess, setShowSuccess] = useState(false);

    const fetchInitialData = async (teacherId: string) => {
        try {
            setIsLoading(true);
            const [classes, subjects, year] = await Promise.all([
                ustadzService.getAssignedClasses(teacherId),
                ustadzService.getAssignedSubjects(teacherId),
                academicYearService.getActive()
            ]);

            setAvailableClasses(classes || []);
            setAvailableSubjects(subjects || []);
            setActiveYear(year);

            if (classes && classes.length > 0) {
                const firstClass = classes[0] as Class;
                if (firstClass?.id) setSelectedClass(firstClass.id);
            }
            if (subjects && subjects.length > 0) {
                const firstSubject = subjects[0] as Subject;
                if (firstSubject?.id) setSelectedSubject(firstSubject.id);
            }

            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching initial data:', error);
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'ustadz') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchInitialData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [router]);

    useEffect(() => {
        if (selectedClass && selectedSubject && activeYear) {
            fetchStudentsAndGrades();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [selectedClass, selectedSubject, activeYear]);

    const fetchStudentsAndGrades = async () => {
        try {
            setIsLoading(true);
            const studentData = await studentsService.getByClass(selectedClass);
            setStudents(studentData);

            const semester = 1;
            const existingGrades = await gradesService.getByClass(selectedClass, selectedSubject);

            const gradeMap: typeof grades = {};
            studentData.forEach(s => {
                const found = existingGrades.find(g => g.student_id === s.id && g.semester === semester);
                gradeMap[s.id] = found ? {
                    id: found.id,
                    uh1: found.uh1 || 0,
                    uh2: found.uh2 || 0,
                    uts: found.uts || 0,
                    uas: found.uas || 0,
                } : { uh1: 0, uh2: 0, uts: 0, uas: 0 };
            });
            setGrades(gradeMap);
            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching students/grades:', error);
            setIsLoading(false);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const handleScoreChange = (id: string, field: 'uh1' | 'uh2' | 'uts' | 'uas', value: string) => {
        const val = parseInt(value) || 0;
        setGrades(prev => ({
            ...prev,
            [id]: { ...prev[id], [field]: Math.min(100, val) }
        }));
    };

    const handleSave = async () => {
        if (!user || !activeYear) return;
        setIsSaving(true);
        try {
            const semester = 1;
            const records = students.map(s => {
                const g = grades[s.id];
                return {
                    id: g.id,
                    student_id: s.id,
                    subject_id: selectedSubject,
                    teacher_id: user.id,
                    academic_year_id: activeYear.id,
                    semester: semester as 1 | 2,
                    uh1: g.uh1,
                    uh2: g.uh2,
                    uts: g.uts,
                    uas: g.uas,
                    final_grade: gradesService.calculateFinalGrade(g),
                    grade_letter: gradesService.getGradeLetter(gradesService.calculateFinalGrade(g) || 0)
                };
            });

            await gradesService.bulkUpsert(records);

            setShowSuccess(true);
            setTimeout(() => setShowSuccess(false), 3000);
        } catch (error) {
            console.error('Error saving grades:', error);
            alert('Gagal menyimpan nilai.');
        } finally {
            setIsSaving(false);
        }
    };

    if (!user) return null;

    const filteredStudents = students.filter(s =>
        s.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        s.nis?.includes(searchTerm)
    );

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-400 font-sans selection:bg-indigo-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-8 max-w-[1600px] mx-auto">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-indigo-400 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <Activity className="w-4 h-4" />
                                Penilaian Akademik
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Input <span className="text-indigo-500">Nilai Mapel</span>
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Lakukan pengisian nilai berkala santri untuk semua kompetensi.</p>
                        </div>

                        <button
                            onClick={handleSave}
                            disabled={isSaving}
                            className="relative group transition-all active:scale-95"
                        >
                            <div className="absolute -inset-1 bg-gradient-to-r from-indigo-600 to-violet-600 rounded-2xl blur opacity-25 group-hover:opacity-50 transition duration-1000 group-hover:duration-200 shadow-[0_0_20px_rgba(79,70,229,0.3)]"></div>
                            <div className="relative flex items-center gap-3 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-bold uppercase tracking-widest text-xs hover:bg-indigo-500 transition-colors">
                                {isSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                                Simpan Semua
                            </div>
                        </button>
                    </div>

                    {showSuccess && (
                        <div className="p-4 bg-emerald-500/10 border border-emerald-500/20 rounded-2xl flex items-center gap-3 text-emerald-400 font-bold text-xs uppercase tracking-wider animate-in fade-in slide-in-from-top-4">
                            <CheckCircle2 className="w-4 h-4" />
                            Data nilai telah berhasil diperbarui & tersinkronisasi!
                        </div>
                    )}

                    {/* Filter Grid */}
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-12 gap-4">
                        <div className="lg:col-span-3 space-y-2">
                            <label className="block text-[10px] font-bold text-neutral-600 uppercase tracking-widest ml-1">Pilih Kelas</label>
                            <div className="relative group">
                                <Filter className="w-4 h-4 text-neutral-500 absolute left-4 top-1/2 -translate-y-1/2 pointer-events-none group-focus-within:text-indigo-500" />
                                <select
                                    value={selectedClass}
                                    onChange={e => setSelectedClass(e.target.value)}
                                    className="w-full pl-10 pr-4 py-3.5 bg-[#0a0a0a] border border-neutral-800 rounded-xl focus:outline-none focus:border-indigo-500 text-white font-bold text-sm appearance-none cursor-pointer transition-all"
                                >
                                    {availableClasses.map(c => <option key={c.id} value={c.id} className="bg-neutral-900">Kelas {c.name}</option>)}
                                </select>
                                <ChevronDown className="w-4 h-4 text-neutral-600 absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none" />
                            </div>
                        </div>

                        <div className="lg:col-span-4 space-y-2">
                            <label className="block text-[10px] font-bold text-neutral-600 uppercase tracking-widest ml-1">Mata Pelajaran</label>
                            <div className="relative group">
                                <ClipboardCheck className="w-4 h-4 text-neutral-500 absolute left-4 top-1/2 -translate-y-1/2 pointer-events-none group-focus-within:text-indigo-500" />
                                <select
                                    value={selectedSubject}
                                    onChange={e => setSelectedSubject(e.target.value)}
                                    className="w-full pl-10 pr-4 py-3.5 bg-[#0a0a0a] border border-neutral-800 rounded-xl focus:outline-none focus:border-indigo-500 text-white font-bold text-sm appearance-none cursor-pointer transition-all"
                                >
                                    {availableSubjects.map(s => <option key={s.id} value={s.id} className="bg-neutral-900">{s.name}</option>)}
                                </select>
                                <ChevronDown className="w-4 h-4 text-neutral-600 absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none" />
                            </div>
                        </div>

                        <div className="lg:col-span-5 space-y-2">
                            <label className="block text-[10px] font-bold text-neutral-600 uppercase tracking-widest ml-1">Cari Nama Santri</label>
                            <div className="relative group">
                                <Search className="w-4 h-4 text-neutral-500 absolute left-4 top-1/2 -translate-y-1/2 group-focus-within:text-indigo-500" />
                                <input
                                    type="text"
                                    placeholder="Cari berdasarkan nama atau NIS..."
                                    value={searchTerm}
                                    onChange={e => setSearchTerm(e.target.value)}
                                    className="w-full pl-10 pr-4 py-3.5 bg-[#0a0a0a] border border-neutral-800 rounded-xl focus:outline-none focus:border-indigo-500 text-white font-bold text-sm transition-all placeholder:text-neutral-700 placeholder:font-medium"
                                />
                            </div>
                        </div>
                    </div>

                    {/* Main Table Card */}
                    <div className="bg-[#0a0a0a] rounded-[2rem] border border-neutral-800/40 overflow-hidden shadow-2xl">
                        <div className="overflow-x-auto custom-scrollbar">
                            <table className="w-full text-left border-collapse">
                                <thead>
                                    <tr className="bg-[#0e0e0e] border-b border-neutral-800/50">
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Santri</th>
                                        <th className="px-4 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">UH 1</th>
                                        <th className="px-4 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">UH 2</th>
                                        <th className="px-4 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">UTS</th>
                                        <th className="px-4 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">UAS</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Rata-rata</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-neutral-800/30">
                                    {isLoading ? (
                                        <tr>
                                            <td colSpan={6} className="py-24 text-center">
                                                <div className="flex flex-col items-center gap-4">
                                                    <Loader2 className="w-10 h-10 text-indigo-500 animate-spin opacity-40" />
                                                    <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-[0.2em]">Menyiapkan Data Santri...</p>
                                                </div>
                                            </td>
                                        </tr>
                                    ) : filteredStudents.length === 0 ? (
                                        <tr>
                                            <td colSpan={6} className="py-24 text-center">
                                                <div className="flex flex-col items-center gap-4 opacity-40">
                                                    <Users className="w-12 h-12 text-neutral-700" />
                                                    <p className="text-xs font-bold text-neutral-500 uppercase tracking-widest italic">Tidak ada data santri ditemukan.</p>
                                                </div>
                                            </td>
                                        </tr>
                                    ) : (
                                        filteredStudents.map((s) => {
                                            const g = grades[s.id] || { uh1: 0, uh2: 0, uts: 0, uas: 0 };
                                            const avg = Math.round((g.uh1 + g.uh2 + g.uts + g.uas) / 4);
                                            return (
                                                <tr key={s.id} className="hover:bg-neutral-900/40 transition-all group">
                                                    <td className="px-8 py-5">
                                                        <div className="flex items-center gap-4">
                                                            <div className="w-10 h-10 rounded-xl bg-indigo-500/5 border border-indigo-500/10 flex items-center justify-center font-bold text-indigo-500 text-sm">
                                                                {s.name.charAt(0)}
                                                            </div>
                                                            <div>
                                                                <p className="font-bold text-white text-sm uppercase tracking-tight">{s.name}</p>
                                                                <p className="text-[10px] text-neutral-600 font-bold tracking-widest mt-0.5">NIS: {s.nis}</p>
                                                            </div>
                                                        </div>
                                                    </td>
                                                    {['uh1', 'uh2', 'uts', 'uas'].map((field) => (
                                                        <td key={field} className="px-4 py-5 text-center">
                                                            <input
                                                                type="number"
                                                                value={g[field as keyof typeof g] || ''}
                                                                onChange={e => handleScoreChange(s.id, field as 'uh1' | 'uh2' | 'uts' | 'uas', e.target.value)}
                                                                className="w-14 h-11 text-center bg-[#0a0a0a] border border-neutral-800 rounded-xl focus:outline-none focus:border-indigo-500 text-white font-extrabold text-sm transition-all appearance-none group-hover:bg-neutral-900 shadow-inner"
                                                            />
                                                        </td>
                                                    ))}
                                                    <td className="px-8 py-5 text-center">
                                                        <div className="flex flex-col items-center">
                                                            <span className={`text-lg font-black tracking-tighter ${avg >= 75 ? 'text-indigo-400' : 'text-neutral-700'}`}>{avg}</span>
                                                            <div className="flex gap-0.5 mt-1 overflow-hidden">
                                                                {[1, 2, 3].map(i => (
                                                                    <Star key={i} className={`w-2.5 h-2.5 ${avg >= 85 ? 'text-amber-500 fill-amber-500' : 'text-neutral-800'}`} />
                                                                ))}
                                                            </div>
                                                        </div>
                                                    </td>
                                                </tr>
                                            );
                                        })
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </main>
            </div>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; height: 5px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #1a1a1a; border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #262626; }
                input[type=number]::-webkit-inner-spin-button, 
                input[type=number]::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
            `}</style>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import {
    getCurrentUser,
    clearSession,
    User,
} from '@/lib/auth';
import {
    BookOpen,
    Users,
    ClipboardCheck,
    Calendar,
    Activity,
    Clock,
    MapPin,
    GraduationCap,
    TrendingUp,
    ChevronRight
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ResponsiveContainer,
    BarChart,
    Bar,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip as RechartsTooltip,
    AreaChart,
    Area,
} from 'recharts';

import { ustadzService } from '@/lib/services/ustadz';

export default function UstadzDashboard() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    // Real Data State
    const [stats, setStats] = useState({ totalStudents: 0, totalSubjects: 0, activeSchedules: 0, totalHafalan: 0 });
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [gradeDistribution, setGradeDistribution] = useState<any[]>([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [hafalanProgress, setHafalanProgress] = useState<any[]>([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [todaySchedule, setTodaySchedule] = useState<any[]>([]);

    const fetchData = useCallback(async (userId: string) => {
        try {
            setIsLoading(true);
            setError(null);

            const [dataStats, dist, hafalan, schedule] = await Promise.all([
                ustadzService.getDashboardStats(userId),
                ustadzService.getGradeDistribution(userId),
                ustadzService.getHafalanProgress(userId),
                ustadzService.getTodaySchedule(userId)
            ]);

            setStats(dataStats);
            setGradeDistribution(dist);
            setHafalanProgress(hafalan);
            setTodaySchedule(schedule);
        } catch (err: unknown) {
            console.error('Dashboard Fetch Error:', err);
            setError('Gagal memuat data dashboard.');
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'ustadz') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
    }, [router, fetchData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (isLoading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-[#050505]">
                <div className="flex flex-col items-center">
                    <div className="w-10 h-10 border-2 border-indigo-500/10 border-t-indigo-500 rounded-full animate-spin mb-4" />
                    <p className="text-neutral-500 text-[10px] font-medium tracking-[0.2em] uppercase">Memuat Dashboard...</p>
                </div>
            </div>
        );
    }

    if (!user) return null;

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-300 font-sans selection:bg-indigo-500/30">
            {/* Inject Modern Font */}
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8 space-y-6 lg:space-y-10 max-w-[1400px] mx-auto">
                    {/* Header - Slimmer for Mobile */}
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                        <div>
                            <div className="flex items-center gap-2 text-indigo-400 text-[10px] font-bold tracking-widest uppercase mb-1">
                                <Activity className="w-3.5 h-3.5" />
                                Portal Ustadz
                            </div>
                            <h1 className="text-2xl lg:text-3xl font-extrabold text-white tracking-tight">
                                Ahlan, <span className="text-indigo-500">{user.name.split(' ')[0]}</span> ­ƒæï
                            </h1>
                        </div>
                        <div className="flex md:hidden items-center gap-2 text-[10px] font-bold text-neutral-500">
                            <Calendar className="w-3 h-3" />
                            {new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' })}
                        </div>
                    </div>

                    {/* Stats Grid - Slim & Horizontal-styled for Mobile */}
                    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 lg:gap-6">
                        {[
                            { label: 'Santri', value: stats.totalStudents, icon: Users, color: 'text-indigo-500', bg: 'bg-indigo-500/10' },
                            { label: 'Mapel', value: stats.totalSubjects, icon: GraduationCap, color: 'text-blue-500', bg: 'bg-blue-500/10' },
                            { label: 'Jadwal', value: stats.activeSchedules, icon: Clock, color: 'text-emerald-500', bg: 'bg-emerald-500/10' },
                            { label: 'Hafalan', value: stats.totalHafalan, icon: BookOpen, color: 'text-amber-500', bg: 'bg-amber-500/10' },
                        ].map((s, i) => (
                            <div key={i} className="bg-[#0a0a0a] p-4 lg:p-6 rounded-2xl border border-neutral-800/40 flex items-center gap-3 lg:gap-5 group">
                                <div className={`w-9 h-9 lg:w-12 lg:h-12 rounded-xl ${s.bg} flex items-center justify-center ${s.color}`}>
                                    <s.icon className="w-4 h-4 lg:w-6 lg:h-6" />
                                </div>
                                <div>
                                    <p className="text-[9px] lg:text-[11px] font-bold text-neutral-500 uppercase tracking-wider">{s.label}</p>
                                    <h4 className="text-lg lg:text-2xl font-bold text-white tracking-tight leading-none mt-0.5">{s.value}</h4>
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Main Content Grid */}
                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 lg:gap-8">
                        {/* Charts Area */}
                        <div className="lg:col-span-8 space-y-6 lg:space-y-8">
                            {/* Academic Chart - Shorter in Mobile */}
                            <div className="bg-[#0a0a0a] p-5 lg:p-8 rounded-[2rem] border border-neutral-800/40">
                                <div className="flex items-center justify-between mb-6 lg:mb-10">
                                    <h3 className="text-xs lg:text-sm font-bold text-white flex items-center gap-2">
                                        <TrendingUp className="w-4 h-4 text-indigo-500" />
                                        Sebaran Nilai
                                    </h3>
                                    <span className="text-[9px] font-medium text-neutral-600 uppercase tracking-widest">Akademik</span>
                                </div>
                                <div className="h-[220px] lg:h-[300px] w-full">
                                    <ResponsiveContainer width="100%" height="100%">
                                        <BarChart data={gradeDistribution}>
                                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#171717" />
                                            <XAxis dataKey="grade" axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#525252', fontWeight: 600 }} dy={5} />
                                            <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#525252' }} />
                                            <RechartsTooltip
                                                cursor={{ fill: '#ffffff05' }}
                                                contentStyle={{ backgroundColor: '#0a0a0a', border: '1px solid #222', borderRadius: '12px', fontSize: '12px' }}
                                            />
                                            <Bar dataKey="count" fill="#6366f1" radius={[4, 4, 0, 0]} barSize={35} />
                                        </BarChart>
                                    </ResponsiveContainer>
                                </div>
                            </div>

                            {/* Hafalan Chart - Shorter in Mobile */}
                            <div className="bg-[#0a0a0a] p-5 lg:p-8 rounded-[2rem] border border-neutral-800/40">
                                <div className="flex items-center justify-between mb-6 lg:mb-10">
                                    <h3 className="text-xs lg:text-sm font-bold text-white flex items-center gap-2">
                                        <Activity className="w-4 h-4 text-emerald-500" />
                                        Update Hafalan
                                    </h3>
                                    <span className="text-[9px] font-medium text-neutral-600 uppercase tracking-widest">Pekanan</span>
                                </div>
                                <div className="h-[220px] lg:h-[300px] w-full">
                                    <ResponsiveContainer width="100%" height="100%">
                                        <AreaChart data={hafalanProgress}>
                                            <defs>
                                                <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
                                                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.1} />
                                                    <stop offset="95%" stopColor="#10b981" stopOpacity={0} />
                                                </linearGradient>
                                            </defs>
                                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#171717" />
                                            <XAxis dataKey="week" axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#525252', fontWeight: 600 }} dy={5} />
                                            <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#525252' }} />
                                            <RechartsTooltip contentStyle={{ backgroundColor: '#0a0a0a', border: '1px solid #222', borderRadius: '12px' }} />
                                            <Area type="monotone" dataKey="average" stroke="#10b981" strokeWidth={2} fill="url(#areaGrad)" dot={{ r: 3, fill: '#10b981' }} />
                                        </AreaChart>
                                    </ResponsiveContainer>
                                </div>
                            </div>
                        </div>

                        {/* Sidebar Area */}
                        <div className="lg:col-span-4 space-y-6 lg:space-y-8">
                            {/* Schedule Slim Card */}
                            <div className="bg-[#0a0a0a] p-5 lg:p-6 rounded-[2rem] border border-neutral-800/40 flex flex-col">
                                <div className="flex items-center justify-between mb-5">
                                    <h3 className="text-xs lg:text-sm font-bold text-white flex items-center gap-2">
                                        <Clock className="w-4 h-4 text-amber-500" />
                                        Jadwal Hari Ini
                                    </h3>
                                </div>
                                <div className="space-y-3">
                                    {todaySchedule.length === 0 ? (
                                        <div className="py-8 flex flex-col items-center justify-center border border-dashed border-neutral-800/60 rounded-2xl">
                                            <p className="text-[10px] font-medium text-neutral-600">Tidak ada jadwal</p>
                                        </div>
                                    ) : (
                                        todaySchedule.map((s, i) => (
                                            <div key={i} className="p-4 bg-neutral-900/20 rounded-2xl border border-neutral-800/40 group">
                                                <div className="flex justify-between items-start mb-2">
                                                    <span className="text-[9px] font-bold text-indigo-400/80 tracking-tighter">{s.time}</span>
                                                    <span className="px-2 py-0.5 bg-neutral-800/50 rounded text-[8px] font-bold text-neutral-500 uppercase">{s.class}</span>
                                                </div>
                                                <h4 className="text-xs font-bold text-white group-hover:text-indigo-400 transition-colors truncate uppercase tracking-tight">{s.subject}</h4>
                                                <div className="mt-2 flex items-center gap-1.5 text-neutral-600 text-[9px] font-medium uppercase">
                                                    <MapPin className="w-3 h-3" />
                                                    {s.room}
                                                </div>
                                            </div>
                                        ))
                                    )}
                                </div>
                            </div>

                            {/* Quick Actions - List Style for Mobile */}
                            <div className="space-y-3">
                                <p className="text-[9px] font-bold text-neutral-600 uppercase tracking-[0.2em] px-2 mb-1">Aksi Cepat</p>
                                <div className="grid grid-cols-1 gap-2.5">
                                    {[
                                        { label: 'Input Tahfidz', path: '/dashboard/ustadz/tahfidz', icon: BookOpen, color: 'bg-indigo-600', sub: 'Setoran Halaqoh' },
                                        { label: 'Input Nilai', path: '/dashboard/ustadz/nilai', icon: ClipboardCheck, color: 'bg-[#0e0e0e]', sub: 'Update Akademik' },
                                        { label: 'Database Santri', path: '/dashboard/ustadz/santri', icon: Users, color: 'bg-[#0e0e0e]', sub: 'Binaan Saya' },
                                    ].map((a, i) => (
                                        <button
                                            key={i}
                                            onClick={() => router.push(a.path)}
                                            className={`w-full p-4 rounded-2xl ${a.color} border border-neutral-800/50 flex items-center justify-between group transition-all active:scale-[0.98]`}
                                        >
                                            <div className="flex items-center gap-4">
                                                <div className="w-9 h-9 bg-white/5 rounded-xl flex items-center justify-center">
                                                    <a.icon className="w-4 h-4 text-white" />
                                                </div>
                                                <div className="text-left">
                                                    <span className="text-xs font-bold text-white block leading-none">{a.label}</span>
                                                    <span className="text-[9px] text-neutral-500 font-medium mt-1 block">{a.sub}</span>
                                                </div>
                                            </div>
                                            <ChevronRight className="w-4 h-4 text-neutral-700 group-hover:text-white transition-colors" />
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                </main>
            </div>

            <style jsx global>{`
                @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap');
                
                body {
                    font-family: 'Plus Jakarta Sans', sans-serif;
                    -webkit-font-smoothing: antialiased;
                    letter-spacing: -0.01em;
                }
                .scrollbar-none::-webkit-scrollbar { display: none; }
                
                /* Selection Color */
                ::selection {
                    background: rgba(99, 102, 241, 0.2);
                    color: #fff;
                }
            `}</style>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    Users,
    Search,
    BookOpen,
    Eye,
    Activity,
    Loader2,
    LayoutGrid
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { ustadzService } from '@/lib/services/ustadz';

export default function SantriSayaPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');

    // Data State
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [students, setStudents] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const fetchStudents = async (userId: string) => {
        try {
            setIsLoading(true);
            const data = await ustadzService.getMyStudents(userId);
            setStudents(data);
        } catch (error) {
            console.error('Error fetching students:', error);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'ustadz') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchStudents(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [router]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (!user) return null;

    const filteredData = students.filter(item =>
        item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        item.nis?.includes(searchTerm)
    );

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-400 font-sans selection:bg-indigo-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-8 max-w-[1600px] mx-auto">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-indigo-400 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <Activity className="w-4 h-4" />
                                Manajemen Binaan
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Santri <span className="text-indigo-500">Halaqah Saya</span>
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Daftar santri binaan dalam kelompok halaqoh asuhan Anda.</p>
                        </div>

                        <div className="relative group self-start md:self-auto">
                            <div className="absolute -inset-1 bg-gradient-to-r from-indigo-600 to-violet-600 rounded-2xl blur opacity-20 group-hover:opacity-40 transition duration-1000 group-hover:duration-200"></div>
                            <div className="relative flex items-center gap-3 px-6 py-3.5 bg-indigo-600 text-white rounded-2xl font-bold uppercase tracking-widest text-[10px] shadow-[0_0_20px_rgba(79,70,229,0.3)]">
                                <Users className="w-4 h-4" />
                                Total: {students.length} Santri
                            </div>
                        </div>
                    </div>

                    {/* Search Strip */}
                    <div className="bg-[#0a0a0a] p-4 lg:p-5 rounded-[2rem] border border-neutral-800/40 shadow-xl">
                        <div className="relative group max-w-md">
                            <Search className="w-4 h-4 text-neutral-500 absolute left-4 top-1/2 -translate-y-1/2 group-focus-within:text-indigo-500 transition-colors" />
                            <input
                                type="text"
                                placeholder="Cari berdasarkan nama atau NIS..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full pl-12 pr-4 py-3 bg-[#0c0c0c] border border-neutral-800 rounded-2xl focus:outline-none focus:border-indigo-500 text-white font-bold text-sm transition-all placeholder:text-neutral-700 placeholder:font-medium"
                            />
                        </div>
                    </div>

                    {/* Data Table */}
                    <div className="bg-[#0a0a0a] rounded-[2.5rem] border border-neutral-800/40 overflow-hidden shadow-2xl">
                        <div className="overflow-x-auto custom-scrollbar">
                            <table className="w-full text-left border-collapse">
                                <thead>
                                    <tr className="bg-[#0e0e0e] border-b border-neutral-800/50">
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] w-20">No</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Nama Lengkap</th>
                                        <th className="px-4 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Kelas</th>
                                        <th className="px-4 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Juz Terakhir</th>
                                        <th className="px-4 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Total Hafalan</th>
                                        <th className="px-4 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Status</th>
                                        <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Aksi</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-neutral-800/30">
                                    {isLoading ? (
                                        <tr>
                                            <td colSpan={7} className="py-24 text-center">
                                                <div className="flex flex-col items-center gap-4">
                                                    <Loader2 className="w-10 h-10 text-indigo-500 animate-spin opacity-40" />
                                                    <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-[0.2em]">Menyamakan Data Binaan...</p>
                                                </div>
                                            </td>
                                        </tr>
                                    ) : filteredData.length === 0 ? (
                                        <tr>
                                            <td colSpan={7} className="py-24 text-center">
                                                <div className="flex flex-col items-center gap-4 opacity-40">
                                                    <LayoutGrid className="w-12 h-12 text-neutral-700" />
                                                    <p className="text-xs font-bold text-neutral-500 uppercase tracking-widest italic">Belum ada santri binaan yang terdaftar.</p>
                                                </div>
                                            </td>
                                        </tr>
                                    ) : (
                                        filteredData.map((s, i) => (
                                            <tr key={s.id} className="hover:bg-neutral-900/40 transition-all group">
                                                <td className="px-8 py-5 text-sm font-bold text-neutral-700">{i + 1}</td>
                                                <td className="px-8 py-5">
                                                    <div className="flex items-center gap-4">
                                                        <div className="w-10 h-10 rounded-xl bg-indigo-500/5 border border-indigo-500/10 flex items-center justify-center font-bold text-indigo-500 text-sm">
                                                            {s.name.charAt(0)}
                                                        </div>
                                                        <div>
                                                            <p className="font-bold text-white text-sm uppercase tracking-tight">{s.name}</p>
                                                            <p className="text-[10px] text-neutral-600 font-bold tracking-widest mt-0.5">NIS: {s.nis || '-'}</p>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td className="px-4 py-5 text-center">
                                                    <span className="px-2.5 py-1 bg-neutral-900 text-neutral-500 border border-neutral-800 rounded-lg text-[9px] font-bold uppercase">{s.class}</span>
                                                </td>
                                                <td className="px-4 py-5 text-center">
                                                    <div className="flex items-center justify-center gap-2 group-hover:scale-110 transition-transform">
                                                        <BookOpen className="w-3.5 h-3.5 text-indigo-500/60" />
                                                        <span className="font-bold text-white text-sm">Juz {s.lastJuz}</span>
                                                    </div>
                                                </td>
                                                <td className="px-4 py-5 text-center">
                                                    <div className="flex flex-col items-center">
                                                        <span className="text-sm font-black text-indigo-400 tracking-tighter">{s.totalHafalan} Juz</span>
                                                        <div className="w-16 h-1 bg-neutral-900 rounded-full mt-2 overflow-hidden border border-neutral-800">
                                                            <div className="h-full bg-indigo-500 shadow-[0_0_10px_rgba(79,70,229,0.5)] transition-all duration-1000" style={{ width: `${Math.min(100, (s.totalHafalan / 30) * 100)}%` }}></div>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td className="px-4 py-5 text-center">
                                                    <span className={`px-3 py-1 rounded-lg text-[9px] font-bold uppercase tracking-widest ${s.status === 'Lancar' ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' :
                                                        s.status === 'Baru' ? 'bg-indigo-500/10 text-indigo-400 border border-indigo-500/20' :
                                                            'bg-amber-500/10 text-amber-400 border border-amber-500/20'
                                                        }`}>
                                                        {s.status}
                                                    </span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <button
                                                        onClick={() => router.push(`/dashboard/ustadz/santri/${s.id}`)}
                                                        className="p-2.5 bg-neutral-900 text-neutral-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all border border-neutral-800 hover:border-indigo-500 group-hover:translate-x-1"
                                                    >
                                                        <Eye className="w-4 h-4" />
                                                    </button>
                                                </td>
                                            </tr>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </main>
            </div>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; height: 5px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #1a1a1a; border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #262626; }
            `}</style>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    BookOpen,
    Search,
    Save,
    CheckCircle2,
    ChevronRight,
    Loader2,
    X,
    TrendingUp,
    History,
    MessageSquare,
    Star,
    Award,
    Calendar,
    Activity,
    Plus,
    UserCircle
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { hafalanService } from '@/lib/services/hafalan';

const GRADE_CONFIG = [
    { value: 'A', label: 'Mumtaz', color: 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20', active: 'bg-emerald-600 text-white border-emerald-600 shadow-lg shadow-emerald-500/20' },
    { value: 'B', label: 'Jayyid Jidda', color: 'bg-blue-500/10 text-blue-500 border-blue-500/20', active: 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-500/20' },
    { value: 'C', label: 'Jayyid', color: 'bg-amber-500/10 text-amber-500 border-amber-500/20', active: 'bg-amber-600 text-white border-amber-600 shadow-lg shadow-amber-500/20' },
    { value: 'D', label: 'Maqbul', color: 'bg-orange-500/10 text-orange-500 border-orange-500/20', active: 'bg-orange-600 text-white border-orange-600 shadow-lg shadow-orange-500/20' },
    { value: 'E', label: 'Dhaif', color: 'bg-rose-500/10 text-rose-500 border-rose-500/20', active: 'bg-rose-600 text-white border-rose-600 shadow-lg shadow-rose-500/20' },
];

export default function InputTahfidzPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');

    // Data State
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [activePrograms, setActivePrograms] = useState<any[]>([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [selectedProgram, setSelectedProgram] = useState<any | null>(null);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [programProgress, setProgramProgress] = useState<any[]>([]);

    // UI State
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [showSuccess, setShowSuccess] = useState(false);

    // Form State
    const [form, setForm] = useState({
        unit_number: 1,
        unit_name: '',
        progress_percentage: 100,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        grade: 'A' as any,
        notes: ''
    });

    const fetchPrograms = async () => {
        try {
            setIsLoading(true);
            const data = await hafalanService.getAllActivePrograms();
            setActivePrograms(data);
        } catch (error: unknown) {
            console.error('Error fetching programs:', error);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'ustadz') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchPrograms();
        });
        return () => cancelAnimationFrame(timer);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [router]);

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const handleSelectProgram = async (program: any) => {
        setSelectedProgram(program);
        setIsLoading(true);
        try {
            const progress = await hafalanService.getProgramProgress(program.id);
            setProgramProgress(progress);

            // Auto-fill next unit
            const lastUnit = progress.length > 0
                ? Math.max(...progress.map(p => p.unit_number))
                : 0;

            setForm({
                unit_number: lastUnit + 1,
                unit_name: `Halaqah Ke-${lastUnit + 1}`,
                progress_percentage: 100,
                grade: 'A',
                notes: ''
            });
        } catch (error) {
            console.error('Error fetching progress:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleSave = async () => {
        if (!selectedProgram || !user) return;
        setIsSaving(true);
        try {
            await hafalanService.recordProgress({
                program_id: selectedProgram.id,
                student_id: selectedProgram.student_id,
                unit_number: form.unit_number,
                unit_name: form.unit_name,
                progress_percentage: form.progress_percentage,
                grade: form.grade,
                notes: form.notes,
                evaluated_by: user.id
            });

            setShowSuccess(true);
            // Refresh progress
            const updatedProgress = await hafalanService.getProgramProgress(selectedProgram.id);
            setProgramProgress(updatedProgress);

            setTimeout(() => {
                setShowSuccess(false);
                setForm(prev => ({
                    ...prev,
                    unit_number: prev.unit_number + 1,
                    unit_name: `Halaqah Ke-${prev.unit_number + 1}`,
                    notes: ''
                }));
            }, 2000);
        } catch (error) {
            console.error('Error saving progress:', error);
            alert('Gagal menyimpan data.');
        } finally {
            setIsSaving(false);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const filteredPrograms = activePrograms.filter(p =>
        p.student?.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.student?.nis?.includes(searchQuery) ||
        p.hafalan_type?.name.toLowerCase().includes(searchQuery.toLowerCase())
    );

    if (!user) return null;

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-300 font-sans selection:bg-indigo-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-8 max-w-[1500px] mx-auto">
                    {/* Header */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-indigo-400 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <Activity className="w-4 h-4" />
                                Halaqah Tahfidz
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Input <span className="text-indigo-500">Setoran Hafalan</span>
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Catat progres hafalan santri binaan secara real-time.</p>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
                        {/* Left: Student List */}
                        <div className="lg:col-span-4 bg-[#0a0a0a] rounded-[2rem] border border-neutral-800/50 flex flex-col overflow-hidden h-[calc(100vh-280px)]">
                            <div className="p-6 border-b border-neutral-800/50 bg-[#0c0c0c]">
                                <div className="relative group">
                                    <Search className="w-4 h-4 text-neutral-500 absolute left-4 top-1/2 -translate-y-1/2 group-focus-within:text-indigo-500 transition-colors" />
                                    <input
                                        type="text"
                                        placeholder="Cari nama santri..."
                                        value={searchQuery}
                                        onChange={(e) => setSearchQuery(e.target.value)}
                                        className="w-full pl-12 pr-4 py-3 bg-neutral-900/50 border border-neutral-800 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 text-sm font-semibold text-white transition-all placeholder:text-neutral-600"
                                    />
                                </div>
                            </div>
                            <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
                                {isLoading && activePrograms.length === 0 ? (
                                    <div className="flex flex-col items-center justify-center h-full gap-4">
                                        <Loader2 className="w-8 h-8 text-indigo-500 animate-spin opacity-40" />
                                        <p className="text-[10px] font-bold uppercase tracking-widest text-neutral-600">Menyeleraskan...</p>
                                    </div>
                                ) : filteredPrograms.length === 0 ? (
                                    <div className="flex flex-col items-center justify-center h-full opacity-40 px-10 text-center">
                                        <UserCircle className="w-12 h-12 text-neutral-700 mb-4" />
                                        <p className="text-xs font-bold text-neutral-500">Tidak ada santri ditemukan.</p>
                                    </div>
                                ) : (
                                    filteredPrograms.map(p => (
                                        <button
                                            key={p.id}
                                            onClick={() => handleSelectProgram(p)}
                                            className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all text-left relative overflow-hidden group ${selectedProgram?.id === p.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'hover:bg-neutral-800 active:scale-[0.98]'}`}
                                        >
                                            <div className="w-10 h-10 rounded-xl bg-white/10 flex items-center justify-center shrink-0 font-bold">
                                                {p.student?.name.charAt(0)}
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <h4 className="font-bold text-sm truncate leading-tight uppercase tracking-tight">{p.student?.name}</h4>
                                                <p className={`text-[9px] font-bold uppercase tracking-wider mt-1 ${selectedProgram?.id === p.id ? 'text-indigo-200' : 'text-neutral-500'}`}>
                                                    {p.hafalan_type?.name}
                                                </p>
                                            </div>
                                            <ChevronRight className={`w-4 h-4 transition-transform ${selectedProgram?.id === p.id ? 'translate-x-1' : 'opacity-0 group-hover:opacity-100'}`} />
                                        </button>
                                    ))
                                )}
                            </div>
                        </div>

                        {/* Right: Form Area */}
                        <div className="lg:col-span-8 space-y-6">
                            {selectedProgram ? (
                                <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
                                    {/* Selected Student Stats Card */}
                                    <div className="bg-[#0a0a0a] p-6 lg:p-8 rounded-[2.5rem] border border-neutral-800/50 flex flex-col md:flex-row items-center justify-between gap-6 relative overflow-hidden">
                                        <div className="absolute right-0 top-0 p-8 opacity-[0.03] pointer-events-none">
                                            <Award className="w-48 h-48 text-indigo-500" />
                                        </div>

                                        <div className="flex items-center gap-6 relative z-10 w-full md:w-auto">
                                            <div className="w-16 h-16 lg:w-20 lg:h-20 bg-indigo-500/10 rounded-[1.8rem] flex items-center justify-center border border-indigo-500/20 shrink-0">
                                                <span className="text-2xl lg:text-3xl font-extrabold text-indigo-500">{selectedProgram.student?.name.charAt(0)}</span>
                                            </div>
                                            <div className="min-w-0">
                                                <h3 className="text-xl lg:text-2xl font-extrabold text-white tracking-tight leading-tight uppercase">{selectedProgram.student?.name}</h3>
                                                <div className="flex flex-wrap items-center gap-2 mt-2">
                                                    <span className="px-2.5 py-1 bg-indigo-600 text-white rounded-lg text-[9px] font-bold uppercase">
                                                        {selectedProgram.hafalan_type?.name}
                                                    </span>
                                                    <span className="text-xs font-semibold text-neutral-500 italic">Kelas {selectedProgram.student?.classes?.name || '-'}</span>
                                                </div>
                                            </div>
                                        </div>

                                        <button
                                            onClick={() => setSelectedProgram(null)}
                                            className="hidden md:flex w-10 h-10 items-center justify-center bg-neutral-900 text-neutral-600 rounded-xl hover:bg-rose-500/10 hover:text-rose-500 transition-all border border-neutral-800"
                                        >
                                            <X className="w-5 h-5" />
                                        </button>
                                    </div>

                                    {/* Main Form */}
                                    <div className="bg-[#0a0a0a] rounded-[2.5rem] border border-neutral-800/50 overflow-hidden shadow-2xl">
                                        <div className="p-6 lg:p-10 space-y-10">
                                            {showSuccess && (
                                                <div className="p-4 bg-emerald-500/10 border border-emerald-500/20 rounded-2xl flex items-center gap-4 text-emerald-500 animate-in zoom-in-95 duration-200">
                                                    <CheckCircle2 className="w-5 h-5 flex-shrink-0" />
                                                    <span className="text-xs font-bold uppercase tracking-wider">Berhasil Disimpan!</span>
                                                </div>
                                            )}

                                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 lg:gap-12">
                                                {/* Left: Program Details */}
                                                <div className="space-y-6">
                                                    <h4 className="text-[10px] font-bold text-indigo-400 uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                                                        <TrendingUp className="w-3.5 h-3.5" /> Progres Halaqah
                                                    </h4>
                                                    <div className="space-y-4">
                                                        <div className="space-y-2">
                                                            <label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">Nomor Seri Capaian</label>
                                                            <input
                                                                type="number"
                                                                value={form.unit_number}
                                                                onChange={e => setForm({ ...form, unit_number: parseInt(e.target.value) })}
                                                                className="w-full px-6 py-4 bg-neutral-900 border border-neutral-800 rounded-2xl focus:outline-none focus:border-indigo-500 text-xl font-bold text-white transition-all"
                                                            />
                                                            <p className="text-[9px] font-medium text-neutral-600 italic">
                                                                *Terakhir tercatat pada level {programProgress.length}
                                                            </p>
                                                        </div>
                                                        <div className="space-y-2">
                                                            <label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">Keterangan Capaian</label>
                                                            <input
                                                                type="text"
                                                                placeholder="Misal: Juz 30 / Al-Baqarah"
                                                                value={form.unit_name}
                                                                onChange={e => setForm({ ...form, unit_name: e.target.value })}
                                                                className="w-full px-6 py-4 bg-neutral-900 border border-neutral-800 rounded-2xl focus:outline-none focus:border-indigo-500 font-bold text-white transition-all placeholder:text-neutral-700"
                                                            />
                                                        </div>
                                                    </div>
                                                </div>

                                                {/* Right: Grade & Percentage */}
                                                <div className="space-y-6">
                                                    <h4 className="text-[10px] font-bold text-amber-500 uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                                                        <Star className="w-3.5 h-3.5" /> Penilaian (Itqan)
                                                    </h4>
                                                    <div className="grid grid-cols-5 gap-2">
                                                        {GRADE_CONFIG.map(g => (
                                                            <button
                                                                key={g.value}
                                                                onClick={() => setForm({ ...form, grade: g.value })}
                                                                className={`h-16 flex flex-col items-center justify-center rounded-xl border transition-all active:scale-95 ${form.grade === g.value ? g.active : g.color}`}
                                                            >
                                                                <span className="text-xl font-bold">{g.value}</span>
                                                                <span className="text-[7px] font-bold uppercase mt-1">{g.label}</span>
                                                            </button>
                                                        ))}
                                                    </div>
                                                    <div className="pt-4 space-y-4">
                                                        <div className="flex justify-between items-end mb-2 px-1">
                                                            <label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">Pencapaian (%)</label>
                                                            <span className="text-xl font-bold text-indigo-500">{form.progress_percentage}%</span>
                                                        </div>
                                                        <input
                                                            type="range"
                                                            min="0" max="100" step="10"
                                                            value={form.progress_percentage}
                                                            onChange={e => setForm({ ...form, progress_percentage: parseInt(e.target.value) })}
                                                            className="w-full h-2 bg-neutral-800 rounded-full appearance-none cursor-pointer accent-indigo-500"
                                                        />
                                                    </div>
                                                </div>

                                                {/* Bottom: Notes */}
                                                <div className="md:col-span-2 space-y-3">
                                                    <label className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest flex items-center gap-2">
                                                        <MessageSquare className="w-3.5 h-3.5" /> Catatan Evaluasi
                                                    </label>
                                                    <textarea
                                                        rows={2}
                                                        value={form.notes}
                                                        onChange={e => setForm({ ...form, notes: e.target.value })}
                                                        placeholder="Contoh: Perhatikan tajwid pada hukum nun mati, Mad Thabi'i sudah bagus..."
                                                        className="w-full px-6 py-4 bg-neutral-900 border border-neutral-800 rounded-2xl focus:outline-none focus:border-indigo-500 font-medium text-sm text-white transition-all resize-none placeholder:text-neutral-700 font-sans"
                                                    />
                                                </div>
                                            </div>

                                            <button
                                                onClick={handleSave}
                                                disabled={isSaving || !form.unit_name}
                                                className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-bold uppercase tracking-[0.2em] shadow-xl shadow-indigo-500/10 hover:bg-indigo-500 transition-all active:scale-[0.98] disabled:opacity-30 flex items-center justify-center gap-3 text-sm group"
                                            >
                                                {isSaving ? <Loader2 className="w-5 h-5 animate-spin" /> : <Save className="w-5 h-5 group-hover:scale-110 transition-transform" />}
                                                Sahkan Setoran Hari Ini
                                            </button>
                                        </div>
                                    </div>

                                    {/* History Area */}
                                    <div className="bg-[#0a0a0a] p-6 lg:p-8 rounded-[2.5rem] border border-neutral-800/50">
                                        <div className="flex items-center justify-between mb-6">
                                            <h4 className="text-xs font-bold text-white flex items-center gap-2">
                                                <History className="w-4 h-4 text-indigo-400" />
                                                Riwayat Setoran Terbaru
                                            </h4>
                                        </div>
                                        <div className="space-y-3">
                                            {programProgress.length === 0 ? (
                                                <div className="py-12 flex flex-col items-center justify-center border border-dashed border-neutral-800/50 rounded-3xl">
                                                    <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest italic">Belum ada riwayat</p>
                                                </div>
                                            ) : (
                                                [...programProgress].reverse().slice(0, 3).map((p, i) => (
                                                    <div key={p.id} className="flex items-center justify-between p-5 bg-neutral-900/30 border border-neutral-800/40 rounded-2xl group transition-all hover:border-neutral-700">
                                                        <div className="flex items-center gap-4">
                                                            <div className="w-10 h-10 bg-neutral-800 rounded-xl flex items-center justify-center font-bold text-neutral-500 text-xs text-indigo-400">
                                                                {p.unit_number}
                                                            </div>
                                                            <div>
                                                                <p className="font-bold text-sm text-white uppercase tracking-tight">{p.unit_name}</p>
                                                                <div className="flex items-center gap-2 mt-1">
                                                                    <Calendar className="w-3 h-3 text-neutral-600" />
                                                                    <p className="text-[10px] font-bold text-neutral-500 uppercase tracking-widest">
                                                                        {new Date(p.evaluated_at).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' })}
                                                                    </p>
                                                                </div>
                                                            </div>
                                                        </div>
                                                        <div className={`w-9 h-9 rounded-xl flex items-center justify-center font-bold text-sm shadow-sm ${p.grade === 'A' ? 'bg-emerald-500/10 text-emerald-500' :
                                                            p.grade === 'B' ? 'bg-blue-500/10 text-blue-500' : 'bg-neutral-800 text-neutral-500'
                                                            }`}>
                                                            {p.grade}
                                                        </div>
                                                    </div>
                                                ))
                                            )}
                                        </div>
                                    </div>
                                </div>
                            ) : (
                                <div className="h-full bg-[#0a0a0a] rounded-[2.5rem] border-2 border-dashed border-neutral-800/50 flex flex-col items-center justify-center p-12 lg:p-20 text-center">
                                    <div className="w-24 h-24 lg:w-32 lg:h-32 bg-indigo-500/5 rounded-full flex items-center justify-center mb-8 border border-white/5">
                                        <BookOpen className="w-10 h-10 lg:w-16 lg:h-16 text-indigo-500/20" />
                                    </div>
                                    <h3 className="text-xl lg:text-2xl font-bold text-white mb-3 tracking-tight">Halaqah Mana Hari Ini?</h3>
                                    <p className="text-neutral-500 text-xs font-medium max-w-xs mx-auto leading-relaxed uppercase tracking-wider opacity-60">
                                        Pilih salah satu santri dari daftar di sebelah kiri untuk mulai mencatat progres setoran hafalan mereka.
                                    </p>
                                </div>
                            )}
                        </div>
                    </div>
                </main>
            </div>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #1a1a1a; border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #262626; }
            `}</style>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import {
    getCurrentUser,
    clearSession,
    User,
} from '@/lib/auth';
import {
    Search,
    MessageSquare,
    Phone,
    ArrowRight,
    UserCircle,
    Send
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';

import { homeroomService } from '@/lib/services/homeroom';
import { studentsService } from '@/lib/services/students';

// ============================================
// Types
// ============================================

interface ParentContact {
    id: string;
    student: string;
    parent: string;
    phone: string;
}

export default function HubungiWaliPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');

    // Data state
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [classInfo, setClassInfo] = useState<any>(null);
    const [contacts, setContacts] = useState<ParentContact[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const fetchInitialData = async (teacherId: string) => {
        try {
            setIsLoading(true);
            const cls = await homeroomService.getClassInfo(teacherId);
            if (!cls) {
                alert('Anda belum ditugaskan sebagai Wali Kelas.');
                router.replace('/dashboard/wali-kelas');
                return;
            }
            setClassInfo(cls);

            const studentData = await studentsService.getByClass(cls.id);
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            setContacts(studentData.map((s: any) => ({
                id: s.id,
                student: s.name,
                parent: s.parent_name || 'Wali Santri',
                phone: s.parent_phone || s.phone || ''
            })));

            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching contacts:', error);
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'wali_kelas') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchInitialData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [router]);

    const handleLogout = () => {
