                                    </a>
                                </div>
                            </div>
                        ))}
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import {
    getCurrentUser,
    clearSession,
    User,
} from '@/lib/auth';
import {
    Plus,
    Search,
    BookOpen,
    Loader2,
    CheckCircle2,
    Clock,
    Award,
    Trash2
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { homeroomService } from '@/lib/services/homeroom';
import { hafalanService } from '@/lib/services/hafalan';
import AssignProgramModal from '@/components/hafalan/AssignProgramModal';

interface StudentWithPrograms {
    id: string;
    name: string;
    nis: string;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    programs: any[];
}

export default function WaliKelasHafalanPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');

    // Data state
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [classInfo, setClassInfo] = useState<any>(null);
    const [students, setStudents] = useState<StudentWithPrograms[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    // Modal state
    const [showAssignModal, setShowAssignModal] = useState(false);
    const [selectedStudent, setSelectedStudent] = useState<StudentWithPrograms | null>(null);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'wali_kelas') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchInitialData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [router]);

    const fetchInitialData = async (teacherId: string) => {
        try {
            setIsLoading(true);

            // Get class info
            const cls = await homeroomService.getClassInfo(teacherId);
            if (!cls) {
                alert('Anda belum ditugaskan sebagai Wali Kelas.');
                router.replace('/dashboard/wali-kelas');
                return;
            }
            setClassInfo(cls);

            // Get students with their hafalan programs
            await fetchStudentsWithPrograms(cls.id);

        } catch (error) {
            console.error('Error fetching data:', error);
            alert('Gagal memuat data');
        } finally {
            setIsLoading(false);
        }
    };

    const fetchStudentsWithPrograms = async (classId: string) => {
        try {
            console.log('Fetching students for class:', classId);
            // Get all students in class
            const studentsData = await homeroomService.getStudents(classId);
            console.log('Students found:', studentsData.length);

            // Get hafalan programs for these students (all statuses)
            const studentIds = studentsData.map(s => s.id);
            const programs = await hafalanService.getProgramsByStudentIds(studentIds);
            console.log('Programs found:', programs.length);

            // Combine data and normalize properties
            const studentsWithPrograms = studentsData.map(student => {
                const studentPrograms = programs
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    .filter((p: any) => p.student_id === student.id)
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    .map((p: any) => ({
                        ...p,
                        // Normalize nested properties to match UI expectations
                        hafalan_type: p.hafalan_types || p.hafalan_type
                    }));

                return {
                    id: student.id,
                    name: student.name,
                    nis: student.nis,
                    programs: studentPrograms
                };
            });

            console.log('Processed students with programs:', studentsWithPrograms.length);
            setStudents(studentsWithPrograms);
        } catch (error) {
            console.error('Error fetching students with programs detailed:', error);
            alert('Gagal memuat data santri: ' + JSON.stringify(error));
        }
    };

    const handleAssignProgram = async (studentId: string, hafalanTypeId: string, notes?: string) => {
        if (!user) return;

        try {
            await hafalanService.assignProgram({
                student_id: studentId,
                hafalan_type_id: hafalanTypeId,
                assigned_by: user.id,
                notes
            });

            // Refresh data
            if (classInfo) {
                await fetchStudentsWithPrograms(classInfo.id);
            }

            alert('Program hafalan berhasil ditugaskan!');
        } catch (error: unknown) {
            throw error;
        }
    };

    const handleDeleteProgram = async (programId: string) => {
        if (!confirm('Yakin ingin menghapus program hafalan ini?')) return;

        try {
            await hafalanService.deleteProgram(programId);

            // Refresh data
            if (classInfo) {
                await fetchStudentsWithPrograms(classInfo.id);
            }

            alert('Program hafalan berhasil dihapus');
        } catch (error: unknown) {
            const message = error instanceof Error ? error.message : 'Gagal menghapus program';
            alert(message);
        }
    };

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    const filteredStudents = students.filter(student =>
        student.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        student.nis.includes(searchTerm)
    );

    if (!user) return null;

    return (
        <div className="min-h-screen bg-gray-50">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Header */}
                    <div className="mb-8">
                        <h1 className="text-2xl font-black text-gray-800 tracking-tight">
                            ­ƒôû Manajemen Hafalan
                        </h1>
                        <p className="text-gray-500">
                            {classInfo ? `Kelas ${classInfo.name}` : 'Memuat...'}
                        </p>
                    </div>

                    {/* Stats Cards */}
                    {!isLoading && (
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
                            <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
                                <div className="flex items-center justify-between mb-2">
                                    <p className="text-sm font-semibold text-gray-500">Total Santri</p>
                                    <BookOpen className="w-5 h-5 text-indigo-600" />
                                </div>
                                <p className="text-3xl font-black text-gray-800">{students.length}</p>
                            </div>

                            <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
                                <div className="flex items-center justify-between mb-2">
                                    <p className="text-sm font-semibold text-gray-500">Program Aktif</p>
                                    <CheckCircle2 className="w-5 h-5 text-emerald-600" />
                                </div>
                                <p className="text-3xl font-black text-emerald-600">
                                    {students.reduce((sum, s) => sum + s.programs.filter(p => p.status === 'active').length, 0)}
                                </p>
                            </div>

                            <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
                                <div className="flex items-center justify-between mb-2">
                                    <p className="text-sm font-semibold text-gray-500">Belum Ada Program</p>
                                    <Clock className="w-5 h-5 text-amber-600" />
                                </div>
                                <p className="text-3xl font-black text-amber-600">
                                    {students.filter(s => s.programs.length === 0).length}
                                </p>
                            </div>
                        </div>
                    )}

                    {/* Search */}
                    <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm mb-6">
                        <div className="relative">
                            <Search className="w-5 h-5 text-gray-400 absolute left-4 top-1/2 -translate-y-1/2" />
                            <input
                                type="text"
                                placeholder="Cari nama atau NIS santri..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 text-gray-900"
                            />
                        </div>
                    </div>

                    {/* Students List */}
                    <div className="space-y-4">
                        {isLoading ? (
                            <div className="bg-white p-12 rounded-2xl border border-gray-100 shadow-sm text-center">
                                <Loader2 className="w-8 h-8 text-indigo-600 animate-spin mx-auto mb-3" />
                                <p className="text-gray-500">Memuat data santri...</p>
                            </div>
                        ) : filteredStudents.length === 0 ? (
                            <div className="bg-white p-12 rounded-2xl border border-gray-100 shadow-sm text-center">
                                <p className="text-gray-400 italic">Tidak ada santri ditemukan</p>
                            </div>
                        ) : (
                            filteredStudents.map((student) => (
                                <div
                                    key={student.id}
                                    className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm hover:shadow-md transition-shadow"
                                >
                                    {/* Student Header */}
                                    <div className="flex items-start justify-between mb-4">
                                        <div>
                                            <h3 className="text-lg font-bold text-gray-800">{student.name}</h3>
                                            <p className="text-sm text-gray-500">NIS: {student.nis}</p>
                                        </div>
                                        <button
                                            onClick={() => {
                                                setSelectedStudent(student);
                                                setShowAssignModal(true);
                                            }}
                                            className="flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white font-semibold rounded-xl transition-colors text-sm"
                                        >
                                            <Plus className="w-4 h-4" />
                                            Tugaskan Program
                                        </button>
                                    </div>

                                    {/* Programs */}
                                    {student.programs.length === 0 ? (
                                        <div className="p-4 bg-amber-50 border border-amber-200 rounded-xl text-center">
                                            <p className="text-sm text-amber-700">
                                                Belum ada program hafalan yang ditugaskan
                                            </p>
                                        </div>
                                    ) : (
                                        <div className="space-y-3">
                                            {student.programs.map((program) => (
                                                <div
                                                    key={program.id}
                                                    className="p-4 bg-gray-50 border border-gray-200 rounded-xl"
                                                >
                                                    <div className="flex items-start justify-between">
                                                        <div className="flex-1">
                                                            <div className="flex items-center gap-3">
                                                                <BookOpen className="w-5 h-5 text-indigo-600" />
                                                                <div>
                                                                    <h4 className="font-semibold text-gray-800">
                                                                        {program.hafalan_type?.name || 'Unknown'}
                                                                    </h4>
                                                                    <p className="text-sm text-gray-500">
                                                                        {program.hafalan_type?.total_units} {program.hafalan_type?.unit_name}
                                                                    </p>
                                                                </div>
                                                            </div>
                                                            {program.notes && (
                                                                <p className="text-sm text-gray-600 mt-2 ml-8">
                                                                    ­ƒôØ {program.notes}
                                                                </p>
                                                            )}
                                                            <div className="flex items-center gap-3 mt-2 ml-8">
                                                                <span className={`px-2 py-1 rounded-full text-xs font-bold ${program.status === 'active'
                                                                    ? 'bg-emerald-100 text-emerald-700'
                                                                    : program.status === 'completed'
                                                                        ? 'bg-blue-100 text-blue-700'
                                                                        : 'bg-gray-100 text-gray-700'
                                                                    }`}>
                                                                    {program.status === 'active' ? 'Aktif' :
                                                                        program.status === 'completed' ? 'Selesai' : 'Dijeda'}
                                                                </span>
                                                                <span className="text-xs text-gray-500">
                                                                    Ditugaskan: {new Date(program.assigned_date).toLocaleDateString('id-ID')}
                                                                </span>
                                                            </div>
                                                        </div>
                                                        <button
                                                            onClick={() => handleDeleteProgram(program.id)}
                                                            className="p-2 hover:bg-red-50 text-red-600 rounded-lg transition-colors"
                                                            title="Hapus Program"
                                                        >
                                                            <Trash2 className="w-4 h-4" />
                                                        </button>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            ))
                        )}
                    </div>
                </main>
            </div>

            {/* Assign Program Modal */}
            {selectedStudent && (
                <AssignProgramModal
                    isOpen={showAssignModal}
                    onClose={() => {
                        setShowAssignModal(false);
                        setSelectedStudent(null);
                    }}
                    onAssign={(hafalanTypeId, notes) => handleAssignProgram(selectedStudent.id, hafalanTypeId, notes)}
                    studentName={selectedStudent.name}
                />
            )}
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User
} from '@/lib/auth';
import { convertGrade, GradeConversion } from '@/lib/gradeConverter';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ArrowLeft,
    Save,
    Loader2,
    CheckCircle2,
    Download,
    Eye,
    EyeOff,
    Activity,
    BookOpen,
    Trophy,
    GraduationCap,
    X
} from 'lucide-react';

import { homeroomService } from '@/lib/services/homeroom';
import { studentsService } from '@/lib/services/students';
import { subjectsService, academicYearService } from '@/lib/services/academic';
import { gradesService } from '@/lib/services/grades';

// ============================================
// Types
// ============================================

interface StudentGrades {
    id: string;
    name: string;
    nis: string;
    subjects: Record<string, {
        score: number | null;
        conversion: GradeConversion | null;
        gradeId?: string; // To keep track of existing records
    }>;
}

export default function WaliKelasNilaiPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);

    // Metadata
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [classInfo, setClassInfo] = useState<any>(null);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [subjects, setSubjects] = useState<any[]>([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [academicYear, setAcademicYear] = useState<any>(null);
    const [semester, setSemester] = useState<1 | 2>(1); // Default to Ganjil

    // Students state with all subject grades
    const [students, setStudents] = useState<StudentGrades[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    // Selected student for detail view
    const [selectedStudent, setSelectedStudent] = useState<string | null>(null);

    // View mode
    const [showArabic, setShowArabic] = useState(true);

    // UI state
    const [isSaving, setIsSaving] = useState(false);
    const [showSuccess, setShowSuccess] = useState(false);

    const fetchInitialData = useCallback(async (teacherId: string) => {
        try {
            setIsLoading(true);
            const [cls, allSubjects, activeYear] = await Promise.all([
                homeroomService.getClassInfo(teacherId),
                subjectsService.getAll(),
                academicYearService.getActive()
            ]);

            if (!cls) {
                alert('Anda belum ditugaskan sebagai Wali Kelas.');
                router.replace('/dashboard/wali-kelas');
                return;
            }

            setClassInfo(cls);
            setSubjects(allSubjects);
            setAcademicYear(activeYear);

            // Fetch students and their current grades
            const classStudents = await studentsService.getByClass(cls.id);
            const existingGrades = await gradesService.getByClass(cls.id);

            const initialStudents: StudentGrades[] = classStudents.map(student => {
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                const studentSubjects: Record<string, any> = {};

                allSubjects.forEach(sub => {
                    const gradeRecord = existingGrades.find(g => g.student_id === student.id && g.subject_id === sub.id);
                    const score = gradeRecord ? Number(gradeRecord.final_grade || gradeRecord.uts || gradeRecord.uas || 0) : null;

                    studentSubjects[sub.id] = {
                        score: score,
                        conversion: score !== null ? convertGrade(score) : null,
                        gradeId: gradeRecord?.id
                    };
                });

                return {
                    id: student.id,
                    name: student.name,
                    nis: student.nis,
                    subjects: studentSubjects
                };
            });

            setStudents(initialStudents);
            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching initial data:', error);
            setIsLoading(false);
        }
    }, [router]);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'wali_kelas') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchInitialData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
    }, [router, fetchInitialData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    // Handle score change with real-time conversion
    const handleScoreChange = (studentId: string, subjectId: string, value: string) => {
        const numValue = value === '' ? null : parseInt(value);

        setStudents(prev => prev.map(student => {
            if (student.id !== studentId) return student;

            const newSubjects = { ...student.subjects };

            if (numValue === null || isNaN(numValue)) {
                newSubjects[subjectId] = { score: null, conversion: null };
            } else {
                const clampedValue = Math.max(0, Math.min(100, numValue));
                newSubjects[subjectId] = {
                    score: clampedValue,
                    conversion: convertGrade(clampedValue)
                };
            }

            return { ...student, subjects: newSubjects };
        }));
    };

    // Calculate average
    const calculateAverage = (student: StudentGrades): number | null => {
        const scores = Object.values(student.subjects)
            .map(s => s.score)
            .filter((s): s is number => s !== null);

        if (scores.length === 0) return null;
        return Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
    };

    // Handle save
    const handleSave = async () => {
        if (!classInfo || !user || !academicYear) return;

        try {
            setIsSaving(true);
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const gradesToUpsert: any[] = [];

            students.forEach(student => {
                subjects.forEach(subject => {
                    const gradeData = student.subjects[subject.id];
                    if (gradeData.score !== null) {
                        gradesToUpsert.push({
                            student_id: student.id,
                            subject_id: subject.id,
                            academic_year_id: academicYear.id,
                            semester: semester,
                            uh1: gradeData.score, // Basic mapping for now
                            uh2: gradeData.score,
                            uts: gradeData.score,
                            uas: gradeData.score,
                            final_grade: gradeData.score,
                            grade_letter: gradeData.conversion?.grade || 'C',
                            notes: '',
                        });
                    }
                });
            });

            if (gradesToUpsert.length > 0) {
                await gradesService.bulkUpsert(gradesToUpsert);
            }

            setIsSaving(false);
            setShowSuccess(true);
            setTimeout(() => setShowSuccess(false), 3000);
        } catch (error) {
            console.error('Error saving grades:', error);
            setIsSaving(false);
            alert('Gagal menyimpan nilai.');
        }
    };

    if (!user) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-black">
                <Loader2 className="w-12 h-12 text-indigo-500 animate-spin" />
            </div>
        );
    }

    const selectedStudentData = students.find(s => s.id === selectedStudent);

    return (
        <div className="min-h-screen bg-black flex flex-col lowercase-none">
            {/* Success Toast (Midnight style) */}
            {showSuccess && (
                <div className="fixed top-24 right-8 z-[60] bg-emerald-500/10 border border-emerald-500/20 backdrop-blur-xl text-emerald-400 px-8 py-5 rounded-3xl shadow-2xl flex items-center gap-4 animate-in fade-in slide-in-from-right-4 duration-500">
                    <div className="w-10 h-10 bg-emerald-500/20 rounded-xl flex items-center justify-center">
                        <CheckCircle2 className="w-6 h-6" />
                    </div>
                    <div>
                        <p className="font-black uppercase tracking-widest text-[10px]">Sinkron Berhasil</p>
                        <p className="text-sm font-bold text-white/90">Semua nilai telah tersimpan aman.</p>
                    </div>
                </div>
            )}

            {/* Detail Modal (Premium Midnight) */}
            {selectedStudentData && (
                <div className="fixed inset-0 bg-black/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
                    <div className="bg-[#0c0c0c] border border-neutral-800 rounded-[3rem] w-full max-w-2xl shadow-3xl max-h-[90vh] overflow-hidden flex flex-col relative">
                        <div className="p-10 border-b border-neutral-800 flex items-center justify-between">
                            <div className="flex items-center gap-6">
                                <div className="w-16 h-16 bg-indigo-500/10 rounded-2xl flex items-center justify-center text-indigo-500 border border-indigo-500/20">
                                    <Trophy className="w-8 h-8" />
                                </div>
                                <div>
                                    <h3 className="text-2xl font-black text-white tracking-tight">{selectedStudentData.name}</h3>
                                    <p className="text-[10px] text-neutral-500 font-black uppercase tracking-[0.2em] mt-1">NIS: {selectedStudentData.nis} ÔÇó Kelas {classInfo?.name}</p>
                                </div>
                            </div>
                            <button
                                onClick={() => setSelectedStudent(null)}
                                className="w-12 h-12 bg-neutral-900 rounded-2xl flex items-center justify-center text-neutral-500 hover:text-white transition-colors border border-neutral-800"
                            >
                                <X className="w-5 h-5" />
                            </button>
                        </div>

                        <div className="p-10 overflow-y-auto flex-1 space-y-6">
                            {subjects.map(subject => {
                                const gradeData = selectedStudentData.subjects[subject.id];
                                return (
                                    <div key={subject.id} className="bg-neutral-900/50 border border-neutral-800 rounded-[2rem] p-8 hover:bg-neutral-900 transition-colors group">
                                        <div className="flex items-center justify-between mb-6">
                                            <div>
                                                <div className="flex items-center gap-3 mb-1">
                                                    <BookOpen className="w-4 h-4 text-indigo-500" />
                                                    <p className="font-black text-white text-lg tracking-tight uppercase tracking-widest text-xs">{subject.name}</p>
                                                </div>
                                                <p className="text-[10px] text-neutral-600 font-black uppercase tracking-widest">{subject.code}</p>
                                            </div>
                                            <div className="text-right">
                                                <p className="text-3xl font-black text-white tabular-nums group-hover:text-indigo-400 transition-colors">
                                                    {gradeData?.score ?? '-'}
                                                </p>
                                            </div>
                                        </div>

                                        {gradeData?.conversion && (
                                            <div className="grid grid-cols-3 gap-6 pt-6 border-t border-neutral-800/50">
                                                <div className="text-center">
                                                    <p className="text-[9px] text-neutral-600 font-black uppercase tracking-widest mb-3">Grade</p>
                                                    <span className={`inline-block px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest border ${gradeData.conversion.grade === 'A' ? 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' :
                                                        gradeData.conversion.grade === 'B' ? 'bg-blue-500/10 text-blue-500 border-blue-500/20' :
                                                            gradeData.conversion.grade === 'C' ? 'bg-amber-500/10 text-amber-500 border-amber-500/20' :
                                                                'bg-rose-500/10 text-rose-500 border-rose-500/20'
                                                        }`}>
                                                        {gradeData.conversion.grade}
                                                    </span>
                                                </div>
                                                <div className="text-center">
                                                    <p className="text-[9px] text-neutral-600 font-black uppercase tracking-widest mb-2">Arab</p>
                                                    <p className="text-white font-black text-xl font-arabic" dir="rtl">
                                                        {gradeData.conversion.arab_angka}
                                                    </p>
                                                </div>
                                                <div className="text-right">
                                                    <p className="text-[9px] text-neutral-600 font-black uppercase tracking-widest mb-1">Status</p>
                                                    <p className="text-[10px] text-white font-black uppercase tracking-widest leading-none">{gradeData.conversion.predikat}</p>
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                );
                            })}
                        </div>

                        <div className="p-10 border-t border-neutral-800 bg-neutral-950/50">
                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="text-[10px] text-neutral-500 font-black uppercase tracking-[0.2em] mb-1">Rata-rata Akumulasi</p>
                                    <div className="flex items-center gap-4">
                                        <p className="text-4xl font-black text-indigo-500 tabular-nums shadow-glow-indigo">
                                            {calculateAverage(selectedStudentData) ?? '-'}
                                        </p>
                                        <div className="w-1.5 h-1.5 bg-neutral-800 rounded-full" />
                                        <p className="text-sm font-black text-white/60 tracking-widest uppercase">Pencapaian Final</p>
                                    </div>
                                </div>
                                <button
                                    onClick={() => setSelectedStudent(null)}
                                    className="px-10 py-5 bg-white text-black font-black uppercase tracking-widest text-[10px] rounded-2xl hover:scale-105 active:scale-95 transition-all shadow-xl"
                                >
                                    Selesai Review
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64 flex-1">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-10">
                    {/* Page Header (Midnight Optimized) */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
                        <div>
                            <button
                                onClick={() => router.push('/dashboard/wali-kelas')}
                                className="flex items-center gap-2 text-neutral-500 hover:text-white transition-colors mb-6 text-[10px] font-black uppercase tracking-[0.2em] group"
                            >
                                <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
                                Kembali Ke Beranda
                            </button>
                            <div className="flex items-center gap-2 text-indigo-500 font-bold text-xs uppercase tracking-[0.2em] mb-4">
                                <Activity className="w-4 h-4" />
                                Master Akademik
                            </div>
                            <h1 className="text-4xl lg:text-5xl font-black text-white tracking-tight leading-none mb-3">
                                Input Nilai <span className="text-indigo-500 italic">Perwalian</span>
                            </h1>
                            <p className="text-neutral-500 font-medium max-w-2xl leading-relaxed">
                                Kelola pencapaian semester <span className="text-white font-bold">{semester === 1 ? 'Ganjil' : 'Genap'}</span> untuk <span className="text-white font-bold">Kelas {classInfo?.name}</span> (T.A. {academicYear?.name}).
                            </p>
                        </div>

                        <div className="flex flex-wrap items-center gap-4">
                            <button
                                onClick={() => setShowArabic(!showArabic)}
                                className={`flex items-center gap-3 px-6 py-4 rounded-2xl font-black uppercase tracking-widest text-[10px] border transition-all ${showArabic
                                    ? 'bg-indigo-500/10 text-indigo-500 border-indigo-500/20 shadow-glow-indigo'
                                    : 'bg-neutral-900 text-neutral-500 border-neutral-800'
                                    }`}
                            >
                                {showArabic ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                                {showArabic ? 'Hide Arabic' : 'Show Arabic'}
                            </button>
                            <button className="flex items-center gap-3 px-6 py-4 bg-neutral-900 border border-neutral-800 text-neutral-400 font-black uppercase tracking-widest text-[10px] rounded-2xl hover:text-white transition-all shadow-xl active:scale-95">
                                <Download className="w-4 h-4" />
                                Export
                            </button>
                        </div>
                    </div>

                    {/* Desktop Matrix (Premium Midnight Table) */}
                    <div className="bg-[#0c0c0c] rounded-[3.5rem] border border-neutral-800 shadow-3xl overflow-hidden relative">
                        <div className="overflow-x-auto scrollbar-thin scrollbar-thumb-neutral-800 scrollbar-track-transparent">
                            <table className="w-full text-left">
                                <thead className="bg-neutral-900/40 border-b border-neutral-800">
                                    <tr>
                                        <th className="px-10 py-10 text-[10px] font-black text-neutral-500 uppercase tracking-[0.2em] sticky left-0 bg-[#0c0c0c] z-20 min-w-[240px]">
                                            Profil Santri
                                        </th>
                                        {subjects.map(subject => (
                                            <th key={subject.id} className="px-8 py-10 transition-colors hover:bg-neutral-900/50 min-w-[140px]">
                                                <div className="text-[9px] text-indigo-500 font-black mb-1.5 uppercase tracking-widest">{subject.code}</div>
                                                <div className="text-white font-black uppercase tracking-widest text-[10px] leading-tight">{subject.name}</div>
                                            </th>
                                        ))}
                                        <th className="px-10 py-10 text-[10px] font-black text-white uppercase tracking-[0.2em] text-center bg-indigo-500/10 min-w-[100px] border-l border-neutral-800">
                                            AVG
                                        </th>
                                        <th className="px-10 py-10 text-[10px] font-black text-neutral-500 uppercase tracking-[0.2em] text-center min-w-[80px]">
                                            OPS
                                        </th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-neutral-800/50">
                                    {isLoading ? (
                                        <tr>
                                            <td colSpan={subjects.length + 3} className="px-10 py-48 text-center">
                                                <div className="flex flex-col items-center gap-6">
                                                    <Loader2 className="w-16 h-16 text-indigo-500 animate-spin" />
                                                    <p className="text-neutral-500 font-black uppercase tracking-[0.3em] text-[10px]">Sinkronisasi Data Akademik...</p>
                                                </div>
                                            </td>
                                        </tr>
                                    ) : (
                                        students.map((student, index) => {
                                            const average = calculateAverage(student);
                                            const avgConversion = average !== null ? convertGrade(average) : null;

                                            return (
                                                <tr key={student.id} className="hover:bg-indigo-500/[0.02] transition-colors group/row">
                                                    <td className="px-10 py-8 sticky left-0 bg-[#0c0c0c] z-10 border-r border-neutral-800/50 group-hover/row:bg-neutral-900 transition-colors">
                                                        <div className="flex items-center gap-5">
                                                            <div className="w-10 h-10 bg-neutral-900 rounded-xl flex items-center justify-center border border-neutral-800 shadow-inner group-hover/row:border-indigo-500/30 transition-all">
                                                                <span className="text-[10px] font-black text-neutral-500 group-hover/row:text-indigo-500">{index + 1}</span>
                                                            </div>
                                                            <div>
                                                                <p className="font-black text-white text-sm tracking-tight mb-1 group-hover/row:text-indigo-400 transition-colors">{student.name}</p>
                                                                <p className="text-[10px] text-neutral-600 font-black uppercase tracking-widest">{student.nis}</p>
                                                            </div>
                                                        </div>
                                                    </td>
                                                    {subjects.map(subject => {
                                                        const gradeData = student.subjects[subject.id];
                                                        return (
                                                            <td key={subject.id} className="p-4 transition-colors group/cell hover:bg-neutral-900">
                                                                <div className="flex flex-col items-center gap-3">
                                                                    <div className="relative">
                                                                        <input
                                                                            type="number"
                                                                            min={0}
                                                                            max={100}
                                                                            value={gradeData?.score ?? ''}
                                                                            onChange={(e) => handleScoreChange(student.id, subject.id, e.target.value)}
                                                                            className="w-20 px-3 py-4 text-center bg-neutral-900 border border-neutral-800 rounded-2xl focus:outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 text-sm font-black text-white transition-all tabular-nums"
                                                                        />
                                                                        <div className="absolute -top-1.5 -right-1.5 w-3 h-3 bg-neutral-900 rounded-full border-2 border-neutral-800 group-focus-within/cell:border-indigo-500 transition-colors" />
                                                                    </div>
                                                                    {showArabic && gradeData?.conversion && (
                                                                        <div className="text-lg font-black text-neutral-600 font-arabic leading-none h-6 group-hover/cell:text-indigo-400/50 transition-colors" dir="rtl">
                                                                            {gradeData.conversion.arab_angka}
                                                                        </div>
                                                                    )}
                                                                </div>
                                                            </td>
                                                        );
                                                    })}
                                                    <td className="px-10 py-8 text-center bg-indigo-500/[0.03] border-l border-neutral-800">
                                                        {avgConversion ? (
                                                            <div className="flex flex-col items-center gap-2">
                                                                <span className="text-xl font-black text-white tabular-nums shadow-glow-indigo">{average}</span>
                                                                <span className={`px-3 py-1 rounded-xl text-[9px] font-black border ${avgConversion.grade === 'A' ? 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' :
                                                                    avgConversion.grade === 'B' ? 'bg-blue-500/10 text-blue-500 border-blue-500/20' :
                                                                        avgConversion.grade === 'C' ? 'bg-amber-500/10 text-amber-500 border-amber-500/20' :
                                                                            'bg-rose-500/10 text-rose-500 border-rose-500/20'
                                                                    }`}>
                                                                    {avgConversion.grade}
                                                                </span>
                                                            </div>
                                                        ) : (
                                                            <span className="text-neutral-700 font-black">ÔÇö</span>
                                                        )}
                                                    </td>
                                                    <td className="px-10 py-8 text-center">
                                                        <button
                                                            onClick={() => setSelectedStudent(student.id)}
                                                            className="w-10 h-10 bg-neutral-900 hover:bg-indigo-500/20 hover:text-indigo-500 border border-neutral-800 rounded-xl flex items-center justify-center text-neutral-600 transition-all active:scale-90"
                                                        >
                                                            <Eye className="w-4 h-4" />
                                                        </button>
                                                    </td>
                                                </tr>
                                            );
                                        })
                                    )}
                                </tbody>
                            </table>
                        </div>

                        {/* Save Bar (Premium Footer) */}
                        <div className="p-10 border-t border-neutral-800 flex flex-col md:flex-row items-center justify-between gap-6 bg-neutral-950/30">
                            <div className="flex items-center gap-8">
                                <div className="flex flex-col">
                                    <span className="text-[10px] text-neutral-500 font-black uppercase tracking-widest mb-1.5">Total Database</span>
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 rounded-lg bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center text-indigo-500 font-black text-xs">
                                            {students.length}
                                        </div>
                                        <span className="text-white font-black text-xs uppercase tracking-widest">Santri Aktif</span>
                                    </div>
                                </div>
                                <div className="w-px h-10 bg-neutral-800" />
                                <div className="flex flex-col">
                                    <span className="text-[10px] text-neutral-500 font-black uppercase tracking-widest mb-1.5">Mata Pelajaran</span>
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 rounded-lg bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-500 font-black text-xs">
                                            {subjects.length}
                                        </div>
                                        <span className="text-white font-black text-xs uppercase tracking-widest">Mapel Terkoneksi</span>
                                    </div>
                                </div>
                            </div>

                            <button
                                onClick={handleSave}
                                disabled={isSaving}
                                className="w-full md:w-auto px-12 py-5 bg-indigo-600 hover:bg-indigo-500 text-white font-black uppercase tracking-[0.2em] text-[10px] rounded-2xl transition-all flex items-center justify-center gap-4 disabled:opacity-50 shadow-2xl shadow-indigo-500/20 active:scale-95 group"
                            >
                                {isSaving ? (
                                    <>
                                        <Loader2 className="w-5 h-5 animate-spin" />
                                        Sync Terminal...
                                    </>
                                ) : (
                                    <>
                                        <Save className="w-5 h-5 group-hover:scale-125 transition-transform" />
                                        Simpan Perubahan
                                    </>
                                )}
                            </button>
                        </div>
                    </div>

                    {/* Bottom Guidance (Midnight Integrated) */}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 pb-10">
                        <div className="bg-indigo-500/5 border border-indigo-500/10 rounded-[2.5rem] p-10 flex gap-6">
                            <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center text-indigo-500 shrink-0">
                                <GraduationCap className="w-7 h-7" />
                            </div>
                            <div>
                                <h4 className="font-black text-white text-lg tracking-tight mb-2">Hak Akses Wali Kelas</h4>
                                <p className="text-sm text-neutral-500 font-medium leading-relaxed">
                                    Sebagai wali kelas, Anda memegang hak penuh untuk mengelola nilai di kelas perwalian Anda. Pastikan semua angka telah diverifikasi sebelum melakukan <span className="text-indigo-400 font-black tracking-widest uppercase text-[10px]">Simpan Perubahan</span>.
                                </p>
                            </div>
                        </div>
                        <div className="bg-neutral-900/30 border border-neutral-800 rounded-[2.5rem] p-10">
                            <h4 className="font-black text-white text-lg tracking-tight mb-6">Grading Matrix</h4>
                            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                                {[
                                    { grade: 'A', range: '90-100', color: 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20' },
                                    { grade: 'B', range: '80-89', color: 'bg-blue-500/10 text-blue-500 border-blue-500/20' },
                                    { grade: 'C', range: '70-79', color: 'bg-amber-500/10 text-amber-500 border-amber-500/20' },
                                    { grade: 'D/E', range: '<70', color: 'bg-rose-500/10 text-rose-500 border-rose-500/20' },
                                ].map((item, idx) => (
                                    <div key={idx} className={`p-4 rounded-2xl border ${item.color} flex flex-col items-center gap-1`}>
                                        <span className="font-black text-xl">{item.grade}</span>
                                        <span className="text-[9px] font-black uppercase tracking-widest opacity-60 text-white">{item.range}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import {
    getCurrentUser,
    clearSession,
    User,
} from '@/lib/auth';
import {
    Users,
    Activity,
    Clock,
    TrendingUp,
    ShieldAlert,
    ChevronRight,
    Search,
    Phone,
    CheckCircle2
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import {
    ResponsiveContainer,
    PieChart,
    Pie,
    Cell,
    BarChart,
    Bar,
    XAxis,
    YAxis,
    CartesianGrid,
    Tooltip as RechartsTooltip,
    Legend
} from 'recharts';

// ============================================
// Mock Data
// ============================================

const ATTENDANCE_DATA = [
    { name: 'Hadir', value: 22, color: '#10b981' },
    { name: 'Sakit', value: 2, color: '#f59e0b' },
    { name: 'Izin', value: 1, color: '#3b82f6' },
    { name: 'Alpha', value: 1, color: '#ef4444' },
];

const GRADE_DATA = [
    { subject: 'Fiqih', score: 85 },
    { subject: 'MTK', score: 70 },
    { subject: 'Arab', score: 88 },
    { subject: 'Inggris', score: 75 },
];

const VIOLATION_LIST = [
    { name: 'Muhammad Rizki', points: 50, color: 'bg-red-500' },
    { name: 'Hasan Basri', points: 35, color: 'bg-orange-500' },
    { name: 'Ibrahim Malik', points: 20, color: 'bg-amber-500' },
];

import { homeroomService } from '@/lib/services/homeroom';
import { Loader2 } from 'lucide-react';

export default function WaliKelasDashboard() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);

    // Real Data State
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [classInfo, setClassInfo] = useState<any>(null);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [attendanceData, setAttendanceData] = useState<any[]>([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [gradeData, setGradeData] = useState<any[]>([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [violationList, setViolationList] = useState<any[]>([]);

    const fetchData = useCallback(async (teacherId: string) => {
        try {
            const info = await homeroomService.getClassInfo(teacherId);
            if (!info) {
                setClassInfo({ name: 'Belum Ada Kelas' });
                setIsLoading(false);
                return;
            }
            setClassInfo(info);

            // Fetch with individual error handling
            try {
                const attendance = await homeroomService.getAttendanceSummary(info.id);
                setAttendanceData(attendance);
            } catch (err) {
                console.warn('Attendance data unavailable:', err);
                setAttendanceData([]);
            }

            try {
                const grades = await homeroomService.getGradeSummary(info.id);
                setGradeData(grades);
            } catch (err) {
                console.warn('Grade data unavailable:', err);
                setGradeData([]);
            }

            try {
                const violations = await homeroomService.getTopViolations(info.id);
                setViolationList(violations);
            } catch (err) {
                console.warn('Violation data unavailable:', err);
                setViolationList([]);
            }

            setIsLoading(false);
        } catch (err) {
            console.error('Error fetching homeroom data:', err);
            setClassInfo({ name: 'Error loading class' });
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'wali_kelas') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
    }, [router, fetchData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (isLoading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50">
                <Loader2 className="w-8 h-8 text-rose-600 animate-spin" />
            </div>
        );
    }

    if (!user) return null;

    return (
        <div className="min-h-screen bg-black flex flex-col">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64 flex-1">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-10">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-indigo-500 font-bold text-xs uppercase tracking-[0.2em] mb-3">
                                <Activity className="w-4 h-4" />
                                Smart Pesantren Monitoring
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-black text-white tracking-tight leading-tight">
                                Portal Wali Kelas<br />
                                <span className="text-indigo-500 italic">Kelas {classInfo?.name || '...'}</span>
                            </h1>
                            <p className="text-neutral-500 font-medium mt-2 max-w-xl text-sm lg:text-base leading-relaxed">
                                Pantau perkembangan akademik, kedisplinan, dan kehadiran santri perwalian Anda secara real-time.
                            </p>
                        </div>
                        <div className="flex">
                            <div className="px-5 py-3 bg-[#0c0c0c] border border-neutral-800 shadow-xl rounded-2xl text-white text-sm font-bold flex items-center gap-3">
                                <div className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-sm shadow-emerald-900"></div>
                                Tahun Ajaran 2024/2025
                            </div>
                        </div>
                    </div>

                    {/* Charts Row */}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                        {/* Attendance Pie Chart */}
                        <div className="bg-[#0c0c0c] p-8 rounded-[2.5rem] border border-neutral-800 shadow-2xl flex flex-col h-[480px] relative overflow-hidden group">
                            <div className="absolute top-0 right-0 p-4 opacity-[0.02] group-hover:opacity-[0.05] transition-opacity pointer-events-none">
                                <Activity className="w-48 h-48 text-indigo-500" />
                            </div>
                            <div className="mb-8 flex items-center justify-between relative z-10">
                                <div className="flex items-center gap-4">
                                    <div className="w-14 h-14 bg-indigo-500/10 rounded-2xl flex items-center justify-center border border-indigo-500/20 shadow-inner">
                                        <Activity className="w-7 h-7 text-indigo-500" />
                                    </div>
                                    <div>
                                        <h3 className="text-xl font-extrabold text-white">Kehadiran</h3>
                                        <p className="text-[10px] text-neutral-500 font-black uppercase tracking-[0.2em] mt-1">Harian Santri</p>
                                    </div>
                                </div>
                            </div>
                            <div className="flex-1 relative z-10">
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={attendanceData}
                                            innerRadius={80}
                                            outerRadius={110}
                                            paddingAngle={8}
                                            dataKey="value"
                                            stroke="none"
                                        >
                                            {attendanceData.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={entry.color} className="hover:opacity-80 transition-opacity outline-none shadow-glow" />
                                            ))}
                                        </Pie>
                                        <RechartsTooltip
                                            contentStyle={{ backgroundColor: '#111', borderRadius: '20px', border: '1px solid #333', color: '#fff' }}
                                        />
                                        <Legend
                                            verticalAlign="bottom"
                                            align="center"
                                            iconType="circle"
                                            wrapperStyle={{ fontSize: '12px', fontWeight: '800', color: '#94a3b8' }}
                                        />
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                        </div>

                        {/* Grade Bar Chart */}
                        <div className="bg-[#0c0c0c] p-8 rounded-[2.5rem] border border-neutral-800 shadow-2xl flex flex-col h-[480px] relative overflow-hidden group">
                            <div className="absolute top-0 right-0 p-4 opacity-[0.02] group-hover:opacity-[0.05] transition-opacity pointer-events-none">
                                <TrendingUp className="w-48 h-48 text-indigo-500" />
                            </div>
                            <div className="mb-8 flex items-center justify-between relative z-10">
                                <div className="flex items-center gap-4">
                                    <div className="w-14 h-14 bg-emerald-500/10 rounded-2xl flex items-center justify-center border border-emerald-500/20 shadow-inner">
                                        <TrendingUp className="w-7 h-7 text-emerald-500" />
                                    </div>
                                    <div>
                                        <h3 className="text-xl font-extrabold text-white">Rata-Rata Nilai</h3>
                                        <p className="text-[10px] text-neutral-500 font-black uppercase tracking-[0.2em] mt-1">Pencapaian Mapel</p>
                                    </div>
                                </div>
                            </div>
                            <div className="flex-1 relative z-10">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={gradeData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1a1a1a" />
                                        <XAxis dataKey="subject" axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#666', fontWeight: 800 }} />
                                        <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#666' }} />
                                        <RechartsTooltip
                                            cursor={{ fill: 'rgba(255,255,255,0.05)', radius: 12 }}
                                            contentStyle={{ backgroundColor: '#111', borderRadius: '20px', border: '1px solid #333', color: '#fff' }}
                                        />
                                        <Bar dataKey="score" fill="#6366f1" radius={[12, 12, 12, 12]} barSize={32}>
                                            {gradeData.map((entry, index) => (
                                                <Cell key={`cell-${index}`} fill={index % 2 === 0 ? '#4f46e5' : '#818cf8'} />
                                            ))}
                                        </Bar>
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 pb-10">
                        {/* Violations List Widget */}
                        <div className="lg:col-span-1 bg-[#0c0c0c] p-8 rounded-[2.5rem] border border-neutral-800 shadow-2xl group">
                            <div className="mb-10 flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <div className="w-12 h-12 bg-rose-500/10 rounded-2xl flex items-center justify-center border border-rose-500/20 shadow-sm">
                                        <ShieldAlert className="w-6 h-6 text-rose-500" />
                                    </div>
                                    <div>
                                        <h3 className="font-extrabold text-white text-lg">Disiplin</h3>
                                        <p className="text-[10px] text-rose-500 font-black uppercase tracking-[0.2em]">Poin Pelanggaran</p>
                                    </div>
                                </div>
                            </div>
                            <div className="space-y-10">
                                {violationList.length === 0 ? (
                                    <div className="text-center py-10 opacity-60">
                                        <div className="w-20 h-20 bg-emerald-500/10 rounded-full flex items-center justify-center mx-auto mb-6">
                                            <CheckCircle2 className="w-10 h-10 text-emerald-500" />
                                        </div>
                                        <p className="text-white text-sm font-black uppercase tracking-widest">Semua Aman</p>
                                    </div>
                                ) : (
                                    violationList.map((std, i) => (
                                        <div key={i} className="group cursor-default">
                                            <div className="flex justify-between items-center text-sm mb-3">
                                                <span className="font-extrabold text-neutral-300 group-hover:text-indigo-500 transition-colors uppercase tracking-tight">{std.name}</span>
                                                <span className="font-black text-rose-500 tabular-nums px-3 py-1 bg-rose-500/10 rounded-lg">{std.points}</span>
                                            </div>
                                            <div className="h-4 w-full bg-neutral-900 rounded-full overflow-hidden p-1 border border-neutral-800 shadow-inner">
                                                <div
                                                    className={`h-full ${std.points > 40 ? 'bg-gradient-to-r from-rose-600 to-rose-500' : 'bg-gradient-to-r from-indigo-600 to-indigo-500'} rounded-full transition-all duration-1000 shadow-sm`}
                                                    style={{ width: `${Math.min(std.points, 100)}%` }}
                                                />
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                            <button
                                onClick={() => router.push('/dashboard/wali-kelas/pelanggaran')}
                                className="w-full mt-10 py-5 bg-neutral-900 hover:bg-neutral-800 text-neutral-400 font-black uppercase tracking-[0.2em] text-xs rounded-3xl transition-all flex items-center justify-center gap-3 group border border-neutral-800"
                            >
                                Rekap Lengkap
                                <ChevronRight className="w-4 h-4 group-hover:translate-x-1 transition-transform text-neutral-600" />
                            </button>
                        </div>

                        {/* Quick Actions (MODERNIZED) */}
                        <div className="lg:col-span-2 bg-[#0c0c0c] p-8 rounded-[2.5rem] border border-neutral-800 shadow-2xl">
                            <div className="mb-10 flex items-center gap-4">
                                <div className="w-12 h-12 bg-indigo-500/10 rounded-full border border-indigo-500/20 flex items-center justify-center">
                                    <Search className="w-6 h-6 text-indigo-500" />
                                </div>
                                <div>
                                    <h3 className="font-extrabold text-white text-lg">Aksi Cepat</h3>
                                    <p className="text-[10px] text-neutral-500 font-black uppercase tracking-[0.2em]">Navigasi Utama</p>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                                {[
                                    { label: 'Daftar Santri', sub: 'Profil & Perwalian', icon: Users, href: '/dashboard/wali-kelas/santri', color: 'text-indigo-500', bg: 'bg-indigo-500/10', border: 'border-indigo-500/20' },
                                    { label: 'Capaian Nilai', sub: 'Performa Akademik', icon: TrendingUp, href: '/dashboard/wali-kelas/nilai', color: 'text-emerald-500', bg: 'bg-emerald-500/10', border: 'border-emerald-500/20' },
                                    { label: 'Rekap Absensi', sub: 'Log Presensi Harian', icon: Clock, href: '/dashboard/wali-kelas/absensi', color: 'text-blue-500', bg: 'bg-blue-500/10', border: 'border-blue-500/20' },
                                    { label: 'Hubungi Wali', sub: 'Komunikasi Ortu', icon: Phone, href: '/dashboard/wali-kelas/chat', color: 'text-rose-500', bg: 'bg-rose-500/10', border: 'border-rose-500/20' },
                                ].map((item, idx) => (
                                    <div
                                        key={idx}
                                        onClick={() => router.push(item.href)}
                                        className={`p-8 bg-neutral-900/50 hover:bg-neutral-900 border ${item.border} rounded-[2rem] cursor-pointer transition-all flex flex-col gap-6 active:scale-95 shadow-sm group`}
                                    >
                                        <div className={`w-14 h-14 ${item.bg} rounded-2xl flex items-center justify-center shadow-md group-hover:scale-110 transition-transform`}>
                                            <item.icon className={`w-7 h-7 ${item.color}`} />
                                        </div>
                                        <div>
                                            <h4 className="font-extrabold text-white text-lg mb-1">{item.label}</h4>
                                            <p className="text-[10px] text-neutral-500 font-black leading-relaxed uppercase tracking-widest">{item.sub}</p>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import {
    getCurrentUser,
    clearSession,
    User,
} from '@/lib/auth';
import {
    Search,
    ChevronDown,
    Activity,
    AlertTriangle,
    Calendar,
    Filter,
    ArrowLeft,
    ShieldAlert,
    Download
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { homeroomService } from '@/lib/services/homeroom';
import { Loader2 } from 'lucide-react';
import { supabase } from '@/lib/supabase';

export default function PelanggaranWaliPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [categoryFilter, setCategoryFilter] = useState('');

    const [isLoading, setIsLoading] = useState(true);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [violations, setViolations] = useState<any[]>([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [classInfo, setClassInfo] = useState<any>(null);

    const fetchInitialData = async (userId: string) => {
        try {
            setIsLoading(true);
            const info = await homeroomService.getClassInfo(userId);
            if (!info) {
                setClassInfo({ name: 'Belum Ada Kelas' });
                setIsLoading(false);
                return;
            }
            setClassInfo(info);

            // Fetch violations for students in this class
            const { data, error } = await supabase
                .from('violations')
                .select(`
                    *,
                    students!inner(name, class_id)
                `)
                .eq('students.class_id', info.id)
                .order('violation_date', { ascending: false });

            if (error) throw error;
            setViolations(data || []);
            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching violations:', error);
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'wali_kelas') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchInitialData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);

    }, [router]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (!user) return null;

    const filteredData = violations.filter(v => {
        const matchesSearch = v.students?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
            v.description?.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesCategory = categoryFilter === '' || v.category === categoryFilter;
        return matchesSearch && matchesCategory;
    });

    return (
        <div className="min-h-screen bg-black flex flex-col lowercase-none">
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64 flex-1">
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-10">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <button
                                onClick={() => router.back()}
                                className="flex items-center gap-2 text-neutral-500 hover:text-white transition-colors mb-6 text-xs font-black uppercase tracking-widest group"
                            >
                                <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
                                Kembali
                            </button>
                            <div className="flex items-center gap-2 text-rose-500 font-bold text-xs uppercase tracking-[0.2em] mb-3">
                                <ShieldAlert className="w-4 h-4" />
                                Monitoring Kedisiplinan
                            </div>
                            <h1 className="text-3xl lg:text-5xl font-black text-white tracking-tight">
                                Buku <span className="text-rose-500 italic">Kedisplinan</span>
                            </h1>
                            <p className="text-neutral-500 font-medium mt-2">
                                Daftar pelanggaran santri <span className="text-white font-bold">Kelas {classInfo?.name || '...'}</span>.
                            </p>
                        </div>
                        <div className="flex gap-4">
                            <div className="px-6 py-3 bg-rose-600 shadow-xl shadow-rose-900/20 rounded-2xl text-white text-[10px] font-black uppercase tracking-widest flex items-center gap-3 border border-rose-500/20">
                                <AlertTriangle className="w-4 h-4" />
                                {violations.length} Total Kasus
                            </div>
                        </div>
                    </div>

                    {/* Stats Summary (Mini) */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        {[
                            { label: 'Ringan', count: violations.filter(v => v.category === 'ringan').length, color: 'text-blue-500', bg: 'bg-blue-500/10' },
                            { label: 'Sedang', count: violations.filter(v => v.category === 'sedang').length, color: 'text-amber-500', bg: 'bg-amber-500/10' },
                            { label: 'Berat', count: violations.filter(v => v.category === 'berat').length, color: 'text-rose-500', bg: 'bg-rose-500/10' },
                        ].map((s, idx) => (
                            <div key={idx} className="bg-[#0c0c0c] p-6 rounded-[2rem] border border-neutral-800 flex items-center justify-between">
                                <p className="text-[10px] font-black text-neutral-500 uppercase tracking-widest">{s.label}</p>
                                <div className={`px-4 py-1 ${s.bg} ${s.color} rounded-lg font-black text-lg border border-white/5`}>
                                    {s.count}
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Filters */}
                    <div className="bg-[#0c0c0c] p-8 rounded-[3rem] border border-neutral-800 shadow-2xl">
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                            <div className="relative group">
                                <Search className="w-5 h-5 text-neutral-600 absolute left-6 top-1/2 -translate-y-1/2 group-focus-within:text-rose-500 transition-colors" />
                                <input
                                    type="text"
                                    placeholder="Cari nama atau deskripsi..."
                                    value={searchTerm}
                                    onChange={(e) => setSearchTerm(e.target.value)}
                                    className="w-full pl-16 pr-8 py-5 bg-neutral-900 border border-neutral-800 rounded-3xl focus:outline-none focus:ring-4 focus:ring-rose-500/10 focus:bg-black focus:border-rose-500 font-bold text-white transition-all placeholder:text-neutral-700"
                                />
                            </div>
                            <div className="relative group">
                                <select
                                    value={categoryFilter}
                                    onChange={(e) => setCategoryFilter(e.target.value)}
                                    className="w-full h-full pl-8 pr-12 py-5 bg-neutral-900 border border-neutral-800 rounded-3xl focus:outline-none focus:ring-4 focus:ring-rose-500/10 focus:bg-black focus:border-rose-500 font-black text-xs uppercase tracking-widest text-white transition-all appearance-none cursor-pointer"
                                >
                                    <option value="">Semua Tingkat</option>
                                    <option value="ringan">Tingkat Ringan</option>
                                    <option value="sedang">Tingkat Sedang</option>
                                    <option value="berat">Tingkat Berat</option>
                                </select>
                                <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-neutral-600 group-focus-within:text-rose-500 transition-colors">
                                    <ChevronDown className="w-5 h-5" />
                                </div>
                            </div>
                            <div className="flex items-center">
                                <button className="w-full py-5 bg-neutral-900 border border-neutral-800 rounded-3xl text-neutral-400 font-black uppercase tracking-widest text-[10px] hover:text-white hover:bg-neutral-800 transition-all flex items-center justify-center gap-3 active:scale-95 shadow-inner">
                                    <Download className="w-4 h-4" />
                                    Export Excel
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Data List */}
                    <div className="bg-[#0c0c0c] rounded-[3rem] border border-neutral-800 shadow-2xl overflow-hidden group">
                        <div className="hidden lg:block overflow-x-auto">
                            <table className="w-full text-left">
                                <thead className="bg-neutral-900/40 border-b border-neutral-800">
                                    <tr>
                                        <th className="px-10 py-8 text-[10px] font-black text-neutral-500 uppercase tracking-[0.2em]">Santri</th>
                                        <th className="px-10 py-8 text-[10px] font-black text-neutral-500 uppercase tracking-[0.2em]">Tingkat</th>
                                        <th className="px-10 py-8 text-[10px] font-black text-neutral-500 uppercase tracking-[0.2em]">Keterangan / Hukuman</th>
                                        <th className="px-10 py-8 text-[10px] font-black text-neutral-500 uppercase tracking-[0.2em] text-center">Poin</th>
                                        <th className="px-10 py-8 text-[10px] font-black text-neutral-500 uppercase tracking-[0.2em] text-right">Tanggal</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-neutral-800/50">
                                    {isLoading ? (
                                        <tr>
                                            <td colSpan={5} className="px-10 py-32 text-center">
                                                <div className="flex flex-col items-center gap-6">
                                                    <Loader2 className="w-16 h-16 text-rose-500 animate-spin" />
                                                    <p className="text-neutral-500 font-black uppercase tracking-[0.3em] text-[10px]">Memuat Rekap Kedisiplinan...</p>
                                                </div>
                                            </td>
                                        </tr>
                                    ) : filteredData.length === 0 ? (
                                        <tr>
                                            <td colSpan={5} className="px-10 py-32 text-center text-neutral-600 font-black uppercase tracking-[0.2em] text-xs italic">
                                                Tidak ada data pelanggaran.
                                            </td>
                                        </tr>
                                    ) : (
                                        filteredData.map((v) => (
                                            <tr key={v.id} className="hover:bg-rose-500/[0.03] transition-colors group/row">
                                                <td className="px-10 py-8">
                                                    <div className="flex items-center gap-4">
                                                        <div className="w-10 h-10 bg-neutral-900 rounded-xl flex items-center justify-center text-rose-500 font-black text-[10px] border border-neutral-800 group-hover/row:border-rose-500/30 transition-all">
                                                            {v.students?.name?.charAt(0)}
                                                        </div>
                                                        <p className="font-black text-white group-hover/row:text-rose-400 transition-colors tracking-tight">{v.students?.name}</p>
                                                    </div>
                                                </td>
                                                <td className="px-10 py-8">
                                                    <span className={`px-4 py-1.5 rounded-xl text-[9px] font-black tracking-[0.2em] uppercase border ${v.category === 'berat' ? 'bg-rose-500/10 text-rose-500 border-rose-500/20' :
                                                        v.category === 'sedang' ? 'bg-amber-500/10 text-amber-500 border-amber-500/20' :
                                                            'bg-blue-500/10 text-blue-500 border-blue-500/20'
                                                        }`}>
                                                        {v.category}
                                                    </span>
                                                </td>
                                                <td className="px-10 py-8">
                                                    <p className="text-sm font-bold text-neutral-400 group-hover/row:text-neutral-200 transition-colors max-w-md italic leading-relaxed">
                                                        &quot;{v.description || '-'}&quot;
                                                        {v.punishment && <span className="block not-italic text-xs text-rose-400/60 mt-2 font-black uppercase tracking-widest">Takzir: {v.punishment}</span>}
                                                    </p>
                                                </td>
                                                <td className="px-10 py-8 text-center">
                                                    <span className="text-lg font-black text-rose-600 shadow-glow-rose">-{v.points}</span>
                                                </td>
                                                <td className="px-10 py-8 text-right text-[10px] font-black text-neutral-600 uppercase tracking-widest tabular-nums font-mono">
                                                    {new Date(v.violation_date).toLocaleDateString('id-ID')}
                                                </td>
                                            </tr>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>

                        {/* Mobile List View */}
                        <div className="lg:hidden p-6 space-y-6 bg-black/40">
                            {filteredData.map((v) => (
                                <div key={v.id} className="bg-neutral-900/40 p-8 rounded-[2.5rem] border border-neutral-800 shadow-xl active:scale-[0.98] transition-all group overflow-hidden relative">
                                    <div className="flex items-center justify-between mb-8">
                                        <span className="text-[9px] font-black text-neutral-600 uppercase tracking-[0.2em]">{new Date(v.violation_date).toLocaleDateString('id-ID')}</span>
                                        <span className={`px-5 py-2 rounded-full text-[8px] font-black uppercase tracking-[0.2em] border ${v.category === 'berat' ? 'bg-rose-500/10 text-rose-500 border-rose-500/20' :
                                            v.category === 'sedang' ? 'bg-amber-500/10 text-amber-500 border-amber-500/20' :
                                                'bg-blue-500/10 text-blue-500 border-blue-500/20'
                                            }`}>
                                            {v.category}
                                        </span>
                                    </div>
                                    <h4 className="font-black text-white text-xl tracking-tight leading-none mb-6">{v.students?.name}</h4>
                                    <div className="space-y-4 pt-6 border-t border-neutral-800/50">
                                        <p className="text-sm font-medium text-neutral-500 italic leading-relaxed">&quot;{v.description || '-'}&quot;</p>
                                        <div className="flex items-center justify-between">
                                            <p className="text-[9px] font-black text-rose-500/60 uppercase tracking-widest">Poin Disiplin</p>
                                            <p className="text-2xl font-black text-rose-600">-{v.points}</p>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </main>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useState, useRef } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import {
    getCurrentUser,
    clearSession,
    User,
    ROLE_NAMES
} from '@/lib/auth';
import {
    RaporConfig,
    StudentRaporData,
    getStoredSettings,
    getSemesterName,
    MOCK_STUDENTS
} from '@/lib/raporConfig';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import RaporSheet from '@/components/rapor/RaporSheet';
import {
    Menu,
    Bell,
    ChevronDown,
    ArrowLeft,
    Printer,
    FileText,
    Users,
    Search,
    Eye,
    X,
    Download,
    CheckCircle2,
    AlertCircle,
    Loader2
} from 'lucide-react';

import { homeroomService } from '@/lib/services/homeroom';
import { academicYearService } from '@/lib/services/academic';
import { raporService } from '@/lib/services/rapor';
import { raporSettingsService } from '@/lib/services/rapor-settings';

export default function WaliKelasRaporPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);

    // Settings
    const [settings, setSettings] = useState<RaporConfig | null>(null);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [classInfo, setClassInfo] = useState<any>(null);

    // Students data
    const [students, setStudents] = useState<StudentRaporData[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [isLoading, setIsLoading] = useState(true);

    // Modal & Print state
    const [selectedStudent, setSelectedStudent] = useState<StudentRaporData | null>(null);
    const [showPreviewModal, setShowPreviewModal] = useState(false);
    const [isPrinting, setIsPrinting] = useState(false);

    // Ref for print
    const printRef = useRef<HTMLDivElement>(null);

    const fetchInitialData = async (userId: string) => {
        try {
            setIsLoading(true);
            console.log('Fetching initial data for user:', userId);

            // Fetch everything we need: Class Info, Academic Year AND Rapor Settings
            const [cls, activeYear, dbSettings] = await Promise.all([
                homeroomService.getClassInfo(userId),
                academicYearService.getActive(),
                raporSettingsService.getSettings()
            ]);

            console.log('Class Info:', cls);
            console.log('Active Year from DB:', activeYear);
            console.log('Rapor Settings from DB:', dbSettings);

            if (!cls) {
                alert('Anda belum ditugaskan sebagai Wali Kelas.');
                router.replace('/dashboard/wali-kelas');
                return;
            }
            setClassInfo(cls);

            // Settings priority: Global Active Year > DB Rapor Settings > Config File Default
            const baseSettings = getStoredSettings();
            const currentSettings = {
                ...baseSettings,
                // ALWAYS prefer the Global Active Academic Year from the Management page
                academic_year: activeYear?.name || dbSettings?.academic_year || baseSettings.academic_year,
                active_semester: (activeYear?.semester || activeYear?.current_semester || dbSettings?.active_semester || 1) as 1 | 2
            };

            console.log('Final Settings Applied:', currentSettings);
            setSettings(currentSettings);

            // Fetch students and their rapor data
            const raporData = await raporService.getRaporDataByClass(cls.id, activeYear?.id, currentSettings.active_semester);
            console.log('Rapor Data Count:', raporData.length);
            setStudents(raporData as StudentRaporData[]);

            setIsLoading(false);
        } catch (error) {
            console.error('Error fetching initial data:', error);
            setIsLoading(false);
        }
    };

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'wali_kelas') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchInitialData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [router]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    // Filter students by search
    const filteredStudents = students.filter(s =>
        s.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        s.nis.includes(searchQuery)
    );

    // Calculate average for a student
    const calculateAverage = (grades: { score: number }[]) => {
        if (!grades || grades.length === 0) return 0;
        const total = grades.reduce((sum, g) => sum + g.score, 0);
        return Math.round(total / grades.length);
    };

    // Handle single print
    const handlePrint = (student: StudentRaporData) => {
        setSelectedStudent(student);
        setIsPrinting(true);

        // Small delay to ensure component renders
        setTimeout(() => {
            window.print();
            setIsPrinting(false);
        }, 500);
    };

    // Handle print all
    const handlePrintAll = () => {
        setIsPrinting(true);
        alert(`­ƒôä Mencetak ${filteredStudents.length} rapor untuk Semester ${settings?.active_semester} (${getSemesterName(settings?.active_semester || 1)})\n\nFitur ini akan menghasilkan PDF untuk semua santri.`);
        setIsPrinting(false);
    };

    // Handle preview
    const handlePreview = (student: StudentRaporData) => {
        setSelectedStudent(student);
        setShowPreviewModal(true);
    };

    if (!user || !settings) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-50">
                <div className="animate-pulse text-gray-400">Memuat...</div>
            </div>
        );
    }

    const activeSemesterName = getSemesterName(settings.active_semester);

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Print Styles */}
            <style jsx global>{`
                @media print {
                    body * {
                        visibility: hidden;
                    }
                    .print-area, .print-area * {
                        visibility: visible;
                    }
                    .print-area {
                        position: absolute;
                        left: 0;
                        top: 0;
                        width: 100%;
                    }
                    .no-print {
                        display: none !important;
                    }
                }
            `}</style>

            {/* Sidebar */}
            <Sidebar
                user={user}
                isOpen={sidebarOpen}
                onClose={() => setSidebarOpen(false)}
                onLogout={handleLogout}
            />

            <div className="lg:pl-64 no-print">
                {/* Reusable Header Component */}
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-8">
                    {/* Breadcrumb & Title */}
                    <div className="mb-6">
                        <Link
                            href="/dashboard/wali-kelas"
                            className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 mb-2"
                        >
                            <ArrowLeft className="w-4 h-4" />
                            Kembali ke Dashboard
                        </Link>
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div>
                                <h1 className="text-2xl font-bold text-gray-800">Cetak Rapor Santri</h1>
                                <p className="text-gray-500">Kelas {classInfo?.name || '-'} ÔÇó {students.length} santri</p>
                            </div>
                            <button
                                onClick={handlePrintAll}
                                disabled={isPrinting}
                                className="flex items-center gap-2 px-5 py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-semibold rounded-xl transition-colors disabled:opacity-50"
                            >
                                {isPrinting ? (
                                    <Loader2 className="w-5 h-5 animate-spin" />
                                ) : (
                                    <Download className="w-5 h-5" />
                                )}
                                Cetak Semua (.PDF)
                            </button>
                        </div>
                    </div>

                    {/* Active Semester Info */}
                    <div className="bg-gradient-to-r from-indigo-50 to-purple-50 border border-indigo-200 rounded-2xl p-5 mb-6">
                        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                            <div className="flex items-center gap-4">
                                <div className="w-14 h-14 bg-indigo-100 rounded-xl flex items-center justify-center">
                                    <FileText className="w-7 h-7 text-indigo-600" />
                                </div>
                                <div>
                                    <h3 className="font-semibold text-gray-800">Semester Aktif</h3>
                                    <p className="text-2xl font-bold text-indigo-600">
                                        Semester {settings.active_semester} ({activeSemesterName})
                                    </p>
                                    <p className="text-sm text-gray-500">Tahun Ajaran {settings.academic_year}</p>
                                </div>
                            </div>
                            <div className="bg-white rounded-xl p-4 border border-indigo-100">
                                <p className="text-sm text-gray-600">
                                    {settings.active_semester === 2 ? (
                                        <>
                                            <CheckCircle2 className="w-4 h-4 inline text-emerald-500 mr-1" />
                                            Rapor semester genap akan menyertakan <strong>Keputusan Kenaikan Kelas</strong>
                                        </>
                                    ) : (
                                        <>
                                            <AlertCircle className="w-4 h-4 inline text-blue-500 mr-1" />
                                            Rapor semester ganjil (tanpa keputusan kenaikan)
                                        </>
                                    )}
                                </p>
                            </div>
                        </div>
                    </div>

                    {/* Search */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-4 mb-6">
                        <div className="relative">
                            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                            <input
                                type="text"
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                placeholder="Cari santri berdasarkan nama atau NIS..."
                                className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500/30 focus:border-indigo-500 text-gray-900"
                            />
                        </div>
                    </div>

                    {/* Students Table */}
                    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
                        <div className="p-5 border-b border-gray-100 flex items-center justify-between">
                            <div className="flex items-center gap-2">
                                <Users className="w-5 h-5 text-gray-600" />
                                <h3 className="font-semibold text-gray-800">Daftar Santri</h3>
                            </div>
                            <span className="text-sm text-gray-500">{filteredStudents.length} santri</span>
                        </div>

                        <div className="overflow-x-auto">
                            <table className="w-full">
                                <thead className="bg-gray-50 border-b border-gray-100">
                                    <tr>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600 w-12">No</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">Nama Santri</th>
                                        <th className="text-left p-4 text-sm font-semibold text-gray-600">NIS</th>
                                        <th className="text-center p-4 text-sm font-semibold text-gray-600">JK</th>
                                        <th className="text-center p-4 text-sm font-semibold text-gray-600">Rata-rata</th>
                                        <th className="text-center p-4 text-sm font-semibold text-gray-600">Kehadiran</th>
                                        {settings.active_semester === 2 && (
                                            <th className="text-center p-4 text-sm font-semibold text-gray-600">Status</th>
                                        )}
                                        <th className="text-center p-4 text-sm font-semibold text-gray-600 w-40">Aksi</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100">
                                    {isLoading ? (
                                        <tr>
                                            <td colSpan={settings.active_semester === 2 ? 8 : 7} className="p-10 text-center text-gray-400">
                                                <div className="flex flex-col items-center gap-2">
                                                    <Loader2 className="w-8 h-8 animate-spin text-indigo-600" />
                                                    <p>Memuat data santri...</p>
                                                </div>
                                            </td>
                                        </tr>
                                    ) : filteredStudents.length === 0 ? (
                                        <tr>
                                            <td colSpan={settings.active_semester === 2 ? 8 : 7} className="p-10 text-center text-gray-400 italic">
                                                Tidak ada santri ditemukan.
                                            </td>
                                        </tr>
                                    ) : (
                                        filteredStudents.map((student, index) => {
                                            const avg = calculateAverage(student.grades);
                                            const totalAbsent = student.attendance.sakit + student.attendance.izin + student.attendance.alpha;

                                            return (
                                                <tr key={student.id} className="hover:bg-gray-50 transition-colors">
                                                    <td className="p-4 text-gray-500">{index + 1}</td>
                                                    <td className="p-4">
                                                        <div className="flex items-center gap-3">
                                                            <div className={`w-9 h-9 rounded-full flex items-center justify-center ${student.gender === 'L' ? 'bg-blue-100' : 'bg-indigo-100'
                                                                }`}>
                                                                <span className={`font-semibold text-sm ${student.gender === 'L' ? 'text-blue-700' : 'text-indigo-700'
                                                                    }`}>
                                                                    {student.name.charAt(0)}
                                                                </span>
                                                            </div>
                                                            <div>
                                                                <p className="font-medium text-gray-800">{student.name}</p>
                                                                <p className="text-xs text-gray-400">NISN: {student.nisn}</p>
                                                            </div>
                                                        </div>
                                                    </td>
                                                    <td className="p-4">
                                                        <span className="px-2 py-1 bg-gray-100 text-gray-700 rounded text-sm font-mono">
                                                            {student.nis}
                                                        </span>
                                                    </td>
                                                    <td className="p-4 text-center">
                                                        <span className={`px-2 py-1 rounded text-xs font-medium ${student.gender === 'L'
                                                            ? 'bg-blue-100 text-blue-700'
                                                            : 'bg-indigo-100 text-indigo-700'
                                                            }`}>
                                                            {student.gender}
                                                        </span>
                                                    </td>
                                                    <td className="p-4 text-center">
                                                        <span className={`font-bold ${avg >= 80 ? 'text-emerald-600' :
                                                            avg >= 70 ? 'text-blue-600' :
                                                                'text-red-600'
                                                            }`}>
                                                            {avg}
                                                        </span>
                                                    </td>
                                                    <td className="p-4 text-center">
                                                        <span className={`text-sm ${totalAbsent <= 3 ? 'text-emerald-600' :
                                                            totalAbsent <= 10 ? 'text-amber-600' :
                                                                'text-red-600'
                                                            }`}>
                                                            {totalAbsent} hari absen
                                                        </span>
                                                    </td>
                                                    {settings.active_semester === 2 && (
                                                        <td className="p-4 text-center">
                                                            {student.promotion?.isPromoted ? (
                                                                <span className="px-2 py-1 bg-emerald-100 text-emerald-700 rounded-full text-xs font-medium">
                                                                    Naik Kelas
                                                                </span>
                                                            ) : (
                                                                <span className="px-2 py-1 bg-red-100 text-red-700 rounded-full text-xs font-medium">
                                                                    Tinggal
                                                                </span>
                                                            )}
                                                        </td>
                                                    )}
                                                    <td className="p-4">
                                                        <div className="flex items-center justify-center gap-2">
                                                            <button
                                                                onClick={() => handlePreview(student)}
                                                                className="p-2 text-gray-500 hover:bg-gray-100 rounded-lg transition-colors"
                                                                title="Preview"
                                                            >
                                                                <Eye className="w-4 h-4" />
                                                            </button>
                                                            <button
                                                                onClick={() => handlePrint(student)}
                                                                disabled={isPrinting}
                                                                className="flex items-center gap-1.5 px-3 py-1.5 bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-medium rounded-lg transition-colors disabled:opacity-50"
                                                            >
                                                                <Printer className="w-4 h-4" />
                                                                Cetak
                                                            </button>
                                                        </div>
                                                    </td>
                                                </tr>
                                            );
                                        })
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </main>
            </div>

            {/* Preview Modal */}
            {showPreviewModal && selectedStudent && (
                <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 no-print">
                    <div className="bg-white rounded-2xl max-w-5xl w-full max-h-[90vh] overflow-hidden flex flex-col">
                        <div className="p-4 border-b border-gray-100 flex items-center justify-between">
                            <div>
                                <h3 className="font-semibold text-gray-800">Preview Rapor</h3>
                                <p className="text-sm text-gray-500">{selectedStudent.name} - Semester {settings.active_semester}</p>
                            </div>
                            <div className="flex items-center gap-2">
                                <button
                                    onClick={() => {
                                        handlePrint(selectedStudent);
                                        setShowPreviewModal(false);
                                    }}
                                    className="flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white font-medium rounded-xl transition-colors"
                                >
                                    <Printer className="w-4 h-4" />
                                    Cetak
                                </button>
                                <button
                                    onClick={() => setShowPreviewModal(false)}
                                    className="p-2 hover:bg-gray-100 rounded-lg"
                                >
                                    <X className="w-5 h-5 text-gray-500" />
                                </button>
                            </div>
                        </div>
                        <div className="flex-1 overflow-auto p-4 bg-gray-100">
                            <div className="transform scale-75 origin-top">
                                <RaporSheet
                                    settings={settings}
                                    student={selectedStudent}
                                    semester={settings.active_semester}
                                />
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Hidden Print Area */}
            {selectedStudent && (
                <div className="print-area">
                    <RaporSheet
                        ref={printRef}
                        settings={settings}
                        student={selectedStudent}
                        semester={settings.active_semester}
                    />
                </div>
            )}
        </div>
    );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { getCurrentUser, clearSession, User } from '@/lib/auth';
import {
    CalendarCheck,
    Search,
    Filter,
    Clock,
    CheckCircle2,
    XCircle,
    AlertCircle,
    Calendar,
    Loader2,
    Users,
    Activity
} from 'lucide-react';
import Sidebar, { DashboardHeader } from '@/components/layout/Sidebar';
import { guardianService } from '@/lib/services/guardian';
import { attendanceService } from '@/lib/services/attendance';

export default function KehadiranSantriPage() {
    const router = useRouter();
    const [user, setUser] = useState<User | null>(null);
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [children, setChildren] = useState<any[]>([]);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [activeChild, setActiveChild] = useState<any>(null);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [attendanceLog, setAttendanceLog] = useState<any[]>([]);
    const [stats, setStats] = useState({ hadir: 0, sakit: 0, izin: 0, alpha: 0, percentage: 0 });
    const [searchQuery, setSearchQuery] = useState('');

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const fetchChildAttendance = async (child: any) => {
        setIsLoading(true);
        setActiveChild(child);
        try {
            const data = await attendanceService.getStudentHistory(child.id);

            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const formatted = data.map((item: any) => ({
                id: item.id,
                date: new Date(item.date).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }),
                day: new Date(item.date).toLocaleDateString('id-ID', { weekday: 'long' }),
                status: item.status.charAt(0).toUpperCase() + item.status.slice(1),
                checkIn: item.check_in_time ? item.check_in_time.slice(0, 5) : '-',
                session: item.session || item.type || 'Kegiatan Umum',
                notes: item.notes
            }));

            setAttendanceLog(formatted);

            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const counts = data.reduce((acc: any, curr: any) => {
                acc[curr.status] = (acc[curr.status] || 0) + 1;
                return acc;
            }, { hadir: 0, sakit: 0, izin: 0, alpha: 0 });

            const total = data.length || 1;
            setStats({
                ...counts,
                percentage: Math.round((counts.hadir / total) * 100)
            });
        } catch (err) {
            console.error('Error fetching attendance:', err);
        } finally {
            setIsLoading(false);
        }
    };

    const fetchInitialData = useCallback(async (parentId: string) => {
        try {
            const childrenList = await guardianService.getChildren(parentId);
            setChildren(childrenList);
            if (childrenList.length > 0) {
                await fetchChildAttendance(childrenList[0]);
            } else {
                setIsLoading(false);
            }
        } catch (err) {
            console.error('Error fetching initial data:', err);
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const currentUser = getCurrentUser();
        if (!currentUser || currentUser.role !== 'wali_santri') {
            router.replace('/login');
            return;
        }
        const timer = requestAnimationFrame(() => {
            setUser(currentUser);
            fetchInitialData(currentUser.id);
        });
        return () => cancelAnimationFrame(timer);
    }, [router, fetchInitialData]);

    const handleLogout = () => {
        clearSession();
        router.replace('/login');
    };

    if (isLoading && !activeChild) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-[#050505]">
                <div className="flex flex-col items-center gap-4">
                    <Loader2 className="w-10 h-10 text-orange-500 animate-spin opacity-40" />
                    <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-[0.2em]">Menyinkronkan Data Kehadiran...</p>
                </div>
            </div>
        );
    }

    if (!user) return null;

    const filteredLogs = attendanceLog.filter(log =>
        log.date.toLowerCase().includes(searchQuery.toLowerCase()) ||
        log.session.toLowerCase().includes(searchQuery.toLowerCase())
    );

    return (
        <div className="min-h-screen bg-[#050505] text-neutral-400 font-sans selection:bg-orange-500/30">
            <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />

            <Sidebar user={user} isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} onLogout={handleLogout} />

            <div className="lg:pl-64 flex-1" style={{ fontFamily: "'Plus Jakarta Sans', sans-serif" }}>
                <DashboardHeader user={user} onMenuClick={() => setSidebarOpen(true)} />

                <main className="p-4 lg:p-10 space-y-10 max-w-[1500px] mx-auto">
                    {/* Header Section */}
                    <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                        <div>
                            <div className="flex items-center gap-2 text-orange-500 text-xs font-bold tracking-[0.2em] mb-2 uppercase">
                                <Activity className="w-4 h-4" />
                                Discipline Monitoring
                            </div>
                            <h1 className="text-3xl lg:text-4xl font-extrabold text-white tracking-tight">
                                Kehadiran & <span className="text-orange-500">Kedisiplinan Santri</span>
                            </h1>
                            <p className="text-neutral-500 text-sm mt-2 font-medium">Laporan kehadiran harian dan riwayat absensi aktivitas pesantren.</p>
                        </div>

                        {children.length > 1 && (
                            <div className="flex bg-[#0a0a0a] p-1.5 rounded-2xl border border-neutral-800 shadow-xl overflow-x-auto no-scrollbar">
                                {children.map(c => (
                                    <button
                                        key={c.id}
                                        onClick={() => fetchChildAttendance(c)}
                                        className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all shrink-0 ${activeChild?.id === c.id
                                            ? 'bg-orange-600 text-white shadow-[0_0_15px_rgba(234,88,12,0.3)]'
                                            : 'text-neutral-600 hover:text-neutral-300'
                                            }`}
                                    >
                                        {c.name.split(' ')[0]}
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>

                    {!activeChild ? (
                        <div className="bg-[#0a0a0a] border border-neutral-800/50 rounded-[3rem] p-24 text-center shadow-2xl">
                            <Users className="w-20 h-20 text-neutral-800 mx-auto mb-6" />
                            <h3 className="text-2xl font-black text-white">Data Belum Tersedia</h3>
                            <p className="text-neutral-500 mt-2 font-medium">Sistem sedang menyiapkan data kehadiran untuk akun Anda.</p>
                        </div>
                    ) : (
                        <>
                            {/* Stats Summary Cards */}
                            <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
                                <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl flex flex-col items-center group">
                                    <div className="w-14 h-14 bg-emerald-500/5 border border-emerald-500/10 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                                        <CheckCircle2 className="w-6 h-6 text-emerald-500" />
                                    </div>
                                    <h4 className="text-4xl font-black text-white tracking-tighter">{stats.percentage}%</h4>
                                    <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mt-2 text-center">Rasio Kehadiran</p>
                                </div>
                                <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl flex flex-col items-center group">
                                    <div className="w-14 h-14 bg-amber-500/5 border border-amber-500/10 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                                        <AlertCircle className="w-6 h-6 text-amber-500" />
                                    </div>
                                    <h4 className="text-4xl font-black text-white tracking-tighter">{stats.izin}</h4>
                                    <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mt-2">Total Izin</p>
                                </div>
                                <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl flex flex-col items-center group">
                                    <div className="w-14 h-14 bg-blue-500/5 border border-blue-500/10 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                                        <Calendar className="w-6 h-6 text-blue-500" />
                                    </div>
                                    <h4 className="text-4xl font-black text-white tracking-tighter">{stats.sakit}</h4>
                                    <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mt-2">Total Sakit</p>
                                </div>
                                <div className="bg-[#0a0a0a] p-8 rounded-[2.5rem] border border-neutral-800/40 shadow-xl flex flex-col items-center group">
                                    <div className="w-14 h-14 bg-rose-500/5 border border-rose-500/10 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform">
                                        <XCircle className="w-6 h-6 text-rose-500" />
                                    </div>
                                    <h4 className="text-4xl font-black text-white tracking-tighter">{stats.alpha}</h4>
                                    <p className="text-[10px] font-black text-neutral-600 uppercase tracking-widest mt-2">Tanpa Ket.</p>
                                </div>
                            </div>

                            {/* Filtering & Search */}
                            <div className="flex flex-col md:flex-row gap-6 items-center justify-between">
                                <div className="relative w-full md:w-96">
                                    <Search className="w-5 h-5 text-neutral-700 absolute left-5 top-1/2 -translate-y-1/2" />
                                    <input
                                        type="text"
                                        placeholder="Cari tanggal atau aktivitas..."
                                        value={searchQuery}
                                        onChange={(e) => setSearchQuery(e.target.value)}
                                        className="w-full pl-14 pr-6 py-4 bg-[#0a0a0a] border border-neutral-800/50 rounded-2xl focus:outline-none focus:border-orange-500/30 text-white font-medium shadow-xl transition-all"
                                    />
                                </div>
                                <div className="flex gap-3 w-full md:w-auto">
                                    <button className="flex-1 md:flex-none flex items-center justify-center gap-3 px-8 py-4 bg-neutral-900 border border-neutral-800 text-neutral-400 font-black rounded-2xl hover:text-white transition-all text-[10px] uppercase tracking-widest">
                                        <Filter className="w-4 h-4" />
                                        Filter Status
                                    </button>
                                </div>
                            </div>

                            {/* Attendance Log Table */}
                            <div className="bg-[#0a0a0a] rounded-[2.5rem] border border-neutral-800/40 shadow-2xl overflow-hidden min-h-[400px]">
                                {isLoading ? (
                                    <div className="flex items-center justify-center h-[400px]">
                                        <Loader2 className="w-10 h-10 text-orange-500 animate-spin opacity-40" />
                                    </div>
                                ) : filteredLogs.length === 0 ? (
                                    <div className="flex flex-col items-center justify-center h-[400px] text-gray-400">
                                        <div className="w-20 h-20 bg-neutral-900 rounded-[2rem] flex items-center justify-center mb-6 border border-neutral-800 opacity-20">
                                            <CalendarCheck className="w-10 h-10" />
                                        </div>
                                        <p className="font-bold italic uppercase text-[10px] tracking-widest opacity-30">Belum ada riwayat kehadiran tercatat.</p>
                                    </div>
                                ) : (
                                    <div className="overflow-x-auto custom-scrollbar">
                                        <table className="w-full text-left">
                                            <thead className="bg-[#0e0e0e] border-b border-neutral-800/50">
                                                <tr>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] w-48">Tanggal / Hari</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Aktivitas / Sesi</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Status</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em] text-center">Jam</th>
                                                    <th className="px-8 py-6 text-[10px] font-bold text-neutral-500 uppercase tracking-[0.2em]">Keterangan</th>
                                                </tr>
                                            </thead>
                                            <tbody className="divide-y divide-neutral-800/20">
                                                {filteredLogs.map((item) => (
                                                    <tr key={item.id} className="hover:bg-neutral-900/30 transition-all group">
                                                        <td className="px-8 py-7">
                                                            <p className="font-black text-white text-sm uppercase tracking-tight">{item.date}</p>
                                                            <p className="text-[10px] font-bold text-neutral-600 uppercase tracking-widest mt-1.5">{item.day}</p>
                                                        </td>
                                                        <td className="px-8 py-7">
                                                            <div className="flex items-center gap-4">
                                                                <div className="w-10 h-10 bg-orange-500/5 border border-orange-500/10 rounded-xl flex items-center justify-center group-hover:bg-orange-600 transition-all group-hover:shadow-[0_0_15px_rgba(234,88,12,0.3)]">
                                                                    <Clock className="w-4 h-4 text-orange-500 group-hover:text-white" />
                                                                </div>
                                                                <p className="font-bold text-white text-sm uppercase tracking-tight">{item.session}</p>
                                                            </div>
                                                        </td>
                                                        <td className="px-8 py-7 text-center">
                                                            <span className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest border transition-all ${item.status === 'Hadir' ? 'bg-emerald-500/5 text-emerald-500 border-emerald-500/10 shadow-[0_0_10px_rgba(16,185,129,0.05)]' :
                                                                item.status === 'Izin' ? 'bg-amber-500/5 text-amber-500 border-amber-500/10' :
                                                                    item.status === 'Sakit' ? 'bg-blue-500/5 text-blue-500 border-blue-500/10' :
                                                                        'bg-rose-500/5 text-rose-500 border-rose-500/10'
                                                                }`}>
                                                                {item.status}
                                                            </span>
                                                        </td>
                                                        <td className="px-8 py-7 text-center">
                                                            <span className={`text-[10px] font-black tracking-widest uppercase ${item.checkIn !== '-' ? 'text-white' : 'text-neutral-800'}`}>
                                                                {item.checkIn}
                                                            </span>
                                                        </td>
                                                        <td className="px-8 py-7">
                                                            <p className="text-xs text-neutral-500 font-medium italic max-w-xs truncate">
                                                                &quot;{item.notes || 'Tidak ada catatan khusus.'}&quot;
                                                            </p>
                                                        </td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    </div>
                                )}
                            </div>
                        </>
                    )}
                </main>
            </div>

            <style jsx global>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; height: 5px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #1a1a1a; border-radius: 10px; }
                .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #262626; }
                .no-scrollbar::-webkit-scrollbar { display: none; }
                .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>
        </div>
    );
}

