import { supabase } from '../supabase';
import { getCurrentUser } from '../auth';

export interface RaporSettingsDB {
    id: string;
    pesantren_id: string;
    yayasan_name: string;
    school_name: string;
    school_name_arabic: string;
    address: string;
    phone: string;
    email: string;
    website: string;
    logo_url: string;
    pengasuh_pondok_name: string;
    pengasuh_pondok_nip: string;
    active_semester: 1 | 2;
    academic_year: string;
    report_city: string;
    created_at: string;
    updated_at: string;
}

/**
 * Helper to get pesantren ID - handles various cases
 */
async function getPesantrenId(): Promise<string | null> {
    const user = getCurrentUser();

    // 1. Check if already in user session
    if (user?.pesantrenId) {
        return user.pesantrenId;
    }

    // 2. Try to get from profiles table
    if (user?.id) {
        const { data: profile } = await supabase
            .from('profiles')
            .select('pesantren_id')
            .eq('id', user.id)
            .single();

        if (profile?.pesantren_id) {
            return profile.pesantren_id;
        }
    }

    // 3. For super_admin without pesantren, get first available
    if (user?.role === 'super_admin') {
        const { data: pesantren } = await supabase
            .from('pesantren')
            .select('id')
            .limit(1)
            .single();

        if (pesantren?.id) {
            return pesantren.id;
        }
    }

    return null;
}

export const raporSettingsService = {
    /**
     * Get settings untuk pesantren saat ini
     */
    async getSettings(): Promise<RaporSettingsDB | null> {
        const pesantrenId = await getPesantrenId();
        if (!pesantrenId) {
            console.warn('No pesantren ID found');
            return null;
        }

        try {
            // Priority: Fetch directly first (safer, avoids 409 Conflict from RPC get-or-create)
            const { data: directData } = await supabase
                .from('rapor_settings')
                .select('*')
                .eq('pesantren_id', pesantrenId)
                .maybeSingle();

            if (directData) return directData;

            // If empty, try RPC as fallback
            const { data, error } = await supabase.rpc('get_or_create_rapor_settings', {
                p_pesantren_id: pesantrenId
            });

            if (error) {
                console.warn('RPC failed or not available:', error);
                return null;
            }

            return Array.isArray(data) ? data[0] : data;
        } catch (e) {
            console.error('Get settings error:', e);
            return null;
        }
    },

    /**
     * Update settings
     */
    async updateSettings(settings: Partial<RaporSettingsDB>): Promise<RaporSettingsDB | null> {
        const pesantrenId = await getPesantrenId();
        if (!pesantrenId) throw new Error('No pesantren ID found');

        try {
            // Try RPC first
            const { data, error } = await supabase.rpc('update_rapor_settings', {
                p_pesantren_id: pesantrenId,
                p_settings: settings
            });

            if (error) {
                console.warn('RPC not available, updating directly:', error);
                // Fallback to direct update
                const { data: directData, error: directError } = await supabase
                    .from('rapor_settings')
                    .upsert({
                        pesantren_id: pesantrenId,
                        ...settings,
                        updated_at: new Date().toISOString()
                    }, { onConflict: 'pesantren_id' })
                    .select()
                    .single();

                if (directError) throw directError;
                return directData;
            }

            // RPC returns array, get first item
            return Array.isArray(data) ? data[0] : data;
        } catch (e) {
            console.error('Update settings error:', e);
            throw e;
        }
    },

    /**
     * Upload logo ke Supabase Storage
     */
    async uploadLogo(file: File): Promise<string> {
        const pesantrenId = await getPesantrenId();
        if (!pesantrenId) throw new Error('No pesantren ID found. Pastikan Anda sudah terhubung ke sebuah pesantren.');

        const fileExt = file.name.split('.').pop()?.toLowerCase() || 'png';
        const fileName = `${pesantrenId}/logo.${fileExt}`;

        // Upload to storage
        const { data, error } = await supabase.storage
            .from('logos')
            .upload(fileName, file, {
                cacheControl: '3600',
                upsert: true // Replace if exists
            });

        if (error) {
            console.error('Upload error:', error);
            throw new Error('Gagal upload logo: ' + error.message);
        }

        // Get public URL
        const { data: urlData } = supabase.storage
            .from('logos')
            .getPublicUrl(fileName);

        return urlData.publicUrl;
    },

    /**
     * Delete logo dari storage
     */
    async deleteLogo(): Promise<void> {
        const pesantrenId = await getPesantrenId();
        if (!pesantrenId) return;

        // Get current settings to find logo filename
        const settings = await this.getSettings();
        if (!settings?.logo_url) return;

        // Extract filename from URL
        const urlParts = settings.logo_url.split('/');
        const fileName = `${pesantrenId}/${urlParts[urlParts.length - 1]}`;

        await supabase.storage
            .from('logos')
            .remove([fileName]);

        // Update settings to remove logo URL
        await this.updateSettings({ logo_url: '' });
    }
};

import { supabase } from '../supabase';
import { StudentWithRelations, studentsService } from './students';
import { gradesService } from './grades';
import { attendanceService } from './attendance';
import { academicYearService } from './academic';

export const raporService = {
    async getRaporDataByClass(classId: string, academicYearId: string, semester: number) {
        // 1. Get all students in class
        const students = await studentsService.getByClass(classId);
        if (!students || students.length === 0) return [];

        // 2. Get all grades for these students
        const grades = await gradesService.getByClass(classId);

        // 3. Get all attendance for these students
        // We'll calculate summary for the whole semester or year?
        // Usually, rapor is for a specific semester.
        // We need a way to get attendance summary per student.
        // For simplicity, we'll fetch all attendance and summarize.
        const { data: attendance, error: attError } = await supabase
            .from('attendance')
            .select('*')
            .in('student_id', students.map(s => s.id));

        if (attError) throw attError;

        // 4. Get active teacher info for the class (Wali Kelas)
        const { data: classWithWali, error: classError } = await supabase
            .from('classes')
            .select(`
                *,
                homeroom_teacher:teachers(
                    id,
                    name,
                    nip
                )
            `)
            .eq('id', classId)
            .single();

        if (classError) throw classError;

        // 5. Build the final mapping
        return students.map(student => {
            const studentGrades = grades.filter(g => g.student_id === student.id && g.academic_year_id === academicYearId && g.semester === semester);
            const studentAttendance = attendance?.filter(a => a.student_id === student.id) || [];

            const attendanceSummary = {
                sakit: studentAttendance.filter(a => a.status === 'sakit').length,
                izin: studentAttendance.filter(a => a.status === 'izin').length,
                alpha: studentAttendance.filter(a => a.status === 'alpha').length,
            };

            return {
                id: student.id,
                name: student.name,
                nis: student.nis,
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                nisn: (student as any).nis || '-', // Fallback to nis or custom logic
                class: classWithWali?.name || 'Unknown',
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                gender: (student as any).gender || 'L',
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                grades: studentGrades.map((g: any) => ({
                    subject: g.subjects?.name || g.subject?.name || 'Mata Pelajaran',
                    score: Number(g.final_grade || g.score || 0),
                    category: (g.subjects?.category || g.subject?.category || 'umum') as 'agama' | 'umum'
                })),
                attendance: attendanceSummary,
                waliKelas: {
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    name: (classWithWali as any).homeroom_teacher?.name || '-',
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    nip: (classWithWali as any).homeroom_teacher?.nip || '-'
                },
                // Default promotion logic
                promotion: {
                    isPromoted: true,
                    nextClass: (parseInt(classWithWali.name) + 1).toString() + (classWithWali.name.replace(/[0-9]/g, ''))
                }
            };
        });
    }
};

import { supabase } from '../supabase';

export const studentDashboardService = {
    async getGPAHistory(studentId: string) {
        // Safe selection of existing columns across versions
        const { data, error } = await supabase
            .from('grades')
            .select('*') // Get everything to handle schema variations safely
            .eq('student_id', studentId);

        if (error) throw error;

        // Group by pseudo-semesters
        const semesterGrades: Record<string, { total: number, count: number }> = {};
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        (data || []).forEach((g: any, i: number) => {
            const sem = `Sem ${Math.floor(i / 5) + 1}`;
            if (!semesterGrades[sem]) semesterGrades[sem] = { total: 0, count: 0 };

            // Integrated Calculation Fallback
            // Support both final_score (MASTER-SETUP) and final_grade (V2/Legacy)
            let score = g.final_score ?? g.final_grade;

            if (score === null || score === undefined) {
                // Fallback to components if final score isn't calculated
                // Handle both short (uh1, uh2) and long (tugas_score, uts_score, uas_score) names
                const uh1 = g.uh1 ?? g.tugas_score ?? 0;
                const uh2 = g.uh2 ?? 0;
                const uts = g.uts ?? g.uts_score ?? 0;
                const uas = g.uas ?? g.uas_score ?? 0;

                const avgUh = (Number(uh1) + Number(uh2)) / (uh2 ? 2 : 1);
                score = (avgUh * 0.25) + (Number(uts) * 0.25) + (Number(uas) * 0.5);
            }

            semesterGrades[sem].total += Number(score);
            semesterGrades[sem].count += 1;
        });

        if (Object.keys(semesterGrades).length === 0) {
            return [
                { semester: 'Sem 1', gpa: 0 },
                { semester: 'Sem 2', gpa: 0 }
            ];
        }

        return Object.entries(semesterGrades).map(([semester, stats]) => ({
            semester,
            gpa: Number((stats.total / stats.count / 25).toFixed(2))
        })).slice(-5);
    },

    async getHafalanData(studentId: string) {
        // 1. Get Active Program first to get correct metadata
        const { data: activePrograms, error: progError } = await supabase
            .from('hafalan_programs')
            .select(`
                id,
                hafalan_types (
                    id,
                    name,
                    unit_name,
                    total_units
                )
            `)
            .eq('student_id', studentId)
            .eq('status', 'active')
            .limit(1);

        if (progError) throw progError;

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const activeProg = activePrograms?.[0] as any;
        const metadata = activeProg?.hafalan_types;

        // 2. Get latest progress for this student
        const { data: v2Data, error: v2Error } = await supabase
            .from('hafalan_progress')
            .select(`
                unit_number,
                unit_name,
                progress_percentage,
                updated_at,
                hafalan_programs (
                    hafalan_types (
                        name,
                        unit_name,
                        total_units
                    )
                )
            `)
            .eq('student_id', studentId)
            .order('updated_at', { ascending: false });

        if (!v2Error && (v2Data && v2Data.length > 0)) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const latest = v2Data[0] as any;
            const progInfo = latest.hafalan_programs?.hafalan_types || metadata;
            const unitLabel = progInfo?.unit_name || 'Unit';
            const progName = progInfo?.name || 'Program';
            const totalTarget = progInfo?.total_units || 30;

            // Calculate completed units (progress_percentage = 100)
            const completedUnits = v2Data.filter(h => h.progress_percentage === 100).length;

            // Calculate total progress percentage across all units
            const totalSumProgress = v2Data.reduce((sum, h) => sum + (h.progress_percentage || 0), 0);
            const totalProgress = Math.min(100, Math.round(totalSumProgress / totalTarget));

            return {
                currentJuz: latest.unit_number,
                unitLabel: unitLabel,
                programName: progName,
                currentName: `${progName} - ${latest.unit_name || `${unitLabel} ${latest.unit_number}`}`,
                currentDetail: null,
                progress: latest.progress_percentage,
                totalProgress: totalProgress,
                completed: completedUnits,
                remaining: Math.max(0, totalTarget - completedUnits),
                totalTarget: totalTarget,
                lastUpdate: latest.updated_at,
                chartData: [
                    { name: 'Selesai', value: completedUnits },
                    { name: 'Target', value: Math.max(0, totalTarget - completedUnits) }
                ]
            };
        }

        // Try 'hafalan_progress_old' first if we suspect 'hafalan_progress' is already V2
        const { data: oldData, error: oldError } = await supabase
            .from('hafalan_progress_old')
            .select('*')
            .eq('student_id', studentId)
            .order('created_at', { ascending: false });

        if (!oldError && (oldData && oldData.length > 0)) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const latest = oldData[0] as any;
            const completedJuz = new Set(oldData.filter((h: any) =>
                ['completed', 'selesai', 'tuntas', 'lulus', 'muroja_ah', 'memorized'].includes(h.status?.toLowerCase())
            ).map((h: any) => h.juz)).size;
            const totalTarget = 30;

            return {
                currentJuz: latest.juz || 30,
                unitLabel: 'Juz',
                programName: 'Hafalan Qur\'an',
                currentName: `Juz ${latest.juz}`,
                currentDetail: latest.surah || '-',
                progress: 100,
                totalProgress: Number(((completedJuz / totalTarget) * 100).toFixed(0)),
                completed: completedJuz,
                remaining: totalTarget - completedJuz,
                totalTarget: totalTarget,
                lastUpdate: latest.created_at,
                chartData: [
                    { name: 'Completed', value: completedJuz },
                    { name: 'Remaining', value: totalTarget - completedJuz }
                ]
            };
        }

        // 3. Fallback: If no progress yet but has active program
        if (activeProg) {
            const unitLabel = metadata.unit_name || 'Unit';
            const progName = metadata.name || 'Program';
            const totalTarget = metadata.total_units || 30;

            return {
                currentJuz: 1,
                unitLabel: unitLabel,
                programName: progName,
                currentName: `${progName} - ${unitLabel} 1`,
                currentDetail: null,
                progress: 0,
                totalProgress: 0,
                completed: 0,
                remaining: totalTarget,
                totalTarget: totalTarget,
                lastUpdate: null,
                chartData: [
                    { name: 'Selesai', value: 0 },
                    { name: 'Target', value: totalTarget }
                ]
            };
        }

        // 2. Fallback to legacy schema (if hafalan_progress_old didn't exist or was empty)
        const tryLegacy = async (tableName: string) => {
            // Check only what we need, with safer selection
            const { data, error } = await supabase
                .from(tableName)
                .select('*') // Safer than listing missing columns
                .eq('student_id', studentId);

            if (error) return { data: [], error };

            // Re-apply ordering in JS to be safe
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const sorted = (data || []).sort((a: any, b: any) => (b.juz || 0) - (a.juz || 0));
            return { data: sorted, error: null };
        };

        let legacyData: any[] = [];
        // If old table doesn't exist/empty, maybe the main table IS legacy
        const mainResult = await tryLegacy('hafalan_progress');
        if (mainResult.data?.[0]?.juz !== undefined) {
            legacyData = mainResult.data;
        }


        const latest = legacyData[0];
        if (!latest) return null; // Return null if absolutely no data found

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const completedJuz = new Set(legacyData.filter((h: any) =>
            ['completed', 'selesai', 'tuntas', 'lulus', 'muroja_ah', 'memorized'].includes(h.status?.toLowerCase())
        ).map((h: any) => h.juz)).size;

        const totalTarget = 30;

        return {
            currentJuz: latest.juz,
            unitLabel: 'Juz',
            programName: 'Hafalan Al-Qur\'an',
            currentName: latest.surah_name ? `Surah ${latest.surah_name}` : `Juz ${latest.juz}`,
            currentDetail: latest ? `Ayat ${latest.start_ayat || 1} - ${latest.end_ayat || '...'}` : null,
            progress: 0,
            totalProgress: Math.round((completedJuz / totalTarget) * 100),
            completed: completedJuz,
            remaining: Math.max(0, totalTarget - completedJuz),
            totalTarget: totalTarget,
            lastUpdate: latest.updated_at,
            chartData: [
                { name: 'Selesai', value: completedJuz },
                { name: 'Target', value: Math.max(0, totalTarget - completedJuz) }
            ]
        };
    },

    async getTodaySchedule(studentId: string) {
        const { data: student, error: sError } = await supabase
            .from('students')
            .select('class_id')
            .eq('id', studentId)
            .maybeSingle();

        if (sError) throw sError;
        if (!student?.class_id) return [];

        const todayIdx = new Date().getDay();

        const { data, error } = await supabase
            .from('schedules')
            .select(`
                id,
                start_time,
                end_time,
                room,
                subjects (name),
                teachers (
                    name
                )
            `)
            .eq('class_id', student.class_id)
            .eq('day_of_week', todayIdx)
            .order('start_time');

        if (error) throw error;

        const now = new Date();
        const currentTime = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:00`;

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        return (data || []).map((s: any) => ({
            id: s.id,
            time: `${s.start_time.slice(0, 5)} - ${s.end_time.slice(0, 5)}`,
            subject: s.subjects?.name || 'Unknown',
            teacher: s.teachers?.name || 'Ustadz/Teacher',
            room: s.room || 'N/A',
            status: currentTime > s.end_time ? 'Selesai' : currentTime < s.start_time ? 'Akan Datang' : 'Sedang Berlangsung'
        }));
    },

    async getTopScore(studentId: string) {
        try {
            const { data, error } = await supabase
                .from('grades')
                .select(`
                    final_score,
                    final_grade,
                    uas_score,
                    uas,
                    subjects (name)
                `)
                .eq('student_id', studentId)
                .order('final_grade', { ascending: false })
                .limit(1)
                .maybeSingle();

            if (error) throw error;
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            return data as any;
        } catch (err) {
            console.error('Error in getTopScore:', err);
            return null;
        }
    },

    async getDisciplinePoints(studentId: string) {
        const { data, error } = await supabase
            .from('violations')
            .select('points')
            .eq('student_id', studentId);

        if (error) {
            // Try legacy table?
            const { data: legacy, error: lErr } = await supabase.from('students').select('total_violation_points').eq('id', studentId).single();
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            if (!lErr && legacy) return 100 - ((legacy as any).total_violation_points || 0);

            return 100;
        }

        // Base points is 100, deducted by violations
        const totalViolations = (data || []).reduce((acc, curr) => acc + (curr.points || 0), 0);
        return Math.max(0, 100 - totalViolations);
    },

    async getRecentViolations(studentId: string) {
        const { data, error } = await supabase
            .from('violations')
            .select(`
                id,
                created_at,
                description,
                points,
                punishment,
                status
            `)
            .eq('student_id', studentId)
            .order('created_at', { ascending: false })
            .limit(3);

        if (error) return [];
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        return (data || []).map((v: any) => ({
            id: v.id,
            created_at: v.created_at,
            description: v.description,
            points: v.points,
            punishment: v.punishment,
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            status: v.status as any
        }));
    },

    async getWeeklySchedule(studentId: string) {
        const { data: student, error: sError } = await supabase
            .from('students')
            .select('class_id')
            .eq('id', studentId)
            .single();

        if (sError) throw sError;

        const { data, error } = await supabase
            .from('schedules')
            .select(`
                id,
                day_of_week,
                start_time,
                end_time,
                room,
                subjects (name),
                teachers (name)
            `)
            .eq('class_id', student?.class_id)
            .order('day_of_week')
            .order('start_time');

        if (error) throw error;
        return data || [];
    }
};

// Subjects Service - CRUD operations for Mata Pelajaran
import { supabase } from '../supabase';
import { getCurrentUser } from '../auth';

export interface Subject {
    id: string;
    code: string;
    name: string;
    category: 'umum' | 'agama' | 'tahfidz' | 'ekstrakurikuler';
    hours_per_week: number;
    pesantren_id: string;
    is_active: boolean;
    created_at: string;
}

export const subjectsService = {
    async getAll(): Promise<Subject[]> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();

        let query = supabase
            .from('subjects')
            .select('*')
            .order('category')
            .order('name');

        if (pesantrenId) {
            query = query.eq('pesantren_id', pesantrenId);
        }

        const { data, error } = await query;
        if (error) throw error;
        return data || [];
    },

    async getById(id: string): Promise<Subject | null> {
        const { data, error } = await supabase
            .from('subjects')
            .select('*')
            .eq('id', id)
            .single();

        if (error) {
            if (error.code === 'PGRST116') return null;
            throw error;
        }
        return data;
    },

    async create(subject: any): Promise<Subject> {
        const { requirePesantrenId } = await import('./helpers');
        const pesantrenId = await requirePesantrenId(subject.pesantren_id);

        const { data, error } = await supabase
            .from('subjects')
            .insert({
                code: subject.code,
                name: subject.name,
                category: subject.category?.toLowerCase() || 'umum',
                hours_per_week: subject.hours_per_week || 2,
                is_active: subject.is_active ?? true,
                pesantren_id: pesantrenId
            })
            .select()
            .single();

        if (error) throw error;
        return data;
    },

    async update(id: string, updates: any): Promise<Subject> {
        const payload: any = {};
        if (updates.code) payload.code = updates.code;
        if (updates.name) payload.name = updates.name;
        if (updates.is_active !== undefined) payload.is_active = updates.is_active;
        if (updates.hours_per_week !== undefined) payload.hours_per_week = updates.hours_per_week;
        if (updates.category) payload.category = updates.category.toLowerCase();

        const { data, error } = await supabase
            .from('subjects')
            .update(payload)
            .eq('id', id)
            .select()
            .single();

        if (error) throw error;
        return data;
    },

    async delete(id: string): Promise<void> {
        const { error } = await supabase
            .from('subjects')
            .delete()
            .eq('id', id);

        if (error) throw error;
    },

    async getByCategory(category: 'umum' | 'agama' | 'tahfidz'): Promise<Subject[]> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();

        let query = supabase
            .from('subjects')
            .select('*')
            .eq('category', category)
            .order('name');

        if (pesantrenId) {
            query = query.eq('pesantren_id', pesantrenId);
        }

        const { data, error } = await query;
        if (error) throw error;
        return data || [];
    }
};

import { supabase } from '../supabase';
import type { ActivityLog } from '@/types/database.types';

export interface SystemLog {
    id: string;
    timestamp: string;
    userName: string;
    userRole: string;
    action: string;
    target: string;
    ipAddress: string;
    status: string;
}

export const systemService = {
    async getLogs(limit = 100, offset = 0): Promise<SystemLog[]> {
        const { data, error } = await supabase
            .from('activity_logs')
            .select(`
                *,
                profiles:user_id (
                    name,
                    user_roles(role)
                )
            `)
            .order('created_at', { ascending: false })
            .range(offset, offset + limit - 1);

        if (error) throw error;

        return (data || []).map(log => ({
            id: log.id,
            timestamp: new Date(log.created_at).toLocaleString('id-ID', {
                day: '2-digit',
                month: 'short',
                year: 'numeric',
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit'
            }),
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            userName: (log.profiles as any)?.name || 'System',
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            userRole: (log.profiles as any)?.user_roles?.[0]?.role || '-',
            action: log.action,
            target: log.entity_type ? `${log.entity_type} (${log.entity_id})` : '-',
            ipAddress: log.ip_address || '-',
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            status: (log.details as any)?.status || 'success'
        }));
    },

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    async logAction(action: string, entityType?: string, entityId?: string, details?: any) {
        const { data: { user } } = await supabase.auth.getUser();

        const { error } = await supabase.from('activity_logs').insert({
            user_id: user?.id,
            action,
            entity_type: entityType,
            entity_id: entityId,
            details,
            ip_address: typeof window !== 'undefined' ? 'client-side' : 'server-side' // Real IP usually handled by DB function or edge
        });

        if (error) console.error('Error logging action:', error);
    },

    async getDatabaseHealth() {
        const start = performance.now();

        // 1. Try to get Real Server Metrics
        const { data: metrics, error: rpcError } = await supabase.rpc('get_system_metrics');
        const latency = Math.round(performance.now() - start);

        if (metrics && !rpcError) {
            const sizeInGB = (metrics.size_bytes / (1024 * 1024 * 1024)).toFixed(2);
            return {
                status: 'healthy',
                latency: `${latency} ms`,
                active_connections: metrics.active_connections,
                storage_usage: `${sizeInGB} GB`,
                total_storage: '1.0 GB', // Tetap estimasi kuota free tier
                last_backup: new Date(new Date().setHours(2, 0, 0, 0)).toLocaleString('id-ID', {
                    day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit'
                })
            };
        }

        // Fallback: If RPC not created yet, check basic connection
        const { count, error } = await supabase.from('profiles').select('*', { count: 'exact', head: true });

        if (error) {
            return {
                status: 'error',
                latency: '0 ms',
                active_connections: 0,
                storage_usage: '0 GB',
                last_backup: 'Unknown'
            };
        }

        return {
            status: 'healthy',
            latency: `${latency} ms`,
            active_connections: Math.floor(Math.random() * 5) + 1, // Minimal active
            storage_usage: 'Simulated',
            total_storage: 'Unknown',
            last_backup: 'Unknown'
        };
    }
};

// Teachers Service - CRUD operations for Ustadz/Guru
import { supabase } from '../supabase';
import type { Teacher, TeacherInsert, TeacherUpdate } from '@/types/database.types';

export interface TeacherWithProfile extends Teacher {
    profile?: { id: string; name: string; email: string; role: string } | null;
}

export interface TeacherFilters {
    isActive?: boolean;
    specialization?: string;
    search?: string;
}

export const teachersService = {
    /**
     * Get all teachers with optional filters
     */
    async getAll(filters?: TeacherFilters): Promise<Teacher[]> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();

        let query = supabase
            .from('teachers')
            .select('*')
            .order('name');

        if (pesantrenId) {
            query = query.eq('pesantren_id', pesantrenId);
        }
        if (filters?.isActive !== undefined) {
            query = query.eq('is_active', filters.isActive);
        }
        if (filters?.specialization) {
            query = query.eq('specialization', filters.specialization);
        }
        if (filters?.search) {
            query = query.or(`name.ilike.%${filters.search}%,nip.ilike.%${filters.search}%`);
        }

        const { data, error } = await query;
        if (error) throw error;
        return data || [];
    },

    /**
     * Get teacher by ID
     */
    async getById(id: string): Promise<Teacher | null> {
        const { data, error } = await supabase
            .from('teachers')
            .select('*')
            .eq('id', id)
            .single();

        if (error) {
            if (error.code === 'PGRST116') return null;
            throw error;
        }
        return data;
    },

    /**
     * Get teacher by user ID (for ustadz login)
     */
    async getByUserId(userId: string): Promise<Teacher | null> {
        const { data, error } = await supabase
            .from('teachers')
            .select('*')
            .eq('user_id', userId)
            .single();

        if (error) {
            if (error.code === 'PGRST116') return null;
            throw error;
        }
        return data;
    },

    /**
     * Create new teacher (with automatic user account)
     */
    async create(teacher: TeacherInsert): Promise<Teacher> {
        try {
            const { requirePesantrenId } = await import('./helpers');
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const pesantrenId = await requirePesantrenId((teacher as any).pesantren_id);

            // Call API route that uses Supabase Auth Admin API
            const response = await fetch('/api/admin/create-teacher', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    ...teacher,
                    pesantren_id: pesantrenId
                })
            });

            const data = await response.json();

            if (!response.ok || !data.success) {
                throw new Error(data.error || 'Failed to create teacher');
            }

            return data as unknown as Teacher;
        } catch (error: unknown) {
            console.error('Create teacher error:', error);
            throw error;
        }
    },

    /**
     * Update teacher
     */
    async update(id: string, updates: TeacherUpdate): Promise<Teacher> {
        const { data, error } = await supabase
            .from('teachers')
            .update(updates)
            .eq('id', id)
            .select()
            .single();

        if (error) throw error;
        return data;
    },

    /**
     * Delete teacher and associated auth user
     */
    async delete(id: string): Promise<void> {
        // Try cascade delete first (removes auth user too)
        const { data, error: rpcError } = await supabase.rpc('delete_teacher_cascade', {
            p_teacher_id: id
        });

        if (rpcError) {
            console.warn('RPC delete failed, falling back to direct delete:', rpcError);
            // Fallback to direct delete (won't remove auth user)
            const { error } = await supabase
                .from('teachers')
                .delete()
                .eq('id', id);

            if (error) throw error;
            return;
        }

        if (data && !data.success) {
            throw new Error(data.message || 'Gagal menghapus guru');
        }
    },

    /**
     * Get active teacher count
     */
    async getActiveCount(): Promise<number> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();

        let query = supabase
            .from('teachers')
            .select('*', { count: 'exact', head: true })
            .eq('is_active', true);

        if (pesantrenId) {
            query = query.eq('pesantren_id', pesantrenId);
        }

        const { count, error } = await query;

        if (error) throw error;
        return count || 0;
    },

    /**
     * Get unique specializations
     */
    async getSpecializations(): Promise<string[]> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();

        let query = supabase
            .from('teachers')
            .select('specialization')
            .not('specialization', 'is', null);

        if (pesantrenId) {
            query = query.eq('pesantren_id', pesantrenId);
        }

        const { data, error } = await query;

        if (error) throw error;
        const specs = new Set(data?.map(t => t.specialization).filter(Boolean));
        return Array.from(specs) as string[];
    },

    async getLoad(): Promise<{ name: string; hours: number }[]> {
        const { getPesantrenId } = await import('./helpers');
        const pesantrenId = await getPesantrenId();

        let query = supabase
            .from('schedules')
            .select(`
                teacher_id,
                teachers(name)
            `);

        if (pesantrenId) {
            query = query.eq('pesantren_id', pesantrenId);
        }

        const { data, error } = await query;

        const loads: Record<string, { name: string, hours: number }> = {};
        data?.forEach((s: any) => {
            const teacherObj = Array.isArray(s.teachers) ? s.teachers[0] : s.teachers;
            if (s.teacher_id && teacherObj) {
                if (!loads[s.teacher_id]) {
                    loads[s.teacher_id] = { name: teacherObj.name, hours: 0 };
                }
                loads[s.teacher_id].hours += 2;
            }
        });

        return Object.values(loads).sort((a, b) => b.hours - a.hours).slice(0, 5);
    },
};

// Users Service - Admin user management
import { supabase } from '../supabase';
import type { Profile, ProfileUpdate } from '@/types/database.types';
import { createUser, UserRole } from '../auth';

export interface UserWithDetails extends Profile {
    last_login?: string;
}

export interface UserFilters {
    role?: UserRole | 'all';
    isActive?: boolean;
    search?: string;
    pesantrenId?: string | 'all';
}

export interface SystemHealthItem {
    name: string;
    status: 'healthy' | 'warning' | 'error';
    value: string;
    icon: string;
}

export interface LoginTrafficItem {
    date: string;
    value: number;
}

export const usersService = {
    async getAll(filters?: UserFilters): Promise<Profile[]> {
        // 1. Get user from local storage cache
        const cachedUser = typeof window !== 'undefined' ? localStorage.getItem('smart_pesantren_user') : null;
        const currentUser = cachedUser ? JSON.parse(cachedUser) : null;

        const isSuperAdmin = currentUser?.role === 'super_admin';

        // 2. Prepare optimized query
        let query = supabase
            .from('profiles')
            .select('*')
            .order('created_at', { ascending: false });

        // 3. Fast Filtering
        // ONLY restrict if NOT super_admin
        if (!isSuperAdmin && currentUser?.pesantrenId) {
            query = query.eq('pesantren_id', currentUser.pesantrenId);
        }

        // Apply additional filters
        if (filters?.isActive !== undefined) {
            query = query.eq('is_active', filters.isActive);
        }

        if (filters?.role && filters.role !== 'all') {
            query = query.eq('role', filters.role);
        }

        if (filters?.search) {
            query = query.or(`name.ilike.%${filters.search}%,email.ilike.%${filters.search}%`);
        }

        // Apply Pesantren Filter from UI (if Super Admin is filtering by a specific pesantren)
        if (isSuperAdmin && filters?.pesantrenId && filters.pesantrenId !== 'all') {
            query = query.eq('pesantren_id', filters.pesantrenId);
        }

        const { data, error } = await query;
        if (error) {
            console.error('Fetch Error:', error);
            throw error;
        }

        return data || [];
    },

    async getById(id: string): Promise<Profile | null> {
        const { data, error } = await supabase
            .from('profiles')
            .select('*')
            .eq('id', id)
            .single();

        if (error) {
            if (error.code === 'PGRST116') return null;
            throw error;
        }
        return data;
    },

    async getByRole(role: UserRole): Promise<Profile[]> {
        const { data, error } = await supabase
            .from('profiles')
            .select('*')
            .eq('role', role)
            .order('name');

        if (error) throw error;
        return data || [];
    },

    async getPotentialSupervisors(): Promise<Profile[]> {
        const { data, error } = await supabase
            .from('profiles')
            .select('*')
            .in('role', ['ustadz', 'musyrif', 'kesantrian', 'super_admin'])
            .order('name');

        if (error) throw error;
        return data || [];
    },

    async create(
        email: string,
        password: string,
        name: string,
        role: UserRole,
        phone?: string,
        pesantrenId?: string
    ): Promise<{ success: boolean; user?: Profile; error?: string }> {
        try {
            // Call API route that uses Supabase Auth Admin API (SAFE & PRODUCTION-READY)
            const response = await fetch('/api/admin/create-user', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    email,
                    password,
                    name,
                    role,
                    phone,
                    pesantren_id: pesantrenId
                })
            });

            const data = await response.json();

            if (!response.ok || !data.success) {
                return { success: false, error: data.error || 'Failed to create user' };
            }

            // Fetch the created profile to return it
            if (data.user_id) {
                const profile = await this.getById(data.user_id);
                return { success: true, user: profile || undefined };
            }

            return { success: true };
        } catch (error: unknown) {
            console.error('Create user error:', error);
            const message = error instanceof Error ? error.message : 'Network error';
            return { success: false, error: message };
        }
    },

    async update(id: string, updates: ProfileUpdate): Promise<Profile> {
        const { data, error } = await supabase
            .from('profiles')
            .update(updates)
            .eq('id', id)
            .select()
            .single();

        if (error) throw error;
        return data;
    },

    async toggleActive(id: string): Promise<Profile> {
        const current = await this.getById(id);
        if (!current) throw new Error('User not found');

        return this.update(id, { is_active: !current.is_active });
    },

    async updateRole(userId: string, newRole: UserRole): Promise<void> {
        // 1. Update profiles table (if column exists)
        await supabase
            .from('profiles')
            .update({ role: newRole })
            .eq('id', userId);

        // 2. Update user_roles table
        // Delete existing roles first to maintain single primary role for this simplified management
        await supabase
            .from('user_roles')
            .delete()
            .eq('user_id', userId);

        const { error } = await supabase
            .from('user_roles')
            .insert({
                user_id: userId,
                role: newRole
            });

        if (error) throw error;
    },

    async delete(id: string): Promise<void> {
        // Use the secure RPC function to delete from both auth.users and public.profiles
        const { error } = await supabase.rpc('delete_user_complete', {
            target_user_id: id
        });

        if (error) {
            console.error('RPC delete_user_complete failed:', error.message, error.details);

            // Fallback: Try hard delete from profiles directly (handling Ghost User case)
            const { error: deleteError } = await supabase
                .from('profiles')
                .delete()
                .eq('id', id);

            if (deleteError) {
                // Check for Foreign Key Constraint violation
                if (deleteError.code === '23503') {
                    throw new Error('Gagal menghapus user: User ini terhubung dengan data lain (misal: mengajar kelas, ada nilai, dll). Hapus data terkait terlebih dahulu.');
                }
                console.error('Direct profile delete failed:', deleteError);
                throw new Error(deleteError.message);
            }
        }
    },

    async getStats(): Promise<{ total: number; active: number; byRole: Record<string, number> }> {
        // High Speed Fetch: Use combined RPC to get all stats in one trip
        const { data, error } = await supabase.rpc('get_super_admin_stats');

        if (error) {
            console.error('Failed to fetch user stats via RPC:', error);
            return { total: 0, active: 0, byRole: {} };
        }

        return {
            total: data.total_users || 0,
            active: data.active_users || 0,
            byRole: {}
        };
    },

    async getSystemHealth(): Promise<SystemHealthItem[]> {
        // Mock health but with real DB check
        const start = Date.now();
        const { error } = await supabase.from('profiles').select('id', { count: 'exact', head: true });
        const latency = Date.now() - start;

        return [
            { name: 'Server Status', status: 'healthy', value: 'Online', icon: 'server' },
            { name: 'Database', status: error ? 'error' : 'healthy', value: error ? 'Disconnected' : 'Connected', icon: 'database' },
            { name: 'Latency', status: latency < 500 ? 'healthy' : 'warning', value: `${latency}ms`, icon: 'wifi' },
            { name: 'Storage', status: 'healthy', value: 'Optimized', icon: 'hard-drive' },
            { name: 'Security', status: 'healthy', value: 'SSL Active', icon: 'shield' },
            { name: 'Backups', status: 'healthy', value: 'Daily Active', icon: 'clock' },
        ];
    },

    async getLoginTraffic(): Promise<LoginTrafficItem[]> {
        const { data, error } = await supabase
            .from('login_logs')
            .select('login_time')
            .gte('login_time', new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString())
            .order('login_time');

        if (error) throw error;

        // Group by day
        const days: Record<string, number> = {};
        // Initialize last 7 days
        for (let i = 6; i >= 0; i--) {
            const d = new Date();
            d.setDate(d.getDate() - i);
            const dateStr = d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short' });
            days[dateStr] = 0;
        }

        data?.forEach(log => {
            const dateStr = new Date(log.login_time).toLocaleDateString('id-ID', { day: '2-digit', month: 'short' });
            if (days[dateStr] !== undefined) days[dateStr]++;
        });

        return Object.entries(days).map(([date, value]) => ({ date, value }));
    },

    subscribeToChanges(callback: (payload: { [key: string]: any }) => void) {
        const channel = supabase
            .channel('profiles_changes')
            .on('postgres_changes',
                { event: '*', schema: 'public', table: 'profiles' },
                callback
            )
            .subscribe();
        return () => supabase.removeChannel(channel);
    },
};

import { supabase } from '../supabase';

export const ustadzService = {
    /**
     * Helper to get teacher record ID from user ID
     */
    async getTeacherId(userId: string) {
        if (!userId) return null;

        try {
            // 1. Try to get existing teacher record
            const { data, error } = await supabase
                .from('teachers')
                .select('id')
                .eq('user_id', userId)
                .maybeSingle();

            // 2. Auto-repair/sync: If user is ustadz but record missing in teachers table
            if (!data && !error) {
                console.log('Teacher record missing. Attempting auto-reconcile for userId:', userId);
                const { data: profile } = await supabase.from('profiles').select('*').eq('id', userId).single();

                if (profile && (profile.role === 'ustadz' || profile.role === 'wali_kelas')) {
                    const { data: newTeacher, error: createError } = await supabase
                        .from('teachers')
                        .insert([{
                            user_id: userId,
                            name: profile.name,
                            email: profile.email,
                            is_active: true,
                            pesantren_id: profile.pesantren_id,
                            status: 'active'
                        }])
                        .select()
                        .single();

                    if (!createError) return newTeacher.id;
                    console.error('Reconcile failed:', createError);
                }
            }

            if (error) {
                console.error('Supabase error in getTeacherId:', error);
                return null;
            }

            return data?.id || null;
        } catch (err) {
            console.error('Unexpected error in getTeacherId:', err);
            return null;
        }
    },

    async getGradeDistribution(userId: string) {
        try {
            const teacherId = await this.getTeacherId(userId);
            if (!teacherId) {
                console.warn('getGradeDistribution: No teacher record found for', userId);
                return [];
            }

            const { data, error } = await supabase
                .from('grades')
                .select('grade_letter')
                .eq('teacher_id', teacherId);

            if (error) throw error;

            const distribution: Record<string, number> = {
                'A': 0, 'B': 0, 'C': 0, 'D': 0, 'E': 0
            };

            const colors: Record<string, string> = {
                'A': '#8b5cf6', 'B': '#a78bfa', 'C': '#c4b5fd', 'D': '#ddd6fe', 'E': '#ede9fe'
            };

            data?.forEach(g => {
                const grade = g.grade_letter || 'C';
                if (distribution[grade] !== undefined) distribution[grade]++;
            });

            return Object.entries(distribution).map(([grade, count]) => ({
                grade,
                count,
                color: colors[grade]
            }));
        } catch (err) {
            console.error('Error in getGradeDistribution:', err);
            return [];
        }
    },

    async getHafalanProgress(userId: string) {
        try {
            // STRATEGY: 
            // 1. Try V2 Schema (New): Hafalan records use evaluated_by (User ID)
            const { data: v2Data, error: v2Error } = await supabase
                .from('hafalan_progress')
                .select('created_at, unit_number')
                .eq('evaluated_by', userId)
                .gte('created_at', new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString());

            // If V2 call succeeded and found data, use it
            if (!v2Error && v2Data && v2Data.length > 0) {
                const weeks: Record<string, { total: number, count: number }> = {
                    'Minggu 1': { total: 0, count: 0 },
                    'Minggu 2': { total: 0, count: 0 },
                    'Minggu 3': { total: 0, count: 0 },
                    'Minggu 4': { total: 0, count: 0 },
                };

                const now = new Date();
                v2Data.forEach(h => {
                    const date = new Date(h.created_at);
                    const diffDays = Math.floor((now.getTime() - date.getTime()) / (1000 * 3600 * 24));
                    let weekKey = '';
                    if (diffDays <= 7) weekKey = 'Minggu 4';
                    else if (diffDays <= 14) weekKey = 'Minggu 3';
                    else if (diffDays <= 21) weekKey = 'Minggu 2';
                    else if (diffDays <= 30) weekKey = 'Minggu 1';

                    if (weekKey) {
                        weeks[weekKey].total += 1;
                        weeks[weekKey].count += 1;
                    }
                });

                return Object.entries(weeks).map(([week, stats]) => ({
                    week,
                    average: stats.total
                }));
            }

            // 2. Fallback to V2 Schema but check if data exists
            // Since the main table no longer has teacher_id, we should NEVER query it there.
            // If we want legacy data, we check hafalan_progress_old
            const { data: oldData, error: oldError } = await supabase
                .from('hafalan_progress_old')
                .select('created_at')
                .eq('teacher_id', await this.getTeacherId(userId));

            if (oldError || !oldData || oldData.length === 0) {
                return [];
            }

            const weeks: Record<string, { total: number, count: number }> = {
                'Minggu 1': { total: 0, count: 0 },
                'Minggu 2': { total: 0, count: 0 },
                'Minggu 3': { total: 0, count: 0 },
                'Minggu 4': { total: 0, count: 0 },
            };

            const now = new Date();
            oldData.forEach(h => {
                const date = new Date(h.created_at);
                const diffDays = Math.floor((now.getTime() - date.getTime()) / (1000 * 3600 * 24));

                let weekKey = '';
                if (diffDays <= 7) weekKey = 'Minggu 4';
                else if (diffDays <= 14) weekKey = 'Minggu 3';
                else if (diffDays <= 21) weekKey = 'Minggu 2';
                else if (diffDays <= 30) weekKey = 'Minggu 1';

                if (weekKey) {
                    weeks[weekKey].total += 1;
                    weeks[weekKey].count += 1;
                }
            });

            return Object.entries(weeks).map(([week, stats]) => ({
                week,
                average: stats.total
            }));
        } catch (err) {
            console.error('Error in getHafalanProgress:', err);
            return [];
        }
    },

    async getTodaySchedule(userId: string) {
        try {
            const teacherId = await this.getTeacherId(userId);
            if (!teacherId) return [];

            const today = new Date().getDay();

            const { data, error } = await supabase
                .from('schedules')
                .select(`
                    id, start_time, end_time, room,
                    classes (name),
                    subjects (name)
                `)
                .eq('teacher_id', teacherId)
                .eq('day_of_week', today)
                .order('start_time');

            if (error) throw error;

            return (data || []).map(s => ({
                time: `${s.start_time?.slice(0, 5) || '--:--'} - ${s.end_time?.slice(0, 5) || '--:--'}`,
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                subject: (s.subjects as any)?.name || 'Unknown',
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                class: (s.classes as any)?.name || 'N/A',
                room: s.room || 'Room N/A'
            }));
        } catch (err) {
            console.error('Error in getTodaySchedule:', err);
            return [];
        }
    },

    async getFullWeeklySchedule(userId: string) {
        try {
            const teacherId = await this.getTeacherId(userId);
            if (!teacherId) return {};

            const { data, error } = await supabase
                .from('schedules')
                .select(`
                    id, day_of_week, start_time, end_time, room,
                    classes (name),
                    subjects (name)
                `)
                .eq('teacher_id', teacherId)
                .order('day_of_week')
                .order('start_time');

            if (error) throw error;

            const dayNames = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
            const grouped: Record<string, any[]> = {};
            dayNames.forEach(day => grouped[day] = []);

            data?.forEach(s => {
                const day = dayNames[s.day_of_week];
                grouped[day].push({
                    id: s.id,
                    time: `${s.start_time?.slice(0, 5) || '--:--'} - ${s.end_time?.slice(0, 5) || '--:--'}`,
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    subject: (s.subjects as any)?.name || 'Unknown',
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    class: (s.classes as any)?.name || 'N/A',
                    room: s.room || 'Room N/A',
                    status: 'Aktif'
                });
            });

            return grouped;
        } catch (err) {
            console.error('Error in getFullWeeklySchedule:', err);
            return {};
        }
    },

    async getAssignedClasses(userId: string) {
        try {
            const teacherId = await this.getTeacherId(userId);
            if (!teacherId) return [];

            const { data, error } = await supabase
                .from('schedules')
                .select(`
                    class_id,
                    classes (id, name)
                `)
                .eq('teacher_id', teacherId);

            if (error) throw error;

            const uniqueClasses = Array.from(new Set(data.map(d => d.class_id)))
                .map(id => {
                    const item = data.find(d => d.class_id === id);
                    return item?.classes;
                })
                .filter(Boolean);

            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            return uniqueClasses as any[];
        } catch (err) {
            console.error('Error in getAssignedClasses:', err);
            return [];
        }
    },

    async getAssignedSubjects(userId: string) {
        try {
            const teacherId = await this.getTeacherId(userId);
            if (!teacherId) return [];

            const { data, error } = await supabase
                .from('schedules')
                .select(`
                    subject_id,
                    subjects (id, name)
                `)
                .eq('teacher_id', teacherId);

            if (error) throw error;

            const uniqueSubjects = Array.from(new Set(data.map(d => d.subject_id)))
                .map(id => {
                    const item = data.find(d => d.subject_id === id);
                    return item?.subjects;
                })
                .filter(Boolean);

            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            return uniqueSubjects as any[];
        } catch (err) {
            console.error('Error in getAssignedSubjects:', err);
            return [];
        }
    },

    async getMyStudents(userId: string) {
        try {
            const teacherId = await this.getTeacherId(userId);
            if (!teacherId) return [];

            const { data: classData } = await supabase
                .from('schedules')
                .select('class_id')
                .eq('teacher_id', teacherId);

            const classIds = Array.from(new Set(classData?.map(d => d.class_id) || []));
            if (classIds.length === 0) return [];

            const { data: students, error: studentError } = await supabase
                .from('students')
                .select(`
                    id, name, nis, class_id, 
                    classes (id, name)
                `)
                .in('class_id', classIds)
                .eq('status', 'active')
                .order('name');

            if (studentError || !students) throw studentError || new Error('No students found');

            const studentIds = students.map(s => s.id);
            const { data: progressData } = await supabase
                .from('hafalan_progress')
                .select('student_id, unit_number, grade')
                .in('student_id', studentIds)
                .order('created_at', { ascending: true });

            return students.map(s => {
                const studentProgress = progressData?.filter(p => p.student_id === s.id) || [];
                // Sort locally to get latest by creation
                const latest = studentProgress.length > 0 ? studentProgress[studentProgress.length - 1] : null;

                return {
                    id: s.id,
                    name: s.name,
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    class: (s.classes as any)?.name || '-',
                    lastJuz: latest ? latest.unit_number : '-',
                    totalJuz: (studentProgress as any[]).length,
                    status: latest && (latest.grade === 'A' || latest.grade === 'B') ? 'Lancar' : (studentProgress as any[]).length > 0 ? 'Perlu Muraja\'ah' : 'Baru'
                };
            });
        } catch (err) {
            console.error('Error in getMyStudents:', err);
            return [];
        }
    },

    async getDashboardStats(userId: string) {
        try {
            const teacherId = await this.getTeacherId(userId);
            if (!teacherId) return { totalStudents: 0, totalSubjects: 0, activeSchedules: 0, totalHafalan: 0 };

            const [students, subjects, schedules, hafalan] = await Promise.all([
                supabase.from('schedules').select('class_id').eq('teacher_id', teacherId),
                supabase.from('schedules').select('subject_id').eq('teacher_id', teacherId),
                supabase.from('schedules').select('id').eq('teacher_id', teacherId),
                supabase.from('hafalan_progress').select('id').eq('evaluated_by', userId)
            ]);

            // Approximate student count by classes taught
            const classIds = Array.from(new Set((students.data || []).map(s => s.class_id)));
            const { count: studentCount } = await supabase
                .from('students')
                .select('id', { count: 'exact', head: true })
                .in('class_id', classIds);

            return {
                totalStudents: studentCount || 0,
                totalSubjects: new Set((subjects.data || []).map(s => s.subject_id)).size,
                activeSchedules: (schedules.data || []).length,
                totalHafalan: (hafalan.data || []).length
            };
        } catch (err) {
            console.error('Error in getDashboardStats:', err);
            return { totalStudents: 0, totalSubjects: 0, activeSchedules: 0, totalHafalan: 0 };
        }
    }
};

